local v

-- ============================================================
-- FANKUN HUB ADD-ON: GLOBAL CHAT v4 (flat minimalis, gaya WhatsApp)
--   * UI flat: tanpa gradien, warna sama dengan UI utama FanKun Hub (#0a0a12 / #00f0ff / #7b61ff).
--   * Pesan sendiri di KANAN, orang lain di KIRI (tampil nama + @username pengirim).
--   * Ikon "users" di header = daftar user online yang sedang memakai script.
--   * Ketuk pesan orang lain -> Blokir (lokal, hanya di layarmu).
--   * Notifikasi: angka di tombol Chat + suara ping tiap pesan masuk (tanpa toast).
--     Tombol lonceng di header = matikan / nyalakan suara (tersimpan di FanKunHub/chat_settings.json).
-- Standalone layer, dijalankan PALING AWAL supaya tombol "Chat" langsung muncul.
--   * Tombol "Chat" kecil di pojok kanan bawah (bisa di-drag).
--     Saat chat dibuka tombolnya hilang, muncul lagi ketika di-minimize ( - ).
--   * Ketuk pesan -> menu aksi: pesan sendiri = Hapus, pesan orang lain = Blokir.
--   * Tombol "blokir" di header = daftar user yang diblokir (bisa Buka blokir).
--     Blokir bersifat lokal (hanya di layarmu) dan disimpan di FanKunHub/chat_blocks.json.
--   * Ikon: Font Awesome (diunduh di belakang layar). Selama belum siap / tidak
--     didukung executor, dipakai ikon gambar-sendiri (tidak pernah kotak kosong).
--   * Backend: Firebase yang sama.
--       /global_chat/<pushId> = { uid, name, display, text, ts }
--       /chat_users/<UserId> = { ts, name, display } (heartbeat; daftar user online)
-- ============================================================
do
    local okChat, errChat = pcall(function()
        local Players = game:GetService("Players")
        local HttpService = game:GetService("HttpService")
        local TweenService = game:GetService("TweenService")
        local UserInputService = game:GetService("UserInputService")
        local ContentProvider = game:GetService("ContentProvider")
        local TextService = game:GetService("TextService")
        local LocalPlayer = Players.LocalPlayer
        local genv = typeof(getgenv) == "function" and getgenv() or _G

        if type(genv.FanKunChat_Cleanup) == "function" then
            pcall(genv.FanKunChat_Cleanup)
        end
        if not LocalPlayer then
            Players:GetPropertyChangedSignal("LocalPlayer"):Wait()
            LocalPlayer = Players.LocalPlayer
        end
        if not LocalPlayer then
            return
        end

        -- --------------------------------------------------------
        -- Konfigurasi
        -- --------------------------------------------------------
        local FIREBASE_BASE = "https://fankunhub-6fb0b-default-rtdb.asia-southeast1.firebasedatabase.app"
        local CHAT_BASE = FIREBASE_BASE .. "/global_chat"
        local CHAT_URL = CHAT_BASE .. ".json"
        local ONLINE_BASE = FIREBASE_BASE .. "/chat_users"

        local POLL_OPEN = 1.5 -- detik, saat panel terbuka
        local POLL_MINIMIZED = 3 -- detik, saat minimize
        local RECONCILE_OPEN = 6 -- cek pesan yang dihapus orang lain
        local RECONCILE_MIN = 15
        local PRESENCE_BEAT = 15 -- heartbeat online
        local ONLINE_WINDOW = 45000 -- ms: dianggap online jika heartbeat < 45 dtk
        local ONLINE_REFRESH = 25 -- detik, hanya saat panel terbuka
        local HISTORY_LIMIT = 40
        local MAX_MESSAGES_UI = 80
        local MAX_LEN = 200
        local SEND_COOLDOWN = 2
        local WIPE_MS = 10 * 60 * 1000 -- chat dihapus total tiap 10 menit
        local DATA_DIR = "FanKunHub"
        local BLOCK_FILE = DATA_DIR .. "/chat_blocks.json"
        local SETTINGS_FILE = DATA_DIR .. "/chat_settings.json"

        local SOUND_IDS = {
            "rbxasset://sounds/electronicpingshort.wav",
            "rbxasset://sounds/bell.wav",
            "rbxasset://sounds/button.wav",
            "rbxasset://sounds/switch.wav",
            "rbxasset://sounds/snap.mp3",
        }

        local FA_URLS = {
            "https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/webfonts/fa-solid-900.ttf",
            "https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/webfonts/fa-solid-900.ttf",
            "https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.4/webfonts/fa-solid-900.ttf",
        }

        local S = {
            dead = false,
            open = false, -- mulai dalam keadaan minimize
            loaded = false,
            lastKey = nil,
            seen = {},
            rows = {},
            rowByKey = {},
            order = 0,
            unread = 0,
            lastSend = 0,
            sending = false,
            toggleToken = 0,
            muted = false, -- true = suara ping dimatikan (FanKunChat.Mute)
            soundId = nil,
            lastSound = 0,
            serverNow = nil,
            serverNowAt = 0,
            blocked = {}, -- [uid string] = { name = "..." }
            actionRow = nil,
            panelCustom = false,
            admins = {}, -- [username lowercase] = true (daftar admin dari database)
            renderers = {}, -- [msgKey] = function() -> render ulang teks pesan (tag admin)
        }
        local conns = {}
        local function track(c)
            conns[#conns + 1] = c
            return c
        end

        -- --------------------------------------------------------
        -- HTTP helper (kompatibel banyak executor)
        -- --------------------------------------------------------
        local function httpRequest(opts)
            local url = tostring(opts.Url or "")
            if url == "" then
                return nil
            end
            local method = tostring(opts.Method or "GET")
            local headers = opts.Headers
                or {
                    ["Content-Type"] = "application/json",
                    ["Accept"] = "application/json",
                }

            local fns = {}
            if type(request) == "function" then
                fns[#fns + 1] = request
            end
            if type(http_request) == "function" then
                fns[#fns + 1] = http_request
            end
            if syn and type(syn.request) == "function" then
                fns[#fns + 1] = syn.request
            end
            if type(http) == "table" and type(http.request) == "function" then
                fns[#fns + 1] = http.request
            end

            for _, f in ipairs(fns) do
                local ok, res = pcall(f, {
                    Url = url,
                    URL = url,
                    Method = method,
                    Headers = headers,
                    Body = opts.Body,
                })
                if ok and type(res) == "table" then
                    local body = res.Body or res.body or res.ResponseBody or res.responseBody
                    if body ~= nil then
                        return body, tonumber(res.StatusCode or res.status_code or res.Status)
                    end
                end
            end

            if method == "GET" then
                local ok, r = pcall(function()
                    return game:HttpGet(url, true)
                end)
                if ok and type(r) == "string" then
                    return r, 200
                end
            end
            return nil
        end

        local function fbGet(url)
            local sep = url:find("?", 1, true) and "&" or "?"
            local bust = tostring(os.time()) .. tostring(math.random(1000, 9999))
            return httpRequest({
                Url = url .. sep .. "t=" .. bust,
                Method = "GET",
                Headers = {
                    ["Cache-Control"] = "no-cache, no-store, must-revalidate",
                    ["Accept"] = "application/json",
                },
            })
        end

        -- --------------------------------------------------------
        -- Util teks
        -- --------------------------------------------------------
        local function esc(s)
            return (tostring(s):gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;"))
        end

        local function cleanText(s, maxLen)
            s = tostring(s or "")
            s = s:gsub("%c", " ")
            s = s:gsub("%s+", " ")
            s = s:gsub("^%s+", "")
            s = s:gsub("%s+$", "")
            local n = utf8.len(s)
            if n and n > maxLen then
                local cut = utf8.offset(s, maxLen + 1)
                if cut then
                    s = s:sub(1, cut - 1)
                end
            elseif not n and #s > maxLen then
                s = s:sub(1, maxLen)
            end
            return s
        end

        local NAME_COLORS = {
            "#0a8f99", "#5a3fd6", "#c2268f", "#b07a00",
            "#1e9650", "#d2531e", "#1f78c1", "#8a3fc0",
        }
        local function colorFor(uid)
            return NAME_COLORS[(tonumber(uid) or 0) % #NAME_COLORS + 1]
        end

        local function fmtTime(ts)
            local t = tonumber(ts)
            if t and t > 1e11 then
                t = t / 1000
            end
            if not t then
                t = os.time()
            end
            local ok, s = pcall(os.date, "%H:%M", t)
            return ok and s or ""
        end

        local function firstChar(s)
            s = tostring(s or "?")
            if s == "" then
                return "?"
            end
            local cut = utf8.offset(s, 2)
            local ch = cut and s:sub(1, cut - 1) or s:sub(1, 1)
            return ch:upper()
        end

        -- --------------------------------------------------------
        -- Daftar blokir (disimpan lokal)
        -- --------------------------------------------------------
        local function loadBlocks()
            if typeof(isfile) ~= "function" or typeof(readfile) ~= "function" then
                return
            end
            local ok, data = pcall(function()
                if isfile(BLOCK_FILE) then
                    return HttpService:JSONDecode(readfile(BLOCK_FILE))
                end
                return nil
            end)
            if ok and type(data) == "table" then
                for uid, info in pairs(data) do
                    local name = type(info) == "table" and info.name or tostring(uid)
                    S.blocked[tostring(uid)] = { name = tostring(name) }
                end
            end
        end

        local function saveBlocks()
            if typeof(writefile) ~= "function" then
                return
            end
            pcall(function()
                if
                    typeof(isfolder) == "function"
                    and typeof(makefolder) == "function"
                    and not isfolder(DATA_DIR)
                then
                    makefolder(DATA_DIR)
                end
                writefile(BLOCK_FILE, HttpService:JSONEncode(S.blocked))
            end)
        end
        loadBlocks()

        local function loadSettings()
            if typeof(isfile) ~= "function" or typeof(readfile) ~= "function" then
                return
            end
            local ok, data = pcall(function()
                if isfile(SETTINGS_FILE) then
                    return HttpService:JSONDecode(readfile(SETTINGS_FILE))
                end
                return nil
            end)
            if ok and type(data) == "table" and data.muted == true then
                S.muted = true
            end
        end

        local function saveSettings()
            if typeof(writefile) ~= "function" then
                return
            end
            pcall(function()
                if
                    typeof(isfolder) == "function"
                    and typeof(makefolder) == "function"
                    and not isfolder(DATA_DIR)
                then
                    makefolder(DATA_DIR)
                end
                writefile(SETTINGS_FILE, HttpService:JSONEncode({ muted = S.muted }))
            end)
        end
        loadSettings()

        -- --------------------------------------------------------
        -- Firebase: ambil, kirim, hapus pesan
        -- --------------------------------------------------------
        local function fetchMessages()
            local q
            if S.lastKey then
                -- lastKey .. "-" selalu > lastKey dan < pushId berikutnya => tidak ada duplikat
                q = "?orderBy=%22%24key%22&startAt=%22" .. S.lastKey .. "-%22"
            else
                q = "?orderBy=%22%24key%22&limitToLast=" .. HISTORY_LIMIT
            end
            local body = fbGet(CHAT_URL .. q)
            if type(body) ~= "string" or body == "" then
                return nil, "tidak ada respon"
            end
            local ok, data = pcall(function()
                return HttpService:JSONDecode(body)
            end)
            if not ok then
                return nil, "respon tidak valid"
            end
            if type(data) ~= "table" then
                return {} -- node kosong / null
            end
            if data.error ~= nil then
                return nil, tostring(data.error)
            end

            local list = {}
            local cutoff = S.windowStart()
            for key, m in pairs(data) do
                if type(m) == "table" and type(m.text) == "string" then
                    local tsn = tonumber(m.ts)
                    list[#list + 1] = {
                        expired = tsn ~= nil and tsn < cutoff,
                        key = tostring(key),
                        uid = tonumber(m.uid) or 0,
                        name = cleanText(m.name, 24),
                        display = cleanText(m.display ~= nil and m.display or m.name, 24),
                        text = cleanText(m.text, MAX_LEN * 2),
                        ts = m.ts,
                    }
                end
            end
            table.sort(list, function(a, b)
                return a.key < b.key
            end)
            return list
        end

        -- Ambil key pesan terbaru saja: dipakai user baru supaya tidak melihat chat lama
        local function fetchBaseline()
            local body = fbGet(CHAT_URL .. "?orderBy=%22%24key%22&limitToLast=1")
            if type(body) ~= "string" or body == "" then
                return nil, "tidak ada respon"
            end
            if body:match("^%s*null%s*$") then
                return ""
            end
            local ok, data = pcall(function()
                return HttpService:JSONDecode(body)
            end)
            if not ok then
                return nil, "respon tidak valid"
            end
            if type(data) ~= "table" then
                return ""
            end
            if data.error ~= nil then
                return nil, tostring(data.error)
            end
            local newest
            for key in pairs(data) do
                key = tostring(key)
                if not newest or key > newest then
                    newest = key
                end
            end
            return newest or ""
        end

        local function postMessage(text)
            local okEnc, encoded = pcall(function()
                return HttpService:JSONEncode({
                    uid = LocalPlayer.UserId,
                    name = LocalPlayer.Name,
                    display = LocalPlayer.DisplayName,
                    text = text,
                    ts = { [".sv"] = "timestamp" },
                })
            end)
            if not okEnc then
                return nil
            end
            local body, status = httpRequest({
                Url = CHAT_URL,
                Method = "POST",
                Body = encoded,
            })
            if type(body) ~= "string" or (status and status >= 300) then
                return nil
            end
            local ok, data = pcall(function()
                return HttpService:JSONDecode(body)
            end)
            if ok and type(data) == "table" and type(data.name) == "string" then
                return data.name
            end
            return nil
        end

        -- --------------------------------------------------------
        -- ADMIN: /admin <username>  (command TIDAK pernah dikirim ke chat, jadi tidak terlihat orang lain)
        --   Disimpan di /chat_admins/<username lowercase>. Semua user membaca daftar ini
        --   berkala, lalu nick admin tampil EMAS dengan mahkota (tanpa tag teks).
        -- --------------------------------------------------------
        local ADMIN_BASE = FIREBASE_BASE .. "/chat_admins"
        local ADM = {}
        function ADM.key(name)
            return (tostring(name or ""):lower():gsub("[^%w_]", ""))
        end
        function ADM.isAdmin(name)
            local k = ADM.key(name)
            if k == "" then
                return false
            end
            return S.admins[k] == true
        end
        function ADM.fetch()
            local body = fbGet(ADMIN_BASE .. ".json")
            if type(body) ~= "string" or body == "" then
                return nil
            end
            if body:match("^%s*null%s*$") then
                return {}
            end
            local ok, data = pcall(function()
                return HttpService:JSONDecode(body)
            end)
            if not ok or type(data) ~= "table" or data.error ~= nil then
                return nil
            end
            local set = {}
            for k, v in pairs(data) do
                if v ~= nil and v ~= false then
                    set[ADM.key(k)] = true
                end
            end
            return set
        end
        function ADM.set(name, on)
            local k = ADM.key(name)
            if k == "" then
                return false
            end
            local body, status
            if on then
                local okEnc, encoded = pcall(function()
                    return HttpService:JSONEncode({ by = LocalPlayer.Name, ts = { [".sv"] = "timestamp" } })
                end)
                if not okEnc then
                    return false
                end
                body, status = httpRequest({ Url = ADMIN_BASE .. "/" .. k .. ".json", Method = "PUT", Body = encoded })
            else
                body, status = httpRequest({
                    Url = ADMIN_BASE .. "/" .. k .. ".json",
                    Method = "DELETE",
                    Headers = { ["Accept"] = "application/json" },
                })
            end
            return body ~= nil and (not status or status < 300)
        end

        local function deleteRemote(key)
            local body, status = httpRequest({
                Url = CHAT_BASE .. "/" .. tostring(key) .. ".json",
                Method = "DELETE",
                Headers = { ["Accept"] = "application/json" },
            })
            return body ~= nil and (not status or status < 300)
        end

        -- --------------------------------------------------------
        -- Online presence yang akurat
        -- --------------------------------------------------------
        local function presenceUrl()
            return ONLINE_BASE .. "/" .. tostring(LocalPlayer.UserId) .. ".json"
        end

        local function presenceBeat()
            local okEnc, enc = pcall(function()
                return HttpService:JSONEncode({
                    name = LocalPlayer.Name,
                    display = LocalPlayer.DisplayName,
                    ts = { [".sv"] = "timestamp" },
                })
            end)
            if not okEnc then
                return false
            end
            local body = httpRequest({
                Url = presenceUrl(),
                Method = "PUT",
                Body = enc,
            })
            if type(body) ~= "string" then
                return false
            end
            local ok, data = pcall(function()
                return HttpService:JSONDecode(body)
            end)
            local n = ok and type(data) == "table" and tonumber(data.ts) or nil
            if n and n > 1e12 then
                S.serverNow = n
                S.serverNowAt = os.clock()
                return true
            end
            return false
        end

        -- Jam server (ms). Sebelum heartbeat pertama selesai, pakai jam lokal.
        function S.serverNowMs()
            if S.serverNow then
                return S.serverNow + (os.clock() - S.serverNowAt) * 1000
            end
            return os.time() * 1000
        end
        function S.windowStart()
            return math.floor(S.serverNowMs() / WIPE_MS) * WIPE_MS
        end

        -- Hapus dari Firebase semua pesan yang lebih lama dari awal jendela 10 menit
        local function purgeExpired()
            local cutoff = S.windowStart()
            local body = fbGet(CHAT_URL)
            if type(body) ~= "string" or body == "" or body:match("^%s*null%s*$") then
                return
            end
            local ok, data = pcall(function()
                return HttpService:JSONDecode(body)
            end)
            if not ok or type(data) ~= "table" or data.error ~= nil then
                return
            end
            local keys = {}
            for key, m in pairs(data) do
                key = tostring(key)
                local tsn = type(m) == "table" and tonumber(m.ts) or nil
                if tsn and tsn < cutoff and key:match("^[%w%-_]+$") then
                    keys[#keys + 1] = key
                end
            end
            if #keys == 0 then
                return
            end
            local parts = {}
            for _, k in ipairs(keys) do
                parts[#parts + 1] = '"' .. k .. '":null'
            end
            local _, status = httpRequest({
                Url = CHAT_URL,
                Method = "PATCH",
                Body = "{" .. table.concat(parts, ",") .. "}",
            })
            if not status or status >= 300 then
                -- cadangan: hapus satu-satu
                for i, k in ipairs(keys) do
                    if i > 60 then
                        break
                    end
                    deleteRemote(k)
                end
            end
        end

        -- Daftar user online (yang heartbeat-nya masih baru)
        local function fetchOnline()
            local minTs = math.floor(S.serverNowMs() - ONLINE_WINDOW)
            local function parse(body)
                if type(body) ~= "string" or body == "" then
                    return nil
                end
                if body:match("^%s*null%s*$") then
                    return {}
                end
                local ok, data = pcall(function()
                    return HttpService:JSONDecode(body)
                end)
                if not ok then
                    return nil
                end
                if data == nil then
                    return {}
                end
                if type(data) ~= "table" or data.error ~= nil then
                    return nil
                end
                return data
            end
            local data = parse(fbGet(ONLINE_BASE .. ".json?orderBy=%22ts%22&startAt=" .. tostring(minTs)))
            if not data then
                data = parse(fbGet(ONLINE_BASE .. ".json")) -- cadangan bila query ditolak
            end
            if not data then
                return nil
            end
            local list, hasMe = {}, false
            for uid, u in pairs(data) do
                if type(u) == "table" then
                    local ts = tonumber(u.ts)
                    if ts and ts >= minTs then
                        local id = tonumber(uid) or 0
                        if id == LocalPlayer.UserId then
                            hasMe = true
                        end
                        list[#list + 1] = {
                            uid = id,
                            name = cleanText(u.name, 24),
                            display = cleanText(u.display ~= nil and u.display or u.name, 24),
                        }
                    end
                end
            end
            if not hasMe then
                list[#list + 1] = { uid = LocalPlayer.UserId, name = LocalPlayer.Name, display = LocalPlayer.DisplayName }
            end
            table.sort(list, function(x, y)
                local xm, ym = x.uid == LocalPlayer.UserId, y.uid == LocalPlayer.UserId
                if xm ~= ym then
                    return xm
                end
                return (x.display ~= "" and x.display or x.name):lower() < (y.display ~= "" and y.display or y.name):lower()
            end)
            return list
        end

        -- --------------------------------------------------------
        -- Font Awesome (asli): unduh TTF -> cache -> Font.new lewat family JSON.
        -- Dijalankan DI BELAKANG LAYAR (tidak menahan munculnya tombol Chat).
        -- --------------------------------------------------------
        local function loadFontAwesome(force)
            if
                typeof(writefile) ~= "function"
                or typeof(readfile) ~= "function"
                or typeof(isfile) ~= "function"
                or typeof(getcustomasset) ~= "function"
            then
                return nil
            end
            local ok, font = pcall(function()
                if typeof(isfolder) == "function" and typeof(makefolder) == "function" and not isfolder(DATA_DIR) then
                    makefolder(DATA_DIR)
                end
                local ttf = DATA_DIR .. "/fa6-solid.ttf"
                local json = DATA_DIR .. "/fa6-solid.json"
                if force and typeof(delfile) == "function" then
                    pcall(function()
                        if isfile(ttf) then
                            delfile(ttf)
                        end
                        if isfile(json) then
                            delfile(json)
                        end
                    end)
                end

                local have = false
                if isfile(ttf) then
                    local okRead, data = pcall(readfile, ttf)
                    have = okRead and type(data) == "string" and #data > 20000
                end
                if not have then
                    local data
                    for _, url in ipairs(FA_URLS) do
                        local okGet, res = pcall(function()
                            return game:HttpGet(url)
                        end)
                        if okGet and type(res) == "string" and #res > 20000 then
                            data = res
                            break
                        end
                    end
                    if not data then
                        error("unduh Font Awesome gagal")
                    end
                    writefile(ttf, data)
                end

                writefile(
                    json,
                    HttpService:JSONEncode({
                        name = "FanKunFA",
                        faces = {
                            {
                                name = "Regular",
                                weight = 400,
                                style = "normal",
                                assetId = getcustomasset(ttf),
                            },
                        },
                    })
                )
                return Font.new(getcustomasset(json))
            end)
            if ok and font then
                return font
            end
            return nil
        end

        local faFont = nil
        local faReady = false

        -- codepoint Font Awesome Free (solid)
        local GLYPH = {
            chat = 0xf086, -- fa-comments
            send = 0xf1d8, -- fa-paper-plane
            minus = 0xf068, -- fa-minus
            bell = 0xf0f3, -- fa-bell
            mute = 0xf1f6, -- fa-bell-slash
            trash = 0xf1f8, -- fa-trash
            ban = 0xf05e, -- fa-ban
            users = 0xf0c0, -- fa-users
            shield = 0xf3ed, -- fa-shield-halved / fa-shield-alt
        }

        -- --------------------------------------------------------
        -- Builder UI
        -- --------------------------------------------------------
        local function new(class, props, parent)
            local o = Instance.new(class)
            for k, val in pairs(props) do
                o[k] = val
            end
            if parent then
                o.Parent = parent
            end
            return o
        end

        local function corner(parent, r)
            return new("UICorner", { CornerRadius = UDim.new(0, r) }, parent)
        end

        local C = {
            bg = Color3.fromRGB(255, 255, 255), -- sama dengan UI utama
            panel = Color3.fromRGB(242, 242, 242),
            field = Color3.fromRGB(230, 230, 230),
            line = Color3.fromRGB(205, 205, 205),
            accent = Color3.fromRGB(14, 14, 14),
            text = Color3.fromRGB(12, 12, 12),
            muted = Color3.fromRGB(100, 100, 100),
