        }

        -- --------------------------------------------------------
        -- Sistem ikon: Font Awesome bila siap, kalau tidak -> gambar dari Frame
        -- --------------------------------------------------------
        local ICONS = {}

        local function makeIcon(parent, name, sz, color, props)
            local holder = new("Frame", {
                Name = "Icon",
                BackgroundTransparency = 1,
                Size = UDim2.fromOffset(sz, sz),
                ZIndex = 3,
            }, parent)
            for k, val in pairs(props or {}) do
                holder[k] = val
            end

            local obj = { Root = holder, Name = name, Color = color, _parts = {}, _strokes = {}, _text = nil }

            local function part(x, y, w, h, radius, rot, into)
                local f = new("Frame", {
                    BackgroundColor3 = obj.Color,
                    BorderSizePixel = 0,
                    Position = UDim2.fromOffset(x, y),
                    Size = UDim2.fromOffset(w, h),
                    Rotation = rot or 0,
                    ZIndex = holder.ZIndex,
                }, into or holder)
                if radius and radius > 0 then
                    corner(f, radius)
                end
                obj._parts[#obj._parts + 1] = f
                return f
            end

            local function draw()
                for _, c in ipairs(holder:GetChildren()) do
                    c:Destroy()
                end
                obj._parts = {}
                obj._strokes = {}
                obj._text = nil
                local s, n = sz, obj.Name

                if faReady and faFont and GLYPH[n] then
                    obj._text = new("TextLabel", {
                        AnchorPoint = Vector2.new(0.5, 0.5),
                        Position = UDim2.fromScale(0.5, 0.5),
                        BackgroundTransparency = 1,
                        Size = UDim2.fromOffset(sz * 2, sz * 2), -- lebih besar dari ikon agar glyph tidak terpotong
                        FontFace = faFont,
                        Text = utf8.char(GLYPH[n]),
                        TextSize = sz,
                        TextColor3 = obj.Color,
                        TextXAlignment = Enum.TextXAlignment.Center,
                        TextYAlignment = Enum.TextYAlignment.Center,
                        ZIndex = holder.ZIndex,
                    }, holder)
                    return
                end

                if n == "minus" then
                    part(s * 0.2, s * 0.5 - 1, s * 0.6, 2, 1)
                elseif n == "chat" then
                    part(s * 0.06, s * 0.12, s * 0.88, s * 0.6, s * 0.2) -- balon
                    part(s * 0.2, s * 0.58, s * 0.26, s * 0.26, 1, 45) -- ekor balon
                elseif n == "send" then
                    -- panah kirim (->): batang + dua garis kepala, tanpa ClipsDescendants
                    local cy = s * 0.5
                    local tipX = s * 0.9
                    local L = s * 0.42
                    local k = L / 2 * 0.7071
                    part(s * 0.1, cy - 1, tipX - s * 0.1, 2, 1) -- batang
                    part(tipX - k - L / 2, cy - k - 1, L, 2, 1, 45) -- kepala atas
                    part(tipX - k - L / 2, cy + k - 1, L, 2, 1, -45) -- kepala bawah
                elseif n == "bell" or n == "mute" then
                    part(s * 0.22, s * 0.1, s * 0.56, s * 0.56, s * 0.28) -- kubah
                    part(s * 0.22, s * 0.4, s * 0.56, s * 0.26, 0) -- badan bawah
                    part(s * 0.1, s * 0.62, s * 0.8, s * 0.1, 1) -- bibir
                    part(s * 0.38, s * 0.76, s * 0.24, s * 0.14, s * 0.07) -- bandul
                    if n == "mute" then
                        part(-s * 0.05, s * 0.5 - 1, s * 1.1, 2, 1, 45) -- coretan
                    end
                elseif n == "trash" then
                    part(s * 0.12, s * 0.2, s * 0.76, 2, 1) -- tutup
                    part(s * 0.36, s * 0.08, s * 0.28, 2, 1) -- gagang
                    part(s * 0.22, s * 0.3, s * 0.56, s * 0.6, 2) -- badan
                elseif n == "users" then
                    part(s * 0.3, s * 0.06, s * 0.4, s * 0.4, s * 0.2) -- kepala
                    part(s * 0.12, s * 0.54, s * 0.76, s * 0.36, s * 0.18) -- bahu
                elseif n == "shield" then
                    part(s * 0.18, s * 0.08, s * 0.64, s * 0.5, s * 0.1) -- badan atas
                    part(s * 0.28, s * 0.46, s * 0.44, s * 0.36, s * 0.18) -- bawah membulat
                elseif n == "ban" then
                    local ring = new("Frame", {
                        BackgroundTransparency = 1,
                        BorderSizePixel = 0,
                        Position = UDim2.fromOffset(s * 0.08, s * 0.08),
                        Size = UDim2.fromOffset(s * 0.84, s * 0.84),
                        ZIndex = holder.ZIndex,
                    }, holder)
                    corner(ring, s)
                    obj._strokes[#obj._strokes + 1] = new("UIStroke", {
                        Thickness = 2,
                        Color = obj.Color,
                        ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
                    }, ring)
                    part(s * 0.12, s * 0.5 - 1, s * 0.76, 2, 1, 45) -- coretan
                end
            end

            function obj:SetColor(c)
                obj.Color = c
                if obj._text then
                    obj._text.TextColor3 = c
                end
                for _, f in ipairs(obj._parts) do
                    f.BackgroundColor3 = c
                end
                for _, st in ipairs(obj._strokes) do
                    st.Color = c
                end
            end

            function obj:SetName(nm)
                obj.Name = nm
                draw()
            end

            obj.Redraw = draw
            ICONS[#ICONS + 1] = obj
            draw()
            return obj
        end

        -- Tombol ikon: mengembalikan (tombol, ikon)
        local function iconButton(parent, name, size, pos, iconSize, color)
            color = color or C.muted
            local b = new("TextButton", {
                AnchorPoint = Vector2.new(1, 0.5),
                Position = pos,
                Size = UDim2.fromOffset(size, size),
                BackgroundTransparency = 1,
                AutoButtonColor = false,
                Text = "",
                ZIndex = 3,
            }, parent)
            b:SetAttribute("base", color)
            local ic = makeIcon(b, name, iconSize or 14, color, {
                AnchorPoint = Vector2.new(0.5, 0.5),
                Position = UDim2.fromScale(0.5, 0.5),
                ZIndex = 4,
            })
            track(b.MouseEnter:Connect(function()
                ic:SetColor(C.accent)
            end))
            track(b.MouseLeave:Connect(function()
                ic:SetColor(b:GetAttribute("base") or C.muted)
            end))
            return b, ic
        end

