        -- --------------------------------------------------------
        -- Font Awesome di belakang layar (tombol Chat sudah tampil duluan)
        -- Font dianggap rusak bila gagal dimuat atau lebar glyph-nya sama persis
        -- dengan font cadangan (= tampil kotak). Kalau rusak -> tetap ikon gambar.
        -- --------------------------------------------------------
        task.spawn(function()
            local function fontWorks(font)
                if not font then
                    return false
                end
                local probe = new("TextLabel", {
                    BackgroundTransparency = 1,
                    TextTransparency = 1,
                    Size = UDim2.fromOffset(40, 20),
                    Text = utf8.char(GLYPH.chat),
                    TextSize = 14,
                }, gui)
                probe.FontFace = font
                local failed, done = false, false
                task.spawn(function()
                    pcall(function()
                        ContentProvider:PreloadAsync({ probe }, function(_, status)
                            if status == Enum.AssetFetchStatus.Failure or status == Enum.AssetFetchStatus.TimedOut then
                                failed = true
                            end
                        end)
                    end)
                    done = true
                end)
                local t0 = os.clock()
                while not done and os.clock() - t0 < 5 do
                    task.wait(0.05)
                end
                local sameAsFallback = false
                pcall(function()
                    local gp = Instance.new("GetTextBoundsParams")
                    gp.Text = utf8.char(GLYPH.chat)
                    gp.Size = 14
                    gp.Width = 1000
                    gp.Font = font
                    local wFA = TextService:GetTextBoundsAsync(gp).X
                    gp.Font = Font.fromEnum(Enum.Font.GothamBold)
                    local wRef = TextService:GetTextBoundsAsync(gp).X
                    sameAsFallback = math.abs(wFA - wRef) < 0.5
                end)
                probe:Destroy()
                return not failed and not sameAsFallback
            end

            local font = loadFontAwesome()
            if S.dead then
                return
            end
            if font and not fontWorks(font) then
                font = loadFontAwesome(true) -- unduh ulang sekali (cache mungkin rusak)
                if font and not fontWorks(font) then
                    font = nil
                end
            end
            if S.dead then
                return
            end
            if font then
                faFont = font
                faReady = true
                for i = #ICONS, 1, -1 do
                    local ic = ICONS[i]
                    if ic.Root.Parent then
                        ic:Redraw()
                    else
                        table.remove(ICONS, i)
                    end
                end
            end
            print("[FanKun Chat] ikon: " .. (faReady and "Font Awesome" or "gambar-sendiri (font tidak didukung executor)"))
        end)

        -- --------------------------------------------------------
        -- Suara notifikasi pesan masuk
        -- --------------------------------------------------------
        local ping = new("Sound", {
            Name = "FanKunChatPing",
            Volume = 0.7,
            SoundId = "",
        }, gui)

        task.spawn(function()
            for _, id in ipairs(SOUND_IDS) do
                if S.dead then
                    return
                end
                local probe = new("Sound", { SoundId = id, Volume = 0 }, gui)
                pcall(function()
                    ContentProvider:PreloadAsync({ probe })
                end)
                local good = probe.IsLoaded and probe.TimeLength > 0
                probe:Destroy()
                if good then
                    S.soundId = id
                    ping.SoundId = id
                    return
                end
            end
        end)

        local function playPing()
            if S.muted or not S.soundId then
                return
            end
            local now = os.clock()
            if now - S.lastSound < 0.4 then
                return
            end
            S.lastSound = now
            pcall(function()
                ping.TimePosition = 0
                ping:Play()
            end)
        end

        -- --------------------------------------------------------
        -- Logic UI
        -- --------------------------------------------------------
        local function updateBadge()
            local show = S.unread > 0 and not S.open
            badge.Visible = show
            badge.Text = S.unread > 99 and "99+" or tostring(S.unread)
        end

        local function scrollToBottom()
            task.spawn(function()
                task.wait(0.08)
                if list and list.Parent then
                    list.CanvasPosition = Vector2.new(0, math.max(0, list.AbsoluteCanvasSize.Y))
                end
            end)
        end

        local function isNearBottom()
            return list.CanvasPosition.Y + list.AbsoluteWindowSize.Y >= list.AbsoluteCanvasSize.Y - 40
        end

        local function closeActions()
            local row = S.actionRow
            S.actionRow = nil
            if row and row.Parent then
                local abar = row:FindFirstChild("Actions")
                if abar then
                    abar.Visible = false
                end
            end
        end

        local function pushRow(row)
            S.rows[#S.rows + 1] = row
            if #S.rows > MAX_MESSAGES_UI then
                local oldest = table.remove(S.rows, 1)
                if oldest then
                    local k = oldest:GetAttribute("key")
                    if k then
                        S.rowByKey[k] = nil
                    end
                    if S.actionRow == oldest then
                        S.actionRow = nil
                    end
                    oldest:Destroy()
                end
            end
        end

        local function addSystem(text)
            S.order += 1
            local lbl = new("TextLabel", {
                BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 0, 0),
                AutomaticSize = Enum.AutomaticSize.Y,
                Font = Enum.Font.Gotham,
                Text = tostring(text),
                TextColor3 = C.muted,
                TextSize = 10,
                TextWrapped = true,
                TextXAlignment = Enum.TextXAlignment.Center,
                LayoutOrder = S.order,
            }, list)
            pushRow(lbl)
            scrollToBottom()
        end

        -- Bersihkan semua pesan dari layar (reset 10 menit)
        local function clearAllRows()
            closeActions()
            for _, r in ipairs(S.rows) do
                if r and r.Parent then
                    r:Destroy()
                end
            end
            S.rows = {}
            S.rowByKey = {}
            S.renderers = {}
            S.unread = 0
            updateBadge()
        end

        -- ---------------- Hapus pesan ----------------
        local function removeRow(key)
            local row = S.rowByKey[key]
            S.rowByKey[key] = nil
            S.renderers[key] = nil
            if row then
                for i, r in ipairs(S.rows) do
                    if r == row then
                        table.remove(S.rows, i)
                        break
                    end
                end
                if S.actionRow == row then
                    S.actionRow = nil
                end
                row:Destroy()
            end
        end

        local function deleteMessage(key)
            task.spawn(function()
                if deleteRemote(key) then
                    removeRow(key)
                else
                    addSystem("Gagal menghapus pesan. Cek koneksi atau Firebase rules.")
                end
            end)
        end

        -- Pesan yang dihapus pemiliknya di device lain ikut hilang dari layar ini
        local function reconcileDeletes()
            local snapshot = {}
            for key in pairs(S.rowByKey) do
                snapshot[#snapshot + 1] = key
            end
            if #snapshot == 0 then
                return
            end
            local body = fbGet(CHAT_URL .. "?orderBy=%22%24key%22&limitToLast=" .. HISTORY_LIMIT)
            if type(body) ~= "string" or body == "" then
                return
            end
            local present, minKey = {}, nil
            if not body:match("^%s*null%s*$") then
                local ok, data = pcall(function()
                    return HttpService:JSONDecode(body)
                end)
                if not ok or type(data) ~= "table" or data.error ~= nil then
                    return
                end
                for key in pairs(data) do
                    key = tostring(key)
                    present[key] = true
                    if not minKey or key < minKey then
                        minKey = key
                    end
                end
            end
            for _, key in ipairs(snapshot) do
                if not present[key] and (minKey == nil or key >= minKey) then
                    removeRow(key)
                end
            end
        end

        -- ---------------- Blokir user (lokal) ----------------
        local function applyBlocks()
            for _, row in ipairs(S.rows) do
                local uid = row:GetAttribute("uid")
                if uid ~= nil then
                    local hide = uid ~= LocalPlayer.UserId and S.blocked[tostring(uid)] ~= nil
                    row.Visible = not hide
                end
            end
        end

        local refreshBlockedView

        local function blockUser(uid, name)
            if not uid or uid == 0 or uid == LocalPlayer.UserId then
                return
            end
            S.blocked[tostring(uid)] = { name = tostring(name or uid) }
            saveBlocks()
            closeActions()
            applyBlocks()
            refreshBlockedView()
            addSystem(tostring(name or uid) .. " diblokir.")
        end

        local function unblockUser(uid)
            S.blocked[tostring(uid)] = nil
            saveBlocks()
            applyBlocks()
            refreshBlockedView()
        end

        function refreshBlockedView()
            for _, c in ipairs(bvList:GetChildren()) do
                if c:IsA("Frame") then
                    c:Destroy()
                end
            end
            local n = 0
            for uid, info in pairs(S.blocked) do
                n += 1
                local item = new("Frame", {
                    Size = UDim2.new(1, 0, 0, 28),
                    BackgroundColor3 = C.field,
                    BorderSizePixel = 0,
                    LayoutOrder = n,
                    ZIndex = 7,
                }, bvList)
                corner(item, 6)
                new("TextLabel", {
                    BackgroundTransparency = 1,
                    Position = UDim2.fromOffset(10, 0),
                    Size = UDim2.new(1, -100, 1, 0),
                    Font = Enum.Font.Gotham,
                    Text = tostring(info.name or uid),
                    TextColor3 = C.text,
                    TextSize = 11,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    TextTruncate = Enum.TextTruncate.AtEnd,
                    ZIndex = 8,
                }, item)
                local ub = new("TextButton", {
                    AnchorPoint = Vector2.new(1, 0.5),
                    Position = UDim2.new(1, -6, 0.5, 0),
                    Size = UDim2.fromOffset(78, 20),
