                    BorderSizePixel = 0,
                    AutoButtonColor = false,
                    Font = Enum.Font.GothamMedium,
                    Text = "Buka blokir",
                    TextColor3 = C.accent,
                    TextSize = 10,
                    ZIndex = 8,
                }, item)
                corner(ub, 5)
                ub.MouseButton1Click:Connect(function()
                    unblockUser(uid)
                end)
            end
            bvEmpty.Visible = n == 0
        end

