        local function avState()
            local gA = genv.FK_AdminAbuse
            return type(gA) == "table" and gA.State or nil
        end
        -- pengaturan steal (diam di target / speed return / visual base)
        local function avCfg()
            local gA = genv.FK_AdminAbuse
            return type(gA) == "table" and type(gA.Config) == "table" and gA.Config or { hold = 1, speed = 4000, visual = false }
        end
        -- angka dari kotak teks: terima koma sebagai desimal ("1,5"), spasi diabaikan
        local function avNum(txt)
            txt = tostring(txt or ""):gsub(",", "."):gsub("%s+", "")
            return tonumber(txt)
        end

        local function avRenderStatus()
            local st = avState()
            local txt
            if st and st.on then
                txt = st.scope == "admin" and "ON - hanya admin (uji coba)" or "ON - semua user"
            else
                txt = "OFF"
            end
            local cfg = avCfg()
            local extra = string.format(
                "\ndiam di target %s dtk  |  speed return %s  |  visual base %s",
                tostring(tonumber(cfg.hold) or 1),
                tostring(tonumber(cfg.speed) or 4000),
                cfg.visual == true and "ON" or "OFF"
            )
            avStatus.Text = "Status saat ini: <b>" .. txt .. "</b>" .. extra
        end

        local function avRender()
            avRenderStatus()
            avPill.BackgroundColor3 = AV.on and C.accent or Color3.fromRGB(180, 180, 180)
            avKnob.Position = AV.on and UDim2.new(1, -16, 0.5, 0) or UDim2.new(0, 2, 0.5, 0)
            avKnob.AnchorPoint = Vector2.new(0, 0.5)

            local function seg(b, selected)
                b.BackgroundColor3 = selected and C.accent or C.field
                b.TextColor3 = selected and Color3.fromRGB(255, 255, 255) or C.text
            end
            seg(avSegAdmin, AV.scope == "admin")
            seg(avSegAll, AV.scope == "all")

            avVisPill.BackgroundColor3 = AV.visual and C.accent or Color3.fromRGB(180, 180, 180)
            avVisKnob.Position = AV.visual and UDim2.new(1, -16, 0.5, 0) or UDim2.new(0, 2, 0.5, 0)

            local canAnnounce = AV.on and AV.scope == "all"
            local checked = canAnnounce and AV.announce
            avBox.BackgroundColor3 = checked and C.accent or C.bg
            avBoxStroke.Color = canAnnounce and C.accent or C.line
            avTick1.Visible = checked
            avTick2.Visible = checked
            avCheckLbl.TextColor3 = canAnnounce and C.text or C.muted
            avCheckLbl.Text = canAnnounce and "Kirim announcement ke semua user"
