                end
                if blockedView.Visible then
                    blockedView.Visible = false
                    blockBtn:SetAttribute("base", C.muted)
                    blockIcon:SetColor(C.muted)
                end
                closeActions()
                local st = avState()
                AV.on = st and st.on == true or false
                AV.scope = (st and st.scope == "all") and "all" or "admin"
                AV.announce = false
                local cfg = avCfg()
