                avHoldBox.Text = tostring(AV.hold)
                avSpeedBox.Text = tostring(AV.speed)
                avSetMsg("", C.muted)
                avRender()
            end
        end
        closeAdminView = function()
            if adminView.Visible then
                setAdminView(false)
            end
        end

        track(adminBtn.MouseButton1Click:Connect(function()
            setAdminView(not adminView.Visible)
        end))
        track(avToggle.MouseButton1Click:Connect(function()
            AV.on = not AV.on
            avRender()
        end))
        track(avVisToggle.MouseButton1Click:Connect(function()
            AV.visual = not AV.visual
            avRender()
        end))
        track(avSegAdmin.MouseButton1Click:Connect(function()
            AV.scope = "admin"
            avRender()
        end))
        track(avSegAll.MouseButton1Click:Connect(function()
            AV.scope = "all"
            avRender()
        end))
        track(avCheck.MouseButton1Click:Connect(function()
            if AV.on and AV.scope == "all" then
                AV.announce = not AV.announce
                avRender()
            end
        end))
        track(avApplyBtn.MouseButton1Click:Connect(function()
            if AV.busy then
                return
            end
            local gA = genv.FK_AdminAbuse
            if type(gA) ~= "table" or type(gA.Post) ~= "function" then
                avSetMsg("Fitur Admin Abuse belum siap. Coba lagi sebentar.", C.danger)
                return
            end
            if not ADM.isAdmin(LocalPlayer.Name) then
                avSetMsg("Khusus admin.", C.danger)
                return
            end
            -- validasi angka dulu (kotak kosong = pakai nilai yang sedang aktif)
            local cfgNow = avCfg()
            local wantHold, wantSpeed = tonumber(cfgNow.hold) or 1, tonumber(cfgNow.speed) or 4000
            if avHoldBox.Text:match("%S") then
                wantHold = avNum(avHoldBox.Text)
                if wantHold == nil or wantHold ~= wantHold then
                    avSetMsg("Angka 'Diam di target' tidak valid.", C.danger)
                    return
                end
            end
            if avSpeedBox.Text:match("%S") then
                wantSpeed = avNum(avSpeedBox.Text)
                if wantSpeed == nil or wantSpeed ~= wantSpeed or wantSpeed <= 0 then
                    avSetMsg("Kecepatan return harus angka lebih dari 0.", C.danger)
                    return
                end
            end
            wantHold = math.clamp(math.floor(wantHold * 10 + 0.5) / 10, 0, 60)
            wantSpeed = math.min(math.floor(wantSpeed * 100 + 0.5) / 100, 1e12)
            if wantSpeed <= 0 then
                wantSpeed = 1
            end
            local wantVisual = AV.visual == true
            avHoldBox.Text = tostring(wantHold)
            avSpeedBox.Text = tostring(wantSpeed)
            AV.busy = true
            avSetMsg("Menyimpan...", C.muted)
            local wantOn, wantScope = AV.on, AV.scope
            local wantAnn = AV.on and AV.scope == "all" and AV.announce
            local wantAnnTitle, wantAnnText = avAnnTitleBox.Text, avAnnTextBox.Text
            task.spawn(function()
                local okP, res, warn = pcall(gA.Post, wantOn, LocalPlayer.Name, wantScope, wantAnn, {
                    hold = wantHold,
                    speed = wantSpeed,
                    visual = wantVisual,
                    annTitle = wantAnnTitle,
                    annText = wantAnnText,
                })
                AV.busy = false
                if S.dead then
                    return
                end
                if okP and res then
                    if not wantOn then
                        avSetMsg("Mode Admin Abuse OFF.", C.muted)
                    elseif wantScope == "admin" then
                        avSetMsg("Mode Admin Abuse ON - hanya admin yang melihat opsinya (uji coba).", C.muted)
                    else
                        avSetMsg(
                            "Mode Admin Abuse ON untuk semua user" .. (wantAnn and " - announcement terkirim." or "."),
                            C.muted
                        )
                    end
                    AV.announce = false
                    local sum = string.format(
                        "  Tersimpan: diam %s dtk, speed %s, visual %s.",
                        tostring(wantHold),
                        tostring(wantSpeed),
                        wantVisual and "ON" or "OFF"
                    )
                    avMsg.Text = avMsg.Text .. sum
                    if type(warn) == "string" and warn ~= "" then
                        avMsg.Text = avMsg.Text .. "\n" .. warn
                        avMsg.TextColor3 = C.danger
                    end
                else
                    avSetMsg("Gagal menyimpan. Pastikan Firebase rules mengizinkan /feature_flags dan /announcement.", C.danger)
                end
                avRender()
            end)
        end))

        -- tampil / sembunyi ikon perisai sesuai status admin akun ini
        local function refreshAdminBtn()
            local isAdm = ADM.isAdmin(LocalPlayer.Name)
            adminBtn.Visible = isAdm
            titleLabel.Size = UDim2.new(1, isAdm and -184 or -156, 1, 0)
            if not isAdm and adminView.Visible then
                setAdminView(false)
            end
        end
        -- dibaca add-on Admin Abuse di akhir file (status admin akun ini)
        genv.FK_IsChatAdmin = function()
            return ADM.isAdmin(LocalPlayer.Name)
        end
        refreshAdminBtn()

        -- status di panel admin ikut ter-update saat panel terbuka
        task.spawn(function()
            while not S.dead do
                if adminView.Visible and not AV.busy then
                    pcall(avRenderStatus)
                end
                task.wait(2)
            end
        end)

        -- ---------------- Menu aksi di bawah pesan ----------------
        local function actionButton(parent, iconName, label, color, order, onClick)
            local b = new("TextButton", {
                Size = UDim2.new(0, 0, 0, 22),
                AutomaticSize = Enum.AutomaticSize.X,
                BackgroundColor3 = C.field,
                BorderSizePixel = 0,
                Text = "",
                AutoButtonColor = false,
                LayoutOrder = order,
                ZIndex = 3,
            }, parent)
            corner(b, 6)
            local st = new("UIStroke", {
                Color = color,
                Transparency = 0.5,
                Thickness = 1,
                ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
            }, b)
            new("UIPadding", { PaddingLeft = UDim.new(0, 8), PaddingRight = UDim.new(0, 8) }, b)
            new("UIListLayout", {
                FillDirection = Enum.FillDirection.Horizontal,
                VerticalAlignment = Enum.VerticalAlignment.Center,
                SortOrder = Enum.SortOrder.LayoutOrder,
                Padding = UDim.new(0, 5),
            }, b)
            makeIcon(b, iconName, 11, color, { LayoutOrder = 1, ZIndex = 4 })
            local lbl = new("TextLabel", {
                BackgroundTransparency = 1,
                Size = UDim2.new(0, 0, 1, 0),
                AutomaticSize = Enum.AutomaticSize.X,
                Font = Enum.Font.GothamMedium,
                Text = label,
                TextColor3 = color,
                TextSize = 11,
                LayoutOrder = 2,
                ZIndex = 4,
            }, b)

            b.MouseEnter:Connect(function()
                st.Transparency = 0.1
            end)
            b.MouseLeave:Connect(function()
                st.Transparency = 0.5
            end)

            -- ketuk 2x (konfirmasi) supaya tidak terhapus/terblokir tanpa sengaja
            local armed = false
            b.MouseButton1Click:Connect(function()
                if not armed then
                    armed = true
                    lbl.Text = "Yakin?"
                    task.delay(2.5, function()
                        if armed and lbl.Parent then
                            armed = false
                            lbl.Text = label
                        end
                    end)
                    return
                end
                armed = false
                lbl.Text = label
                onClick()
            end)
            return b
        end

        local function buildActions(row, m, isMe, who)
            local abar = new("Frame", {
                Name = "Actions",
                BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 0, 24),
                LayoutOrder = 2,
                Visible = false,
            }, row)
            new("UIListLayout", {
                FillDirection = Enum.FillDirection.Horizontal,
                HorizontalAlignment = isMe and Enum.HorizontalAlignment.Right or Enum.HorizontalAlignment.Left,
                VerticalAlignment = Enum.VerticalAlignment.Center,
                SortOrder = Enum.SortOrder.LayoutOrder,
                Padding = UDim.new(0, 6),
            }, abar)
            if isMe then
                actionButton(abar, "trash", "Hapus", C.danger, 1, function()
                    deleteMessage(m.key)
                end)
            else
                actionButton(abar, "ban", "Blokir", C.danger, 1, function()
                    blockUser(m.uid, who)
                end)
            end
            return abar
        end

        local function addMessage(m, countUnread)
            if S.seen[m.key] then
                return false
            end
            S.seen[m.key] = true
            if m.text == "" or m.expired then
                return false
            end

            local isMe = m.uid == LocalPlayer.UserId
            local who = (m.display ~= "" and m.display) or (m.name ~= "" and m.name) or "Player"
            local blocked = (not isMe) and S.blocked[tostring(m.uid)] ~= nil
            local col = colorFor(m.uid)
            S.order += 1

            local row = new("Frame", {
                Name = "Msg",
                BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 0, 0),
                AutomaticSize = Enum.AutomaticSize.Y,
                LayoutOrder = S.order,
                Visible = not blocked,
            }, list)
            row:SetAttribute("key", m.key)
            row:SetAttribute("uid", m.uid)
            new("UIListLayout", {
                Padding = UDim.new(0, 2),
                SortOrder = Enum.SortOrder.LayoutOrder,
                HorizontalAlignment = isMe and Enum.HorizontalAlignment.Right or Enum.HorizontalAlignment.Left,
            }, row)

            local baseColor = isMe and C.mine or C.other
            local hoverColor = isMe and C.mineHover or C.otherHover
            local bubble = new("TextButton", {
                Name = "Bubble",
                Text = "",
                AutoButtonColor = false,
                Size = UDim2.fromOffset(0, 0),
                AutomaticSize = Enum.AutomaticSize.XY,
                BackgroundColor3 = baseColor,
                BackgroundTransparency = 0,
                BorderSizePixel = 0,
                LayoutOrder = 1,
            }, row)
            corner(bubble, 8)
            new("UIPadding", {
                PaddingLeft = UDim.new(0, 9),
                PaddingRight = UDim.new(0, 9),
                PaddingTop = UDim.new(0, 5),
                PaddingBottom = UDim.new(0, 5),
            }, bubble)

            -- nama hanya untuk pesan orang lain; waktu kecil di akhir teks; admin = nick emas + mahkota
            local ADMIN_GOLD = "#E3A400"
            local CROWN = "\u{1F451}"
            local function buildText()
                local adm = ADM.isAdmin(m.name)
                local head = ""
                if not isMe then
                    local tag = (m.name ~= "" and m.name ~= who) and string.format('  <font color="#646464" size="9">@%s</font>', esc(m.name)) or ""
                    if adm then
                        head = string.format('<font size="11">%s</font> <font color="%s"><b>%s</b></font>%s\n', CROWN, ADMIN_GOLD, esc(who), tag)
                    else
                        head = string.format('<font color="%s"><b>%s</b></font>%s\n', col, esc(who), tag)
                    end
                elseif adm then
                    head = string.format('<font size="11">%s</font> <font color="%s"><b>%s</b></font>\n', CROWN, ADMIN_GOLD, esc(who))
                end
                return head .. esc(m.text) .. string.format('  <font color="%s" size="9">%s</font>', isMe and "#bdbdbd" or "#646464", fmtTime(m.ts))
            end
            local body = new("TextLabel", {
                BackgroundTransparency = 1,
                Size = UDim2.fromOffset(0, 0),
                AutomaticSize = Enum.AutomaticSize.XY,
                Font = Enum.Font.Gotham,
                RichText = true,
                TextSize = 12,
                TextColor3 = isMe and Color3.new(1, 1, 1) or C.text,
                TextWrapped = true,
                TextXAlignment = Enum.TextXAlignment.Left,
                TextYAlignment = Enum.TextYAlignment.Top,
                Text = buildText(),
                ZIndex = 3,
            }, bubble)
            S.renderers[m.key] = function()
                if body.Parent then
                    body.Text = buildText()
                end
            end
            new("UISizeConstraint", { MaxSize = Vector2.new(BUBBLE_MAX - 18, math.huge) }, body)

            bubble.MouseEnter:Connect(function()
                bubble.BackgroundColor3 = hoverColor
            end)
            bubble.MouseLeave:Connect(function()
                bubble.BackgroundColor3 = baseColor
            end)
            bubble.MouseButton1Click:Connect(function()
                local abar = row:FindFirstChild("Actions") or buildActions(row, m, isMe, who)
                local show = not abar.Visible
                local stick = isNearBottom()
                closeActions()
                if show then
                    abar.Visible = true
                    S.actionRow = row
                    if stick then
                        scrollToBottom()
                    end
                end
            end)

            S.rowByKey[m.key] = row
            pushRow(row)

            if countUnread and not isMe and not blocked then
                playPing()
                if not S.open then
                    S.unread += 1
                    updateBadge()
                end
            end
            return true
        end

        -- --------------------------------------------------------
        -- Buka / minimize
        --   Dibuka  -> tombol "Chat" disembunyikan, panel muncul di tempat tombol.
        --   Minimize ( - ) -> panel menutup, tombol "Chat" muncul lagi.
        -- --------------------------------------------------------
        local function placePanelAtPill()
            local c = cornerOf(pill)
            local x, y = clampToScreen(c.X, c.Y, W, H)
            panel.Position = UDim2.fromOffset(x, y)
        end

        local tweenInfo = TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
        local function setOpen(open)
            if S.dead or S.open == open then
                return
            end
            S.open = open
            S.toggleToken += 1
            local token = S.toggleToken

            if open then
                if not S.panelCustom then
                    placePanelAtPill()
                end
                pill.Visible = false
                panel.Visible = true
                TweenService:Create(panel, tweenInfo, { GroupTransparency = 0 }):Play()
                TweenService:Create(panelScale, tweenInfo, { Scale = 1 }):Play()
                S.unread = 0
                S.onlineForce = true
                updateBadge()
                scrollToBottom()
            else
                closeActions()
                local t = TweenService:Create(panel, tweenInfo, { GroupTransparency = 1 })
                TweenService:Create(panelScale, tweenInfo, { Scale = 0.9 }):Play()
                t.Completed:Connect(function()
                    if S.toggleToken == token and not S.open then
                        panel.Visible = false
                    end
                end)
                t:Play()
                pill.Visible = true
                pillScale.Scale = 0.7
                TweenService:Create(pillScale, TweenInfo.new(0.25, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
                    Scale = 1,
                }):Play()
                updateBadge()
            end
        end

        -- Drag tombol "Chat": klik biasa = buka, geser = pindahkan posisi.
        local pillMoved = false
        do
            local DRAG_THRESHOLD = 8
            local dragging, pressed = false, false
            local grab = Vector2.zero -- selisih sudut kanan-bawah tombol dengan pointer
            local pressPos = Vector3.zero
            local function pointerNow(input)
                return Vector2.new(input.Position.X, input.Position.Y)
            end
            track(pill.InputBegan:Connect(function(input)
                if
                    input.UserInputType == Enum.UserInputType.MouseButton1
                    or input.UserInputType == Enum.UserInputType.Touch
                then
                    pressed = true
                    dragging = false
                    pillMoved = false
                    pressPos = input.Position
                    grab = cornerOf(pill) - pointerNow(input)
                    local c
                    c = input.Changed:Connect(function()
                        if input.UserInputState == Enum.UserInputState.End then
                            pressed = false
                            dragging = false
                            if c then
                                c:Disconnect()
                            end
                        end
                    end)
                end
            end))
            track(UserInputService.InputChanged:Connect(function(input)
                if not pressed then
                    return
                end
                if
                    input.UserInputType ~= Enum.UserInputType.MouseMovement
                    and input.UserInputType ~= Enum.UserInputType.Touch
                then
                    return
                end
                if not dragging then
                    if (input.Position - pressPos).Magnitude < DRAG_THRESHOLD then
                        return
                    end
                    dragging = true
                    pillMoved = true
                    grab = cornerOf(pill) - pointerNow(input) -- mulai geser dari posisi sekarang (tanpa lompat)
                end
                local target = pointerNow(input) + grab
                local x, y = clampToScreen(target.X, target.Y, pill.AbsoluteSize.X, pill.AbsoluteSize.Y)
                pill.Position = UDim2.fromOffset(x, y)
                S.panelCustom = false
            end))
            -- jaga tombol tetap di layar kalau ukuran layar berubah
            track(gui:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
                if pill.Position.X.Scale == 0 then
                    local x, y = clampToScreen(
                        pill.Position.X.Offset,
                        pill.Position.Y.Offset,
                        pill.AbsoluteSize.X,
                        pill.AbsoluteSize.Y
                    )
                    pill.Position = UDim2.fromOffset(x, y)
                end
            end))
        end

        track(pill.MouseButton1Click:Connect(function()
            if pillMoved then -- baru selesai di-drag, bukan klik
                pillMoved = false
                return
            end
            setOpen(true)
        end))
        track(minBtn.MouseButton1Click:Connect(function()
            setOpen(false)
        end))

        -- Tombol lonceng: matikan / nyalakan suara notifikasi
        local function setSoundMuted(m, persist)
            S.muted = m
            muteIcon:SetName(m and "mute" or "bell")
            muteIcon:SetColor(m and C.danger or C.muted)
            muteBtn:SetAttribute("base", m and C.danger or C.muted)
            if persist then
                saveSettings()
                if not m then
                    S.lastSound = 0
                    playPing() -- bunyi sekali sebagai tanda suara sudah aktif
                end
            end
        end
        track(muteBtn.MouseButton1Click:Connect(function()
            setSoundMuted(not S.muted, true)
        end))
        setSoundMuted(S.muted, false)

        -- Drag panel lewat header
        do
            local dragging, dragStart, startCorner = false, nil, nil
            track(header.InputBegan:Connect(function(input)
                if
                    input.UserInputType == Enum.UserInputType.MouseButton1
                    or input.UserInputType == Enum.UserInputType.Touch
                then
                    dragging = true
                    dragStart = input.Position
                    startCorner = cornerOf(panel)
                    local c
                    c = input.Changed:Connect(function()
                        if input.UserInputState == Enum.UserInputState.End then
                            dragging = false
                            if c then
                                c:Disconnect()
                            end
                        end
                    end)
                end
            end))
            track(UserInputService.InputChanged:Connect(function(input)
                if
                    dragging
                    and (
                        input.UserInputType == Enum.UserInputType.MouseMovement
                        or input.UserInputType == Enum.UserInputType.Touch
                    )
                then
                    local d = input.Position - dragStart
                    local x, y = clampToScreen(startCorner.X + d.X, startCorner.Y + d.Y, W, H)
                    panel.Position = UDim2.fromOffset(x, y)
                    S.panelCustom = true
                end
            end))
        end

        -- Kirim pesan
        local function trySend()
            if S.sending or S.dead then
                return
            end
            local text = cleanText(box.Text, MAX_LEN)
            if text == "" then
                return
            end

            -- Command rahasia: /admin <username>  dan  /unadmin <username>
            -- Selalu ditelan secara lokal -> TIDAK dikirim ke chat, jadi tidak terlihat siapa pun.
            local cmd, rest = text:match("^/(%a+)%s*(.*)$")
            cmd = cmd and cmd:lower() or nil

            -- [ADMIN ABUSE] /add mode admin abuse  |  /remove mode admin abuse   (khusus admin)
            -- Command ditelan lokal (tidak dikirim ke chat). Membuka / menutup opsi "Admin Abuse" di
            -- Steal Mode untuk SEMUA user lewat Firebase, dan saat dibuka otomatis kirim announcement.
            if cmd == "add" or cmd == "remove" then
                local sub = tostring(rest or ""):lower():gsub("%s+", " ")
                sub = sub:match("^%s*(.-)%s*$") or sub
                if sub == "mode admin abuse" then
                    box.Text = ""
                    if S.sending then
                        return
                    end
                    S.sending = true
                    task.spawn(function()
                        local isAdm = ADM.isAdmin(LocalPlayer.Name)
                        if not isAdm then
                            -- daftar admin lokal bisa telat sinkron: cek ulang ke database sekali
                            local okF, set = pcall(ADM.fetch)
                            if okF and set then
                                S.admins = set
                                isAdm = ADM.isAdmin(LocalPlayer.Name)
                            end
                        end
                        local gAA = typeof(getgenv) == "function" and getgenv() or _G
                        local AA = gAA.FK_AdminAbuse
                        if not isAdm then
                            addSystem("Command ini khusus admin. Jadikan akun admin dulu: /admin username")
                        elseif type(AA) ~= "table" or type(AA.Post) ~= "function" then
                            addSystem("Fitur Admin Abuse belum siap. Coba lagi sebentar.")
                        else
                            local turnOn = cmd == "add"
                            local okP, res = pcall(AA.Post, turnOn, LocalPlayer.Name, "all", true)
                            if okP and res then
                                addSystem(
                                    turnOn and "Mode Admin Abuse DIBUKA untuk semua user (announcement terkirim)."
                                        or "Mode Admin Abuse DITUTUP."
                                )
                            else
                                addSystem("Gagal mengubah mode Admin Abuse. Pastikan Firebase rules mengizinkan /feature_flags dan /announcement.")
                            end
                        end
                        S.sending = false
                    end)
                    return
                end
            end
            if cmd == "admin" or cmd == "unadmin" then
                box.Text = ""
                local uname = tostring(rest or ""):match("^@?([%w_]+)")
                if not uname then
                    addSystem("Format: /" .. cmd .. " username")
                    return
                end
                if S.sending then
                    return
                end
                S.sending = true
                task.spawn(function()
                    local on = cmd == "admin"
                    if ADM.set(uname, on) then
                        local k = ADM.key(uname)
                        S.admins[k] = on and true or nil
                        pcall(refreshAdminBtn)
                        for _, fnR in pairs(S.renderers) do
                            pcall(fnR)
                        end
                        addSystem(on and (uname .. " sekarang ADMIN.") or (uname .. " bukan admin lagi."))
                    else
                        addSystem("Gagal mengatur admin. Pastikan Firebase rules mengizinkan /chat_admins.")
                    end
                    S.sending = false
                end)
                return
            end

            local remain = SEND_COOLDOWN - (os.clock() - S.lastSend)
            if remain > 0 then
                return
            end

            S.sending = true
            S.lastSend = os.clock()
            box.Text = ""

            task.spawn(function()
                local key = postMessage(text)
                if key then
                    addMessage({
                        key = key,
                        uid = LocalPlayer.UserId,
                        name = LocalPlayer.Name,
                        display = LocalPlayer.DisplayName,
                        text = text,
                        ts = nil,
                    }, false)
                    scrollToBottom()
                else
                    box.Text = text
                    addSystem("Gagal mengirim. Cek koneksi atau Firebase rules.")
                end
                S.sending = false
            end)
        end

        track(sendBtn.MouseButton1Click:Connect(trySend))
        track(box.FocusLost:Connect(function(enterPressed)
            if enterPressed then
                trySend()
                if not UserInputService.TouchEnabled then
                    task.defer(function()
                        if box and box.Parent and not S.dead and S.open then
                            box:CaptureFocus()
                        end
                    end)
                end
            end
        end))

        -- --------------------------------------------------------
        -- Loop polling pesan
        -- --------------------------------------------------------
        task.spawn(function()
            pcall(presenceBeat) -- sinkronkan jam server dulu (dipakai untuk reset 10 menit)
            local fails = 0
            while not S.dead do
                local msgs, err
                if not S.loaded then
                    -- User baru: jangan tampilkan chat lama, mulai dari pesan terbaru saat ini
                    local base
                    base, err = fetchBaseline()
                    if base then
                        S.lastKey = base ~= "" and base or nil
                        S.loaded = true
                        addSystem("Terhubung ke chat global.")
                        msgs = {}
                    end
                else
                    msgs, err = fetchMessages()
                end
                if msgs then
                    fails = 0
                    local stick = isNearBottom()
                    local added = 0
                    for _, m in ipairs(msgs) do
                        if addMessage(m, true) then
                            added += 1
                        end
                    end
                    if #msgs > 0 then
                        S.lastKey = msgs[#msgs].key
                    end
                    if added > 0 and stick then
                        scrollToBottom()
                    end
                else
                    fails += 1
                    if fails == 3 then
                        addSystem("Chat tidak bisa dimuat (" .. tostring(err) .. "). Cek Firebase rules /global_chat.")
                    end
                end
                local interval = S.open and POLL_OPEN or POLL_MINIMIZED
                if fails > 0 then
                    interval = math.min(2 + fails, 10)
                end
                task.wait(interval)
            end
        end)

        -- Reset otomatis tiap 10 menit (jendela waktu berbasis jam server, jadi semua user serempak)
        task.spawn(function()
            local t0 = os.clock()
            while not S.serverNow and not S.dead and os.clock() - t0 < 8 do
                task.wait(0.25)
            end
            local curWin = math.floor(S.serverNowMs() / WIPE_MS)
            task.spawn(function()
                pcall(purgeExpired) -- bersihkan sisa pesan lama di database
            end)
            while not S.dead do
                task.wait(1)
                local win = math.floor(S.serverNowMs() / WIPE_MS)
                if win ~= curWin then
                    curWin = win
                    clearAllRows()
                    addSystem("Chat dibersihkan otomatis (tiap 10 menit).")
                    task.spawn(function()
                        task.wait(math.random() * 4) -- acak supaya tidak semua user menghapus bersamaan
                        pcall(purgeExpired)
                    end)
                end
                if S.open then
                    refreshTitle()
                end
            end
        end)

        -- Sinkron daftar admin (nick emas + mahkota terlihat oleh semua user)
        task.spawn(function()
            task.wait(1)
            while not S.dead do
                local okA, set = pcall(ADM.fetch)
                if okA and set then
                    local changed = false
                    for k in pairs(set) do
                        if not S.admins[k] then
                            changed = true
                        end
                    end
                    for k in pairs(S.admins) do
                        if not set[k] then
                            changed = true
                        end
                    end
                    S.admins = set
                    pcall(refreshAdminBtn)
                    if changed then
                        for _, fnR in pairs(S.renderers) do
                            pcall(fnR)
                        end
                    end
                end
                task.wait(S.open and 8 or 20)
            end
        end)

        -- Sinkron pesan yang dihapus
        task.spawn(function()
            task.wait(4)
            while not S.dead do
                if S.loaded then
                    pcall(reconcileDeletes)
                end
                task.wait(S.open and RECONCILE_OPEN or RECONCILE_MIN)
            end
        end)

        -- --------------------------------------------------------
        -- Presence heartbeat + hitung online (hitung hanya saat panel terbuka)
        -- --------------------------------------------------------
        task.spawn(function()
            while not S.dead do
                pcall(presenceBeat)
                task.wait(PRESENCE_BEAT)
            end
        end)

        task.spawn(function()
            task.wait(1.5)
            local last = 0
            while not S.dead do
                if S.open then
                    local every = onlineView.Visible and 8 or ONLINE_REFRESH
                    if S.onlineForce or os.clock() - last >= every then
                        S.onlineForce = false
                        last = os.clock()
                        local okC, list = pcall(fetchOnline)
                        if okC and list then
                            S.onlineList = list
                            setOnline(#list)
                            refreshOnlineView()
                        end
                    end
                end
                task.wait(1)
            end
        end)

        -- --------------------------------------------------------
        -- Cleanup + API publik
        -- --------------------------------------------------------
        local api
        local function cleanup()
            if S.dead then
                return
            end
            S.dead = true
            pcall(function()
                httpRequest({
                    Url = presenceUrl(),
                    Method = "DELETE",
                    Headers = { ["Accept"] = "application/json" },
                })
            end)
            for _, c in ipairs(conns) do
                pcall(function()
                    c:Disconnect()
                end)
            end
            pcall(function()
                gui:Destroy()
            end)
            if genv.FanKunChat == api then
                genv.FanKunChat = nil
            end
        end

        api = {
            Open = function()
                setOpen(true)
            end,
            Close = function()
                setOpen(false)
            end,
            Toggle = function()
                setOpen(not S.open)
            end,
            Mute = function(m)
                setSoundMuted(m ~= false, true)
            end,
            Block = function(uid, name)
                blockUser(tonumber(uid), name)
            end,
            Unblock = function(uid)
                unblockUser(uid)
            end,
            Destroy = cleanup,
        }
        genv.FanKunChat_Cleanup = cleanup
        genv.FanKunChat = api
    end)

    if not okChat then
        warn("[FanKun Chat] gagal dimuat: " .. tostring(errChat))
    end
end

-- ============================================================
-- NEBULA HUB UI (WindUI) - ADAPTER
-- UI native bergaya UI_LOGINKEY (tanpa WindUI / library luar).
-- API yang dipakai logic TIDAK berubah:
--   Lib:CreateWindow / Lib:Finalize / Lib.Notify / Lib.ManualQuickDefaults
--   window:CreateTab / GetDefaultTab / CreateState / _selectTab / _tabs
--   tab:CreateSection
--   section:CreateToggle / CreateDropdown / CreateMultiDropdown /
--           CreateSlider / CreateText / CreateButton
-- Semua logic di bawah blok ini dibiarkan apa adanya.
-- ============================================================
do
    local Players = game:GetService("Players")
    local RunService = game:GetService("RunService")
    local genvN = typeof(getgenv) == "function" and getgenv() or _G

    -- Bersihkan UI Nebula lama bila script di-execute ulang
    if type(genvN.FanKunNebula_Cleanup) == "function" then
        pcall(genvN.FanKunNebula_Cleanup)
    end

    -- ============================================================
    -- NATIVE UI (gaya UI_LOGINKEY) - pengganti WindUI
    -- Tanpa loadstring/HttpGet library luar. API dibuat kompatibel dengan yang dipakai adapter:
    --   :CreateWindow / :Notify / :AddTheme / .Creator.Icon
    --   Window: :Tab :Tag :Destroy      Tab: :Select :Section :Paragraph :Button
    --                                         :Toggle :Dropdown :Slider :Input :Divider :Space
    -- ============================================================
    local WindUI = (function()
        local TweenService = game:GetService("TweenService")
        local UserInputService = game:GetService("UserInputService")
        local RunService = game:GetService("RunService")
        local CoreGui = game:GetService("CoreGui")
        local LP = Players.LocalPlayer

        local WHITE = Color3.new(1, 1, 1)
        local C = {
            bg = Color3.fromRGB(255, 255, 255),
            panel = Color3.fromRGB(240, 240, 242),
            panel2 = Color3.fromRGB(246, 246, 247),
            field = Color3.fromRGB(234, 234, 237),
            stroke = Color3.fromRGB(215, 215, 220),
            text = Color3.fromRGB(12, 12, 12),
            sub = Color3.fromRGB(107, 107, 114),
            accent = Color3.fromRGB(17, 17, 17),
            accentDim = Color3.fromRGB(160, 160, 166),
            green = Color3.fromRGB(30, 150, 90),
            red = Color3.fromRGB(210, 50, 50),
        }

        -- ---------- Suara klik UI (ganti ID di bawah kalau mau suara lain) ----------
        local UI_CLICK_SOUND_ID = "rbxassetid://6895079853"
        local UI_CLICK_VOLUME = 0.6
        local uiClickSnd
        do
            pcall(function()
                local SoundService = game:GetService("SoundService")
                local old = SoundService:FindFirstChild("WS_UIClick")
                if old then
                    old:Destroy()
                end
                uiClickSnd = Instance.new("Sound")
                uiClickSnd.Name = "WS_UIClick"
                uiClickSnd.SoundId = UI_CLICK_SOUND_ID
                uiClickSnd.Volume = UI_CLICK_VOLUME
                uiClickSnd.Parent = SoundService
            end)
        end
        local function playClick()
            if uiClickSnd then
                pcall(function()
                    uiClickSnd.TimePosition = 0
                    uiClickSnd:Play()
                end)
            end
        end

        local function New(class, props, parent)
            local o = Instance.new(class)
            for k, val in pairs(props or {}) do
                o[k] = val
            end
            if parent then
                o.Parent = parent
            end
            -- semua tombol (tab, toggle, button, dropdown, dll) otomatis bunyi saat diklik
            if
                (class == "TextButton" or class == "ImageButton")
                and not (props and (props.Name == "ResizeGrip" or props.Name == "FabButton"))
            then
                o.MouseButton1Click:Connect(playClick)
            end
            return o
        end
        local function Round(o, r)
            return New("UICorner", { CornerRadius = UDim.new(0, r or 10) }, o)
        end
        local function Circle(o)
            return New("UICorner", { CornerRadius = UDim.new(1, 0) }, o)
        end
        local function Stroke(o, color, thick, trans)
            return New("UIStroke", {
                Color = color or C.stroke,
                Thickness = thick or 1,
                Transparency = trans or 0,
                ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
            }, o)
        end
        local function Tween(o, t, props, style, dir)
            local tw = TweenService:Create(
                o,
                TweenInfo.new(t, style or Enum.EasingStyle.Quad, dir or Enum.EasingDirection.Out),
                props
            )
            tw:Play()
            return tw
        end
        local function KP(t, c)
            return ColorSequenceKeypoint.new(t, c)
        end
        local function List(parent, pad, dir, order)
            return New("UIListLayout", {
                Padding = UDim.new(0, pad or 0),
                FillDirection = dir or Enum.FillDirection.Vertical,
                SortOrder = order or Enum.SortOrder.LayoutOrder,
            }, parent)
        end
        local function Pad(parent, l, r, t, b)
            return New("UIPadding", {
                PaddingLeft = UDim.new(0, l or 0),
                PaddingRight = UDim.new(0, r or 0),
                PaddingTop = UDim.new(0, t or 0),
                PaddingBottom = UDim.new(0, b or 0),
            }, parent)
        end
        local function safe(f, ...)
            if type(f) == "function" then
                return pcall(f, ...)
            end
            return false
        end
        local function copyList(t)
            local out = {}
            if type(t) == "table" then
                for i, x in ipairs(t) do
                    out[i] = x
                end
            end
            return out
        end
        local function guiParent()
            if typeof(gethui) == "function" then
                local ok, h = pcall(gethui)
                if ok and typeof(h) == "Instance" then
                    return h
                end
            end
            return CoreGui
        end
        local function protect(gui)
            pcall(function()
                if syn and syn.protect_gui then
                    syn.protect_gui(gui)
                end
            end)
        end

        -- ---------------- Icon Font Awesome (PNG putih, di-cache) ----------------
        local ICON_DIR = "fankun_icons"
        local ICON_SOURCES = {
            "https://raw.githubusercontent.com/encharm/Font-Awesome-SVG-PNG/master/white/png/128/",
            "https://cdn.jsdelivr.net/gh/encharm/Font-Awesome-SVG-PNG@master/white/png/128/",
        }
        local getAsset = getcustomasset or getsynasset
        local assetCache, assetFail = {}, {}

        local ICON_MAP = {
            ["zap"] = "bolt", ["hand"] = "hand-paper-o", ["clock"] = "clock-o", ["bug"] = "bug",
            ["sparkles"] = "magic", ["eye"] = "eye", ["user"] = "user", ["server"] = "server",
            ["users"] = "users", ["sun"] = "sun-o", ["package"] = "cube", ["box"] = "cube",
            ["egg"] = "circle-o", ["coins"] = "money", ["badge-dollar-sign"] = "money",
            ["dollar-sign"] = "money", ["paw-print"] = "paw", ["dog"] = "paw", ["star"] = "star",
            ["heart"] = "heart", ["trending-up"] = "line-chart", ["chart-line"] = "line-chart",
            ["arrow-up"] = "arrow-up", ["battery-charging"] = "bolt", ["palette"] = "paint-brush",
            ["refresh-cw"] = "refresh", ["chart-column"] = "bar-chart", ["chart-bar"] = "bar-chart",
            ["bar-chart-3"] = "bar-chart", ["activity"] = "line-chart",
            ["solar:chart-2-bold"] = "bar-chart", ["solar:graph-up-bold"] = "line-chart",
            ["solar:wallet-money-bold"] = "money", ["solar:star-bold"] = "star",
            ["solar:box-bold"] = "cube", ["solar:stars-bold"] = "cog", ["solar:user-bold"] = "user",
            ["solar:stars-bold-duotone"] = "cog",
        }

        local function getIconAsset(name)
            if assetCache[name] then
                return assetCache[name]
            end
            if assetFail[name] then
                return nil
            end
            if not (getAsset and writefile and isfile) then
                return nil
            end
            pcall(function()
                if makefolder and isfolder and not isfolder(ICON_DIR) then
                    makefolder(ICON_DIR)
                end
            end)
            local path = ICON_DIR .. "/" .. name .. "_128.png"
            if not isfile(path) then
                for _, base in ipairs(ICON_SOURCES) do
                    local ok, data = pcall(function()
                        return game:HttpGet(base .. name .. ".png")
                    end)
                    if ok and type(data) == "string" and #data > 100 and data:sub(2, 4) == "PNG" then
                        pcall(writefile, path, data)
                        break
                    end
                end
            end
            if isfile(path) then
                local ok, asset = pcall(getAsset, path)
                if ok and asset then
                    assetCache[name] = asset
                    return asset
                end
            end
            assetFail[name] = true
            return nil
        end

        local function SetIcon(img, name, color, cb)
            if color then
                img.ImageColor3 = color
            end
            if type(name) ~= "string" or name == "" then
                return
            end
            if name:find("^rbxassetid://") or name:find("^rbxthumb://") then
                img.Image = name
                img.Visible = true
                if cb then
                    cb()
                end
                return
            end
            name = ICON_MAP[name] or name
            img:SetAttribute("want", name)
            local cached = assetCache[name]
            if cached then
                img.Image = cached
                img.Visible = true
                if cb then
                    cb()
                end
                return
            end
            task.spawn(function()
                local asset = getIconAsset(name)
                if asset and img.Parent and img:GetAttribute("want") == name then
                    img.Image = asset
                    img.Visible = true
                    if cb then
                        cb()
                    end
                end
            end)
        end

        local function NewIcon(parent, name, size, tint, props, cb)
            local icon = New("ImageLabel", {
                BackgroundTransparency = 1,
                Size = UDim2.fromOffset(size, size),
                ScaleType = Enum.ScaleType.Fit,
                ImageColor3 = tint or WHITE,
                Visible = false,
            }, parent)
            for k, val in pairs(props or {}) do
                icon[k] = val
            end
            SetIcon(icon, name, tint, cb)
            return icon
        end

        -- overlay hover (tanpa scale supaya aman di dalam list)
        local function Hover(host, radius)
            local overlay = New("Frame", {
                Size = UDim2.fromScale(1, 1),
                BackgroundColor3 = Color3.new(0, 0, 0),
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                ZIndex = 2,
            }, host)
            Round(overlay, radius or 10)
            return overlay
        end
        local function HoverBind(btn, overlay)
            btn.MouseEnter:Connect(function()
                Tween(overlay, 0.15, { BackgroundTransparency = 0.93 })
            end)
            btn.MouseLeave:Connect(function()
                Tween(overlay, 0.15, { BackgroundTransparency = 1 })
            end)
            btn.MouseButton1Down:Connect(function()
                Tween(overlay, 0.08, { BackgroundTransparency = 0.86 })
            end)
            btn.MouseButton1Up:Connect(function()
                Tween(overlay, 0.12, { BackgroundTransparency = 0.93 })
            end)
        end

        local Lib = {}
        Lib.Creator = {
            Icon = function()
                return true
            end,
        }
        function Lib:AddTheme() end

        -- ---------------- Notifikasi (toast) ----------------
        local notifyGui, notifyHolder
        local function ensureNotify()
            if notifyGui and notifyGui.Parent then
                return
            end
            local parent = guiParent()
            local old = parent:FindFirstChild("FanKunHUB_Notify")
            if old then
                old:Destroy()
            end
            notifyGui = New("ScreenGui", {
                Name = "FanKunHUB_Notify",
                ResetOnSpawn = false,
                DisplayOrder = 110,
                IgnoreGuiInset = true,
                ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
            })
            protect(notifyGui)
            notifyGui.Parent = parent
            notifyHolder = New("Frame", {
                AnchorPoint = Vector2.new(1, 1),
                Position = UDim2.new(1, -12, 1, -12),
                Size = UDim2.new(0, 270, 1, -24),
                BackgroundTransparency = 1,
            }, notifyGui)
            New("UIListLayout", {
                Padding = UDim.new(0, 6),
                SortOrder = Enum.SortOrder.LayoutOrder,
                VerticalAlignment = Enum.VerticalAlignment.Bottom,
            }, notifyHolder)
        end

        local notifyOrder = 0
        function Lib:Notify(o)
            o = o or {}
            pcall(function()
                ensureNotify()
                notifyOrder += 1
                local card = New("CanvasGroup", {
                    Size = UDim2.new(1, 0, 0, 0),
                    AutomaticSize = Enum.AutomaticSize.Y,
                    BackgroundColor3 = C.panel,
                    BorderSizePixel = 0,
                    GroupTransparency = 1,
                    LayoutOrder = notifyOrder,
                }, notifyHolder)
                New("UISizeConstraint", { MinSize = Vector2.new(0, 50) }, card)
                Round(card, 10)
                Stroke(card, C.stroke, 1, 0.1)
                New("Frame", {
                    Size = UDim2.new(0, 3, 1, 0),
                    BackgroundColor3 = C.accent,
                    BorderSizePixel = 0,
                }, card)
                local body = New("Frame", {
                    Size = UDim2.new(1, 0, 0, 0),
                    AutomaticSize = Enum.AutomaticSize.Y,
                    BackgroundTransparency = 1,
                }, card)
                Pad(body, 54, 12, 10, 10)
                List(body, 2)
                local nLogo = New("ImageLabel", {
                    Position = UDim2.fromOffset(14, 10),
                    Size = UDim2.fromOffset(30, 30),
                    BackgroundColor3 = C.bg,
                    BorderSizePixel = 0,
                    Image = "rbxassetid://96012031195817",
                    ScaleType = Enum.ScaleType.Fit,
                    ZIndex = 5,
                }, card)
                Round(nLogo, 100)
                Stroke(nLogo, Color3.fromRGB(0, 0, 0), 2, 0)
                New("TextLabel", {
                    Size = UDim2.new(1, 0, 0, 0),
                    AutomaticSize = Enum.AutomaticSize.Y,
                    BackgroundTransparency = 1,
                    Text = tostring(o.Title or "Notify"),
                    Font = Enum.Font.GothamBold,
                    TextSize = 14,
                    TextColor3 = C.text,
                    TextWrapped = true,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    LayoutOrder = 1,
                }, body)
                if o.Content and tostring(o.Content) ~= "" then
                    New("TextLabel", {
                        Size = UDim2.new(1, 0, 0, 0),
                        AutomaticSize = Enum.AutomaticSize.Y,
                        BackgroundTransparency = 1,
                        Text = tostring(o.Content),
                        Font = Enum.Font.GothamMedium,
                        TextSize = 12,
                        TextColor3 = C.sub,
                        TextWrapped = true,
                        TextXAlignment = Enum.TextXAlignment.Left,
                        LayoutOrder = 2,
                    }, body)
                end
                Tween(card, 0.25, { GroupTransparency = 0 })
                task.delay(tonumber(o.Duration) or 3, function()
                    if card.Parent then
                        Tween(card, 0.3, { GroupTransparency = 1 })
                        task.wait(0.32)
                        if card.Parent then
                            card:Destroy()
                        end
                    end
                end)
            end)
        end

        -- ---------------- Kartu elemen ----------------
        -- card (Frame, auto tinggi)
        --   Stack (UIListLayout) -> Row [textHolder, controlHolder, click], extra...
        --   overlay hover
        local function makeCard(page, o, ctrlW, full)
            local slotParent, slotOrder = page:_slot(full)
            local card = New("Frame", {
                Size = UDim2.new(1, 0, 0, 0),
                AutomaticSize = Enum.AutomaticSize.Y,
                BackgroundColor3 = C.panel2,
                BorderSizePixel = 0,
                LayoutOrder = slotOrder,
            }, slotParent)
            card:SetAttribute("est", (o.Desc ~= nil and tostring(o.Desc) ~= "") and 44 or 32)
            Round(card, 10)
            local cardStroke = Stroke(card, C.stroke, 1, 0)

            local stack = New("Frame", {
                Name = "Stack",
                Size = UDim2.new(1, 0, 0, 0),
                AutomaticSize = Enum.AutomaticSize.Y,
                BackgroundTransparency = 1,
            }, card)
            List(stack, 0)

            local row = New("Frame", {
                Name = "Row",
                Size = UDim2.new(1, 0, 0, 0),
                AutomaticSize = Enum.AutomaticSize.Y,
                BackgroundTransparency = 1,
                LayoutOrder = 1,
            }, stack)
            Pad(row, 14, 14, 8, 8)

            local holder = New("Frame", {
                Size = UDim2.new(1, -((ctrlW or 0) + ((ctrlW or 0) > 0 and 8 or 0)), 0, 0),
                AutomaticSize = Enum.AutomaticSize.Y,
                BackgroundTransparency = 1,
            }, row)
            New("UISizeConstraint", { MinSize = Vector2.new(0, 24) }, holder)
            List(holder, 3)

            local title = New("TextLabel", {
                Size = UDim2.new(1, 0, 0, 0),
                AutomaticSize = Enum.AutomaticSize.Y,
                BackgroundTransparency = 1,
                Text = tostring(o.Title or ""),
                Font = Enum.Font.GothamBold,
                TextSize = 15,
                TextColor3 = C.text,
                TextWrapped = true,
                TextXAlignment = Enum.TextXAlignment.Left,
                TextYAlignment = Enum.TextYAlignment.Center,
                LayoutOrder = 1,
            }, holder)
            local desc = New("TextLabel", {
                Size = UDim2.new(1, 0, 0, 0),
                AutomaticSize = Enum.AutomaticSize.Y,
                BackgroundTransparency = 1,
                Text = tostring(o.Desc or ""),
                Font = Enum.Font.GothamMedium,
                TextSize = 12,
                TextColor3 = C.sub,
                TextWrapped = true,
                TextXAlignment = Enum.TextXAlignment.Left,
                Visible = o.Desc ~= nil and tostring(o.Desc) ~= "",
                LayoutOrder = 2,
            }, holder)

            local ctrl
            if (ctrlW or 0) > 0 then
                ctrl = New("Frame", {
                    AnchorPoint = Vector2.new(1, 0),
                    Position = UDim2.new(1, 0, 0, 0),
                    Size = UDim2.new(0, ctrlW, 1, 0),
                    BackgroundTransparency = 1,
                }, row)
            end

            local api = {
                ElementFrame = card,
                Frame = card,
                UIElements = { Container = card, Main = card },
                _card = card,
                _stroke = cardStroke,
                _stack = stack,
                _row = row,
                _title = title,
                _desc = desc,
            }
            function api:SetTitle(t)
                title.Text = tostring(t)
            end
            function api:SetDesc(t)
                t = tostring(t or "")
                desc.Text = t
                desc.Visible = t ~= ""
            end
            function api:Destroy()
                if card.Parent then
                    card:Destroy()
                end
            end
            function api:SetVisible(v)
                card.Visible = v ~= false
            end
            return api, ctrl
        end

        -- tombol klik transparan yang menutupi Row (termasuk padding)
        local function rowClick(row)
            return New("TextButton", {
                Text = "",
                AutoButtonColor = false,
                BackgroundTransparency = 1,
                Position = UDim2.new(0, -14, 0, -8),
                Size = UDim2.new(1, 28, 1, 16),
                ZIndex = 5,
            }, row)
        end

        local function chevron(parent)
            local fb = New("TextLabel", {
                AnchorPoint = Vector2.new(1, 0.5),
                Position = UDim2.new(1, -8, 0.5, 0),
                Size = UDim2.fromOffset(12, 12),
                BackgroundTransparency = 1,
                Text = "v",
                Font = Enum.Font.GothamBold,
                TextSize = 11,
                TextColor3 = C.sub,
            }, parent)
            NewIcon(parent, "chevron-down", 12, C.sub, {
                AnchorPoint = Vector2.new(1, 0.5),
                Position = UDim2.new(1, -8, 0.5, 0),
            }, function()
                fb.Visible = false
            end)
        end

        -- ---------------- Ikon header digambar sendiri (tanpa font, tidak pernah jadi kotak) ----------------
        local function DrawIcon(parent, kind, color, order)
            local holder = New("Frame", {
                Size = UDim2.fromOffset(14, 14),
                BackgroundTransparency = 1,
                LayoutOrder = order or 0,
            }, parent)
            local recolor = {}
            local function bar(x, y, w, h, r)
                local f = New("Frame", {
                    Position = UDim2.fromOffset(x, y),
                    Size = UDim2.fromOffset(w, h),
                    BackgroundColor3 = color,
                    BorderSizePixel = 0,
                }, holder)
                New("UICorner", { CornerRadius = UDim.new(0, r or 1) }, f)
                recolor[#recolor + 1] = function(c)
                    f.BackgroundColor3 = c
                end
                return f
            end
            if kind == "gauge" then
                -- speedometer: lingkaran + jarum + titik tengah
                local ring = New("Frame", {
                    AnchorPoint = Vector2.new(0.5, 0.5),
                    Position = UDim2.fromScale(0.5, 0.5),
                    Size = UDim2.fromOffset(13, 13),
                    BackgroundTransparency = 1,
                }, holder)
                New("UICorner", { CornerRadius = UDim.new(1, 0) }, ring)
                local rs = Stroke(ring, color, 1.5, 0)
                recolor[#recolor + 1] = function(c)
                    rs.Color = c
                end
                local pivot = New("Frame", {
                    AnchorPoint = Vector2.new(0.5, 0.5),
                    Position = UDim2.fromScale(0.5, 0.5),
                    Size = UDim2.fromOffset(2, 10),
                    BackgroundTransparency = 1,
                    Rotation = 38,
                }, holder)
                local needle = New("Frame", {
                    Size = UDim2.fromOffset(2, 5),
                    BackgroundColor3 = color,
                    BorderSizePixel = 0,
                }, pivot)
                recolor[#recolor + 1] = function(c)
                    needle.BackgroundColor3 = c
                end
                local dot = New("Frame", {
                    AnchorPoint = Vector2.new(0.5, 0.5),
                    Position = UDim2.fromScale(0.5, 0.5),
                    Size = UDim2.fromOffset(4, 4),
                    BackgroundColor3 = color,
                    BorderSizePixel = 0,
                }, holder)
                New("UICorner", { CornerRadius = UDim.new(1, 0) }, dot)
                recolor[#recolor + 1] = function(c)
                    dot.BackgroundColor3 = c
                end
            else
                -- sinyal / ping: 4 batang naik
                bar(0, 9, 2.5, 4, 1)
                bar(3.5, 6, 2.5, 7, 1)
                bar(7, 3, 2.5, 10, 1)
                bar(10.5, 0, 2.5, 13, 1)
            end
            local api = { Holder = holder }
            function api:SetColor(c)
                for _, fnC in ipairs(recolor) do
                    fnC(c)
                end
            end
            return api
        end

        -- ---------------- Window ----------------
        function Lib:CreateWindow(cfg)
            cfg = cfg or {}
            local parent = guiParent()
            local oldGui = parent:FindFirstChild("FanKunHUB_Main")
            if oldGui then
                oldGui:Destroy()
            end

            local Gui = New("ScreenGui", {
                Name = "FanKunHUB_Main",
                ResetOnSpawn = false,
                DisplayOrder = 100,
                ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
            })
            protect(Gui)
            Gui.Parent = parent
            ensureNotify()

            local conns = {}
            local function track(c)
                conns[#conns + 1] = c
                return c
            end
            Gui.Destroying:Connect(function()
                for _, c in ipairs(conns) do
                    pcall(function()
                        c:Disconnect()
                    end)
                end
                conns = {}
            end)

            local W, H = 720, 270
            local HEADER_H, SIDE_W = 48, 132
            local PAGE_Y, FOOTER_H = HEADER_H + 2, 26
            local vp = workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize or Vector2.new(1280, 720)
            local baseScale = math.min(1, (vp.X - 20) / W, (vp.Y - 20) / H)

            local Main = New("Frame", {
                Name = "Main",
                AnchorPoint = Vector2.new(0.5, 0.5),
                Position = UDim2.new(0.5, 0, 0.5, 0),
                Size = UDim2.fromOffset(W, H),
                BackgroundColor3 = C.bg,
                BorderSizePixel = 0,
            }, Gui)
            Round(Main, 16)
            Stroke(Main, C.stroke, 1, 0)
            local MainScale = New("UIScale", { Scale = baseScale * 0.9 }, Main)

            -- Header (minimalis: hanya tombol  -  )
            local Header = New("Frame", { Size = UDim2.new(1, 0, 0, HEADER_H), BackgroundTransparency = 1 }, Main)
            local logoImg = type(cfg.Icon) == "string" and cfg.Icon:find("^rbxassetid://") and cfg.Icon
                or "rbxassetid://96012031195817"
            local logoSmall = New("ImageLabel", {
                Position = UDim2.fromOffset(14, 10),
                Size = UDim2.fromOffset(28, 28),
                BackgroundTransparency = 1,
                Image = logoImg,
                ScaleType = Enum.ScaleType.Fit,
            }, Header)
            Round(logoSmall, 100)
            Stroke(logoSmall, Color3.fromRGB(0, 0, 0), 2, 0)
            local HOME_TITLE = "White<font color='#6e6e6e'>SCRIPT</font>"
            local TitleLbl = New("TextLabel", {
                Position = UDim2.fromOffset(52, 7),
                Size = UDim2.fromOffset(170, 19),
                BackgroundTransparency = 1,
                Text = HOME_TITLE,
                RichText = true,
                Font = Enum.Font.GothamBlack,
                TextSize = 17,
                TextColor3 = C.text,
                TextXAlignment = Enum.TextXAlignment.Left,
            }, Header)
            New("TextLabel", {
                Position = UDim2.fromOffset(52, 28),
                Size = UDim2.fromOffset(160, 12),
                BackgroundTransparency = 1,
                Text = string.upper((tostring(cfg.Author or "Premium"):gsub("^WhiteSCRIPT%s*/%s*", ""))),
                Font = Enum.Font.GothamBold,
                TextSize = 9,
                TextColor3 = C.sub,
                TextXAlignment = Enum.TextXAlignment.Left,
                TextTruncate = Enum.TextTruncate.AtEnd,
            }, Header)

            local function headerBtn(xOff, iconName, fallback, hoverColor)
                local b = New("TextButton", {
                    AnchorPoint = Vector2.new(1, 0.5),
                    Position = UDim2.new(1, xOff, 0.5, 0),
                    Size = UDim2.fromOffset(28, 26),
                    BackgroundColor3 = hoverColor,
                    BackgroundTransparency = 1,
                    Text = fallback,
                    Font = Enum.Font.GothamBold,
                    TextSize = 16,
                    TextColor3 = C.sub,
                    AutoButtonColor = false,
                }, Header)
                Round(b, 6)
                b.MouseEnter:Connect(function()
                    Tween(b, 0.12, { BackgroundTransparency = 0 })
                    b.TextColor3 = C.text
                end)
                b.MouseLeave:Connect(function()
                    Tween(b, 0.12, { BackgroundTransparency = 1 })
                    b.TextColor3 = C.sub
                end)
                return b
            end
            local MinBtn = headerBtn(-8, nil, "-", C.stroke)

            -- Tombol kembali "<" (muncul saat membuka isi tab)
            local BackBtn = New("TextButton", {
                Position = UDim2.fromOffset(10, 11),
                Size = UDim2.fromOffset(30, 26),
                BackgroundColor3 = C.field,
                BackgroundTransparency = 0,
                Text = "<",
                Font = Enum.Font.GothamBold,
                TextSize = 16,
                TextColor3 = C.text,
                AutoButtonColor = false,
                Visible = false,
                ZIndex = 5,
            }, Header)
            Round(BackBtn, 8)

            local TagHolder = New("Frame", {
                AnchorPoint = Vector2.new(1, 0.5),
                Position = UDim2.new(1, -46, 0.5, 0),
                Size = UDim2.new(0, 0, 0, 22),
                AutomaticSize = Enum.AutomaticSize.X,
                BackgroundTransparency = 1,
            }, Header)
            New("UIListLayout", {
                FillDirection = Enum.FillDirection.Horizontal,
                HorizontalAlignment = Enum.HorizontalAlignment.Right,
                VerticalAlignment = Enum.VerticalAlignment.Center,
                Padding = UDim.new(0, 6),
                SortOrder = Enum.SortOrder.LayoutOrder,
            }, TagHolder)

            -- ---------- Discord: logo digambar sendiri (tanpa font, tidak jadi kotak) ----------
            local DC = Color3.fromRGB(88, 101, 242)
            local function drawDiscord(parent, k, color, cut)
                local holder = New("Frame", {
                    AnchorPoint = Vector2.new(0.5, 0.5),
                    Position = UDim2.fromScale(0.5, 0.5),
                    Size = UDim2.fromOffset(math.floor(20 * k), math.floor(16 * k)),
                    BackgroundTransparency = 1,
                }, parent)
                local parts = {}
                local function box(x, y, w, h, r, col)
                    local f = New("Frame", {
                        Position = UDim2.fromOffset(x * k, y * k),
                        Size = UDim2.fromOffset(w * k, h * k),
                        BackgroundColor3 = col,
                        BorderSizePixel = 0,
                    }, holder)
                    New("UICorner", { CornerRadius = UDim.new(0, math.floor(r * k)) }, f)
                    return f
                end
                parts[#parts + 1] = box(0.5, 0, 6, 6, 3, color) -- telinga kiri
                parts[#parts + 1] = box(13.5, 0, 6, 6, 3, color) -- telinga kanan
                parts[#parts + 1] = box(0, 2.5, 20, 12, 6, color) -- badan
                parts[#parts + 1] = box(1.5, 12, 6, 4, 2, color) -- kaki kiri
                parts[#parts + 1] = box(12.5, 12, 6, 4, 2, color) -- kaki kanan
                box(4.2, 6.2, 3.8, 5, 2, cut) -- mata kiri
                box(12, 6.2, 3.8, 5, 2, cut) -- mata kanan
                local api = { Holder = holder }
                function api:SetColor(c)
                    for _, f in ipairs(parts) do
                        f.BackgroundColor3 = c
                    end
                end
                return api
            end

            local function copyDiscord()
                local link = tostring((genvN and genvN.WhiteScript_Discord) or "")
                local copier = (type(setclipboard) == "function" and setclipboard)
                    or (type(toclipboard) == "function" and toclipboard)
                    or (type(Clipboard) == "table" and type(Clipboard.set) == "function" and Clipboard.set)
                local okCopy = false
                if copier and link ~= "" then
                    okCopy = pcall(copier, link)
                end
                pcall(function()
                    Lib:Notify({
                        Title = "Discord",
                        Content = okCopy and "Link Discord berhasil disalin! Tempel di browser / Discord." or ("Salin manual: " .. link),
                        Icon = "solar:stars-bold",
                        Duration = 3,
                    })
                end)
                return okCopy
            end

            -- Tombol ikon Discord di header (ketuk = salin link)
            do
                local dcPill = New("Frame", {
                    Size = UDim2.fromOffset(34, 24),
                    BackgroundColor3 = C.panel2,
                    BorderSizePixel = 0,
                    LayoutOrder = 0,
                }, TagHolder)
                Circle(dcPill)
                local dcStroke = Stroke(dcPill, DC, 1, 0.55)
                local dcLogo = drawDiscord(dcPill, 0.8, DC, C.panel2)
                local dcBtn = New("TextButton", {
                    Size = UDim2.fromScale(1, 1),
                    BackgroundTransparency = 1,
                    Text = "",
                    AutoButtonColor = false,
                    ZIndex = 6,
                }, dcPill)
                dcBtn.MouseEnter:Connect(function()
                    Tween(dcStroke, 0.12, { Transparency = 0 })
                end)
                dcBtn.MouseLeave:Connect(function()
                    Tween(dcStroke, 0.12, { Transparency = 0.55 })
                end)
                dcBtn.MouseButton1Click:Connect(function()
                    copyDiscord()
                    dcLogo:SetColor(C.green)
                    task.delay(1.2, function()
                        dcLogo:SetColor(DC)
                    end)
                end)
            end

            New("Frame", {
                Position = UDim2.new(0, 0, 0, HEADER_H),
                Size = UDim2.new(1, 0, 0, 1),
                BackgroundColor3 = C.stroke,
                BorderSizePixel = 0,
            }, Main)
            local brandLine = New("Frame", {
                Position = UDim2.new(0, 14, 0, HEADER_H - 1),
                Size = UDim2.fromOffset(46, 3),
                BackgroundColor3 = C.accent,
                BorderSizePixel = 0,
                ZIndex = 3,
            }, Main)
            Round(brandLine, 2)

            -- Drag via header (mouse & touch)
            do
                local dragging, dragStart, startPos
                Header.InputBegan:Connect(function(input)
                    if
                        input.UserInputType == Enum.UserInputType.MouseButton1
                        or input.UserInputType == Enum.UserInputType.Touch
                    then
                        dragging = true
                        dragStart = input.Position
                        startPos = Main.Position
                        input.Changed:Connect(function()
                            if input.UserInputState == Enum.UserInputState.End then
                                dragging = false
                            end
                        end)
                    end
                end)
                track(UserInputService.InputChanged:Connect(function(input)
                    if
                        dragging
                        and (
                            input.UserInputType == Enum.UserInputType.MouseMovement
                            or input.UserInputType == Enum.UserInputType.Touch
                        )
                    then
                        local d = input.Position - dragStart
                        Main.Position =
                            UDim2.new(startPos.X.Scale, startPos.X.Offset + d.X, startPos.Y.Scale, startPos.Y.Offset + d.Y)
                    end
                end))
            end

            -- Halaman MENU (hanya daftar tab, tiap baris punya panah ">")
            local Body = New("Frame", {
                Position = UDim2.fromOffset(SIDE_W + 1, PAGE_Y),
                Size = UDim2.new(1, -(SIDE_W + 1), 1, -(PAGE_Y + FOOTER_H)),
                BackgroundTransparency = 1,
            }, Main)
            New("Frame", {
                Position = UDim2.fromOffset(SIDE_W, HEADER_H + 1),
                Size = UDim2.new(0, 1, 1, -(HEADER_H + 1)),
                BackgroundColor3 = C.stroke,
                BorderSizePixel = 0,
            }, Main)

            local showUser = not (type(cfg.User) == "table" and cfg.User.Enabled == false)
            local MenuPage = New("Frame", {
                Name = "MenuPage",
                Position = UDim2.fromOffset(0, HEADER_H + 1),
                Size = UDim2.new(0, SIDE_W, 1, -(HEADER_H + 1)),
                BackgroundTransparency = 1,
            }, Main)
            local TabList = New("ScrollingFrame", {
                Position = UDim2.fromOffset(8, 8),
                Size = UDim2.new(1, -16, 1, -52),
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                ScrollBarThickness = 2,
                ScrollBarImageColor3 = C.accentDim,
                CanvasSize = UDim2.new(0, 0, 0, 0),
                AutomaticCanvasSize = Enum.AutomaticSize.Y,
            }, MenuPage)
            New("UIListLayout", {
                Padding = UDim.new(0, 2),
                SortOrder = Enum.SortOrder.LayoutOrder,
            }, TabList)

            if showUser and LP then
                local U = New("Frame", {
                    AnchorPoint = Vector2.new(0, 1),
                    Position = UDim2.new(0, 8, 1, -3),
                    Size = UDim2.new(1, -16, 0, 26),
                    BackgroundTransparency = 1,
                    BorderSizePixel = 0,
                }, MenuPage)
                New("Frame", {
                    Size = UDim2.new(1, 0, 0, 1),
                    Position = UDim2.fromOffset(0, -3),
                    BackgroundColor3 = C.stroke,
                    BorderSizePixel = 0,
                }, U)
                local av = New("ImageLabel", {
                    AnchorPoint = Vector2.new(0, 0.5),
                    Position = UDim2.new(0, 0, 0.5, 1),
                    Size = UDim2.fromOffset(22, 22),
                    BackgroundColor3 = C.panel,
                    BorderSizePixel = 0,
                    Image = "rbxthumb://type=AvatarHeadShot&id=" .. tostring(LP.UserId) .. "&w=48&h=48",
                    ZIndex = 3,
                }, U)
                Circle(av)
                Stroke(av, C.stroke, 1, 0)
                local dn = (LP.DisplayName:gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;"))
                local un = (LP.Name:gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;"))
                New("TextLabel", {
                    Position = UDim2.fromOffset(30, 1),
                    Size = UDim2.new(1, -34, 1, 0),
                    BackgroundTransparency = 1,
                    RichText = true,
                    Text = "<b>" .. dn .. "</b>",
                    Font = Enum.Font.GothamMedium,
                    TextSize = 12,
                    TextColor3 = C.text,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    TextTruncate = Enum.TextTruncate.AtEnd,
                }, U)
            end

            -- Join Discord (footer, kanan bawah): ketuk = salin link Discord
            local DC_PILL_W = 176
            do
                local logoW, gap, padX = 16, 6, 10
                local dcBg = Color3.fromRGB(240, 241, 255)
                local dcFoot = New("Frame", {
                    AnchorPoint = Vector2.new(0, 1),
                    Position = UDim2.new(0, SIDE_W + 10, 1, -5),
                    Size = UDim2.fromOffset(DC_PILL_W, 20),
                    BackgroundColor3 = dcBg,
                    BorderSizePixel = 0,
                    ZIndex = 20,
                }, Main)
                Circle(dcFoot)
                local dcFootStroke = Stroke(dcFoot, DC, 1, 0.45)
                local logoWrap = New("Frame", {
                    Position = UDim2.fromOffset(padX, 2),
                    Size = UDim2.fromOffset(logoW, 16),
                    BackgroundTransparency = 1,
                    ZIndex = 20,
                }, dcFoot)
                local fLogo = drawDiscord(logoWrap, 0.8, DC, dcBg)
                New("TextLabel", {
                    Position = UDim2.fromOffset(padX + logoW + gap, 0),
                    Size = UDim2.new(1, -(padX + logoW + gap + 6), 1, 0),
                    BackgroundTransparency = 1,
                    Text = "Join Discord - klik disini",
                    Font = Enum.Font.GothamBold,
                    TextSize = 11,
                    TextColor3 = C.text,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    TextTruncate = Enum.TextTruncate.AtEnd,
                    ZIndex = 20,
                }, dcFoot)
                local dcFootBtn = New("TextButton", {
                    Size = UDim2.fromScale(1, 1),
                    BackgroundTransparency = 1,
                    Text = "",
                    AutoButtonColor = false,
                    ZIndex = 21,
                }, dcFoot)
                dcFootBtn.MouseEnter:Connect(function()
                    Tween(dcFootStroke, 0.12, { Transparency = 0 })
                end)
                dcFootBtn.MouseLeave:Connect(function()
                    Tween(dcFootStroke, 0.12, { Transparency = 0.45 })
                end)
                dcFootBtn.MouseButton1Click:Connect(function()
                    copyDiscord()
                    fLogo:SetColor(C.green)
                    task.delay(1.2, function()
                        fLogo:SetColor(DC)
                    end)
                end)
            end

            -- Halaman ISI tab (tampil setelah salah satu tab diketuk)
            local Content = New("Frame", {
                Name = "ContentPage",
                Position = UDim2.fromOffset(12, 4),
                Size = UDim2.new(1, -24, 1, -8),
                BackgroundTransparency = 1,
                ClipsDescendants = true,
                Visible = false,
            }, Body)

            -- Handle resize (pojok kanan bawah): tarik untuk memperbesar / memperkecil jendela
            do
                local MIN_W, MIN_H, MAX_W, MAX_H = 560, 220, 1100, 620
                local grip = New("TextButton", {
                    Name = "ResizeGrip",
                    AnchorPoint = Vector2.new(1, 1),
                    Position = UDim2.new(1, -2, 1, -2),
                    Size = UDim2.fromOffset(24, 24),
                    BackgroundTransparency = 1,
                    Text = "",
                    AutoButtonColor = false,
                    ZIndex = 30,
                }, Main)
                for _, ln in ipairs({ { 11, 11, 20 }, { 15, 15, 11 } }) do
                    local l = New("Frame", {
                        AnchorPoint = Vector2.new(0.5, 0.5),
                        Position = UDim2.fromOffset(ln[1], ln[2]),
                        Size = UDim2.fromOffset(ln[3], 2),
                        Rotation = -45,
                        BackgroundColor3 = C.stroke,
                        BorderSizePixel = 0,
                        ZIndex = 31,
                    }, grip)
                    Round(l, 1)
                end
                local hint = New("Frame", {
                    Name = "ResizeHint",
                    AnchorPoint = Vector2.new(1, 1),
                    Position = UDim2.new(1, -32, 1, -6),
                    Size = UDim2.fromOffset(0, 14),
                    AutomaticSize = Enum.AutomaticSize.X,
                    BackgroundTransparency = 1,
                    ZIndex = 30,
                }, Main)
                New("UIListLayout", {
                    FillDirection = Enum.FillDirection.Horizontal,
                    VerticalAlignment = Enum.VerticalAlignment.Center,
                    SortOrder = Enum.SortOrder.LayoutOrder,
                    Padding = UDim.new(0, 4),
                }, hint)
                New("TextLabel", {
                    Size = UDim2.fromOffset(0, 12),
                    AutomaticSize = Enum.AutomaticSize.X,
                    BackgroundTransparency = 1,
                    Text = "tahan untuk besar kecilkan UI",
                    Font = Enum.Font.GothamMedium,
                    TextSize = 10,
                    TextColor3 = C.sub,
                    TextXAlignment = Enum.TextXAlignment.Right,
                    LayoutOrder = 1,
                    ZIndex = 30,
                }, hint)
                -- tanda panah (digambar sendiri) menunjuk ke handle resize
                local arrowBox = New("Frame", {
                    Size = UDim2.fromOffset(14, 12),
                    BackgroundTransparency = 1,
                    LayoutOrder = 2,
                    ZIndex = 30,
                }, hint)
                local function arrowPart(pos, size, rot)
                    local f = New("Frame", {
                        AnchorPoint = Vector2.new(0.5, 0.5),
                        Position = pos,
                        Size = size,
                        Rotation = rot or 0,
                        BackgroundColor3 = C.sub,
                        BorderSizePixel = 0,
                        ZIndex = 30,
                    }, arrowBox)
                    Round(f, 1)
                end
                arrowPart(UDim2.fromOffset(6, 6), UDim2.fromOffset(12, 2), 0)
                arrowPart(UDim2.fromOffset(9.9, 3.9), UDim2.fromOffset(6, 2), 45)
                arrowPart(UDim2.fromOffset(9.9, 8.1), UDim2.fromOffset(6, 2), -45)
                -- bergerak bolak-balik ke arah handle resize
                pcall(function()
                    TweenService:Create(
                        hint,
                        TweenInfo.new(0.55, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true),
                        { Position = UDim2.new(1, -27, 1, -6) }
                    ):Play()
                end)
                local rs, startPos, startW, startH = false, nil, 0, 0
                grip.InputBegan:Connect(function(input)
                    if
                        input.UserInputType == Enum.UserInputType.MouseButton1
                        or input.UserInputType == Enum.UserInputType.Touch
                    then
                        rs = true
                        hint.Visible = false
                        startPos = input.Position
                        startW, startH = Main.Size.X.Offset, Main.Size.Y.Offset
                        input.Changed:Connect(function()
                            if input.UserInputState == Enum.UserInputState.End then
                                rs = false
                                hint.Visible = true
                            end
                        end)
                    end
                end)
                track(UserInputService.InputChanged:Connect(function(input)
                    if
                        rs
                        and (
                            input.UserInputType == Enum.UserInputType.MouseMovement
                            or input.UserInputType == Enum.UserInputType.Touch
                        )
                    then
                        local sc = MainScale.Scale
                        if sc < 0.05 then
                            sc = 1
                        end
                        local nw = math.clamp(startW + (input.Position.X - startPos.X) / sc, MIN_W, MAX_W)
                        local nh = math.clamp(startH + (input.Position.Y - startPos.Y) / sc, MIN_H, MAX_H)
                        local dw = nw - Main.Size.X.Offset
                        local dh = nh - Main.Size.Y.Offset
                        local p = Main.Position
                        Main.Size = UDim2.fromOffset(nw, nh)
                        -- anchor di tengah: geser posisi supaya pojok kiri-atas tetap diam
                        Main.Position = UDim2.new(p.X.Scale, p.X.Offset + dw * sc / 2, p.Y.Scale, p.Y.Offset + dh * sc / 2)
                    end
                end))
            end

            -- Logo minimize: bisa di-drag, tanpa cincin. Ketuk (tanpa geser) = buka kembali.
            local FAB = 54
            local Fab = New("ImageButton", {
                Name = "FabButton",
                Position = UDim2.fromOffset(12, math.floor(vp.Y / 2 - FAB / 2)),
                Size = UDim2.fromOffset(FAB, FAB),
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                AutoButtonColor = false,
                Image = logoImg,
                ScaleType = Enum.ScaleType.Fit,
                Visible = false,
                ZIndex = 10,
            }, Gui)
            Round(Fab, 100)
            Stroke(Fab, Color3.fromRGB(0, 0, 0), 2, 0)

            local visible = true
            local function setVisible(v)
                visible = v
                Main.Visible = v
                Fab.Visible = not v
                if v then
                    playClick()
                    MainScale.Scale = baseScale * 0.92
                    Tween(MainScale, 0.3, { Scale = baseScale }, Enum.EasingStyle.Back)
                end
            end
            MinBtn.MouseButton1Click:Connect(function()
                setVisible(false)
            end)
            do
                local fdrag, moved, fstart, fpos = false, false, nil, nil
                Fab.InputBegan:Connect(function(input)
                    if
                        input.UserInputType == Enum.UserInputType.MouseButton1
                        or input.UserInputType == Enum.UserInputType.Touch
                    then
                        fdrag, moved = true, false
                        fstart = input.Position
                        fpos = Fab.Position
                        input.Changed:Connect(function()
                            if input.UserInputState == Enum.UserInputState.End then
                                local wasDrag = fdrag
                                fdrag = false
                                if wasDrag and not moved then
                                    setVisible(true)
                                end
                            end
                        end)
                    end
                end)
                track(UserInputService.InputChanged:Connect(function(input)
                    if
                        fdrag
                        and (
                            input.UserInputType == Enum.UserInputType.MouseMovement
                            or input.UserInputType == Enum.UserInputType.Touch
                        )
                    then
                        local d = input.Position - fstart
                        if d.Magnitude > 5 then
                            moved = true
                        end
                        if moved then
                            local sz = Gui.AbsoluteSize
                            local x = fpos.X.Offset + d.X
                            local y = fpos.Y.Offset + d.Y
                            if sz.X > FAB and sz.Y > FAB then
                                x = math.clamp(x, 0, sz.X - FAB)
                                y = math.clamp(y, 0, sz.Y - FAB)
                            end
                            Fab.Position = UDim2.fromOffset(x, y)
                        end
                    end
                end))
            end
            if typeof(cfg.ToggleKey) == "EnumItem" then
                track(UserInputService.InputBegan:Connect(function(input, gp)
                    if not gp and input.KeyCode == cfg.ToggleKey then
                        setVisible(not visible)
                    end
                end))
            end

            Tween(MainScale, 0.55, { Scale = baseScale }, Enum.EasingStyle.Back)

            -- ---------------- Window object ----------------
            local Window = { _tabs = {}, _current = nil, UIElements = { Main = Main } }

            -- Navigasi: Menu (daftar tab) <-> Isi tab
            function Window:_showPage(title)
                Content.Visible = true
                Content.Position = UDim2.fromOffset(26, 4)
                Tween(Content, 0.2, { Position = UDim2.fromOffset(12, 4) })
            end
            function Window:Home()
                local first = Window._tabs[1]
                if first then
                    first:Select()
                end
            end
            BackBtn.MouseButton1Click:Connect(function()
                Window:Home()
            end)
            BackBtn.MouseEnter:Connect(function()
                Tween(BackBtn, 0.12, { BackgroundColor3 = C.stroke })
            end)
            BackBtn.MouseLeave:Connect(function()
                Tween(BackBtn, 0.12, { BackgroundColor3 = C.field })
            end)

            function Window:Destroy()
                if Gui.Parent then
                    Gui:Destroy()
                end
            end
            function Window:SetVisible(v)
                setVisible(v ~= false)
            end

            function Window:Tag(o)
                o = o or {}
                local col = o.Color or C.accent
                local pill = New("Frame", {
                    Size = UDim2.new(0, 0, 0, 24),
                    AutomaticSize = Enum.AutomaticSize.X,
                    BackgroundColor3 = C.panel2,
                    BorderSizePixel = 0,
                    LayoutOrder = #TagHolder:GetChildren() + 1,
                }, TagHolder)
                Circle(pill)
                local st = Stroke(pill, col, 1, 0.55)
                Pad(pill, 9, 11, 0, 0)
                New("UIListLayout", {
                    FillDirection = Enum.FillDirection.Horizontal,
                    VerticalAlignment = Enum.VerticalAlignment.Center,
                    SortOrder = Enum.SortOrder.LayoutOrder,
                    Padding = UDim.new(0, 5),
                }, pill)
                local glyph
                if o.Draw then
                    glyph = DrawIcon(pill, o.Draw, col, 1)
                end
                local lb = New("TextLabel", {
                    Size = UDim2.new(0, 0, 1, 0),
                    AutomaticSize = Enum.AutomaticSize.X,
                    BackgroundTransparency = 1,
                    Text = "",
                    Font = Enum.Font.GothamBold,
                    TextSize = 11,
                    TextColor3 = col,
                    LayoutOrder = 2,
                }, pill)
                local function fmt(t)
                    t = tostring(t)
                    if o.StripLabel then
                        t = t:gsub("^%a+:%s*", "")
                    end
                    return t .. (o.Suffix or "")
                end
                lb.Text = fmt(o.Title or "")
                local tag = {}
                function tag:SetTitle(t)
                    lb.Text = fmt(t)
                end
                function tag:SetColor(c)
                    lb.TextColor3 = c
                    st.Color = c
                    if glyph then
                        glyph:SetColor(c)
                    end
                end
                return tag
            end

            function Window:Tab(o)
                o = o or {}
                local title = tostring(o.Title or "Tab")

                local TAB_DESC = {
                    ["Farm"] = "Farming otomatis",
                    ["Auto Steal"] = "Curi egg & pet otomatis",
                    ["Dr Scramble"] = "Lab & mech Dr Scramble",
                    ["Anti AFK"] = "Cegah kick saat idle",
                    ["Butterfly"] = "Event Butterfly Bloom",
                    ["Wisp"] = "Wisp companion",
                    ["Auto Place Egg"] = "Taruh egg otomatis",
                    ["Auto Hatch"] = "Tetas egg otomatis",
                    ["Auto Sell Pet"] = "Jual pet otomatis",
                    ["Auto Sell Egg"] = "Jual egg otomatis",
                    ["Server Hop"] = "Pindah ke server lain",
                    ["Online"] = "Pengguna yang sedang online",
                    ["ESP"] = "Tampilkan target di layar",
                    ["Player"] = "Pengaturan karakter",
                    ["Informasi"] = "Info script & game",
                }
                local descText = o.Desc or TAB_DESC[title]
                local rowH = 30
                local btn = New("TextButton", {
                    Size = UDim2.new(1, 0, 0, rowH),
                    BackgroundColor3 = C.accent,
                    BackgroundTransparency = 1,
                    BorderSizePixel = 0,
                    Text = "",
                    AutoButtonColor = false,
                    ClipsDescendants = true,
                    LayoutOrder = #self._tabs + 1,
                }, TabList)
                Round(btn, 8)
                local ov = Hover(btn, 8)
                HoverBind(btn, ov)

                local letter = New("TextLabel", {
                    AnchorPoint = Vector2.new(0, 0.5),
                    Position = UDim2.new(0, 10, 0.5, 0),
                    Size = UDim2.fromOffset(12, 12),
                    BackgroundTransparency = 1,
                    Text = string.upper(string.sub(title, 1, 1)),
                    Font = Enum.Font.GothamBold,
                    TextSize = 11,
                    TextColor3 = C.sub,
                    ZIndex = 4,
                }, btn)
                local tabIcon = NewIcon(btn, o.Icon, 12, C.sub, {
                    AnchorPoint = Vector2.new(0, 0.5),
                    Position = UDim2.new(0, 10, 0.5, 0),
                    ZIndex = 4,
                }, function()
                    letter.Visible = false
                end)

                local label = New("TextLabel", {
                    Position = UDim2.fromOffset(29, 0),
                    Size = UDim2.new(1, -34, 1, 0),
                    BackgroundTransparency = 1,
                    Text = title,
                    Font = Enum.Font.GothamMedium,
                    TextSize = 12,
                    TextColor3 = C.sub,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    TextTruncate = Enum.TextTruncate.AtEnd,
                    ZIndex = 3,
                }, btn)

                local pageFrame = New("ScrollingFrame", {
                    Name = title,
                    Size = UDim2.fromScale(1, 1),
                    BackgroundTransparency = 1,
                    BorderSizePixel = 0,
                    ScrollBarThickness = 4,
                    ScrollBarImageColor3 = C.accentDim,
                    CanvasSize = UDim2.new(0, 0, 0, 0),
                    AutomaticCanvasSize = Enum.AutomaticSize.Y,
                    ScrollingDirection = Enum.ScrollingDirection.Y,
                    Visible = false,
                }, Content)
                Pad(pageFrame, 0, 10, 0, 10)
                List(pageFrame, 8)

                local tab = {
                    Page = pageFrame,
                    _order = 0,
                    _block = nil,
                    UIElements = { Main = btn, TabItem = btn, Item = btn },
                }

                -- Semua elemen disusun SATU kolom ke bawah (scroll vertikal), tidak ada kolom kanan.
                function tab:_slot(full)
                    self._order += 1
                    return pageFrame, self._order
                end

                function tab:Select()
                    for _, t in ipairs(Window._tabs) do
                        t.Page.Visible = (t == tab)
                        if t._setActive then
                            t._setActive(t == tab)
                        end
                    end
                    Window._current = tab
                    Window:_showPage(title)
                end
                function tab._setActive(on)
                    Tween(btn, 0.15, { BackgroundTransparency = on and 0 or 1 })
                    local col = on and C.bg or C.sub
                    label.TextColor3 = col
                    letter.TextColor3 = col
                    tabIcon.ImageColor3 = col
                    label.Font = on and Enum.Font.GothamBold or Enum.Font.GothamMedium
                end
                btn.MouseButton1Click:Connect(function()
                    tab:Select()
                end)

                -- ------- Section -------
                function tab:Section(s)
                    s = s or {}
                    self._order += 1
                    self._block = nil
                    local f = New("Frame", {
                        Size = UDim2.new(1, 0, 0, 36),
                        BackgroundTransparency = 1,
                        LayoutOrder = self._order,
                    }, pageFrame)
                    local band = New("Frame", {
                        Position = UDim2.fromOffset(0, 8),
                        Size = UDim2.new(1, 0, 0, 28),
                        BackgroundColor3 = Color3.fromRGB(238, 238, 241),
                        BorderSizePixel = 0,
                    }, f)
                    Round(band, 8)
                    Stroke(band, C.stroke, 1, 0.2)
                    local accentBar = New("Frame", {
                        AnchorPoint = Vector2.new(0, 0.5),
                        Position = UDim2.new(0, 8, 0.5, 0),
                        Size = UDim2.fromOffset(4, 16),
                        BackgroundColor3 = C.accent,
                        BorderSizePixel = 0,
                    }, band)
                    Round(accentBar, 2)
                    New("TextLabel", {
                        Position = UDim2.fromOffset(20, 0),
                        Size = UDim2.new(1, -28, 1, 0),
                        BackgroundTransparency = 1,
                        Text = string.upper(tostring(s.Title or "")),
                        Font = Enum.Font.GothamBlack,
                        TextSize = 12,
                        TextColor3 = C.text,
                        TextXAlignment = Enum.TextXAlignment.Left,
                        TextTruncate = Enum.TextTruncate.AtEnd,
                    }, band)
                    local api = { ElementFrame = f, UIElements = { Container = f, Main = f } }
                    function api:Destroy()
                        f:Destroy()
                    end
                    return api
                end

                function tab:Divider()
                    self._block = nil
                    self._order += 1
                    New("Frame", {
                        Size = UDim2.new(1, 0, 0, 2),
                        BackgroundColor3 = C.stroke,
                        BorderSizePixel = 0,
                        LayoutOrder = self._order,
                    }, pageFrame)
                end
                function tab:Space(s)
                    self._block = nil
                    self._order += 1
                    New("Frame", {
                        Size = UDim2.new(1, 0, 0, (type(s) == "table" and s.Columns or 1) * 6),
                        BackgroundTransparency = 1,
                        LayoutOrder = self._order,
                    }, pageFrame)
                end

                -- ------- Paragraph -------
                function tab:Paragraph(p)
                    local api = makeCard(self, p or {}, 0, true)
                    return api
                end

                -- ------- Button -------
                function tab:Button(p)
                    p = p or {}
                    local api, ctrl = makeCard(self, p, 30)
                    local overlay = Hover(api._card, 10)
                    local click = rowClick(api._row)
                    HoverBind(click, overlay)
                    local fb = New("TextLabel", {
                        AnchorPoint = Vector2.new(1, 0.5),
                        Position = UDim2.new(1, 0, 0.5, 0),
                        Size = UDim2.fromOffset(18, 18),
                        BackgroundTransparency = 1,
                        Text = ">",
                        Font = Enum.Font.GothamBlack,
                        TextSize = 15,
                        TextColor3 = C.accent,
                    }, ctrl)
                    local ic = NewIcon(ctrl, p.Icon or "play", 18, C.accent, {
                        AnchorPoint = Vector2.new(1, 0.5),
                        Position = UDim2.new(1, 0, 0.5, 0),
                    }, function()
                        fb.Visible = false
                    end)
                    click.MouseButton1Click:Connect(function()
                        if type(p.Callback) == "function" then
                            task.spawn(pcall, p.Callback)
                        end
                    end)
                    function api:SetIcon(n)
                        SetIcon(ic, n, C.accent)
                    end
                    return api
                end

                -- ------- Toggle -------
                function tab:Toggle(p)
                    p = p or {}
                    local api, ctrl = makeCard(self, p, 56)
                    local state = p.Value == true
                    local overlay = Hover(api._card, 10)
                    if state then
                        api._stroke.Color = C.green
                    end
                    local click = rowClick(api._row)
                    HoverBind(click, overlay)

                    local track_ = New("Frame", {
                        AnchorPoint = Vector2.new(1, 0.5),
                        Position = UDim2.new(1, 0, 0.5, 0),
                        Size = UDim2.fromOffset(52, 28),
                        BackgroundColor3 = state and C.green or C.field,
                    }, ctrl)
                    Circle(track_)
                    local trackStroke = Stroke(track_, state and C.green or C.stroke, 1.5, 0)
                    local knob = New("Frame", {
                        AnchorPoint = Vector2.new(0, 0.5),
                        Position = UDim2.new(0, state and 28 or 4, 0.5, 0),
                        Size = UDim2.fromOffset(20, 20),
                        BackgroundColor3 = state and C.bg or C.sub,
                    }, track_)
                    Circle(knob)

                    local function paint(animate)
                        local t = animate and 0.2 or 0
                        Tween(track_, t, { BackgroundColor3 = state and C.green or C.field })
                        Tween(trackStroke, t, { Color = state and C.green or C.stroke })
                        Tween(api._stroke, t, { Color = state and C.green or C.stroke })
                        Tween(knob, t, {
                            Position = UDim2.new(0, state and 28 or 4, 0.5, 0),
                            BackgroundColor3 = state and C.bg or C.sub,
                        }, Enum.EasingStyle.Back)
                    end
                    click.MouseButton1Click:Connect(function()
                        state = not state
                        paint(true)
                        if type(p.Callback) == "function" then
                            task.spawn(pcall, p.Callback, state)
                        end
                    end)
                    function api:Set(v)
                        state = v == true
                        paint(true)
                    end
                    function api:Get()
                        return state
                    end
                    api.Value = state
                    return api
                end

                -- ------- Input -------
                function tab:Input(p)
                    p = p or {}
                    local api = makeCard(self, p, 0)
                    local box_h = New("Frame", {
                        Size = UDim2.new(1, 0, 0, 44),
                        BackgroundTransparency = 1,
                        LayoutOrder = 2,
                    }, api._stack)
                    Pad(box_h, 14, 14, 0, 12)
                    local bg = New("Frame", {
                        Size = UDim2.fromScale(1, 1),
                        BackgroundColor3 = C.field,
                        BorderSizePixel = 0,
                    }, box_h)
                    Round(bg, 8)
                    local st = Stroke(bg, C.stroke, 1, 0.1)
                    api._card:SetAttribute("est", 74)
                    local tb = New("TextBox", {
                        Position = UDim2.fromOffset(10, 0),
                        Size = UDim2.new(1, -20, 1, 0),
                        BackgroundTransparency = 1,
                        Text = tostring(p.Value or ""),
                        PlaceholderText = tostring(p.Placeholder or ""),
                        PlaceholderColor3 = Color3.fromRGB(95, 104, 130),
                        TextColor3 = C.text,
                        Font = Enum.Font.GothamMedium,
                        TextSize = 13,
                        TextXAlignment = Enum.TextXAlignment.Left,
                        ClearTextOnFocus = false,
                    }, bg)
                    tb.Focused:Connect(function()
                        Tween(st, 0.2, { Color = C.accent })
                    end)
                    tb.FocusLost:Connect(function()
                        Tween(st, 0.2, { Color = C.stroke })
                        if type(p.Callback) == "function" then
                            task.spawn(pcall, p.Callback, tb.Text)
                        end
                    end)
                    function api:Set(v)
                        tb.Text = tostring(v or "")
                    end
                    return api
                end

                -- ------- Slider -------
                function tab:Slider(p)
                    p = p or {}
                    local vcfg = type(p.Value) == "table" and p.Value or {}
                    local api, ctrl = makeCard(self, p, 72)
                    api._card:SetAttribute("est", 58)
                    local sv = { Min = tonumber(vcfg.Min) or 0, Max = tonumber(vcfg.Max) or 100 }
                    local step = tonumber(p.Step) or 1
                    local value = tonumber(vcfg.Default) or sv.Min
                    api.Value = sv

                    local vbg = New("Frame", {
                        AnchorPoint = Vector2.new(1, 0.5),
                        Position = UDim2.new(1, 0, 0.5, 0),
                        Size = UDim2.fromOffset(72, 30),
                        BackgroundColor3 = C.field,
                    }, ctrl)
                    Round(vbg, 8)
                    local vst = Stroke(vbg, C.stroke, 1, 0.1)
                    local vbox = New("TextBox", {
                        Size = UDim2.fromScale(1, 1),
                        BackgroundTransparency = 1,
                        Text = "",
                        TextColor3 = C.text,
                        Font = Enum.Font.GothamBold,
                        TextSize = 13,
                        ClearTextOnFocus = false,
                    }, vbg)

                    local area = New("Frame", {
                        Size = UDim2.new(1, 0, 0, 30),
                        BackgroundTransparency = 1,
                        LayoutOrder = 2,
                    }, api._stack)
                    Pad(area, 14, 14, 0, 8)
                    local trackF = New("Frame", {
                        AnchorPoint = Vector2.new(0, 0.5),
                        Position = UDim2.new(0, 0, 0.5, 0),
                        Size = UDim2.new(1, 0, 0, 4),
                        BackgroundColor3 = C.field,
                        BorderSizePixel = 0,
                    }, area)
                    Circle(trackF)
                    local fill = New("Frame", {
                        Size = UDim2.fromScale(0, 1),
                        BackgroundColor3 = C.accent,
                        BorderSizePixel = 0,
                    }, trackF)
                    Circle(fill)
                    local knob = New("Frame", {
                        AnchorPoint = Vector2.new(0.5, 0.5),
                        Position = UDim2.fromScale(0, 0.5),
                        Size = UDim2.fromOffset(12, 12),
                        BackgroundColor3 = C.bg,
                        ZIndex = 3,
                    }, trackF)
                    Circle(knob)
                    Stroke(knob, C.accent, 2, 0)
                    local hit = New("TextButton", {
                        Text = "",
                        AutoButtonColor = false,
                        BackgroundTransparency = 1,
                        Position = UDim2.new(0, -10, 0, 0),
                        Size = UDim2.new(1, 20, 1, 0),
                        ZIndex = 5,
                    }, area)

                    local function fmt(v)
                        if step < 1 then
                            return string.format("%.2f", v):gsub("0+$", ""):gsub("%.$", "")
                        end
                        return tostring(math.floor(v + 0.5))
                    end
                    local function norm(v)
                        v = tonumber(v) or sv.Min
                        if step > 0 then
                            v = math.floor((v - sv.Min) / step + 0.5) * step + sv.Min
                        end
                        return math.clamp(v, sv.Min, sv.Max)
                    end
                    local function paint()
                        local span = sv.Max - sv.Min
                        local rel = span > 0 and (value - sv.Min) / span or 0
                        rel = math.clamp(rel, 0, 1)
                        fill.Size = UDim2.fromScale(rel, 1)
                        knob.Position = UDim2.fromScale(rel, 0.5)
                        vbox.Text = fmt(value)
                    end
                    local function commit(v, fire)
                        v = norm(v)
                        local changed = v ~= value
                        value = v
                        paint()
                        if fire and changed and type(p.Callback) == "function" then
                            task.spawn(pcall, p.Callback, value)
                        end
                    end
                    value = norm(value)
                    paint()

                    local dragging = false
                    local function fromX(x)
                        local w = trackF.AbsoluteSize.X
                        if w <= 0 then
                            return
                        end
                        local rel = math.clamp((x - trackF.AbsolutePosition.X) / w, 0, 1)
                        commit(sv.Min + (sv.Max - sv.Min) * rel, true)
                    end
                    hit.InputBegan:Connect(function(input)
                        if
                            input.UserInputType == Enum.UserInputType.MouseButton1
                            or input.UserInputType == Enum.UserInputType.Touch
                        then
                            dragging = true
                            playClick()
                            fromX(input.Position.X)
                            input.Changed:Connect(function()
                                if input.UserInputState == Enum.UserInputState.End then
                                    dragging = false
                                end
                            end)
                        end
                    end)
                    track(UserInputService.InputChanged:Connect(function(input)
                        if
                            dragging
                            and (
                                input.UserInputType == Enum.UserInputType.MouseMovement
                                or input.UserInputType == Enum.UserInputType.Touch
                            )
                        then
                            fromX(input.Position.X)
                        end
                    end))
                    vbox.Focused:Connect(function()
                        Tween(vst, 0.2, { Color = C.accent })
                    end)
                    vbox.FocusLost:Connect(function()
                        Tween(vst, 0.2, { Color = C.stroke })
                        local n = tonumber(vbox.Text)
                        if n then
                            commit(n, true)
                        else
                            paint()
                        end
                    end)

                    function api:Set(v)
                        commit(v, false)
                    end
                    function api:SetMin(v)
                        sv.Min = tonumber(v) or sv.Min
                        commit(value, false)
                    end
                    function api:SetMax(v)
                        sv.Max = tonumber(v) or sv.Max
                        commit(value, false)
                    end
                    return api
                end

                -- ------- Dropdown (single & multi) -------
                function tab:Dropdown(p)
                    p = p or {}
                    local multi = p.Multi == true
                    local allowNone = p.AllowNone ~= false
                    local options = copyList(p.Values)
                    local sel = {}
                    local current
                    local api, ctrl = makeCard(self, p, 150)
                    api._card:SetAttribute("est", 34)
                    local open = false

                    local function titleOf(v)
                        if type(v) == "table" then
                            return v.Title or v[1]
                        end
                        return v
                    end
                    local function setValue(v)
                        if multi then
                            sel = {}
                            if type(v) == "table" then
                                for k, x in pairs(v) do
                                    if type(x) == "string" then
                                        sel[x] = true
                                    elseif type(x) == "table" and type(x.Title) == "string" then
                                        sel[x.Title] = true
                                    elseif x == true and type(k) == "string" then
                                        sel[k] = true
                                    end
                                end
                            end
                        else
                            v = titleOf(v)
                            if v == "" then
                                v = nil
                            end
                            current = v
                        end
                    end
                    setValue(p.Value)

                    local pill = New("Frame", {
                        AnchorPoint = Vector2.new(1, 0.5),
                        Position = UDim2.new(1, 0, 0.5, 0),
                        Size = UDim2.fromOffset(150, 32),
                        BackgroundColor3 = C.field,
                        BorderSizePixel = 0,
                    }, ctrl)
                    Round(pill, 8)
                    local pst = Stroke(pill, C.stroke, 1, 0.05)
                    local vlabel = New("TextLabel", {
                        Position = UDim2.fromOffset(12, 0),
                        Size = UDim2.new(1, -32, 1, 0),
                        BackgroundTransparency = 1,
                        Text = "",
                        Font = Enum.Font.GothamBold,
                        TextSize = 12,
                        TextColor3 = C.text,
                        TextXAlignment = Enum.TextXAlignment.Left,
                        TextTruncate = Enum.TextTruncate.AtEnd,
                    }, pill)
                    chevron(pill)

                    local function display()
                        if multi then
                            local n, only = 0, nil
                            for _, o2 in ipairs(options) do
                                if sel[o2] then
                                    n += 1
                                    only = only or o2
                                end
                            end
                            if n == 0 then
                                vlabel.Text = "None"
                            elseif n == 1 then
                                vlabel.Text = tostring(only)
                            elseif n == #options then
                                vlabel.Text = "All (" .. n .. ")"
                            else
                                vlabel.Text = n .. " selected"
                            end
                        else
                            vlabel.Text = current ~= nil and tostring(current) or "None"
                        end
                    end

                    -- panel opsi: WADAH (kotak berbingkai) berisi search + daftar opsi + footer jumlah terpilih
                    local drop = New("Frame", {
                        Size = UDim2.new(1, 0, 0, 0),
                        BackgroundTransparency = 1,
                        Visible = false,
                        LayoutOrder = 2,
                    }, api._stack)
                    local hasSearch = #options > 10
                    local box = New("Frame", {
                        Position = UDim2.fromOffset(14, 2),
                        Size = UDim2.new(1, -28, 0, 0),
                        BackgroundColor3 = C.panel2,
                        BorderSizePixel = 0,
                    }, drop)
                    Round(box, 10)
                    Stroke(box, C.accentDim, 1, 0.1)
                    local search = New("TextBox", {
                        Position = UDim2.fromOffset(8, 8),
                        Size = UDim2.new(1, -16, 0, 30),
                        BackgroundColor3 = C.bg,
                        BorderSizePixel = 0,
                        Text = "",
                        PlaceholderText = "Search...",
                        PlaceholderColor3 = Color3.fromRGB(95, 104, 130),
                        TextColor3 = C.text,
                        Font = Enum.Font.GothamMedium,
                        TextSize = 12,
                        ClearTextOnFocus = false,
                        Visible = hasSearch,
                    }, box)
                    Round(search, 8)
                    Stroke(search, C.stroke, 1, 0.2)
                    local listF = New("ScrollingFrame", {
                        Position = UDim2.fromOffset(8, 8),
                        Size = UDim2.new(1, -16, 0, 0),
                        BackgroundTransparency = 1,
                        BorderSizePixel = 0,
                        ScrollBarThickness = 3,
                        ScrollBarImageColor3 = C.accentDim,
                        CanvasSize = UDim2.new(0, 0, 0, 0),
                        AutomaticCanvasSize = Enum.AutomaticSize.Y,
                    }, box)
                    List(listF, 4)
                    local foot = New("TextLabel", {
                        Position = UDim2.fromOffset(12, 0),
                        Size = UDim2.new(1, -24, 0, 16),
                        BackgroundTransparency = 1,
                        Text = "",
                        Font = Enum.Font.GothamMedium,
                        TextSize = 11,
                        TextColor3 = C.sub,
                        TextXAlignment = Enum.TextXAlignment.Left,
                    }, box)

                    local function fire(v)
                        if type(p.Callback) == "function" then
                            task.spawn(pcall, p.Callback, v)
                        end
                    end

                    local rebuild
                    rebuild = function()
                        for _, c in ipairs(listF:GetChildren()) do
                            if c:IsA("TextButton") then
                                c:Destroy()
                            end
                        end
                        hasSearch = #options > 10
                        search.Visible = hasSearch
                        local q = hasSearch and string.lower(search.Text) or ""
                        local n = 0
                        local picked = 0
                        for _, o2 in ipairs(options) do
                            if multi and sel[o2] then
                                picked += 1
                            end
                        end
                        for i, opt in ipairs(options) do
                            local name = tostring(opt)
                            if q == "" or string.find(string.lower(name), q, 1, true) then
                                n += 1
                                local on = multi and sel[opt] == true or (not multi and current == opt)
                                local b = New("TextButton", {
                                    Size = UDim2.new(1, -6, 0, 34),
                                    BackgroundColor3 = on and C.accent or C.bg,
                                    BackgroundTransparency = on and 0.86 or 0,
                                    BorderSizePixel = 0,
                                    Text = "",
                                    AutoButtonColor = false,
                                    LayoutOrder = i,
                                }, listF)
                                Round(b, 8)
                                Stroke(b, on and C.accent or C.stroke, 1, on and 0.2 or 0.35)
                                -- indikator: kotak centang (multi) / bulatan radio (single)
                                local ind = New("Frame", {
                                    AnchorPoint = Vector2.new(0, 0.5),
                                    Position = UDim2.new(0, 10, 0.5, 0),
                                    Size = UDim2.fromOffset(16, 16),
                                    BackgroundColor3 = on and C.accent or C.bg,
                                    BorderSizePixel = 0,
                                }, b)
                                if multi then
                                    Round(ind, 4)
                                else
                                    Circle(ind)
                                end
                                Stroke(ind, on and C.accent or C.accentDim, 1.5, 0)
                                if on then
                                    if multi then
                                        local ck = New("Frame", {
                                            Position = UDim2.fromOffset(2, 2),
                                            Size = UDim2.fromOffset(12, 12),
                                            BackgroundTransparency = 1,
                                        }, ind)
                                        New("Frame", {
                                            AnchorPoint = Vector2.new(0.5, 0.5),
                                            Position = UDim2.fromOffset(3, 7),
                                            Size = UDim2.fromOffset(5, 2),
                                            Rotation = 45,
                                            BackgroundColor3 = C.bg,
                                            BorderSizePixel = 0,
                                        }, ck)
                                        New("Frame", {
                                            AnchorPoint = Vector2.new(0.5, 0.5),
                                            Position = UDim2.fromOffset(7, 5.5),
                                            Size = UDim2.fromOffset(9, 2),
                                            Rotation = -50,
                                            BackgroundColor3 = C.bg,
                                            BorderSizePixel = 0,
                                        }, ck)
                                    else
                                        local dot = New("Frame", {
                                            AnchorPoint = Vector2.new(0.5, 0.5),
                                            Position = UDim2.fromScale(0.5, 0.5),
                                            Size = UDim2.fromOffset(6, 6),
                                            BackgroundColor3 = C.bg,
                                            BorderSizePixel = 0,
                                        }, ind)
                                        Circle(dot)
                                    end
                                end
                                New("TextLabel", {
                                    Position = UDim2.fromOffset(34, 0),
                                    Size = UDim2.new(1, -44, 1, 0),
                                    BackgroundTransparency = 1,
                                    Text = name,
                                    Font = on and Enum.Font.GothamBold or Enum.Font.GothamMedium,
                                    TextSize = 12,
                                    TextColor3 = on and C.accent or C.text,
                                    TextXAlignment = Enum.TextXAlignment.Left,
                                    TextTruncate = Enum.TextTruncate.AtEnd,
                                }, b)
                                b.MouseEnter:Connect(function()
                                    if not on then
                                        Tween(b, 0.1, { BackgroundColor3 = C.panel })
                                    end
                                end)
                                b.MouseLeave:Connect(function()
                                    if not on then
                                        Tween(b, 0.1, { BackgroundColor3 = C.bg })
                                    end
                                end)
                                b.MouseButton1Click:Connect(function()
                                    if multi then
                                        sel[opt] = (not sel[opt]) or nil
                                        local arr = {}
                                        for _, o2 in ipairs(options) do
                                            if sel[o2] then
                                                arr[#arr + 1] = o2
                                            end
                                        end
                                        display()
                                        rebuild()
                                        fire(arr)
                                    else
                                        if current == opt and allowNone then
                                            current = nil
                                            display()
                                            fire("")
                                        elseif current ~= opt then
                                            current = opt
                                            display()
                                            fire(opt)
                                        end
                                        open = false
                                        drop.Visible = false
                                        Tween(pst, 0.15, { Color = C.stroke })
                                    end
                                end)
                            end
                        end
                        if multi then
                            foot.Text = string.format("%d dari %d dipilih", picked, #options)
                        else
                            foot.Text = current ~= nil and ("Dipilih: " .. tostring(current)) or "Belum ada yang dipilih"
                        end
                        local listH = math.min(math.max(n, 1) * 38, 190)
                        local top = hasSearch and 38 or 0
                        search.Position = UDim2.fromOffset(8, 8)
                        listF.Position = UDim2.fromOffset(8, 8 + top)
                        listF.Size = UDim2.new(1, -16, 0, listH)
                        foot.Position = UDim2.fromOffset(12, 8 + top + listH + 6)
                        local boxH = 8 + top + listH + 6 + 16 + 8
                        box.Size = UDim2.new(1, -28, 0, boxH)
                        drop.Size = UDim2.new(1, 0, 0, boxH + 10)
                    end
                    search:GetPropertyChangedSignal("Text"):Connect(function()
                        if open then
                            rebuild()
                        end
                    end)

                    local click = rowClick(api._row)
                    local overlay = Hover(api._card, 10)
                    HoverBind(click, overlay)
                    click.MouseButton1Click:Connect(function()
                        open = not open
                        drop.Visible = open
                        Tween(pst, 0.15, { Color = open and C.accent or C.stroke })
                        if open then
                            rebuild()
                        end
                    end)
                    display()

                    function api:Select(v)
                        setValue(v)
                        display()
                        if open then
                            rebuild()
                        end
                    end
                    function api:Refresh(newOptions)
                        options = copyList(newOptions)
                        display()
                        if open then
                            rebuild()
                        end
                    end
                    return api
                end

                table.insert(Window._tabs, tab)
                if #Window._tabs == 1 then
                    task.defer(function()
                        pcall(function()
                            tab:Select()
                        end)
                    end)
                end
                return tab
            end

            return Window
        end

        return Lib
    end)()

    local Lib = {}
    Lib._windows = {}
    Lib.ManualQuickDefaults = {}
    Lib.WindUI = WindUI

    function Lib.Notify(title, content, duration)
        pcall(function()
            WindUI:Notify({
                Title = tostring(title or "Notify"),
                Content = tostring(content or ""),
                Icon = "solar:stars-bold",
                Duration = tonumber(duration) or 3,
            })
        end)
    end

    -- --------------------------------------------------------
    -- Helper
    -- --------------------------------------------------------
    local function call(obj, method, ...)
        if obj == nil then
            return false
        end
        local ok, f = pcall(function()
            return obj[method]
        end)
        if ok and type(f) == "function" then
            return pcall(f, obj, ...)
        end
        return false
    end

    -- Cari frame root dari elemen WindUI (dipakai logic untuk ShowWhen -> .Visible)
    local function resolveFrame(elem)
        if type(elem) ~= "table" then
            return nil
        end
        local function isGui(x)
            return typeof(x) == "Instance" and x:IsA("GuiObject")
        end
        local ok, found = pcall(function()
            if isGui(elem.ElementFrame) then
                return elem.ElementFrame
            end
            local ui = elem.UIElements
            if type(ui) == "table" then
                for _, k in ipairs({ "Container", "Main", "Frame", "Element", "ElementFrame" }) do
                    if isGui(ui[k]) then
                        return ui[k]
                    end
                end
            end
            return nil
        end)
        if ok then
            return found
        end
        return nil
    end

    local function copyList(t)
        local out = {}
        if type(t) == "table" then
            for i, v in ipairs(t) do
                out[i] = v
            end
        end
        return out
    end

    local function safeCreate(kind, factory)
        local ok, res = pcall(factory)
        if ok then
            return res
        end
        warn("[FanKun HUB UI] gagal membuat " .. kind .. ": " .. tostring(res))
        return nil
    end

    -- --------------------------------------------------------
    -- Save / Load config DIHAPUS. Config di bawah hanya stub kosong supaya
    -- widget (toggle / dropdown / slider) tetap jalan tanpa baca/tulis file.
    -- --------------------------------------------------------
    local NONE = "__NONE__"

    local Config = { values = {}, entries = {}, ready = false }
    Lib.Config = Config

    function Config.notify() end
    function Config.applyEntry() end
    function Config.register(_, kind)
        return { kind = kind }
    end

    local TAB_ICONS = {
        ["Dr Scramble"] = "zap",
        ["Informasi"] = "info",
        ["Auto Steal"] = "hand",
        ["Anti AFK"] = "clock",
        ["Butterfly"] = "bug",
        ["Wisp"] = "sparkles",
        ["ESP"] = "eye",
        ["Player"] = "user",
        ["Server Hop"] = "server",
        ["Online"] = "users",
        ["Visual"] = "sun",
        ["Session"] = "solar:chart-2-bold",
        ["Auto Place Egg"] = "package",
        ["Auto Hatch"] = "egg",
        ["Auto Sell"] = "coins",
        ["Auto Sell Pet"] = "paw-print",
        ["Auto Sell Egg"] = "coins",
        ["Auto Favorite"] = "star",
        ["Progress"] = "trending-up",
        ["Anti Lag"] = "battery-charging",
        ["UI"] = "palette",
    }

    -- Kandidat icon cadangan: kalau icon utama tidak ada di icon-pack WindUI,
    -- otomatis dicoba icon berikutnya supaya tab tidak pernah tanpa icon.
    local TAB_ICON_FALLBACK = {
        ["Informasi"] = { "info", "solar:info-circle-bold", "circle-help", "solar:stars-bold" },
        ["Session"] = { "solar:chart-2-bold", "chart-column", "chart-bar", "bar-chart-3", "activity", "solar:graph-up-bold", "solar:stars-bold" },
        ["Auto Place Egg"] = { "package", "box", "solar:box-bold", "solar:stars-bold" },
        ["Auto Hatch"] = { "egg", "sparkles", "solar:stars-bold" },
        ["Auto Sell Pet"] = { "paw-print", "dog", "coins", "solar:wallet-money-bold", "solar:stars-bold" },
        ["Auto Sell Egg"] = { "coins", "badge-dollar-sign", "dollar-sign", "solar:wallet-money-bold", "solar:stars-bold" },
        ["Auto Sell"] = { "coins", "badge-dollar-sign", "dollar-sign", "solar:wallet-money-bold", "solar:stars-bold" },
        ["Auto Favorite"] = { "star", "heart", "solar:star-bold", "solar:stars-bold" },
        ["Progress"] = { "trending-up", "chart-line", "arrow-up", "solar:graph-up-bold", "solar:stars-bold" },
    }
    local function resolveTabIcon(name)
        local cands = TAB_ICON_FALLBACK[name] or { TAB_ICONS[name] or "solar:stars-bold" }
        for _, ic in ipairs(cands) do
            local ok, res = pcall(function()
                local cr = WindUI and WindUI.Creator
                if cr and type(cr.Icon) == "function" then
                    return cr.Icon(ic)
                end
                return true -- API cek tidak ada: pakai kandidat pertama
            end)
            if ok and res then
                return ic
            end
        end
        return cands[#cands]
    end

    -- --------------------------------------------------------
    -- Header section (dibuat malas: baru muncul saat elemen pertama
    -- ditambahkan, supaya urutan tampilan sama dengan urutan elemen)
    -- --------------------------------------------------------
    local function ensureHeader(sec)
        if sec._headerDone then
            return
        end
        sec._headerDone = true
        if sec._showHeader then
            pcall(function()
                sec._tab._w:Section({ Title = tostring(sec.Name or "Section") })
            end)
        end
    end

    -- --------------------------------------------------------
    -- Toggle
    -- --------------------------------------------------------
    local function buildToggle(sec, cfg)
        cfg = cfg or {}
        ensureHeader(sec)
        local wtab = sec._tab._w
        local baseTitle = tostring(cfg.Name or "Toggle")
        local state = cfg.Default == true
        local elem, entry

        local function fire()
            if entry then
                Config.notify(entry)
            end
            if type(cfg.Callback) == "function" then
                task.spawn(pcall, cfg.Callback, state)
            end
        end

        elem = safeCreate("Toggle '" .. baseTitle .. "'", function()
            return wtab:Toggle({
                Title = baseTitle,
                Desc = cfg.Note,
                Value = state,
                Callback = function(v)
                    v = v == true
                    if v == state then
                        return
                    end
                    state = v
                    fire()
                end,
            })
        end)

        local function set(v, silent)
            v = v == true
            state = v
            call(elem, "Set", v)
            if not silent then
                fire()
            end
        end

        local api = {
            _kind = "toggle",
            Name = cfg.Name,
            Instance = resolveFrame(elem),
            Get = function()
                return state
            end,
            Set = function(_, v)
                set(v, false)
            end,
            SetStatus = function(_, status)
                local waiting = tostring(status or ""):lower() == "wait"
                call(elem, "SetTitle", waiting and (baseTitle .. " [WAIT]") or baseTitle)
            end,
        }
        api.GetValue = api.Get
        api.SetValue = api.Set
        api._controller = {
            GetValue = function()
                return state
            end,
            SetValue = function(_, v)
                set(v, false)
            end,
        }

        entry = Config.register(sec, "toggle", cfg.Name, {
            get = function()
                return state
            end,
            apply = function(v)
                if type(v) == "boolean" and v ~= state then
                    set(v, false)
                end
            end,
        })

        if state and type(cfg.Callback) == "function" then
            task.defer(function()
                pcall(cfg.Callback, true)
            end)
        end
        return api
    end

    -- --------------------------------------------------------
    -- Dropdown (single) & MultiDropdown
    -- --------------------------------------------------------
    local function buildSelect(sec, cfg, multi)
        cfg = cfg or {}
        ensureHeader(sec)
        local wtab = sec._tab._w
        local baseTitle = tostring(cfg.Name or "Select")
        local options = copyList(cfg.Options)
        local selected = {}
        local current = nil
        local elem, entry

        if multi then
            local def = cfg.Default
            if type(def) == "table" then
                for k, v in pairs(def) do
                    if v == true and type(k) == "string" then
                        selected[k] = true
                    elseif type(v) == "string" then
                        selected[v] = true
                    end
                end
            elseif def == nil then
                for _, o in ipairs(options) do
                    selected[o] = true
                end
            end
        else
            current = cfg.Default
            if current == nil and options[1] ~= nil then
                current = options[1]
            end
            if cfg.Default == false then
                current = nil -- Default = false -> dropdown mulai kosong ("None")
            end
        end

        local function toArray(set)
            local list = {}
            for _, o in ipairs(options) do
                if set[o] then
                    list[#list + 1] = o
                end
            end
            return list
        end

        local function toSet(v)
            local s = {}
            if type(v) == "table" then
                for k, val in pairs(v) do
                    if type(val) == "string" then
                        s[val] = true
                    elseif type(val) == "table" and type(val.Title) == "string" then
                        s[val.Title] = true
                    elseif val == true and type(k) == "string" then
                        s[k] = true
                    end
                end
            elseif type(v) == "string" then
                s[v] = true
            end
            return s
        end

        local function sameSet(a, b)
            for k in pairs(a) do
                if not b[k] then
                    return false
                end
            end
            for k in pairs(b) do
                if not a[k] then
                    return false
                end
            end
            return true
        end

        local function fire()
            if entry then
                Config.notify(entry)
            end
            if type(cfg.Callback) ~= "function" then
                return
            end
            if multi then
                local copy = {}
                for k, v in pairs(selected) do
                    if v then
                        copy[k] = true
                    end
                end
                task.spawn(pcall, cfg.Callback, copy)
            else
                task.spawn(pcall, cfg.Callback, current)
            end
        end

        elem = safeCreate((multi and "MultiDropdown '" or "Dropdown '") .. baseTitle .. "'", function()
            return wtab:Dropdown({
                Title = baseTitle,
                Desc = cfg.Note,
                Values = options,
                Value = multi and toArray(selected) or current,
                Multi = multi == true,
                AllowNone = true,
                Callback = function(v)
                    if multi then
                        local newSet = toSet(v)
                        if sameSet(newSet, selected) then
                            return
                        end
                        if entry then
                            entry.wantSaved = false
                        end
                        selected = newSet
                        fire()
                    else
                        local val = v
                        if type(val) == "table" then
                            val = val.Title or val[1]
                        end
                        if val == "" then
                            val = nil
                        end
                        if val == current then
                            return
                        end
                        if entry then
                            entry.wantSaved = false
                        end
                        current = val
                        fire()
                    end
                end,
            })
        end)

        local api = {
            _kind = multi and "multidrop" or "dropdown",
            Name = cfg.Name,
            Instance = resolveFrame(elem),
        }
        api.Get = function()
            if multi then
                return selected
            end
            return current
        end
        api.GetValue = api.Get
        api.Set = function(_, v)
            if multi and type(v) == "table" then
                selected = toSet(v)
            elseif not multi then
                current = v
            end
            call(elem, "Select", multi and toArray(selected) or current)
            fire()
        end
        api.SetValue = api.Set
        api.SetOptions = function(_, newOptions, preserveSelection)
            if type(newOptions) ~= "table" then
                return
            end
            local oldSelected = selected
            options = copyList(newOptions)
            if multi then
                local nextSelected = {}
                if preserveSelection ~= false then
                    for _, opt in ipairs(options) do
                        if oldSelected[opt] then
                            nextSelected[opt] = true
                        end
                    end
                end
                selected = nextSelected
            else
                local found = false
                for _, opt in ipairs(options) do
                    if opt == current then
                        found = true
                        break
                    end
                end
                if not found then
                    current = options[1]
                end
            end
            call(elem, "Refresh", options)
            call(elem, "Select", multi and toArray(selected) or current)
            -- opsi baru muncul (mis. daftar dimuat belakangan) -> coba pulihkan nilai tersimpan
            if entry and entry.wantSaved and Config.values[entry.key] ~= nil then
                task.defer(Config.applyEntry, entry, Config.values[entry.key])
            end
        end
        api._controller = {
            GetValue = api.Get,
            SetValue = function(_, v)
                api:Set(v)
            end,
        }

        local function hasOption(o)
            for _, x in ipairs(options) do
                if x == o then
                    return true
                end
            end
            return false
        end

        entry = Config.register(sec, multi and "multi" or "dropdown", cfg.Name, {
            get = function()
                if multi then
                    local list = {}
                    for k, on in pairs(selected) do
                        if on then
                            list[#list + 1] = k
                        end
                    end
                    table.sort(list)
                    return list
                end
                if current == nil then
                    return NONE
                end
                return current
            end,
            apply = function(v)
                if multi then
                    if type(v) ~= "table" then
                        return
                    end
                    local filtered = {}
                    if #options > 0 then
                        for _, s in ipairs(v) do
                            if hasOption(s) then
                                filtered[#filtered + 1] = s
                            end
                        end
                        entry.wantSaved = false
                    else
                        filtered = v
                        entry.wantSaved = true
                    end
                    if sameSet(toSet(filtered), selected) then
                        return
                    end
                    api:Set(filtered)
                else
                    if v == NONE then
                        v = nil
                    end
                    if v ~= nil and #options > 0 and not hasOption(v) then
                        return -- opsi sudah tidak ada
                    end
                    entry.wantSaved = (v ~= nil and #options == 0)
                    if v == current then
                        return
                    end
                    api:Set(v)
                end
            end,
        })
        return api
    end

    -- --------------------------------------------------------
    -- Slider (+ selector Unit sebagai dropdown pendamping)
    -- --------------------------------------------------------
    local function buildSlider(sec, cfg)
        cfg = cfg or {}
        ensureHeader(sec)
        local wtab = sec._tab._w
        local baseTitle = tostring(cfg.Name or "Slider")
        local minV = tonumber(cfg.Min) or 0
        local maxV = tonumber(cfg.Max) or 100
        local increment = tonumber(cfg.Increment) or 1
        local unitCfg = cfg.Unit
        local unitName = type(unitCfg) == "table" and (unitCfg.Default or "")
            or (type(unitCfg) == "string" and unitCfg or "")
        local elem, unitElem, entry, unitEntry

        local function norm(v, fallback)
            v = tonumber(v) or fallback or minV
            if increment and increment > 0 then
                v = math.floor(v / increment + 0.5) * increment
            end
            return math.clamp(v, minV, maxV)
        end

        local value = norm(cfg.Default, minV)

        local function fire()
            if entry then
                Config.notify(entry)
            end
            if type(cfg.Callback) == "function" then
                task.spawn(pcall, cfg.Callback, value)
            end
        end

        local hasUnitSelector = type(unitCfg) == "table" and type(unitCfg.Options) == "table"
        local titleText = baseTitle
        if not hasUnitSelector and unitName ~= "" then
            titleText = baseTitle .. " (" .. unitName .. ")"
        end

        elem = safeCreate("Slider '" .. baseTitle .. "'", function()
            return wtab:Slider({
                Title = titleText,
                Desc = cfg.Note,
                Step = increment,
                Value = { Min = minV, Max = maxV, Default = value },
                Callback = function(v)
                    v = norm(v, value)
                    if v == value then
                        return
                    end
                    if entry then
                        entry.wantSaved = false
                    end
                    value = v
                    fire()
                end,
            })
        end)

        local function setValue(v, silent)
            value = norm(v, value)
            call(elem, "Set", value)
            if not silent then
                fire()
            end
        end

        local api = {
            _kind = "slider",
            Name = cfg.Name,
            Instance = resolveFrame(elem),
            Get = function()
                return value
            end,
            Set = function(_, v)
                setValue(v, false)
            end,
            SetRange = function(_, a, b)
                minV = tonumber(a) or minV
                maxV = tonumber(b) or maxV
                if maxV < minV then
                    maxV = minV
                end
                call(elem, "SetMin", minV)
                call(elem, "SetMax", maxV)
                pcall(function()
                    if type(elem.Value) == "table" then
                        elem.Value.Min = minV
                        elem.Value.Max = maxV
                    end
                end)
                setValue(value, true)
                if entry and entry.wantSaved and Config.values[entry.key] ~= nil then
                    task.defer(Config.applyEntry, entry, Config.values[entry.key])
                end
            end,
        }
        api.GetValue = api.Get
        api.SetValue = api.Set
        api._controller = {
            GetValue = function()
                return value
            end,
            SetValue = function(_, v)
                setValue(v, false)
            end,
        }

        entry = Config.register(sec, "slider", cfg.Name, {
            get = function()
                return value
            end,
            apply = function(v)
                local n = tonumber(v)
                if not n then
                    return
                end
                local target = norm(n, value)
                entry.wantSaved = (target ~= n)
                if target == value then
                    return
                end
                setValue(n, false)
            end,
        })

        if hasUnitSelector then
            local unitOptions = copyList(unitCfg.Options)
            unitElem = safeCreate("Unit '" .. baseTitle .. "'", function()
                return wtab:Dropdown({
                    Title = baseTitle .. " - Unit",
                    Values = unitOptions,
                    Value = unitName ~= "" and unitName or unitOptions[1],
                    Multi = false,
                    AllowNone = false,
                    Callback = function(u)
                        if type(u) == "table" then
                            u = u.Title or u[1]
                        end
                        if u == nil or u == unitName then
                            return
                        end
                        unitName = u
                        if unitEntry then
                            Config.notify(unitEntry)
                        end
                        if type(unitCfg.Callback) == "function" then
                            task.spawn(pcall, unitCfg.Callback, unitName)
                        end
                        if type(cfg.Callback) == "function" then
                            task.spawn(pcall, cfg.Callback, value)
                        end
                    end,
                })
            end)

            unitEntry = Config.register(sec, "unit", tostring(cfg.Name) .. " [unit]", {
                get = function()
                    return unitName
                end,
                apply = function(u)
                    if type(u) ~= "string" or u == unitName then
                        return
                    end
                    unitName = u
                    call(unitElem, "Select", u)
                    if type(unitCfg.Callback) == "function" then
                        task.spawn(pcall, unitCfg.Callback, unitName)
                    end
                    if type(cfg.Callback) == "function" then
                        task.spawn(pcall, cfg.Callback, value)
                    end
                end,
            })

            -- Dropdown unit ikut tampil/sembunyi bersama slider (ShowWhen)
            pcall(function()
                local sf, uf = api.Instance, resolveFrame(unitElem)
                if sf and uf then
                    uf.Visible = sf.Visible
                    sf:GetPropertyChangedSignal("Visible"):Connect(function()
                        uf.Visible = sf.Visible
                    end)
                end
            end)
        end

        return api
    end

    -- --------------------------------------------------------
    -- Text (status label)
    -- --------------------------------------------------------
    local function buildText(sec, cfg)
        cfg = cfg or {}
        ensureHeader(sec)
        local wtab = sec._tab._w
        local name = cfg.Name ~= nil and tostring(cfg.Name) or nil
        local text = tostring(cfg.Text or cfg.Name or "")
        local hasDesc = name ~= nil and cfg.Text ~= nil
        local elem

        elem = safeCreate("Text '" .. tostring(name or text) .. "'", function()
            if hasDesc then
                return wtab:Paragraph({ Title = name, Desc = text })
            end
            return wtab:Paragraph({ Title = text })
        end)

        local function setText(t)
            text = tostring(t)
            if hasDesc then
                call(elem, "SetDesc", text)
            elseif name ~= nil then
                -- Name saja: tampilkan Name sebagai judul, isi baru di deskripsi
                hasDesc = true
                call(elem, "SetTitle", name)
                call(elem, "SetDesc", text)
            else
                call(elem, "SetTitle", text)
            end
        end

        return {
            _kind = "text",
            Name = cfg.Name,
            Instance = resolveFrame(elem),
            Set = function(_, v)
                if type(v) == "table" then
                    if v.Text ~= nil then
                        setText(v.Text)
                    end
                else
                    setText(v)
                end
            end,
            SetText = function(_, t)
                setText(t)
            end,
        }
    end

    -- --------------------------------------------------------
    -- Icon Row: deretan icon (ImageLabel) + angka berwarna.
    -- WindUI tidak punya CreateCanvas, jadi baris ini dibuat manual di atas elemen Paragraph.
    -- cfg.Items = { { Key, Icon ("rbxassetid://..."), Color ("#RRGGBB"), Text } ... }
    -- --------------------------------------------------------
    local function buildIconRow(sec, cfg)
        cfg = cfg or {}
        ensureHeader(sec)
        local wtab = sec._tab._w
        local elem = safeCreate("IconRow", function()
            return wtab:Paragraph({ Title = " " })
        end)
        local frame = resolveFrame(elem)
        local labels = {}
        local built = false

        pcall(function()
            if not frame then
                return
            end
            -- sembunyikan teks/gambar bawaan paragraph, sisakan background-nya
            for _, d in ipairs(frame:GetDescendants()) do
                if d:IsA("TextLabel") or d:IsA("ImageLabel") or d:IsA("TextButton") then
                    d.Visible = false
                end
            end
            frame.AutomaticSize = Enum.AutomaticSize.None
            frame.Size = UDim2.new(frame.Size.X.Scale, frame.Size.X.Offset, 0, cfg.Height or 46)

            local holder = Instance.new("Frame")
            holder.Name = "FKIconRow"
            holder.BackgroundTransparency = 1
            holder.BorderSizePixel = 0
            holder.Size = UDim2.new(1, 0, 1, 0)
            holder.ZIndex = frame.ZIndex + 5

            local layout = Instance.new("UIListLayout")
            layout.FillDirection = Enum.FillDirection.Horizontal
            layout.HorizontalAlignment = Enum.HorizontalAlignment.Left
            layout.VerticalAlignment = Enum.VerticalAlignment.Center
            layout.SortOrder = Enum.SortOrder.LayoutOrder
            layout.Padding = UDim.new(0, 6)
            layout.Parent = holder

            local pad = Instance.new("UIPadding")
            pad.PaddingLeft = UDim.new(0, 12)
            pad.PaddingRight = UDim.new(0, 8)
            pad.Parent = holder

            for index, item in ipairs(cfg.Items or {}) do
                local image = Instance.new("ImageLabel")
                image.Name = "Icon_" .. tostring(item.Key)
                image.BackgroundTransparency = 1
                image.BorderSizePixel = 0
                image.Size = UDim2.fromOffset(28, 28)
                image.Image = tostring(item.Icon or "")
                image.ScaleType = Enum.ScaleType.Fit
                image.ZIndex = holder.ZIndex
                image.LayoutOrder = index * 2 - 1
                image.Parent = holder

                local label = Instance.new("TextLabel")
                label.Name = "Count_" .. tostring(item.Key)
                label.BackgroundTransparency = 1
                label.BorderSizePixel = 0
                label.AutomaticSize = Enum.AutomaticSize.X
                label.Size = UDim2.new(0, 0, 0, 28)
                label.Font = Enum.Font.GothamBold
                label.TextSize = 15
                label.Text = tostring(item.Text or "0")
                label.TextXAlignment = Enum.TextXAlignment.Left
                label.TextColor3 = Color3.fromHex(tostring(item.Color or "#FFFFFF"))
                label.TextStrokeTransparency = 0.7
                label.ZIndex = holder.ZIndex
                label.LayoutOrder = index * 2
                label.Parent = holder
                labels[item.Key] = label

                -- jarak antar kelompok icon
                local gap = Instance.new("UIPadding")
                gap.PaddingRight = UDim.new(0, 8)
                gap.Parent = label
            end

            holder.Parent = frame
            built = true
        end)

        return {
            _kind = "iconrow",
            Instance = frame,
            Built = function()
                return built
            end,
            SetCount = function(_, key, text)
                local label = labels[key]
                if label then
                    label.Text = tostring(text)
                end
            end,
        }
    end

    -- --------------------------------------------------------
    -- Button
    -- --------------------------------------------------------
    local function buildButton(sec, cfg)
        cfg = cfg or {}
        ensureHeader(sec)
        local wtab = sec._tab._w
        local baseTitle = tostring(cfg.Name or "Button")
        local elem = safeCreate("Button '" .. baseTitle .. "'", function()
            return wtab:Button({
                Title = baseTitle,
                Desc = cfg.Note,
                Callback = function()
                    if type(cfg.Callback) == "function" then
                        task.spawn(pcall, cfg.Callback)
                    end
                end,
            })
        end)
        return {
            _kind = "button",
            Name = cfg.Name,
            Instance = resolveFrame(elem),
            Set = function(_, v)
                if type(v) == "string" then
                    call(elem, "SetTitle", v)
                end
            end,
        }
    end

    -- --------------------------------------------------------
    -- Section & Tab
    -- --------------------------------------------------------
    local function createSection(tab, cfg)
        cfg = cfg or {}
        local sec = {
            Name = cfg.Name,
            _tab = tab,
            _showHeader = cfg.Header ~= false,
            _headerDone = false,
        }
        function sec:CreateToggle(c)
            return buildToggle(sec, c)
        end
        function sec:CreateDropdown(c)
            return buildSelect(sec, c, false)
        end
        function sec:CreateMultiDropdown(c)
            return buildSelect(sec, c, true)
        end
        function sec:CreateSlider(c)
            return buildSlider(sec, c)
        end
        function sec:CreateText(c)
            return buildText(sec, c)
        end
        function sec:CreateButton(c)
            return buildButton(sec, c)
        end
        function sec:CreateIconRow(c)
            return buildIconRow(sec, c)
        end
        return sec
    end

    local function makeBtnProxy(wtab)
        local visible = true
        return setmetatable({}, {
            __index = function(_, k)
                if k == "Visible" then
                    return visible
                end
                return nil
            end,
            __newindex = function(_, k, val)
                if k ~= "Visible" then
                    return
                end
                visible = val ~= false
                pcall(function()
                    local ui = wtab.UIElements
                    local item = ui and (ui.Main or ui.TabItem or ui.Item)
                    if typeof(item) == "Instance" then
                        item.Visible = visible
                    end
                end)
            end,
        })
    end

    -- --------------------------------------------------------
    -- Window
    -- --------------------------------------------------------
    function Lib:CreateWindow(cfg)
        cfg = cfg or {}
        local defaultTabName = tostring(cfg.DefaultTab or "Farm")

        -- Tema mengikuti UI_LOGINKEY (bg gelap navy, aksen biru, stroke abu-biru)
        pcall(function()
            WindUI:AddTheme({
                Name = "FanKunLogin",
                Accent = Color3.fromRGB(17, 17, 17),
                Background = Color3.fromRGB(255, 255, 255),
                Outline = Color3.fromRGB(215, 215, 220),
                Text = Color3.fromRGB(12, 12, 12),
                Placeholder = Color3.fromRGB(160, 160, 166),
                Button = Color3.fromRGB(246, 246, 247),
                Icon = Color3.fromRGB(160, 160, 166),
            })
        end)

        local Window = WindUI:CreateWindow({
            Title = "WhiteSCRIPT",
            Author = tostring(cfg.Name or "WhiteSCRIPT"),
            Icon = "rbxassetid://96012031195817",
            Folder = "FanKunHub",
            Theme = "FanKunLogin",
            Size = UDim2.fromOffset(720, 290),
            MinSize = Vector2.new(500, 380),
            MaxSize = Vector2.new(900, 650),
            ToggleKey = Enum.KeyCode.LeftControl,
            Acrylic = false,
            Transparent = false,
            Resizable = true,
            SideBarWidth = 170,

            -- Background image
            Background = "rbxassetid://",
            BackgroundImageTransparency = 0.45,

            -- Avatar player di pojok kiri bawah sidebar
            User = {
                Enabled = true,
                Anonymous = false,
                Callback = function()
                    WindUI:Notify({
                        Title = "Profile",
                        Content = "Halo, " .. Players.LocalPlayer.DisplayName .. "!",
                        Icon = "solar:user-bold",
                        Duration = 3,
                    })
                end,
            },
        })

        -- ==================== FPS & MS TAG (dekat title) ====================
        local alive = true
        local conns = {}

        genvN.FanKunNebula_Cleanup = function()
            alive = false
            for _, c in ipairs(conns) do
                pcall(function()
                    c:Disconnect()
                end)
            end
            pcall(function()
                Window:Destroy()
            end)
        end

        local FPSTag, MSTag
        pcall(function()
            FPSTag = Window:Tag({
                Title = "FPS: --",
                Color = Color3.fromRGB(30, 30, 30),
                Draw = "gauge",
                StripLabel = true,
            })
            MSTag = Window:Tag({
                Title = "MS: --",
                Color = Color3.fromRGB(60, 60, 60),
                Draw = "signal",
                StripLabel = true,
                Suffix = " ms",
            })
        end)

        local lastUpdate = tick()
        local frameCount = 0
        conns[#conns + 1] = RunService.RenderStepped:Connect(function()
            frameCount += 1
            local now = tick()
            if now - lastUpdate >= 1 then
                local fps = math.floor(frameCount / (now - lastUpdate))
                if FPSTag then
                    pcall(function()
                        FPSTag:SetTitle("FPS: " .. fps)
                        if fps >= 55 then
                            FPSTag:SetColor(Color3.fromRGB(0, 150, 80))
                        elseif fps >= 35 then
                            FPSTag:SetColor(Color3.fromRGB(190, 135, 0))
                        else
                            FPSTag:SetColor(Color3.fromRGB(205, 40, 40))
                        end
                    end)
                end
                frameCount = 0
                lastUpdate = now
            end
        end)

        task.spawn(function()
            while alive do
                local success, ping = pcall(function()
                    return math.floor(game:GetService("Stats").Network.ServerStatsItem["Data Ping"]:GetValue())
                end)
                if success and ping and MSTag then
                    pcall(function()
                        MSTag:SetTitle("MS: " .. ping)
                        if ping <= 50 then
                            MSTag:SetColor(Color3.fromRGB(0, 150, 80))
                        elseif ping <= 100 then
                            MSTag:SetColor(Color3.fromRGB(190, 135, 0))
                        elseif ping <= 180 then
                            MSTag:SetColor(Color3.fromRGB(205, 100, 0))
                        else
                            MSTag:SetColor(Color3.fromRGB(205, 40, 40))
                        end
                    end)
                end
                task.wait(1.5)
            end
        end)

        -- ==================== Window API (kompatibel dengan logic) ====================
        local states = {}
        local window = {
            _w = Window,
            _tabs = {},
            _states = states,
            _defaultTabName = defaultTabName,
            _current = nil,
            _defaultTab = nil,
        }

        function window:_selectTab(tab)
            if not tab then
                return
            end
            -- UI baru: jangan langsung membuka isi tab; user memilih sendiri dari menu.
            self._current = tab
        end

        function window:CreateTab(c)
            c = c or {}
            local name = tostring(c.Name or "Tab")
            local wtab = Window:Tab({
                Title = name,
                Icon = resolveTabIcon(name),
            })
            local tab = {
                Name = name,
                _w = wtab,
                _btn = makeBtnProxy(wtab),
            }
            function tab:CreateSection(sc)
                return createSection(tab, sc)
            end
            table.insert(self._tabs, tab)
            if name == defaultTabName then
                self._defaultTab = tab
            end
            if not self._defaultTab and #self._tabs == 1 then
                self._defaultTab = tab
            end
            return tab
        end

        function window:GetDefaultTab()
            return self._defaultTab or self._tabs[1]
        end

        function window:CreateState(c)
            c = c or {}
            local name = tostring(c.Name or "state")
            local val = c.Default
            local api = {
                Name = name,
                Get = function()
                    return val
                end,
                GetValue = function()
                    return val
                end,
                Set = function(_, v)
                    val = v
                end,
                SetValue = function(_, v)
                    val = v
                end,
            }
            states[name] = api
            return api
        end

        local farmTab = window:CreateTab({ Name = defaultTabName, SectionsExpanded = true })
        window._defaultTab = farmTab

        table.insert(Lib._windows, window)

        WindUI:Notify({
            Title = "WhiteSCRIPT",
            Content = "Welcome",
            Icon = "solar:stars-bold",
            Duration = 5,
        })
        print("✨ WhiteSCRIPT loaded!")

        return window
    end


    -- --------------------------------------------------------
    -- Tab "Server Hop"
    -- Daftar server publik game ini (jumlah player + ping), klik untuk langsung join.
    -- Data diambil dari Roblox Games API (lewat request executor).
    -- --------------------------------------------------------
    function Lib:_buildServerHopTab(window)
        if Lib._serverHopBuilt or not window then
            return
        end
        Lib._serverHopBuilt = true

        local TeleportService = game:GetService("TeleportService")
        local HttpSvc = game:GetService("HttpService")
        local LocalPlayer = Players.LocalPlayer

        local tab = window:CreateTab({ Name = "Server Hop" })
        local w = tab._w

        local PLACE_ID = game.PlaceId
        local MAX_PAGES = 3 -- 3 x 100 server
        local HOSTS = { "https://games.roblox.com", "https://games.roproxy.com" }
        local SORT_VALUES = { "Paling sepi dulu", "Paling ramai dulu", "Ping terendah" }

        local sortMode = SORT_VALUES[1]
        local hideFull = true
        local filterMin, filterMax -- nil = tanpa filter jumlah player
        local cacheSig = { Asc = "", Desc = "" } -- filter yang dipakai saat data di-cache
        local DEEP_PAGES = 6 -- halaman maksimal saat filter aktif (6 x 100 server), dikurangi agar tidak freeze
        local warnedOnce = false
        local fetching = false
        local lastFetch = 0
        local cache = { Asc = {}, Desc = {} } -- cache per urutan API (Asc = tersepi dulu, Desc = teramai dulu)
        local statusElem
        local renderFn -- diisi setelah render didefinisikan
        local lastTry -- server terakhir yang dicoba di-join

        local function isFull(sv)
            return sv.maxPlayers > 0 and sv.playing >= sv.maxPlayers
        end

        -- ---------- HTTP ----------
        local function httpGet(url)
            local fns = {}
            if type(request) == "function" then
                fns[#fns + 1] = request
            end
            if type(http_request) == "function" then
                fns[#fns + 1] = http_request
            end
            if type(syn) == "table" and type(syn.request) == "function" then
                fns[#fns + 1] = syn.request
            end
            if type(http) == "table" and type(http.request) == "function" then
                fns[#fns + 1] = http.request
            end
            if type(fluxus) == "table" and type(fluxus.request) == "function" then
                fns[#fns + 1] = fluxus.request
            end

            local lastCode
            for _, f in ipairs(fns) do
                local ok, res = pcall(f, {
                    Url = url,
                    Method = "GET",
                    Headers = { ["Accept"] = "application/json" },
                })
                if ok and type(res) == "table" then
                    local code = tonumber(res.StatusCode or res.status_code or res.Status)
                    local body = res.Body or res.body
                    if type(body) == "string" and (res.Success == true or (code and code >= 200 and code < 300)) then
                        return body, code
                    end
                    lastCode = code or lastCode
                    if code == 429 then
                        return nil, 429
                    end
                end
            end

            local ok, body = pcall(function()
                return game:HttpGet(url)
            end)
            if ok and type(body) == "string" and body ~= "" then
                return body, 200
            end
            return nil, lastCode
        end

        local function fetchServers(order, fMin, fMax, onProgress)
            local pages = (fMin and DEEP_PAGES) or MAX_PAGES
            local lastErr = "Gagal mengambil data server."
            for _, host in ipairs(HOSTS) do
                local list, seen = {}, {}
                local cursor = ""
                local partialErr
                for page = 1, pages do
                    local url = ("%s/v1/games/%d/servers/Public?sortOrder=%s&limit=100%s"):format(
                        host,
                        PLACE_ID,
                        order,
                        cursor ~= "" and ("&cursor=" .. cursor) or ""
                    )
                    task.wait() -- beri frame napas sebelum request
                    local body, code = httpGet(url)
                    task.wait() -- beri frame napas sebelum decode JSON besar
                    if not body then
                        if code == 429 then
                            lastErr = "Terkena rate limit Roblox (429). Tunggu beberapa detik lalu Refresh."
                        else
                            lastErr = "Gagal mengambil data server (kode " .. tostring(code) .. ")."
                        end
                        partialErr = lastErr
                        break
                    end
                    local okJ, data = pcall(function()
                        return HttpSvc:JSONDecode(body)
                    end)
                    if not okJ or type(data) ~= "table" or type(data.data) ~= "table" then
                        lastErr = "Respon server tidak valid."
                        partialErr = lastErr
                        break
                    end
                    task.wait()
                    local pageEdge
                    for _, sv in ipairs(data.data) do
                        if type(sv) == "table" and type(sv.id) == "string" then
                            local pl = tonumber(sv.playing) or 0
                            pageEdge = pl
                            if not seen[sv.id] then
                                seen[sv.id] = true
                                list[#list + 1] = {
                                    id = sv.id,
                                    playing = pl,
                                    maxPlayers = tonumber(sv.maxPlayers) or 0,
                                    ping = tonumber(sv.ping),
                                    fps = tonumber(sv.fps),
                                }
                            end
                        end
                    end
                    if onProgress then
                        pcall(onProgress, page, pages, #list)
                    end
                    -- Filter aktif: berhenti kalau sudah melewati rentang yang dicari
                    if fMin and pageEdge then
                        if order == "Asc" and pageEdge > fMax then
                            break
                        elseif order == "Desc" and pageEdge < fMin then
                            break
                        end
                    end
                    cursor = data.nextPageCursor
                    if type(cursor) ~= "string" or cursor == "" then
                        break
                    end
                    task.wait(0.6)
                end
                if #list > 0 then
                    return list, partialErr
                end
            end
            return {}, lastErr
        end

        -- ---------- Join ----------
        local function joinServer(s)
            if s.id == game.JobId then
                Lib.Notify("Server Hop", "Kamu sudah berada di server ini.", 3)
                return
            end
            lastTry = s
            Lib.Notify("Server Hop", ("Join server %d/%d player... (angka bisa berbeda, data tidak selalu akurat)"):format(math.min(s.playing, s.maxPlayers), s.maxPlayers), 4)
            local ok, err = pcall(function()
                TeleportService:TeleportToPlaceInstance(PLACE_ID, s.id, LocalPlayer)
            end)
            if not ok then
                Lib.Notify("Server Hop", "Gagal teleport: " .. tostring(err), 4)
            end
        end

        pcall(function()
            TeleportService.TeleportInitFailed:Connect(function(plr, _, msg)
                if plr == LocalPlayer then
                    Lib.Notify("Server Hop", "Teleport gagal: " .. tostring(msg or "server penuh / tidak tersedia") .. ". Server disembunyikan, pilih yang lain.", 5)
                    if lastTry then
                        lastTry.bad = true
                        lastTry = nil
                        if renderFn then
                            pcall(renderFn)
                        end
                    end
                end
            end)
        end)

        -- ---------- Render daftar ----------
        local function filterSig()
            if filterMin then
                return filterMin .. ":" .. filterMax
            end
            return ""
        end

        local function ordersNeeded()
            if filterMin then
                -- Filter aktif: ambil dari sisi yang paling dekat dengan jumlah yang dicari
                local maxP = Players.MaxPlayers > 0 and Players.MaxPlayers or 8
                if (filterMin + math.min(filterMax, maxP)) / 2 <= maxP / 2 then
                    return { "Asc" }
                end
                return { "Desc" }
            end
            if sortMode == "Paling ramai dulu" then
                return { "Desc" }
            elseif sortMode == "Ping terendah" then
                return { "Asc", "Desc" }
            end
            return { "Asc" }
        end

        local function mergedServers(orders)
            local out, seen = {}, {}
            for _, o in ipairs(orders) do
                for _, sv in ipairs(cache[o]) do
                    if not seen[sv.id] then
                        seen[sv.id] = true
                        out[#out + 1] = sv
                    end
                end
            end
            return out
        end

        local function hasCache(orders)
            for _, o in ipairs(orders) do
                if #cache[o] == 0 or cacheSig[o] ~= filterSig() then
                    return false
                end
            end
            return true
        end

        local function sortedView()
            local view = {}
            for _, s in ipairs(mergedServers(ordersNeeded())) do
                local cp = s.maxPlayers > 0 and math.min(s.playing, s.maxPlayers) or s.playing
                local passFilter = not filterMin or (cp >= filterMin and cp <= filterMax)
                if passFilter and not s.bad and not (hideFull and isFull(s)) then
                    view[#view + 1] = s
                end
            end
            table.sort(view, function(a, b)
                if sortMode == "Paling ramai dulu" then
                    if a.playing ~= b.playing then
                        return a.playing > b.playing
                    end
                elseif sortMode == "Ping terendah" then
                    local pa, pb = a.ping or 99999, b.ping or 99999
                    if pa ~= pb then
                        return pa < pb
                    end
                else
                    if a.playing ~= b.playing then
                        return a.playing < b.playing
                    end
                end
                return (a.ping or 99999) < (b.ping or 99999)
            end)
            return view
        end

        local function filterLabel()
            if not filterMin then
                return "Semua jumlah player"
            elseif filterMin == filterMax then
                return filterMin .. " player"
            elseif filterMax >= 99 then
                return filterMin .. " player ke atas"
            end
            return filterMin .. "-" .. filterMax .. " player"
        end

        local function statusText(shown, err)
            local cur = ("%d/%d"):format(#Players:GetPlayers(), Players.MaxPlayers)
            local line = ("Server kamu: %s player (live)\nFilter: %s | Data %d server, cocok %d"):format(
                cur,
                filterLabel(),
                #mergedServers(ordersNeeded()),
                shown
            )
            if lastFetch > 0 then
                line = line .. " | Diperbarui " .. os.date("%H:%M:%S")
            end
            if shown == 0 and lastFetch > 0 and not err then
                if filterMin then
                    line = line .. "\nTidak ada server dengan " .. filterLabel() .. " di data yang terambil. Coba Refresh atau ubah filter."
                else
                    line = line .. "\nTidak ada server yang cocok."
                end
            end
            if err then
                line = line .. "\n⚠ " .. err
            end
            line = line .. "\nℹ Jumlah player dari Roblox tidak selalu akurat (data tertunda)."
            return line
        end

        local function render(err)
            local shown = #sortedView()
            call(statusElem, "SetDesc", statusText(shown, err))
        end

        renderFn = render

        local function refresh()
            if fetching then
                return
            end
            fetching = true
            call(statusElem, "SetDesc", filterMin and "Mencari server sesuai filter (bisa agak lama)..." or "Mengambil daftar server...")
            task.spawn(function()
                local err
                local orders = ordersNeeded()
                local sig = filterSig()
                local fMin, fMax = filterMin, filterMax
                for i, order in ipairs(orders) do
                    local list, e = fetchServers(order, fMin, fMax, function(pg, total, count)
                        call(statusElem, "SetDesc", ("Mengambil server... halaman %d/%d (%d server)"):format(pg, total, count))
                    end)
                    if #list > 0 then
                        cache[order] = list
                        cacheSig[order] = sig
                    end
                    if e then
                        err = e
                    end
                    if i < #orders then
                        task.wait(1)
                    end
                end
                lastFetch = os.clock()
                local okR, errR = pcall(render, err)
                if not okR then
                    warn("[FanKun Server Hop] render gagal: " .. tostring(errR))
                end
                if not warnedOnce then
                    warnedOnce = true
                    Lib.Notify("Server Hop", "Perhatian: jumlah player dari Roblox tidak selalu akurat, bisa berbeda saat kamu masuk.", 6)
                end
                fetching = false
            end)
        end

        -- ---------- UI statis ----------
        pcall(function()
            w:Section({ Title = "Hop Server" })
        end)

        safeCreate("ServerHop warning", function()
            return w:Paragraph({
                Title = "⚠ Tidak selalu akurat",
                Desc = "Jumlah player berasal dari data Roblox yang tertunda. Angkanya bisa berbeda dari kondisi asli, dan server bisa sudah penuh/hilang saat kamu klik join. Tekan Refresh sebelum memilih.",
            })
        end)

        statusElem = safeCreate("ServerHop status", function()
            return w:Paragraph({ Title = "Status", Desc = "Menunggu..." })
        end)

        safeCreate("ServerHop Filter", function()
            return w:Input({
                Title = "Filter jumlah player",
                Desc = "Contoh: 2 (tepat 2 orang), 2-4 (rentang), 3+ (3 ke atas). Kosongkan untuk semua. Tekan Enter untuk mencari.",
                Value = "",
                Placeholder = "contoh: 2",
                Callback = function(text)
                    local t = (tostring(text or ""):gsub("%s", ""))
                    local a, b
                    if t == "" then
                        a, b = nil, nil
                    elseif t:match("^%d+%-%d+$") then
                        local x, y = t:match("^(%d+)%-(%d+)$")
                        a, b = tonumber(x), tonumber(y)
                        if a > b then
                            a, b = b, a
                        end
                    elseif t:match("^%d+%+$") then
                        a, b = tonumber(t:match("^(%d+)%+$")), 99
                    elseif t:match("^%d+$") then
                        a = tonumber(t)
                        b = a
                    else
                        Lib.Notify("Server Hop", "Format filter tidak valid. Pakai: 2, 2-4, atau 3+", 4)
                        return
                    end
                    if a == filterMin and b == filterMax then
                        return
                    end
                    filterMin, filterMax = a, b
                    if hasCache(ordersNeeded()) then
                        task.defer(pcall, render)
                    else
                        task.delay(0.25, refresh)
                    end
                end,
            })
        end)

        safeCreate("ServerHop Refresh", function()
            return w:Button({
                Title = "Refresh Server",
                Desc = "Ambil ulang daftar server publik game ini.",
                Icon = "refresh-cw",
                Callback = function()
                    if fetching then
                        Lib.Notify("Server Hop", "Masih mengambil data...", 2)
                        return
                    end
                    if os.clock() - lastFetch < 3 then
                        Lib.Notify("Server Hop", "Tunggu beberapa detik sebelum refresh lagi.", 2)
                        return
                    end
                    refresh()
                end,
            })
        end)

        safeCreate("ServerHop Quick", function()
            return w:Button({
                Title = "Hop Server",
                Desc = "Pindah ke server yang sepi (player paling sedikit). Kalau filter jumlah player diisi, hanya server yang cocok.",
                Icon = "zap",
                Callback = function()
                    if fetching then
                        Lib.Notify("Server Hop", "Masih mengambil data, coba lagi sebentar.", 2)
                        return
                    end
                    if not hasCache(ordersNeeded()) then
                        Lib.Notify("Server Hop", "Belum ada data. Tekan Refresh Server dulu.", 3)
                        return
                    end
                    local best
                    for _, sv in ipairs(sortedView()) do
                        if sv.id ~= game.JobId then
                            best = sv
                            break
                        end
                    end
                    if best then
                        joinServer(best)
                    else
                        Lib.Notify("Server Hop", "Tidak ada server yang cocok. Coba Refresh atau ubah filter.", 3)
                    end
                end,
            })
        end)

        -- Ambil otomatis sekali saat script dimuat
        task.delay(2, refresh)
    end



    -- --------------------------------------------------------
    -- Tab "Online": pengguna hub yang sedang online + join ke servernya
    -- Data dari /online_users (heartbeat tiap 5 detik oleh script).
    -- --------------------------------------------------------
    function Lib:_buildOnlineTab(window)
        if Lib._onlineBuilt or not window then
            return
        end
        Lib._onlineBuilt = true

        local TeleportService = game:GetService("TeleportService")
        local HttpSvc = game:GetService("HttpService")
        local LocalPlayer = Players.LocalPlayer
        local FIREBASE = "https://fankunhub-6fb0b-default-rtdb.asia-southeast1.firebasedatabase.app"
        local ACTIVE_WINDOW = 45 -- detik; dianggap online bila last_seen sebaru ini
        local REFRESH_EVERY = 30

        local tab = window:CreateTab({ Name = "Online" })
        local w = tab._w
        local rows = {}
        local statusElem
        local fetching = false
        local alive = true
        local lastAt = 0

        local prevCleanup = genvN.FanKunNebula_Cleanup
        genvN.FanKunNebula_Cleanup = function()
            alive = false
            if type(prevCleanup) == "function" then
                pcall(prevCleanup)
            end
        end

        local function clearRows()
            for _, e in ipairs(rows) do
                local destroyed = call(e, "Destroy")
                if not destroyed then
                    local f = resolveFrame(e)
                    if f then
                        pcall(function()
                            f.Visible = false
                        end)
                    end
                end
            end
            rows = {}
        end

        local function fetchOnline()
            local body, code = Lib._request({ Url = FIREBASE .. "/online_users.json", Method = "GET" })
            if not body then
                return nil, "Gagal mengambil data online (kode " .. tostring(code) .. ")."
            end
            local ok, data = pcall(function()
                return HttpSvc:JSONDecode(body)
            end)
            if not ok then
                return nil, "Respon tidak valid."
            end
            if type(data) ~= "table" then
                return {}, nil
            end
            local now = os.time()
            local list = {}
            for uid, sessions in pairs(data) do
                if type(sessions) == "table" then
                    local best
                    for _, s in pairs(sessions) do
                        if type(s) == "table" then
                            local ls = tonumber(s.last_seen) or 0
                            if now - ls <= ACTIVE_WINDOW and (not best or ls > best.ls) then
                                best = {
                                    ls = ls,
                                    username = tostring(s.username or "?"),
                                    display = tostring(s.display_name or s.username or "?"),
                                    userId = tonumber(s.user_id) or tonumber(uid) or 0,
                                    placeId = tonumber(s.place_id) or 0,
                                    jobId = tostring(s.job_id or ""),
                                }
                            end
                        end
                    end
                    if best and best.userId ~= LocalPlayer.UserId then
                        list[#list + 1] = best
                    end
                end
            end
            table.sort(list, function(a, b)
                return a.display:lower() < b.display:lower()
            end)
            return list, nil
        end

        local function joinUser(u)
            if u.jobId == "" or u.placeId == 0 then
                Lib.Notify("Online", "Data server user ini tidak lengkap.", 3)
                return
            end
            if u.jobId == game.JobId then
                Lib.Notify("Online", "Kamu sudah satu server dengan " .. u.display .. ".", 3)
                return
            end
            Lib.Notify("Online", "Join ke server " .. u.display .. "...", 3)
            local ok, err = pcall(function()
                TeleportService:TeleportToPlaceInstance(u.placeId, u.jobId, LocalPlayer)
            end)
            if not ok then
                Lib.Notify("Online", "Gagal teleport: " .. tostring(err), 4)
            end
        end

        local function refresh()
            if fetching then
                return
            end
            fetching = true
            call(statusElem, "SetDesc", "Mengambil daftar pengguna online...")
            task.spawn(function()
                local list, err = fetchOnline()
                clearRows()
                if list then
                    lastAt = os.clock()
                    for _, u in ipairs(list) do
                        local same = u.jobId == game.JobId
                        local title = u.display
                        if u.display:lower() ~= u.username:lower() then
                            title = title .. "  (@" .. u.username .. ")"
                        end
                        local desc = ("Server %s  |  %s%s"):format(
                            u.jobId ~= "" and u.jobId:sub(1, 8) or "?",
                            u.placeId == game.PlaceId and "game ini" or ("place " .. u.placeId),
                            same and "  |  satu server denganmu" or ""
                        )
                        local elem = safeCreate("Online row", function()
                            return w:Button({
                                Title = title,
                                Desc = desc,
                                Icon = "user",
                                Callback = function()
                                    joinUser(u)
                                end,
                            })
                        end)
                        if not elem then
                            elem = safeCreate("Online row (tanpa icon)", function()
                                return w:Button({
                                    Title = title,
                                    Desc = desc,
                                    Callback = function()
                                        joinUser(u)
                                    end,
                                })
                            end)
                        end
                        if elem then
                            rows[#rows + 1] = elem
                        end
                    end
                    call(
                        statusElem,
                        "SetDesc",
                        ("%d pengguna hub online (selain kamu) | Diperbarui %s\nPresence diperbarui tiap 5 detik. Server bisa sudah berubah saat kamu klik."):format(
                            #list,
                            os.date("%H:%M:%S")
                        )
                    )
                else
                    call(statusElem, "SetDesc", "⚠ " .. tostring(err))
                end
                fetching = false
            end)
        end

        pcall(function()
            w:Section({ Title = "Pengguna Hub Online" })
        end)
        statusElem = safeCreate("Online status", function()
            return w:Paragraph({ Title = "Status", Desc = "Menunggu..." })
        end)
        safeCreate("Online refresh", function()
            return w:Button({
                Title = "Refresh",
                Desc = "Ambil ulang daftar pengguna online. Otomatis diperbarui tiap 30 detik.",
                Icon = "refresh-cw",
                Callback = function()
                    if os.clock() - lastAt < 2 then
                        return
                    end
                    refresh()
                end,
            })
        end)
        pcall(function()
            w:Section({ Title = "Daftar (klik untuk join ke servernya)" })
        end)

        task.spawn(function()
            task.wait(2)
            while alive do
                refresh()
                task.wait(REFRESH_EVERY)
            end
        end)
    end

    -- HTTP helper bersama (dipakai tab Online)
    function Lib._request(opts)
        local url = tostring(opts.Url or "")
        if url == "" then
            return nil
        end
        local method = tostring(opts.Method or "GET")
        local headers = opts.Headers or { ["Accept"] = "application/json" }
        if opts.Body and not headers["Content-Type"] then
            headers["Content-Type"] = "application/json"
        end
        local fns = {}
        if type(request) == "function" then
            fns[#fns + 1] = request
        end
        if type(http_request) == "function" then
            fns[#fns + 1] = http_request
        end
        if type(syn) == "table" and type(syn.request) == "function" then
            fns[#fns + 1] = syn.request
        end
        if type(http) == "table" and type(http.request) == "function" then
            fns[#fns + 1] = http.request
        end
        if type(fluxus) == "table" and type(fluxus.request) == "function" then
            fns[#fns + 1] = fluxus.request
        end
        local lastCode
        for _, f in ipairs(fns) do
            local ok, res = pcall(f, { Url = url, Method = method, Headers = headers, Body = opts.Body })
            if ok and type(res) == "table" then
                local code = tonumber(res.StatusCode or res.status_code or res.Status)
                local body = res.Body or res.body
                if type(body) == "string" and (res.Success == true or (code and code >= 200 and code < 300)) then
                    return body, code
                end
                lastCode = code or lastCode
                if code == 429 then
                    return nil, 429
                end
            end
        end
        if method == "GET" then
            local ok, body = pcall(function()
                return game:HttpGet(url)
            end)
            if ok and type(body) == "string" and body ~= "" then
                return body, 200
            end
        end
        return nil, lastCode
    end

    function Lib:Finalize(cfg)
        cfg = cfg or {}
        if cfg.Window then
            for _, builder in ipairs({ "_buildServerHopTab", "_buildOnlineTab" }) do
                pcall(function()
                    Lib[builder](Lib, cfg.Window)
                end)
            end
        end
        if cfg.Window and cfg.MainTab then
            pcall(function()
                cfg.Window:_selectTab(cfg.MainTab)
            end)
        end
        return true
    end

    v = Lib
end

