-- ============================================================
-- [FanKun FIX] Shim modul Save.
-- Game versi baru bisa mengganti nama fungsi modul Save (Get -> Peek, FieldSignal -> Watch, dst).
-- Akibatnya Auto Sell Pet, Progress, Auto Favorite dll yang memakai tbl.Save.Get()/FieldSignal()
-- tidak mendapat data. Shim ini mencoba beberapa nama fungsi secara dinamis.
-- ============================================================
do
    local rawSave = tbl.Save
    if rawSave == nil then
        pcall(function()
            local shared = ReplicatedStorage:FindFirstChild("Shared")
            local m = shared and shared:FindFirstChild("Save", true)
            if m and m:IsA("ModuleScript") then
                rawSave = require(m)
            end
        end)
    end
    if type(rawSave) == "table" then
        local GET = { "Get", "Peek", "GetData", "GetSave", "GetAll", "GetState", "Snapshot" }
        local SIG = { "FieldSignal", "Watch", "Observe", "GetFieldSignal", "OnField", "Signal" }
        local cachedGet

        local function field(k)
            local ok, v = pcall(function()
                return rawSave[k]
            end)
            if ok then
                return v
            end
            return nil
        end

        local function looksLikeSave(t)
            return type(t) == "table"
                and (t.Inventory ~= nil or t.EggInventory ~= nil or t.Money ~= nil or t.EquippedAssets ~= nil)
        end

        local function callGet()
            local order = {}
            if cachedGet then
                order[1] = cachedGet
            end
            for _, n in ipairs(GET) do
                if n ~= cachedGet then
                    order[#order + 1] = n
                end
            end
            local fallback
            for _, n in ipairs(order) do
                local f = field(n)
                if type(f) == "function" then
                    for style = 1, 2 do
                        local ok, r
                        if style == 1 then
                            ok, r = pcall(f)
                        else
                            ok, r = pcall(f, rawSave)
                        end
                        if ok and type(r) == "table" then
                            if looksLikeSave(r) then
                                cachedGet = n
                                return r
                            end
                            fallback = fallback or r
                        end
                    end
                end
            end
            if looksLikeSave(rawSave) then
                return rawSave
            end
            local d = field("Data")
            if looksLikeSave(d) then
                return d
            end
            return fallback
        end

        local function callSignal(name)
            for _, n in ipairs(SIG) do
                local f = field(n)
                if type(f) == "function" then
                    for style = 1, 2 do
                        local ok, r
                        if style == 1 then
                            ok, r = pcall(f, name)
                        else
                            ok, r = pcall(f, rawSave, name)
                        end
                        if ok and type(r) == "table" and type(r.Connect) == "function" then
                            return r
                        end
                    end
                end
            end
            return nil
        end

        tbl.Save = setmetatable({
            Get = callGet,
            FieldSignal = callSignal,
            _raw = rawSave,
        }, { __index = rawSave })

        tbl.SaveDiag = function()
            local names = {}
            pcall(function()
                for k, v in pairs(rawSave) do
                    names[#names + 1] = tostring(k) .. ":" .. type(v)
                end
            end)
            table.sort(names)
            if #names == 0 then
                return "(kosong / tidak bisa dibaca)"
            end
            while #names > 14 do
                table.remove(names)
            end
            return table.concat(names, ", ")
        end
    end
end

