                return child
            end
            local magnitude = (v16.Position - v14).Magnitude

            if magnitude < huge then
                v15 = child
                huge = magnitude
            end
        end
    end

    if v15 and huge <= 60 then
        return v15
    end
    return nil
end

tbl4.Belt = function()
    local v13 = tbl4.Plot()
    if not v13 then
        return nil
    end
    local treadmillBottom = v13:FindFirstChild("TreadmillBottom")
    if treadmillBottom and treadmillBottom:IsA("BasePart") then
        return treadmillBottom
    end
    local clientTreadmillRenders = workspace:FindFirstChild("__ClientTreadmillRenders")
    clientTreadmillRenders = clientTreadmillRenders
        and clientTreadmillRenders:FindFirstChild("TreadmillRender_" .. v13.Name)
    local primaryPart

    if clientTreadmillRenders then
        local boundingBoxPart = clientTreadmillRenders:FindFirstChild("BoundingBoxPart")

        if boundingBoxPart then
            primaryPart = boundingBoxPart
        else
            primaryPart = clientTreadmillRenders:IsA("Model") and clientTreadmillRenders.PrimaryPart
        end

        primaryPart = primaryPart or clientTreadmillRenders:FindFirstChildWhichIsA("BasePart")
    else
        primaryPart = clientTreadmillRenders
    end

    if primaryPart then
        return primaryPart
    end
    local treadmillUpgrade = v13:FindFirstChild("TreadmillUpgrade")
    treadmillUpgrade = treadmillUpgrade and treadmillUpgrade:FindFirstChildWhichIsA("BasePart")
    treadmillUpgrade = treadmillUpgrade or nil
    return treadmillUpgrade
end

tbl4.DistanceTo = function(arg)
    local v13 = tbl4.Root()
    if not v13 or not arg then
        return math.huge
    end
    return (v13.Position - arg).Magnitude
end

do
    local tbl6 = {}
    local n = 0

    local function fn9()
        local v13 = tbl4.Plot()
        if not v13 then
            return {}
        end
        local tbl7 = {}

        for _, v14 in ipairs({ "TreadmillBottom", "TreadmillUpgrade" }) do
            local v15 = v13:FindFirstChild(v14)

            if v15 then
                if v15:IsA("BasePart") then
                    table.insert(tbl7, v15)
                else
                    for _, descendant in ipairs(v15:GetDescendants()) do
                        if descendant:IsA("BasePart") then
                            table.insert(tbl7, descendant)
                        end
                    end
                end
            end
        end

        local clientTreadmillRenders = workspace:FindFirstChild("__ClientTreadmillRenders")
        clientTreadmillRenders = clientTreadmillRenders
            and clientTreadmillRenders:FindFirstChild("TreadmillRender_" .. v13.Name)

        if clientTreadmillRenders then
            for _, descendant in ipairs(clientTreadmillRenders:GetDescendants()) do
                if descendant:IsA("BasePart") then
                    table.insert(tbl7, descendant)
                end
            end
        end

        return tbl7
    end

    local function fn10()
        for _, v13 in ipairs(fn9()) do
            if not tbl6[v13] then
                tbl6[v13] = {
                    CFrame = v13.CFrame,
                    CanTouch = v13.CanTouch,
                    CanCollide = v13.CanCollide,
                    Transparency = v13.Transparency,
                }

                pcall(function()
                    v13.CanTouch = false
                    v13.CanCollide = false
                    v13.Transparency = 1
                    v13.CFrame = v13.CFrame - Vector3.new(0, 120, 0)
                end)
            end
        end
    end

    local function fn11()
        for k, v13 in pairs(tbl6) do
            if k and k.Parent then
                pcall(function()
                    k.CFrame = v13.CFrame
                    k.CanTouch = v13.CanTouch
                    k.CanCollide = v13.CanCollide
                    k.Transparency = v13.Transparency
                end)
            end
        end

        table.clear(tbl6)
    end

    tbl4.HoldBelt = function()
        n = n + 1
        fn10()
    end

    tbl4.ReleaseBelt = function()
        n = math.max(0, n - 1)

        if n == 0 then
            fn11()
        end
    end

    tbl4.BeltHeld = function()
        return n > 0
    end

    tbl4.RefreshBeltHide = function()
        if n > 0 then
            fn10()
        end
    end

    fn6(function()
        n = 0
        fn11()
    end)

    tbl4.LeaveBelt = function()
        local rfTreadmillAskDoff = networking:FindFirstChild("RF/Treadmill/AskDoff")

        if rfTreadmillAskDoff and rfTreadmillAskDoff:IsA("RemoteFunction") then
            pcall(rfTreadmillAskDoff.InvokeServer, rfTreadmillAskDoff)
        end
    end

    tbl4.Treadmill = { Riding = false }

    tbl4.ResetBelt = function()
        n = 0
        fn11()
    end

    tbl4.OnBelt = function()
        local v13 = tbl4.Belt()
        if not v13 or tbl6[v13] then
            return false
        end
        local v14 = tbl4.Root()
        if not v14 then
            return false
        end
        local v15 = v13.CFrame:PointToObjectSpace(v14.Position)
        local n2 = v13.Size.X / 2 + 2
        local flag = math.abs(v15.X) <= n2
        local flag2

        if flag then
            local n3 = v13.Size.Z / 2 + 2
            flag2 = math.abs(v15.Z) <= n3
        else
            flag2 = flag
        end

        flag2 = flag2 and v15.Y >= -2
        flag2 = flag2 and v15.Y <= v13.Size.Y / 2 + 8
        return flag2
    end
end

tbl4.ExitBelt = function()
    tbl4.Treadmill.Riding = false
    tbl4.LeaveBelt()
    local character = localPlayer.Character
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")

    if humanoid then
        pcall(function()
            humanoid.Jump = true
            humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
        end)
    end

    task.wait(0.35)
end

-- ============================================================
-- Anti AFK (Auto Treadmill) — from ChilliHub treadmill logic
-- Stay on treadmill while idle / Auto Steal WAIT.
-- When steal finds a target it already calls ExitBelt + ClaimMovement.
-- ============================================================
do
    local REACH_DIST = 8
    local STAY_RECHECK = 5
    local AFK_GEN = 0
    local busyMount = false
    local stopped = false
    local treadmill = tbl4.Treadmill
    local toggleAfk = nil
    local toggleStay = nil
    local groundedFails = 0
    local undidSwap = false
    -- true while Anti AFK itself is flying/walking to the belt
    local selfNavigating = false

    local function invokeWear()
        local rf = networking:FindFirstChild("RF/Treadmill/AskWearStill")
        if not rf or not rf:IsA("RemoteFunction") then
            return false, nil, nil
        end
        local ok, result, result2 = pcall(rf.InvokeServer, rf)
        return ok, result, result2
    end

    local function acceptWear(ok, result, errMsg)
        if ok and result ~= false then
            groundedFails = 0
            undidSwap = false
            return true
        end
        if ok and tostring(errMsg) == "Already using treadmill" then
            groundedFails = 0
            undidSwap = false
            return true
        end
        -- Some executors only return a string error as `result`
        if ok and type(result) == "string" then
            if result == "Already using treadmill" then
                groundedFails = 0
                undidSwap = false
                return true
            end
            errMsg = result
        end
        if (not ok or tostring(errMsg) == "Not grounded" or tostring(result) == "Not grounded")
            and tbl4.Grounded() then
            groundedFails = groundedFails + 1
            if groundedFails >= 2 then
                groundedFails = 0
                if not undidSwap then
                    undidSwap = true
                    pcall(tbl4.UndoSwap)
                elseif type(tbl4.RequestRespawn) == "function" then
                    undidSwap = false
                    pcall(tbl4.RequestRespawn)
                end
            end
        end
        return false
    end

    local function afkEnabled()
        return tbl4.Toggle(toggleAfk, false) == true
    end

    local function stayEnabled()
        return tbl4.Toggle(toggleStay, true) ~= false
    end

    -- Busy = steal/other features need control.
    -- IMPORTANT: ignore Flying/Driving while selfNavigating (our own path to belt).
    local function isBusy()
        local movement = tbl4.Movement
        if tbl4.Steal.Active or tbl4.Steal.Carrying then
            return true
        end
        if not selfNavigating then
            if tbl4.Flying or (tbl4.Driving and tbl4.Driving > 0) then
                return true
            end
        end
        if movement.PlaceWanted or movement.StealFirst
            or movement.MutationWanted or movement.FracturedWanted
            or movement.ScrambleWanted then
            return true
        end
        if movement.Owner ~= nil and movement.Owner ~= "treadmill" then
            return true
        end
        return false
    end

    local function cancelMount(gen)
        if gen ~= AFK_GEN or not afkEnabled() then
            return true
        end
        if tbl4.Steal.Active or tbl4.Steal.Carrying then
            return true
        end
        local owner = tbl4.Movement.Owner
        if owner ~= nil and owner ~= "treadmill" then
            return true
        end
        return false
    end

    local function beltTarget()
        local belt = tbl4.Belt()
        if not belt then
            return nil, nil
        end
        local top = belt.Position + Vector3.new(0, belt.Size.Y / 2 + 2.5, 0)
        return belt, top
    end

    -- Fast flight to belt (FanKun may not have FlyTo)
    local function flyToPoint(target, gen)
        local root = tbl4.Root()
        if not root then
            return false
        end
        selfNavigating = true
        pcall(tbl4.BeginFlight)
        local deadline = os.clock() + 10
        local ok = false
        while os.clock() < deadline do
            if cancelMount(gen) then
                break
            end
            root = tbl4.Root()
            if not root then
                break
            end
            local delta = target - root.Position
            local dist = delta.Magnitude
            if dist <= 4.5 then
                pcall(function()
                    root.CFrame = CFrame.new(target)
                    root.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                end)
                ok = true
                break
            end
            local speed = math.clamp(dist * 6, 60, 160)
            pcall(tbl4.SetFlightVelocity, delta.Unit * speed)
            RunService.Heartbeat:Wait()
        end
        pcall(tbl4.EndFlight)
        selfNavigating = false
        return ok or tbl4.DistanceTo(target) <= REACH_DIST
    end

    local function reachBelt(gen)
        local belt, target = beltTarget()
        if not belt or not target then
            return false
        end
        if tbl4.DistanceTo(target) <= REACH_DIST then
            return true
        end
        if type(tbl4.FlyTo) == "function" then
            selfNavigating = true
            local ok, res = pcall(tbl4.FlyTo, target, function()
                return cancelMount(gen)
            end, "treadmill")
            selfNavigating = false
            if ok and res == true then
                return true
            end
        end
        if flyToPoint(target, gen) then
            return true
        end
        if type(tbl4.WalkTo) == "function" then
            selfNavigating = true
            local ok, res = pcall(tbl4.WalkTo, target, 5, 10, function()
                return cancelMount(gen)
            end)
            selfNavigating = false
            if ok and res == true then
                return true
            end
        end
        return tbl4.DistanceTo(target) <= REACH_DIST
    end

    local function mountBelt(gen)
        if cancelMount(gen) then
            return false
        end
        if not tbl4.ClaimMovement("treadmill") then
            return false
        end
        if tbl4.BeltHeld and tbl4.BeltHeld() then
            pcall(tbl4.ResetBelt)
        end
        if not reachBelt(gen) then
            return false
        end
        if cancelMount(gen) then
            return false
        end
        -- Settle on belt briefly so server accepts grounded wear
        local root = tbl4.Root()
        local _, target = beltTarget()
        if root and target then
            pcall(function()
                root.CFrame = CFrame.new(target)
                root.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
            end)
            task.wait(0.12)
        end
        local ok, result, errMsg = invokeWear()
        local worn = acceptWear(ok, result, errMsg)
        if not worn then
            -- one quick retry
            task.wait(0.2)
            ok, result, errMsg = invokeWear()
            worn = acceptWear(ok, result, errMsg)
        end
        treadmill.Riding = worn == true
        return treadmill.Riding
    end

    local function tryMountNow(reason)
        if busyMount or not afkEnabled() then
            return
        end
        if tbl4.Steal.Active or tbl4.Steal.Carrying then
            return
        end
        if treadmill.Riding and tbl4.OnBelt() then
            return
        end
        busyMount = true
        local gen = AFK_GEN
        task.spawn(function()
            local ok, result = pcall(mountBelt, gen)
            local success = ok and result == true
            treadmill.LastFailed = not success
            treadmill.NextTry = os.clock() + (success and 2 or 1.25)
            if tbl4.Movement.Owner == "treadmill" then
                tbl4.ReleaseMovement("treadmill")
            end
            busyMount = false
            if success then
                pcall(function()
                    if Lib and type(Lib.Notify) == "function" then
                        Lib.Notify("Anti AFK", "Naik treadmill ✓", 2)
                    end
                end)
            end
            tbl2.Wake()
        end)
    end

    tbl2.Add(function()
        if not afkEnabled() then
            if treadmill.Riding and not busyMount then
                busyMount = true
                task.spawn(function()
                    pcall(tbl4.ExitBelt)
                    busyMount = false
                    tbl2.Wake()
                end)
            end
            return false
        end

        if busyMount then
            return false
        end

        -- Steal/other feature owns movement → do not fight
        if tbl4.Steal.Active or tbl4.Steal.Carrying then
            return false
        end
        local owner = tbl4.Movement.Owner
        if owner ~= nil and owner ~= "treadmill" then
            return false
        end

        -- Already riding + Stay On: periodic re-wear
        if treadmill.Riding and stayEnabled() and tbl4.OnBelt() then
            local now = os.clock()
            local nextCheck = treadmill.NextCheck or 0
            if now >= nextCheck and not selfNavigating and tbl4.Grounded() then
                treadmill.NextCheck = os.clock() + STAY_RECHECK
                busyMount = true
                task.spawn(function()
                    local ok, result, errMsg = invokeWear()
                    treadmill.Riding = acceptWear(ok, result, errMsg)
                    if not treadmill.Riding then
                        treadmill.NextTry = 0
                    end
                    busyMount = false
                    tbl2.Wake()
                end)
            end
            return false
        end

        local now = os.clock()
        local nextTry = treadmill.NextTry or 0
        if now < nextTry then
            return false
        end
        treadmill.NextCheck = 0
        tryMountNow("loop")
        return false
    end)

    -- Detect fell off belt while AFK thought we were riding
    task.spawn(function()
        local offFor = 0
        while not stopped do
            local dt = task.wait(0.25)
            if not afkEnabled() or not treadmill.Riding or tbl4.Steal.Active or tbl4.Steal.Carrying then
                offFor = 0
            elseif tbl4.OnBelt() then
                offFor = 0
            else
                offFor = offFor + dt
                if offFor >= 1.25 then
                    treadmill.Riding = false
                    treadmill.NextTry = 0
                    tbl2.Wake()
                    offFor = 0
                end
            end
        end
    end)

    fn6(function()
        stopped = true
        treadmill.Riding = false
        selfNavigating = false
    end)

    if vAfk and type(vAfk.CreateToggle) == "function" then
        toggleAfk = vAfk:CreateToggle({
            Name = "Anti AFK",
            Note = "Naik treadmill otomatis saat idle / Auto Steal WAIT",
            Default = false,
            Callback = function(on)
                AFK_GEN = AFK_GEN + 1
                local enabled = on
                if type(enabled) ~= "boolean" then
                    enabled = tbl4.Toggle(toggleAfk, false)
                end
                treadmill.NextTry = 0
                treadmill.LastFailed = false
                pcall(tbl4.StopWalking)
                if enabled then
                    -- Immediate mount on toggle ON (no scheduler wait)
                    tryMountNow("toggle")
                else
                    task.spawn(function()
                        pcall(tbl4.ExitBelt)
                        tbl2.Wake()
                    end)
                end
                tbl2.Wake()
            end,
        })
        toggleStay = vAfk:CreateToggle({
            Name = "Stay On Treadmill",
            Note = "Tetap di treadmill sampai ada target steal",
            Default = true,
            Callback = function()
                tbl2.Wake()
            end,
        })
        vAfk:CreateText({
            Name = "Info",
            Text = "ON = langsung ke treadmill. Auto Steal WAIT tetap di belt. Target spawn → lompat & steal.",
        })
    end
end

tbl4.Flying = false
tbl4.Driving = 0

tbl4.BeginFlight = function()
    tbl4.Flying = true
    local character = localPlayer.Character
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")

    if humanoid then
        humanoid.PlatformStand = true

        pcall(function()
            humanoid:ChangeState(Enum.HumanoidStateType.Freefall)
        end)
    end

    return tbl4.Root() ~= nil
end

tbl4.SetFlightVelocity = function(arg)
    local v13 = tbl4.Root()

    if v13 then
        v13.AssemblyLinearVelocity = arg
        v13.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
    end
end

tbl4.RecoverStance = function()
    local character = localPlayer.Character
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    local root = tbl4.Root and tbl4.Root() or (character and character:FindFirstChild("HumanoidRootPart"))
    if root then
        pcall(function()
            root.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
            root.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
        end)
    end
    if not humanoid then
        return
    end
    pcall(function()
        humanoid.PlatformStand = false
        humanoid.Sit = false
        local st = humanoid:GetState()
        if st == Enum.HumanoidStateType.Physics
            or st == Enum.HumanoidStateType.Ragdoll
            or st == Enum.HumanoidStateType.FallingDown
            or st == Enum.HumanoidStateType.Freefall
            or st == Enum.HumanoidStateType.PlatformStanding
            or st == Enum.HumanoidStateType.Seated
        then
            humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
            task.defer(function()
                if humanoid.Parent then
                    humanoid.PlatformStand = false
                    humanoid.Sit = false
                    humanoid:ChangeState(Enum.HumanoidStateType.Running)
                end
            end)
        end
    end)
end

tbl4.EndFlight = function()
    tbl4.Flying = false
    local v13 = tbl4.Root()

    if v13 then
        pcall(function()
            v13.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
            v13.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
        end)
    end

    pcall(tbl4.RecoverStance)
end

-- Keep character standing while steal/carry is active (anti fall / sleep)
task.spawn(function()
    while true do
        task.wait(0.2)
        local steal = tbl4.Steal
        if steal and (steal.Active or steal.Carrying) and not tbl4.Flying and not tbl4.SAEManaged then
            pcall(tbl4.RecoverStance)
        end
    end
end)

do
    local tbl6 = {
        Enum.HumanoidStateType.FallingDown,
        Enum.HumanoidStateType.Ragdoll,
        Enum.HumanoidStateType.Physics,
        Enum.HumanoidStateType.Seated,
        Enum.HumanoidStateType.PlatformStanding,
    }
    local tbl7 = {}
    local flag = false

    tbl4.GodMode = function(arg)
        local character = localPlayer.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        if not character or not humanoid then
            return
        end

        if arg then
            flag = true

            for _, v13 in ipairs(tbl6) do
                pcall(function()
                    humanoid:SetStateEnabled(v13, false)
                end)
            end

            pcall(function()
                humanoid.BreakJointsOnDeath = false
            end)

            for _, descendant in ipairs(character:GetDescendants()) do
                if descendant:IsA("BasePart") and tbl7[descendant] == nil then
                    tbl7[descendant] = descendant.CanCollide

                    pcall(function()
                        descendant.CanCollide = false
                    end)
                end
            end
        elseif flag then
            flag = false

            for _, v13 in ipairs(tbl6) do
                pcall(function()
                    humanoid:SetStateEnabled(v13, true)
                end)
            end

            for k, v13 in pairs(tbl7) do
                if k and k.Parent then
                    pcall(function()
                        k.CanCollide = v13
                    end)
                end
            end

            table.clear(tbl7)
        end
    end
end

tbl4.GodTick = function()
    local character = localPlayer.Character
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")

    if humanoid and humanoid.Health < humanoid.MaxHealth then
        pcall(function()
            humanoid.Health = humanoid.MaxHealth
        end)
    end
end

tbl4.StopWalking = function()
    local character = localPlayer.Character
    local humanoidRootPart = character and character:FindFirstChild("HumanoidRootPart")
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")

    if humanoid and humanoidRootPart then
        pcall(function()
            humanoid:MoveTo(humanoidRootPart.Position)
            humanoid:Move(Vector3.new(0, 0, 0), false)
        end)
    end
end

local function fn9(arg, arg2, arg3, arg4)
    local n = tonumber(arg2) or 6
    local n2 = tonumber(arg3) or 10
    local n3 = 0
    local position = nil
    local n4 = 0
    local n5 = 0

    while n3 < n2 do
        if type(arg4) == "function" and arg4() then
            tbl4.StopWalking()
            return false
        end
        local character = localPlayer.Character
        local humanoidRootPart = character and character:FindFirstChild("HumanoidRootPart")
        character = character and character:FindFirstChildOfClass("Humanoid")
        if not humanoidRootPart or not character or character.Health <= 0 then
            return false
        end

        if (humanoidRootPart.Position - arg).Magnitude <= n then
            tbl4.StopWalking()
            return true
        end

        if position and (humanoidRootPart.Position - position).Magnitude < 1 then
            n4 = n4 + 0.2
        else
            n4 = 0
        end

        position = humanoidRootPart.Position
        n5 = math.max(0, n5 - 0.2)

        if n4 >= 0.8 and n5 <= 0 then
            tbl4.LeaveBelt()

            pcall(function()
                character.Jump = true
            end)

            n4 = 0
            n5 = 1.5
        end

        character:MoveTo(arg)
        n3 = n3 + task.wait(0.2)
    end

    tbl4.StopWalking()
    return tbl4.DistanceTo(arg) <= n
end

tbl4.WalkTo = function(arg, arg2, arg3, arg4)
    tbl4.Driving = tbl4.Driving + 1
    local ok, result = pcall(fn9, arg, arg2, arg3, arg4)
    tbl4.Driving = math.max(0, tbl4.Driving - 1)
    ok = ok and result == true
    return ok
end

local fn10
local tbl6 =
    { Boss = "Fractured", GreatBloom = "Spirit Bloom", Sakura = "Bloom", Monstrous = "Parasite" }

task.spawn(function()
    local mutations = tbl.Mutations

    local ok, result = pcall(function()
        return mutations.All()
    end)

    local v13 = result

    if ok and type(v13) == "table" then
        for k, v14 in pairs(v13) do
            local flag = type(v14) == "table"
            local id

            if flag then
                id = v14.Id or k
            else
                id = flag
            end

            id = id or nil
            local label = type(v14) == "table" and v14.Label or nil

            if id ~= nil and type(label) == "string" and label ~= "" then
                tbl6[tostring(id)] = label
            end
        end
    end
end)

fn10 = function(arg)
    local str = tbl6[tostring(arg)] or tostring(arg)
    return str
end

local tbl7, tbl8, tbl9, tbl10, n, tbl11, tbl12, tbl13, n2, n3
local n4, fn11, v13, v14, v15, v16, v17, str, str2, flag
local n5, tbl14, v18, fn12, fn13

-- [Auto Steal] Isi fitur & logic dihapus. Sisa di bawah hanya data bersama yang dipakai tab lain
-- (daftar rarity untuk Dr Scramble) + nilai default. Tab "Auto Steal" tetap ada tapi kosong.
do
    do
        tbl7 = { "Any" }
        tbl8 = { Any = 0 }
        local tbl19 = {}
        local directory = tbl.Assets and tbl.Assets.Directory

        if type(directory) == "table" then
            for _, v20 in pairs(directory) do
                local rarity = type(v20) == "table" and v20.Rarity or nil
                local flag3 = type(rarity) == "table"

                if flag3 then
                    local v21 = tonumber
                    local rarityNumber = rarity.RarityNumber or rarity.Rank
                    flag3 = v21(rarityNumber)
