    })

    local tbl17 = {
        ["K/s"] = { Min = 0, Max = 1000, Mult = 1000 },
        ["M/s"] = { Min = 0, Max = 1000, Mult = 1000000 },
        ["B/s"] = { Min = 0, Max = 100, Mult = 1000000000 },
    }
    local tbl18 = { Slider = nil, Value = 0, Unit = "M/s" }

    local function fn20(arg, arg2)
        if arg ~= nil then
            local v20 = tbl18
            local max = math.max
            local floor = math.floor
            local value = tonumber(arg) or tbl18.Value
            v20.Value = max(0, floor(value))
        end

        if arg2 ~= nil then
            tbl18.Unit = tostring(arg2)
        end

        local ms = tbl17[tbl18.Unit] or tbl17["M/s"]
        tbl16.MinIncome = tbl18.Value * ms.Mult
