                local ms = tbl17[arg] or tbl17["M/s"]
                local slider = tbl18.Slider

                if slider and slider.SetRange then
                    slider:SetRange(ms.Min, ms.Max)
                    local min = tonumber(slider:Get()) or ms.Min
                    local min2 = ms.Min
