    local tbl19 = {}
    local tbl20 = {}
    local directory = tbl.Assets and tbl.Assets.Directory
    local n9 = 0

    while (type(directory) ~= "table" or next(directory) == nil) and n9 < 2 do
        n9 = n9 + task.wait(0.1)

        if type(tbl.Assets) ~= "table" then
            tbl.Assets = fn3(function()
                return ReplicatedStorage.Data.Assets
            end)
