        directory = tbl.Assets and tbl.Assets.Directory
    end

    local tbl21 = {}

    if type(directory) == "table" then
        for k, v20 in pairs(directory) do
            local rarity = type(v20) == "table" and v20.Rarity or nil
            local flag3 = type(rarity) == "table"

            if flag3 then
                local v21 = tonumber
                local rarityNumber = rarity.RarityNumber or rarity.Rank
                flag3 = v21(rarityNumber)
            end

            flag3 = flag3 or nil

            if flag3 then
                local insert = table.insert
                local tbl22 = { Category = tostring(k) }
                local v21 = tostring
                local displayName = v20.DisplayName or k
                tbl22.Name = v21(displayName)
                tbl22.Rarity = flag3
                local v22 = tostring
                local displayName2 = rarity.DisplayName or rarity._id or flag3
                tbl22.RarityName = v22(displayName2)
