                if type(arg) == "table" then
                    for k, v20 in pairs(arg) do
                        local flag3 = v20 == true and type(k) == "string"

                        if not flag3 then
                            k = flag3
                        end

                        k = k or type(v20) == "string" and v20
                        k = k or nil

                        if k and tbl20[k] then
                            tbl22[tbl20[k]] = true
                        end
                    end
                end

                tbl16.Eggs = tbl22
                fn19()
            end,
        }))
    end

    tbl4.Rift.Restart.Hatch = fn19
end
end

-- ---------- Auto Sell v3 (tabel scroll DI DALAM tab, ikon sendiri, Sell hanya lewat klik) ----------
-- Data   : Save.Get().Inventory (pet), EggState.ReadOwnerEggs (egg); cadangan: tool di Backpack (atribut UID)
-- Ikon   : Assets.Directory[Category].Icon -> ImageLabel buatan sendiri (tidak lewat parameter Image WindUI)
-- Jual   : RemoteEvent "RE/PetSatchel/SellSelection" { Eggs = {...}, Assets = {...} }  (sama seperti ChiliHub)
-- Tabel  : satu elemen setinggi TABLE_H di dalam tab, isinya ScrollingFrame -> tab tidak memanjang ke bawah.
-- Dibungkus fungsi sendiri supaya tidak menambah local di level atas (batas 200 local).
;(function()
    warn("[FanKun][AutoSell] modul v3 dimuat")

    local BATCH = 50
    local MAX_ROWS = 300
    local TABLE_H = 300
    local ROW_H = 58
    local SELL_REMOTE = "RE/PetSatchel/SellSelection"
    local SORTS = { "Rarity (rendah dulu)", "Value (rendah dulu)", "Value (tinggi dulu)", "Nama (A-Z)" }
    local ACCENT = Color3.fromRGB(14, 14, 14)

    local function getDirectory()
        local a = tbl.Assets
        local d = type(a) == "table" and a.Directory or nil
        if type(d) == "table" then
            return d
        end
        return {}
    end

    local function AssetItems()
        return fn3(function()
            return ReplicatedStorage.Shared.Util.AssetItems
        end)
    end

    local function fmt(n)
        n = tonumber(n) or 0
        local suf = { "", "K", "M", "B", "T", "Qa", "Qi" }
        local i = 1
        while math.abs(n) >= 1000 and i < #suf do
            n = n / 1000
            i = i + 1
        end
        if i == 1 then
            return string.format("$%.0f%s", n, suf[i])
        end
        return string.format("$%.2f%s", n, suf[i])
    end

    local function catInfo(cat)
        local rec = getDirectory()[tostring(cat)]
        if type(rec) == "table" then
            return rec
        end
        return nil
    end

    local function rarityOf(cat)
        local rec = catInfo(cat)
        local r = rec and rec.Rarity
        if type(r) == "table" then
            return tonumber(r.RarityNumber or r.Rank) or 0, tostring(r.DisplayName or r._id or "?")
        end
        return 0, "?"
    end

    local function rarityColor(cat)
        local rec = catInfo(cat)
        local r = rec and rec.Rarity
        if type(r) == "table" then
            local c = r.Color or r.Colour
            if typeof(c) == "Color3" then
                return c
            end
            if type(c) == "string" then
                local ok, res = pcall(Color3.fromHex, c)
                if ok and typeof(res) == "Color3" then
                    return res
                end
            end
        end
        return Color3.fromRGB(130, 135, 155)
    end

    local function nameOf(cat)
        local rec = catInfo(cat)
        return tostring(rec and rec.DisplayName or cat)
    end

    local function normIcon(v)
        if v == nil then
            return nil
        end
        if type(v) == "number" then
            return "rbxassetid://" .. tostring(math.floor(v))
        end
        if type(v) == "string" then
            if v == "" then
                return nil
            end
            if tonumber(v) then
                return "rbxassetid://" .. v
            end
            return v
        end
        return nil
    end

    local function iconOf(cat)
        local rec = catInfo(cat)
        if not rec then
            return nil
        end
        for _, k in ipairs({ "Icon", "Image", "ImageId", "Thumbnail", "Texture", "TextureId" }) do
            local i = normIcon(rec[k])
            if i then
                return i
            end
        end
        return nil
    end

    local function valueOf(cat, scale, muts)
        local rec = catInfo(cat)
        local rate = rec and tonumber(rec.EarningRate) or 0
        scale = tonumber(scale) or 0
        if rate <= 0 or scale <= 0 then
            return 0
        end
        local f
        if scale > 5 then
            f = (scale / 5) ^ 1.2 * 19.637875755794113
        else
            f = scale ^ 1.85
        end
        local mult = 1
        local M = tbl.Mutations
        if type(M) == "table" and type(M.EarningsFor) == "function" then
            local ok, r = pcall(M.EarningsFor, type(muts) == "table" and muts or {})
            if ok and type(r) == "number" then
                mult = r
            end
        end
        return rate * f * mult
    end

    local function mutNames(muts, base)
        local out = {}
        if type(muts) == "table" then
            for k, v in pairs(muts) do
                if type(v) == "string" then
                    out[#out + 1] = v
                elseif v == true and type(k) == "string" then
                    out[#out + 1] = k
                end
            end
        end
        if type(base) == "string" and base ~= "" then
            out[#out + 1] = base
        end
        table.sort(out)
        return out
    end

    local function hasMut(muts)
        return type(muts) == "table" and next(muts) ~= nil
    end

    local rarityOptions = { "Semua" }
    local rarityNum = {}
    do
        local names = {}
        for _, rec in pairs(getDirectory()) do
            local r = type(rec) == "table" and rec.Rarity or nil
            if type(r) == "table" then
                local num = tonumber(r.RarityNumber or r.Rank)
                if num then
                    names[num] = tostring(r.DisplayName or r._id or num)
                end
            end
        end
        local nums = {}
        for n in pairs(names) do
            nums[#nums + 1] = n
        end
        table.sort(nums)
        for _, n in ipairs(nums) do
            local label = string.format("%d - %s", n, names[n])
            rarityOptions[#rarityOptions + 1] = label
            rarityNum[label] = n
        end
    end

    local function readSave()
        local s = tbl.Save
        if type(s) ~= "table" or type(s.Get) ~= "function" then
            return nil
        end
        local ok, r = pcall(s.Get)
        if ok and type(r) == "table" then
            return r
        end
        return nil
    end

    local function makeItem(uid, cat, scale, muts, base, price)
        local rn, rname = rarityOf(cat)
        local v = valueOf(cat, scale, muts)
        local names = mutNames(muts, base)
        return {
            uid = uid,
            cat = cat,
            name = nameOf(cat),
            icon = iconOf(cat),
            color = rarityColor(cat),
            rarity = rn,
            rarityName = rname,
            scale = tonumber(scale) or 0,
            value = v,
            price = price,
            muts = names,
            mutated = #names > 0 or hasMut(muts),
        }
    end

    -- cadangan: baca tool di Backpack/Character bila data Save/EggState tidak bisa dibaca
    local function scanTools(isEgg)
        local items, seen = {}, {}
        local function consider(tool)
            if not tool:IsA("Tool") then
                return
            end
            local uid = tool:GetAttribute("UID") or tool:GetAttribute("Uid") or tool:GetAttribute("uid")
            if type(uid) ~= "string" or seen[uid] then
                return
            end
            if tool:GetAttribute("ItemType") ~= nil then
                return -- gear / consumable, bukan pet atau egg
            end
            local looksEgg = string.find(string.lower(tool.Name), "egg", 1, true) ~= nil
            if looksEgg ~= isEgg then
                return
            end
            seen[uid] = true
            local icon
            if tool.TextureId and tool.TextureId ~= "" then
                icon = tool.TextureId
            end
            items[#items + 1] = {
                uid = uid,
                cat = tool.Name,
                name = tool.Name,
                icon = icon,
                color = Color3.fromRGB(130, 135, 155),
                rarity = 0,
                rarityName = "?",
                scale = 0,
                value = 0,
                price = 0,
                muts = {},
                mutated = false,
                fromTool = true,
            }
        end
        local bp = localPlayer:FindFirstChildOfClass("Backpack")
        if bp then
            for _, c in ipairs(bp:GetChildren()) do
                consider(c)
            end
        end
        local ch = localPlayer.Character
        if ch then
            for _, c in ipairs(ch:GetChildren()) do
                consider(c)
            end
        end
        return items
    end

    local function scanPets()
        local items, hidden, notes = {}, 0, {}
        local save = readSave()
        if not save then
            notes[#notes + 1] = "Save TIDAK terbaca"
            if type(tbl.SaveDiag) == "function" then
                notes[#notes + 1] = "isi modul Save: " .. tostring(tbl.SaveDiag())
            end
        else
            local inv = save.Inventory
            if type(inv) ~= "table" and type(save.Data) == "table" then
                inv = save.Data.Inventory
            end
            if type(inv) ~= "table" then
                notes[#notes + 1] = "Save.Inventory kosong/tidak ada"
            else
                local equipped = {}
                for _, uid in pairs(save.EquippedAssets or {}) do
                    equipped[uid] = true
                end
                local AI = AssetItems()
                for uid, rec in pairs(inv) do
                    if type(rec) == "table" then
                        if rec.InFuse == true or rec.IsFavorite == true or equipped[uid] then
                            hidden = hidden + 1
                        else
                            local price
                            if type(AI) == "table" and type(AI.SalePrice) == "function" then
                                local ok, r = pcall(AI.SalePrice, rec)
                                if ok and tonumber(r) then
                                    price = tonumber(r)
                                end
                            end
                            local it = makeItem(uid, tostring(rec.Category), rec.Scale, rec.Mutations, rec.BaseMutation, 0)
                            it.price = price or it.value * 100
                            items[#items + 1] = it
                        end
                    end
                end
            end
        end
        if #items == 0 then
            local t = scanTools(false)
            if #t > 0 then
                notes[#notes + 1] = "pakai cadangan: tool Backpack"
                items = t
            end
        end
        return items, hidden, notes
    end

    local function scanEggs()
        local items, hidden, notes = {}, 0, {}
        local es = tbl.EggState
        if type(es) ~= "table" or type(es.ReadOwnerEggs) ~= "function" then
            notes[#notes + 1] = "EggState TIDAK ada"
        else
            local ok, data = pcall(es.ReadOwnerEggs, localPlayer.UserId)
            if not ok or type(data) ~= "table" then
                notes[#notes + 1] = "ReadOwnerEggs gagal"
            else
                local held
                local ch = localPlayer.Character
                local tool = ch and ch:FindFirstChildWhichIsA("Tool")
                if tool then
                    held = tool:GetAttribute("UID")
                end
                local ER = tbl.EggRecords
                for uid, rec in pairs(data) do
                    if type(rec) == "table" then
                        if rec.Placement ~= nil or uid == held then
                            hidden = hidden + 1
                        else
                            local price = 0
                            if type(ER) == "table" and type(ER.SellPrice) == "function" then
                                local ok2, r = pcall(ER.SellPrice, rec)
                                if ok2 and tonumber(r) then
                                    price = tonumber(r)
                                end
                            end
                            items[#items + 1] =
                                makeItem(uid, tostring(rec.AssetCategory), rec.AssetScale, rec.Mutations, nil, price)
                        end
                    end
                end
            end
        end
        if #items == 0 then
            local t = scanTools(true)
            if #t > 0 then
                notes[#notes + 1] = "pakai cadangan: tool Backpack"
                items = t
            end
        end
        return items, hidden, notes
    end

    -- ------------------------------------------------------------
    -- UI tabel (Instance buatan sendiri, ditanam di dalam tab)
    -- ------------------------------------------------------------
    local function corner(parent, r)
        local c = Instance.new("UICorner")
        c.CornerRadius = UDim.new(0, r)
        c.Parent = parent
        return c
    end

    local function stroke(parent, color, transp, th)
        local s = Instance.new("UIStroke")
        s.Color = color
        s.Transparency = transp or 0
        s.Thickness = th or 1
        s.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        s.Parent = parent
        return s
    end

    local function label(parent, props)
        local t = Instance.new("TextLabel")
        t.BackgroundTransparency = 1
        t.BorderSizePixel = 0
        t.Font = props.Font or Enum.Font.GothamMedium
        t.TextSize = props.Size or 12
        t.TextColor3 = props.Color or Color3.fromRGB(14, 14, 14)
        t.TextXAlignment = props.AlignX or Enum.TextXAlignment.Left
        t.TextYAlignment = Enum.TextYAlignment.Center
        t.TextTruncate = Enum.TextTruncate.AtEnd
        t.RichText = props.Rich == true
        t.Text = props.Text or ""
        t.Position = props.Position
        t.Size = props.Size2
        t.Parent = parent
        return t
    end

    local function esc(s)
        return (tostring(s):gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;"))
    end

    local function makePanel(tabName, kind)
        local sec = __featureTab(tabName)
        local wtab = sec and sec._tab and sec._tab._w
        if not wtab then
            warn("[FanKun][AutoSell] tab '" .. tabName .. "' tidak bisa dibuat")
            return nil
        end
        local isEgg = kind == "egg"
        local noun = isEgg and "egg" or "pet"

        local items, shown = {}, {}
        local rarityFilter, sortMode = "Semua", SORTS[1]
        local protectMut = true
        local busy = false
        local confirmUntil = 0
        local lastNote = ""
        local renderToken = 0
        local statusT, sellAllBtn
        local scroll, emptyLbl, countLbl

        local function setStatus(text)
            if statusT then
                pcall(statusT.Set, statusT, text)
            end
        end

        local function sellAllList()
            local list, total = {}, 0
            for _, it in ipairs(shown) do
                if not (protectMut and it.mutated) then
                    list[#list + 1] = it
                    total = total + (it.price or 0)
                end
            end
            return list, total
        end

        local function refreshSellAll()
            local list, total = sellAllList()
            if sellAllBtn then
                pcall(
                    sellAllBtn.Set,
                    sellAllBtn,
                    string.format("Sell Semua yang tampil (%d)  -  %s", #list, fmt(total))
                )
            end
        end

        local function applyFilter()
            shown = {}
            local want = rarityNum[rarityFilter]
            for _, it in ipairs(items) do
                if want == nil or it.rarity == want then
                    shown[#shown + 1] = it
                end
            end
            table.sort(shown, function(a, b)
                if sortMode == SORTS[2] then
                    if a.value ~= b.value then
                        return a.value < b.value
                    end
                elseif sortMode == SORTS[3] then
                    if a.value ~= b.value then
                        return a.value > b.value
                    end
                elseif sortMode == SORTS[4] then
                    if a.name ~= b.name then
                        return a.name < b.name
                    end
                else
                    if a.rarity ~= b.rarity then
                        return a.rarity < b.rarity
                    end
                end
                if a.name ~= b.name then
                    return a.name < b.name
                end
                if a.value ~= b.value then
                    return a.value < b.value
                end
                return tostring(a.uid) < tostring(b.uid)
            end)
        end

        local sellUids, scan

        -- satu baris tabel
        local function makeRow(it, order)
            local row = Instance.new("Frame")
            row.Name = "Row"
            row.LayoutOrder = order
            row.Size = UDim2.new(1, 0, 0, ROW_H)
            row.BackgroundColor3 = Color3.fromRGB(240, 240, 240)
            row.BorderSizePixel = 0
            corner(row, 8)
            stroke(row, it.color, 0.65, 1)

            -- kotak ikon (huruf awal sebagai cadangan di belakang gambar)
            local box = Instance.new("Frame")
            box.Position = UDim2.new(0, 6, 0.5, -21)
            box.Size = UDim2.new(0, 42, 0, 42)
            box.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
            box.BorderSizePixel = 0
            box.Parent = row
            corner(box, 8)
            stroke(box, it.color, 0.2, 1.5)

            local initial = label(box, {
                Text = string.upper(string.sub(it.name, 1, 1)),
                Font = Enum.Font.GothamBold,
                Size = 20,
                Color = it.color,
                AlignX = Enum.TextXAlignment.Center,
                Position = UDim2.new(0, 0, 0, 0),
                Size2 = UDim2.new(1, 0, 1, 0),
            })

            if it.icon then
                local img = Instance.new("ImageLabel")
                img.BackgroundTransparency = 1
                img.BorderSizePixel = 0
                img.Position = UDim2.new(0, 2, 0, 2)
                img.Size = UDim2.new(1, -4, 1, -4)
                img.ScaleType = Enum.ScaleType.Fit
                img.ZIndex = 2
                img.Image = it.icon
                img.Parent = box
                -- sembunyikan huruf cadangan begitu gambar berhasil termuat
                task.spawn(function()
                    for _ = 1, 20 do
                        local ok, loaded = pcall(function()
                            return img.IsLoaded
                        end)
                        if ok and loaded then
                            initial.Visible = false
                            return
                        end
                        task.wait(0.25)
                    end
                end)
            end

            local hex = it.color:ToHex()
            local title
            if it.fromTool then
                title = esc(it.name)
            else
                title = string.format('%s  <font color="#%s">[%s]</font>', esc(it.name), hex, esc(it.rarityName))
            end
            label(row, {
                Text = title,
                Rich = true,
                Font = Enum.Font.GothamBold,
                Size = 13,
                Position = UDim2.new(0, 56, 0, 5),
                Size2 = UDim2.new(1, -56 - 76, 0, 16),
            })

            local l2, l3
            if it.fromTool then
                l2 = "Dibaca dari Backpack (detail value tidak tersedia)"
                l3 = ""
            else
                l2 = string.format("x%.2f  |  Value %s/s", it.scale, fmt(it.value))
                l3 = string.format("Jual %s", fmt(it.price))
                if #it.muts > 0 then
                    l3 = l3 .. "  |  " .. table.concat(it.muts, ", ")
                end
            end
            label(row, {
                Text = l2,
                Size = 11,
                Color = Color3.fromRGB(95, 95, 95),
                Position = UDim2.new(0, 56, 0, 22),
                Size2 = UDim2.new(1, -56 - 76, 0, 14),
            })
            label(row, {
                Text = l3,
                Size = 11,
                Color = Color3.fromRGB(0, 125, 65),
                Position = UDim2.new(0, 56, 0, 36),
                Size2 = UDim2.new(1, -56 - 76, 0, 14),
            })

            local btn = Instance.new("TextButton")
            btn.AutoButtonColor = true
            btn.AnchorPoint = Vector2.new(1, 0.5)
            btn.Position = UDim2.new(1, -8, 0.5, 0)
            btn.Size = UDim2.new(0, 62, 0, 32)
            btn.BackgroundColor3 = Color3.fromRGB(0, 170, 110)
            btn.BorderSizePixel = 0
            btn.Font = Enum.Font.GothamBold
            btn.TextSize = 13
            btn.TextColor3 = Color3.fromRGB(255, 255, 255)
            btn.Text = "Sell"
            btn.Parent = row
            corner(btn, 7)
            -- HANYA lewat klik / tap pada tombol ini, dan WAJIB konfirmasi:
            --   klik 1 -> tombol jadi "Yakin?" (merah, aktif 3 detik)
            --   klik 2 -> baru dijual. Klik ke-2 dalam 0.4 detik diabaikan (anti dobel-tap tidak sengaja).
            local SELL_COLOR = Color3.fromRGB(0, 170, 110)
            local ARM_COLOR = Color3.fromRGB(215, 70, 60)
            local armedAt, armedUntil = 0, 0
            btn.Activated:Connect(function()
                if busy then
                    return
                end
                local now = os.clock()
                if now > armedUntil then
                    armedAt = now
                    armedUntil = now + 3
                    btn.Text = "Yakin?"
                    btn.BackgroundColor3 = ARM_COLOR
                    local mine = armedUntil
                    task.delay(3.1, function()
                        if armedUntil == mine and btn.Parent then
                            armedUntil = 0
                            btn.Text = "Sell"
                            btn.BackgroundColor3 = SELL_COLOR
                        end
                    end)
                    return
                end
                if now - armedAt < 0.4 then
                    return
                end
                armedUntil = 0
                btn.Text = "..."
                btn.BackgroundColor3 = Color3.fromRGB(90, 95, 110)
                sellUids({ it.uid })
            end)
            return row
        end

        local function renderRows()
            renderToken = renderToken + 1
            local token = renderToken
            if not scroll then
                return
            end
            local keepPos = scroll.CanvasPosition
            for _, c in ipairs(scroll:GetChildren()) do
                if c:IsA("GuiObject") then
                    c:Destroy()
                end
            end
            local total = #shown
            local n = math.min(total, MAX_ROWS)
            if countLbl then
                local extra = total > MAX_ROWS and string.format("  (menampilkan %d pertama)", MAX_ROWS) or ""
                countLbl.Text = string.format("%d %s tampil dari %d%s", total, noun, #items, extra)
            end
            if emptyLbl then
                emptyLbl.Visible = total == 0
            end
            for i = 1, n do
                if token ~= renderToken then
                    return
                end
                local ok, row = pcall(makeRow, shown[i], i)
                if ok and row then
                    row.Parent = scroll
                else
                    warn("[FanKun][AutoSell] gagal membuat baris: " .. tostring(row))
                end
                if i % 25 == 0 then
                    task.wait()
                end
            end
            if token == renderToken then
                pcall(function()
                    scroll.CanvasPosition = Vector2.new(0, keepPos.Y)
                end)
            end
            refreshSellAll()
        end

        scan = function()
            local list, hidden, notes
            local ok, a, b, c = pcall(isEgg and scanEggs or scanPets)
            if ok then
                list, hidden, notes = a, b, c
            else
                list, hidden, notes = {}, 0, { "error scan: " .. tostring(a) }
                warn("[FanKun][AutoSell] " .. tostring(a))
            end
            items = list

            local dirCount = 0
            for _ in pairs(getDirectory()) do
                dirCount = dirCount + 1
            end
            lastNote = string.format(
                "Ditemukan %d %s  (%d disembunyikan: favorit/equip/dipasang)  |  katalog game: %d entri",
                #items,
                noun,
                hidden or 0,
                dirCount
            )
            if #notes > 0 then
                lastNote = lastNote .. "\nCatatan: " .. table.concat(notes, "; ")
            end
            if #items == 0 then
                lastNote = lastNote .. "\nBackpack/inventory kosong atau data game belum termuat. Coba Scan lagi."
            end
            setStatus(lastNote)
            applyFilter()
            task.spawn(renderRows)
        end

        sellUids = function(list)
            if busy then
                setStatus("Masih memproses penjualan, tunggu sebentar...")
                return
            end
            if #list == 0 then
                setStatus("Tidak ada " .. noun .. " untuk dijual.")
                return
            end
            local remote = networking:FindFirstChild(SELL_REMOTE) or networking:FindFirstChild(SELL_REMOTE, true)
            if not remote or not remote:IsA("RemoteEvent") then
                setStatus("Remote " .. SELL_REMOTE .. " tidak ditemukan. Kemungkinan game sudah update.")
                return
            end
            busy = true
            task.spawn(function()
                local n = #list
                for i = 1, n, BATCH do
                    local chunk = {}
                    for j = i, math.min(i + BATCH - 1, n) do
                        chunk[#chunk + 1] = list[j]
                    end
                    local payload
                    if isEgg then
                        payload = { Eggs = chunk, Assets = {} }
                    else
                        payload = { Eggs = {}, Assets = chunk }
                    end
                    pcall(remote.FireServer, remote, payload)
                    if i + BATCH <= n then
                        task.wait(0.3)
                    end
                end
                local sent = {}
                for _, uid in ipairs(list) do
                    sent[uid] = true
                end
                task.wait(1.5)
                busy = false
                scan()
                task.wait(0.2)
                local still = 0
                for _, it in ipairs(items) do
                    if sent[it.uid] then
                        still = still + 1
                    end
                end
                local result
                if still == 0 then
                    result = string.format("Berhasil: %d %s terjual.", n, noun)
                else
                    result = string.format(
                        "Request %d %s terkirim, tapi %d masih ada (server menolak atau data belum ter-update).",
                        n,
                        noun,
                        still
                    )
                end
                setStatus(result .. "\n" .. lastNote)
            end)
        end

        -- ---------------- kontrol di atas tabel ----------------
        statusT = sec:CreateText({ Name = "Status", Text = "Belum di-scan. Tekan 'Scan Backpack'." })

        sec:CreateButton({
            Name = "Scan Backpack",
            Note = "Baca isi backpack lalu tampilkan daftar " .. noun .. " di tabel",
            Callback = function()
                scan()
            end,
        })

        sec:CreateDropdown({
            Name = "Filter Rarity",
            Options = rarityOptions,
            Default = rarityOptions[1],
            Callback = function(arg)
                if table.find(rarityOptions, arg) and arg ~= rarityFilter then
                    rarityFilter = arg
                    applyFilter()
                    task.spawn(renderRows)
                end
            end,
        })

        sec:CreateDropdown({
            Name = "Urutkan",
            Options = SORTS,
            Default = SORTS[1],
            Callback = function(arg)
                if table.find(SORTS, arg) and arg ~= sortMode then
                    sortMode = arg
                    applyFilter()
                    task.spawn(renderRows)
                end
            end,
        })

        sec:CreateToggle({
            Name = "Pengaman: lewati yang bermutasi",
            Note = "Tombol 'Sell Semua' tidak ikut menjual " .. noun .. " bermutasi",
            Default = true,
            Callback = function(v)
                protectMut = v == true
                refreshSellAll()
            end,
        })

        sellAllBtn = sec:CreateButton({
            Name = "Sell Semua yang tampil (0)  -  $0",
            Note = "Klik dua kali (konfirmasi) untuk menjual semua baris di tabel sesuai filter",
            Callback = function()
                local list, total = sellAllList()
                if #list == 0 then
                    setStatus("Tidak ada " .. noun .. " yang bisa dijual dengan filter ini.")
                    return
                end
                if confirmUntil > 0 and os.clock() < confirmUntil - 4.6 then
                    return -- klik ke-2 terlalu cepat (<0.4 dtk): kemungkinan tidak sengaja
                end
                if os.clock() > confirmUntil then
                    confirmUntil = os.clock() + 5
                    pcall(
                        sellAllBtn.Set,
                        sellAllBtn,
                        string.format("YAKIN? Klik lagi: jual %d %s (%s)", #list, noun, fmt(total))
                    )
                    task.delay(5.2, function()
                        if os.clock() >= confirmUntil then
                            confirmUntil = 0
                            refreshSellAll()
                        end
                    end)
                    return
                end
                confirmUntil = 0
                local uids = {}
                for _, it in ipairs(list) do
                    uids[#uids + 1] = it.uid
                end
                sellUids(uids)
            end,
        })

        -- ---------------- tabel scroll (ditanam di elemen WindUI) ----------------
        local anchor = sec:CreateText({ Name = "Daftar " .. noun, Text = " " })
        local frame = anchor and anchor.Instance
        if typeof(frame) ~= "Instance" then
            warn("[FanKun][AutoSell] frame tabel tidak ditemukan; tabel tidak dibuat")
            setStatus("PERINGATAN: tabel tidak bisa ditanam di tab (UI library tidak memberi frame).")
        else
            pcall(function()
                frame.AutomaticSize = Enum.AutomaticSize.None
                frame.Size = UDim2.new(1, 0, 0, TABLE_H)
                frame.ClipsDescendants = true
                for _, c in ipairs(frame:GetChildren()) do
                    if c:IsA("UIListLayout") or c:IsA("UIGridLayout") or c:IsA("UIPadding") then
                        c:Destroy()
                    elseif c:IsA("GuiObject") then
                        c.Visible = false
                    end
                end
            end)

            local holder = Instance.new("Frame")
            holder.Name = "FanKunSellTable"
            holder.Size = UDim2.new(1, 0, 1, 0)
            holder.BackgroundColor3 = Color3.fromRGB(250, 250, 250)
            holder.BorderSizePixel = 0
            holder.ZIndex = 1
            holder.Parent = frame
            corner(holder, 8)
            stroke(holder, ACCENT, 0.7, 1)

            -- header tabel
            local head = Instance.new("Frame")
            head.Size = UDim2.new(1, 0, 0, 26)
            head.BackgroundColor3 = Color3.fromRGB(232, 232, 232)
            head.BorderSizePixel = 0
            head.Parent = holder
            corner(head, 8)
            label(head, {
                Text = string.upper(noun) .. "  /  RARITY  /  VALUE  /  HARGA JUAL",
                Font = Enum.Font.GothamBold,
                Size = 11,
                Color = ACCENT,
                Position = UDim2.new(0, 10, 0, 0),
                Size2 = UDim2.new(0.62, 0, 1, 0),
            })
            countLbl = label(head, {
                Text = "0 " .. noun,
                Size = 11,
                Color = Color3.fromRGB(95, 95, 95),
                AlignX = Enum.TextXAlignment.Right,
                Position = UDim2.new(0.38, -10, 0, 0),
                Size2 = UDim2.new(0.62, 0, 1, 0),
            })

            scroll = Instance.new("ScrollingFrame")
            scroll.Name = "Scroll"
            scroll.Active = true
            scroll.BackgroundTransparency = 1
            scroll.BorderSizePixel = 0
            scroll.Position = UDim2.new(0, 0, 0, 30)
            scroll.Size = UDim2.new(1, 0, 1, -32)
            scroll.CanvasSize = UDim2.new(0, 0, 0, 0)
            scroll.AutomaticCanvasSize = Enum.AutomaticSize.Y
            scroll.ScrollingDirection = Enum.ScrollingDirection.Y
            scroll.ScrollBarThickness = 5
            scroll.ScrollBarImageColor3 = ACCENT
            scroll.ElasticBehavior = Enum.ElasticBehavior.Never
            scroll.Parent = holder

            local pad = Instance.new("UIPadding")
            pad.PaddingLeft = UDim.new(0, 6)
            pad.PaddingRight = UDim.new(0, 8)
            pad.PaddingTop = UDim.new(0, 2)
            pad.PaddingBottom = UDim.new(0, 4)
            pad.Parent = scroll

            local lay = Instance.new("UIListLayout")
            lay.Padding = UDim.new(0, 5)
            lay.SortOrder = Enum.SortOrder.LayoutOrder
            lay.Parent = scroll

            emptyLbl = label(holder, {
                Text = "Belum ada data. Tekan 'Scan Backpack'.",
                Size = 12,
                Color = Color3.fromRGB(110, 110, 110),
                AlignX = Enum.TextXAlignment.Center,
                Position = UDim2.new(0, 0, 0, 30),
                Size2 = UDim2.new(1, 0, 1, -30),
            })

            fn6(function()
                pcall(function()
                    holder:Destroy()
                end)
            end)
        end

        -- auto-refresh tabel saat inventory berubah (mis. pet baru / sudah terjual)
        local save = tbl.Save
        if type(save) == "table" and type(save.FieldSignal) == "function" then
            local pending = false
            for _, field in ipairs(isEgg and { "EggInventory" } or { "Inventory", "EquippedAssets" }) do
                local ok, sig = pcall(save.FieldSignal, field)
                if ok and type(sig) == "table" and type(sig.Connect) == "function" then
                    local ok2, conn = pcall(sig.Connect, sig, function()
                        if pending or busy then
                            return
                        end
                        pending = true
                        task.delay(1, function()
                            pending = false
                            if not busy then
                                pcall(scan)
                            end
                        end)
                    end)
                    if ok2 and conn then
                        fn6(function()
                            pcall(function()
                                conn:Disconnect()
                            end)
                        end)
                    end
                end
            end
        end

        return {
            Scan = scan,
            Count = function()
                return #items
            end,
        }
    end

    for _, def in ipairs({ { "Auto Sell Pet", "pet" }, { "Auto Sell Egg", "egg" } }) do
        local ok, panel = pcall(makePanel, def[1], def[2])
        if not ok then
            warn("[FanKun][AutoSell] gagal membuat panel " .. def[1] .. ": " .. tostring(panel))
        elseif panel then
            task.spawn(function()
                for _, delay in ipairs({ 3, 6, 12 }) do
                    task.wait(delay)
                    pcall(panel.Scan)
                    task.wait(0.5)
                    if panel.Count() > 0 then
                        break
                    end
                end
            end)
        end
    end
end)()

local v26

do
