										v30.CFrame = CFrame.new(v28 + Vector3.new(0, 3, 0)) * CFrame.Angles(0, 1.5707963267948966, 0)
									end)
								end
							end

							n30 += task.wait(0.15)
						end

						if steal.Carrying and not steal.WrongEgg(carryUid) then
							break
						end
					end

					if not steal.Carrying then
						fn59()
						str3 = "Line Drop: could not pick the egg up again"
						return false
					end

					local v28 = tbl4.Root()

					if v28 and v28.Position.X - x > safeCarry.FarFromLine then
						fn59()
						str3 = "Line Drop: egg ended up far from the line, carrying it home safely"
						return tbl4.SafeCarry.Home(arg)
					end

					str3 = "Line Drop: stepping over the line"
					local crossRatio = safeCarry.CrossRatio

					fn60(v25, tbl4.WalkSpeed() * crossRatio, 6, function()
						return safeCarry.LastDelivered >= now or not steal.Carrying
					end)

					local v29 = tbl4.Root()

					if v29 then
						pcall(function()
							v29.AssemblyLinearVelocity = Vector3.new(0, v29.AssemblyLinearVelocity.Y, 0)
						end)
					end

					local n29 = 0

					while n29 < 2 and safeCarry.LastDelivered < now and steal.Carrying and not fn16(arg) do
						n29 += RunService.Heartbeat:Wait()
					end

					fn59()
					return safeCarry.LastDelivered >= now
				end

				tbl4.SafeCarry.Home = function(arg)
					local safeCarry = tbl4.SafeCarry
					local v25 = stealHome()
					local v26 = tbl4.Root()
					if not v25 or not v26 then
						return false
					end
					fn25()
					local world = workspace:FindFirstChild("World") or workspace:FindFirstChild("__OBJECTS")
					world = world and world:FindFirstChild("Areas")
					world = world and world:FindFirstChild("SeparationLine")
					local n23 = (world and world:IsA("BasePart") and world.Position.X or 552) - 7
					local character = localPlayer.Character
					local humanoid = character and character:FindFirstChildOfClass("Humanoid")

					if humanoid then
						humanoid.PlatformStand = false
					end

					local now = os.clock()
					local n24 = 0

					local function fn57()
						local v27 = tbl4.Root()
						if not v27 then
							return
						end
						local v28, v29, v30, v31, v32 = safeCarry.Plan(tbl4.Steal.CarryAreaId, (Vector3.new(v27.Position.X, 0, v27.Position.Z) - Vector3.new(v25.X, 0, v25.Z)).Magnitude + math.max(0, safeCarry.Height) * 2, safeCarry.Mult)
						local n25 = v28 * safeCarry.CarryScale
						n24 = n25
						safeCarry.PlanOk = v29
						safeCarry.FloorSpeed = safeCarry.BeatGuard and math.min(v32 + math.max(safeCarry.GuardMargin, 1), v31) or 0
						str3 = string.format("Carrying home at %d (carry %d, guard %d, max %d)%s", math.floor(n25 + 0.5), math.floor(v30 + 0.5), math.floor(v32 + 0.5), math.floor(v31 + 0.5), v29 and "" or ", guard is faster, going at your max safe speed")
					end

					local function fn58()
						local n25 = math.max(0, safeCarry.Height)
						local v27 = tbl4.Root()
						local character2 = localPlayer.Character
						if n25 <= 0.5 or not v27 or not character2 then
							return
						end
						local n26 = v25.Y + n25
						if v27.Position.Y >= n26 - 2 then
							return
						end
						-- [V12] Egg berat: naik bertahap (bukan teleport 1x) supaya egg ikut terbawa
						if (tonumber(safeCarry.Mult) or 1) < 0.75 and tbl4.Steal.Carrying then
							local curY = v27.Position.Y
							while curY < n26 - 0.5 and tbl4.Steal.Carrying and not fn16(arg) do
								local r = tbl4.Root()
								if not r then
									break
								end
								curY = math.min(curY + 5, n26)
								pcall(function()
									character2:PivotTo(CFrame.new(Vector3.new(r.Position.X, curY, r.Position.Z)) * r.CFrame.Rotation)
									r.AssemblyLinearVelocity = Vector3.zero
									r.AssemblyAngularVelocity = Vector3.zero
								end)
								RunService.Heartbeat:Wait()
							end
							return
						end
						local rotation = v27.CFrame.Rotation
						local n27 = CFrame.new(Vector3.new(v27.Position.X, n26, v27.Position.Z)) * rotation

						pcall(function()
							character2:PivotTo(n27)
							v27.AssemblyLinearVelocity = Vector3.zero
							v27.AssemblyAngularVelocity = Vector3.zero
						end)
					end

					fn57()
					local v27 = safeCarry.NewHuman(true)
					local v28 = tbl4.Root()
					local n25 = math.clamp((v28 and v28.Position.Z or v25.Z) + v27.Lane, -425, -300)
					local now2 = os.clock()

					if safeCarry.CarryReact > 0 then
						local n26 = os.clock() + safeCarry.React(0, safeCarry.CarryReact)

						while os.clock() < n26 and not fn16(arg) do
							RunService.Heartbeat:Wait()
						end
					end

					local n26 = 0

					if safeCarry.CarryStyle ~= "Walk" then
						fn58()
					end

					while not fn16(arg) do
						local v29 = tbl4.Root()
						if not v29 then
							return false
						end

						if not tbl4.Steal.Carrying then
							if now <= safeCarry.LastDelivered then
								return true
							end
							task.wait(0.1)
							if now <= safeCarry.LastDelivered then
								return true
							end

							if safeCarry.LastFailed >= now then
								str3 = "Delivery was rewound, too fast for your speed"
								return false
							end

							if not safeCarry.PlanOk and tbl4.Steal.CarryUid then
								safeCarry.Blocked[tbl4.Steal.CarryUid] = true
								str3 = string.format("The guard caught you with %s, it is faster than your max safe speed, skipping this egg", tostring(safeCarry.Category))
								return false
							end

							n26 += 1
							if safeCarry.RecoverTries < n26 then
								str3 = "The egg is gone"
								return false
							end
							str3 = "Egg dropped, taking it back"
							if not fn53(arg) then
								str3 = "Could not take the egg back"
								return false
							end
							local n27 = 0

							while fn34() and n27 < 4 and not fn16(arg) do
								n27 += RunService.Heartbeat:Wait()
							end

							local n28 = math.min(now, os.clock())
							fn57()

							if safeCarry.CarryStyle ~= "Walk" then
								fn58()
							end

							v29 = tbl4.Root()
							if not v29 then
								return false
							end
							now = n28
						end

						local now3 = os.clock()
						local n27 = math.max(now3 - now2, 0.0041666666666666666)
						local flag5 = safeCarry.CarryStyle == "Walk"
						local n28 = flag5 and 0 or math.max(0, safeCarry.Height)
						local v30, v31 = v27.Step(n27, n28 <= 0.5 and humanoid or nil, humanoid and humanoid.FloorMaterial ~= Enum.Material.Air)
						local n29 = math.clamp(n25 + v31, -425, -300)
						local vector = v29.Position.X > n23 + 2 and Vector3.new(n23, v29.Position.Y, n29) or v25
						local v32, v33 = safeCarry.Avoid(v29.Position, vector)

						if v33 then
							vector = v32
						end

						local vector2 = Vector3.new(vector.X - v29.Position.X, 0, vector.Z - v29.Position.Z)
						if vector2.Magnitude < 2 and vector == v25 then
							break
						end
						local n30 = math.max(n24 * v30, safeCarry.FloorSpeed or 0)

						if os.clock() < (safeCarry.SlowUntil or 0) then
							n30 *= safeCarry.SlowFactor
						end

						if flag5 then
							pcall(function()
								if humanoid and vector2.Magnitude > 0.01 then
									humanoid:MoveTo(v29.Position + vector2.Unit * math.min(vector2.Magnitude, 30))
								end
							end)
						elseif n28 > 0.5 then
							local n31 = math.clamp(safeCarry.ClimbShare, 0.1, 0.9)
							local y = v25.Y
							local n32 = math.max(0, v29.Position.X - n23)
							local n33 = n28 * math.sqrt(1 - n31 * n31) / n31
							local n34 = y + n28

							if vector == v25 or n32 <= n33 then
								n34 = y + n28 * math.clamp((vector == v25 and 0 or n32) / math.max(n33, 1), 0, 1)
							end

							local n35 = math.clamp((n34 - v29.Position.Y) / 0.12, -n30 * n31, n30 * n31)
							local v34 = math.sqrt(math.max(n30 * n30 - n35 * n35, 0))
							local vector3 = vector2.Magnitude > 0.01 and vector2.Unit * math.min(v34, vector2.Magnitude / 0.05) or Vector3.zero

							pcall(function()
								v29.AssemblyLinearVelocity = Vector3.new(vector3.X, n35, vector3.Z)
							end)
						else
							local vector3 = vector2.Magnitude > 0.01 and vector2.Unit * math.min(n30, vector2.Magnitude / 0.05) or Vector3.zero

							pcall(function()
								v29.AssemblyLinearVelocity = Vector3.new(vector3.X, v29.AssemblyLinearVelocity.Y, vector3.Z)

								if safeCarry.RunAnimate and humanoid and vector2.Magnitude > 0.01 then
									humanoid:Move(vector2.Unit, false)
								end
							end)
						end

						RunService.Heartbeat:Wait()
						now2 = now3
					end

					if humanoid then
						pcall(function()
							local v29 = tbl4.Root()

							if safeCarry.CarryStyle == "Walk" and v29 then
								humanoid:MoveTo(v29.Position)
							end

							humanoid:Move(Vector3.zero, false)
						end)
					end

					local n27 = 0

					while n27 < 2 and not fn16(arg) do
						if now <= safeCarry.LastDelivered then
							return true
						end

						if safeCarry.LastFailed >= now then
							str3 = "Delivery was rewound, too fast for your speed"
							return false
						end

						if not tbl4.Steal.Carrying then
							break
						end
						n27 += RunService.Heartbeat:Wait()
					end

					if tbl4.Steal.Carrying then
						task.wait(0.2)
						local eggState = tbl.EggState

						if type(eggState) == "table" and type(eggState.DropFieldEgg) == "function" then
							pcall(eggState.DropFieldEgg, "PlayerRequest")
						end
					end

					return safeCarry.LastDelivered >= now
				end

				-- ============================================================
				-- [V2] INSTANT STEAL V2 (dipindah dari SAE X CHILI "chililatest")
				-- Zona: Titan Temple / Light Dark / Enchanted Forest.
				-- Alur: terbang ke safe zone -> sentuh portal Fuse Biome -> keluar zona
				-- dekat telur -> ambil telur -> loncat per langkah ke garis -> drop di garis
				-- -> reset treadmill -> ambil ulang dari sisi aman -> masuk base.
				-- ============================================================
				do
					local sc = tbl4.SafeCarry
					local defaults = {
						V2On = false, V2Method = "Instant", V2LineGap = 45, V2HopRatio = 3.64,
						V2HopGap = 0.12, V2DropWait = 0.45, V2RegrabTime = 25, V2RegrabGap = 0.03,
						V2RunRatio = 1, V2ChaseMax = 1200, V2FallTries = 3, V2SafeHop = 0.5,
						V2CarryHeight = 40, V2SafeSpeed = 400, V2DirectRadius = 69, V2NearRadius = 150,
						V2SafeWait = 0.3, V2SafeWaitMax = 0.5, V2GrabTime = 8, V2FakeGrabs = 3, V2RunScale = 1,
					}
					for k, val in pairs(defaults) do
						if sc[k] == nil then
							sc[k] = val
						end
					end
					sc.V2Other = "Fast"
					sc.V2Zones = { ["Titan Temple"] = true, ["Light Dark"] = true, ["Enchanted Forest"] = true }

					local FACE = CFrame.Angles(0, math.pi / 2, 0)

					-- [V2 VISUAL-ONLY] Pisahkan karakter yang terlihat dari karakter yang
					-- benar-benar menjalankan logic Instant Steal V2.
					-- Karakter asli tetap dipakai semua fungsi V2; visual clone hanya diam
					-- di base dan kamera lokal diarahkan ke clone sampai V2 selesai.
					local V2Visual = {
						Active = false,
						Model = nil,
						Character = nil,
						Camera = nil,
						CameraSubject = nil,
						HiddenParts = {},
						Link = nil,
					}

					local function v2VisualHideCharacter(character)
						if not character then
							return
						end
						-- [LIGHT] jangan scan seluruh karakter tiap frame (berat di HP); cukup tiap 0.15 detik
						local nowHide = os.clock()
						if V2Visual.HideChar == character and nowHide - (V2Visual.HideAt or 0) < 0.15 then
							return
						end
						V2Visual.HideAt, V2Visual.HideChar = nowHide, character
						for _, obj in ipairs(character:GetDescendants()) do
							if obj:IsA("BasePart") then
								if V2Visual.HiddenParts[obj] == nil then
									V2Visual.HiddenParts[obj] = obj.LocalTransparencyModifier
								end
								if obj.LocalTransparencyModifier ~= 1 then
									pcall(function()
										obj.LocalTransparencyModifier = 1
									end)
								end
							end
						end
					end

					local function v2VisualRestoreCharacter()
						for part, oldTransparency in pairs(V2Visual.HiddenParts) do
							if part and part.Parent then
								pcall(function()
									part.LocalTransparencyModifier = oldTransparency
								end)
							end
						end
						table.clear(V2Visual.HiddenParts)
					end

					-- [FIX NO-BLACK] Hilangkan efek "masuk dimensi lain" (layar gelap) saat masuk/keluar portal Fuse.
-- Selama visual V2 aktif: (1) Lighting dikunci ke kondisi sebelum portal, (2) PostEffect baru
-- (blur/color-correction/bloom/dll) dimatikan & yang lama dikunci nilainya, (3) Sky/Atmosphere
-- zona dibuang, (4) frame gelap full-screen di PlayerGui disembunyikan.
local Lighting = game:GetService("Lighting")
local FxProps = { "Ambient", "OutdoorAmbient", "Brightness", "ColorShift_Top", "ColorShift_Bottom",
	"ExposureCompensation", "FogColor", "FogEnd", "FogStart", "EnvironmentDiffuseScale", "EnvironmentSpecularScale" }
local FxClassProps = {
	ColorCorrectionEffect = { "Enabled", "Brightness", "Contrast", "Saturation", "TintColor" },
	BlurEffect = { "Enabled", "Size" },
	BloomEffect = { "Enabled", "Intensity", "Size", "Threshold" },
	DepthOfFieldEffect = { "Enabled", "FarIntensity", "FocusDistance", "InFocusRadius", "NearIntensity" },
	SunRaysEffect = { "Enabled", "Intensity", "Spread" },
}
local AtmoProps = { "Density", "Offset", "Color", "Decay", "Glare", "Haze" }
local Fx = { Active = false }
V2Visual.Fx = Fx

local function fxIsOurs(obj)
	local cur = obj
	while cur do
		if string.find(string.lower(cur.Name), "fankun", 1, true) then
			return true
		end
		cur = cur.Parent
	end
	return false
end

local function fxDarkCover(obj, view)
	if not (obj:IsA("Frame") or obj:IsA("ImageLabel") or obj:IsA("ImageButton") or obj:IsA("CanvasGroup")) then
		return false
	end
	if not obj.Visible or obj.BackgroundTransparency >= 1 then
		return false
	end
	local sz = obj.AbsoluteSize
	if sz.X < view.X * 0.85 or sz.Y < view.Y * 0.85 then
		return false
	end
	local c = obj.BackgroundColor3
	if (c.R * 0.299 + c.G * 0.587 + c.B * 0.114) > 0.25 then
		return false
	end
	return true
end

local function fxPlayerGui()
	return localPlayer:FindFirstChildOfClass("PlayerGui")
end

local function fxSnapContainer(container)
	for _, o in ipairs(container:GetChildren()) do
		local names = FxClassProps[o.ClassName]
		if names then
			local snap = {}
			for _, n in ipairs(names) do
				local ok, v = pcall(function() return o[n] end)
				if ok then
					snap[n] = v
				end
			end
			Fx.Effects[o] = snap
		elseif o:IsA("Atmosphere") then
			local snap = {}
			for _, n in ipairs(AtmoProps) do
				local ok, v = pcall(function() return o[n] end)
				if ok then
					snap[n] = v
				end
			end
			Fx.Atmos[o] = snap
		elseif o:IsA("Sky") then
			Fx.Skies[o] = true
		end
	end
end

-- [FIX NO-BLACK v2] Penjaga INSTAN berbasis event. Versi lama hanya mengecek tiap 0.1-0.25 detik,
-- jadi saat game men-tween overlay hitam portal, layar sempat hitam sesaat (kedip).
-- Sekarang tiap perubahan properti langsung dikembalikan di frame yang sama sebelum dirender.
function Fx.Guard(o)
	if not Fx.Active or not Fx.Ignore or Fx.Ignore[o] or not o.Parent then
		return
	end
	local cam = workspace.CurrentCamera
	if not cam or fxIsOurs(o) then
		return
	end
	if fxDarkCover(o, cam.ViewportSize) then
		Fx.Hidden[o] = true
		pcall(function()
			o.BackgroundTransparency = 1
			if o:IsA("ImageLabel") or o:IsA("ImageButton") then
				o.ImageTransparency = 1
			end
		end)
	end
end

function Fx.Hook(o)
	if not Fx.Active or Fx.Hooked[o] or Fx.Ignore[o] or fxIsOurs(o) then
		return
	end
	if not (o:IsA("Frame") or o:IsA("ImageLabel") or o:IsA("ImageButton") or o:IsA("CanvasGroup")) then
		return
	end
	Fx.Hooked[o] = true
	for _, prop in ipairs({ "BackgroundTransparency", "ImageTransparency", "Visible", "Size", "BackgroundColor3" }) do
		pcall(function()
			table.insert(Fx.Conns, o:GetPropertyChangedSignal(prop):Connect(function()
				Fx.Guard(o)
			end))
		end)
	end
	Fx.Guard(o)
end

function Fx.Candidate(o)
	-- overlay layar penuh yang gelap, walau sekarang masih transparan/tersembunyi
	local cam = workspace.CurrentCamera
	if not cam or not (o:IsA("Frame") or o:IsA("ImageLabel") or o:IsA("ImageButton") or o:IsA("CanvasGroup")) then
		return false
	end
	local sz = o.AbsoluteSize
	if sz.X < cam.ViewportSize.X * 0.85 or sz.Y < cam.ViewportSize.Y * 0.85 then
		return false
	end
	local c = o.BackgroundColor3
	return (c.R * 0.299 + c.G * 0.587 + c.B * 0.114) <= 0.25
end

local fxEnforceContainer -- forward declaration (diisi di bawah)
local function fxBegin()
	Fx.Active = true
	Fx.Props, Fx.Effects, Fx.Atmos, Fx.Skies, Fx.Hidden, Fx.Ignore = {}, {}, {}, {}, {}, {}
	Fx.Hooked, Fx.Conns = {}, {}
	Fx.NextScan = 0
	for _, n in ipairs(FxProps) do
		local ok, v = pcall(function() return Lighting[n] end)
		if ok then
			Fx.Props[n] = v
		end
	end
	Fx.Clock = Lighting.ClockTime
	fxSnapContainer(Lighting)
	if workspace.CurrentCamera then
		fxSnapContainer(workspace.CurrentCamera)
	end
	local pg = fxPlayerGui()
	local cam = workspace.CurrentCamera
	if pg and cam then
		for _, o in ipairs(pg:GetDescendants()) do
			if o:IsA("GuiObject") and fxDarkCover(o, cam.ViewportSize) then
				Fx.Ignore[o] = true -- overlay gelap yang memang sudah ada sebelum portal: jangan disentuh
			end
		end
		-- pasang penjaga event pada semua overlay gelap layar penuh (termasuk yang masih transparan)
		for _, o in ipairs(pg:GetDescendants()) do
			if o:IsA("GuiObject") and not Fx.Ignore[o] and Fx.Candidate(o) then
				pcall(Fx.Hook, o)
			end
		end
		-- overlay baru yang dibuat game saat masuk portal
		table.insert(Fx.Conns, pg.DescendantAdded:Connect(function(o)
			if not Fx.Active or not o:IsA("GuiObject") then
				return
			end
			pcall(Fx.Hook, o) -- cek langsung (bila sudah gelap+terlihat langsung disembunyikan)
			task.defer(function()
				if Fx.Active and o.Parent and Fx.Candidate(o) then
					pcall(Fx.Hook, o)
				end
			end)
		end))
	end
	-- Lighting + PostEffect: kembalikan seketika begitu berubah / efek baru muncul
	table.insert(Fx.Conns, Lighting.Changed:Connect(function(prop)
		if Fx.Active and Fx.Props and Fx.Props[prop] ~= nil then
			local ok, cur = pcall(function() return Lighting[prop] end)
			if ok and cur ~= Fx.Props[prop] then
				pcall(function() Lighting[prop] = Fx.Props[prop] end)
			end
		end
	end))
	for _, container in ipairs({ Lighting, workspace.CurrentCamera }) do
		if container then
			table.insert(Fx.Conns, container.ChildAdded:Connect(function(ch)
				if Fx.Active then
					pcall(fxEnforceContainer, container)
					pcall(function()
						table.insert(Fx.Conns, ch.Changed:Connect(function()
							if Fx.Active and ch.Parent then
								pcall(fxEnforceContainer, ch.Parent)
							end
						end))
					end)
				end
			end))
			for _, ch in ipairs(container:GetChildren()) do
				pcall(function()
					table.insert(Fx.Conns, ch.Changed:Connect(function()
						if Fx.Active and ch.Parent then
							pcall(fxEnforceContainer, ch.Parent)
						end
					end))
				end)
			end
		end
	end
end

fxEnforceContainer = function(container)
	for _, o in ipairs(container:GetChildren()) do
		if o:IsA("PostEffect") then
			local snap = Fx.Effects[o]
			if snap then
				for n, v in pairs(snap) do
					local ok, cur = pcall(function() return o[n] end)
					if ok and cur ~= v then
						pcall(function() o[n] = v end)
					end
				end
			elseif o.Enabled then
				pcall(function() o.Enabled = false end) -- efek baru dari zona
			end
		elseif o:IsA("Atmosphere") then
			local snap = Fx.Atmos[o]
			if snap then
				for n, v in pairs(snap) do
					local ok, cur = pcall(function() return o[n] end)
					if ok and cur ~= v then
						pcall(function() o[n] = v end)
					end
				end
			elseif o.Density ~= 0 or o.Haze ~= 0 then
				pcall(function()
					o.Density = 0
					o.Haze = 0
					o.Glare = 0
				end)
			end
		elseif o:IsA("Sky") then
			if not Fx.Skies[o] then
				pcall(function() o.Parent = nil end) -- sky zona dibuang
			end
		end
	end
	if container == Lighting then
		for sky in pairs(Fx.Skies) do
			if sky.Parent ~= Lighting then
				pcall(function() sky.Parent = Lighting end)
			end
		end
	end
end

local function fxStep()
	if not Fx.Active then
		return
	end
	-- overlay yang sudah ketahuan: tahan TIAP FRAME (murah) supaya tidak sempat tampil
	for obj in pairs(Fx.Hidden) do
		if obj.Parent then
			if obj.BackgroundTransparency < 1 then
				pcall(function() obj.BackgroundTransparency = 1 end)
			end
			if (obj:IsA("ImageLabel") or obj:IsA("ImageButton")) and obj.ImageTransparency < 1 then
				pcall(function() obj.ImageTransparency = 1 end)
			end
		else
			Fx.Hidden[obj] = nil
		end
	end
	-- [LIGHT] bagian berat dibatasi 0.1 detik (event hook sudah menangani perubahan instan)
	local stepNow = os.clock()
	if Fx.StepAt and stepNow - Fx.StepAt < 0.1 then
		return
	end
	Fx.StepAt = stepNow
	for n, v in pairs(Fx.Props) do
		local ok, cur = pcall(function() return Lighting[n] end)
		if ok and cur ~= v then
			pcall(function() Lighting[n] = v end)
		end
	end
	if Fx.Clock then
		local d = math.abs(Lighting.ClockTime - Fx.Clock)
		d = math.min(d, 24 - d)
		if d > 2 then
			pcall(function() Lighting.ClockTime = Fx.Clock end)
		end
	end
	fxEnforceContainer(Lighting)
	local cam = workspace.CurrentCamera
	if cam then
		fxEnforceContainer(cam)
	end
	-- overlay gelap yang sudah ketahuan: tahan terus supaya tidak muncul lagi saat di-tween game
	for obj in pairs(Fx.Hidden) do
		if obj.Parent then
			if obj.BackgroundTransparency < 1 then
				pcall(function() obj.BackgroundTransparency = 1 end)
			end
			if obj:IsA("ImageLabel") or obj:IsA("ImageButton") then
				if obj.ImageTransparency < 1 then
					pcall(function() obj.ImageTransparency = 1 end)
				end
			end
		else
			Fx.Hidden[obj] = nil
		end
	end
	local now = os.clock()
	if now >= Fx.NextScan and cam then
		Fx.NextScan = now + 0.25
		local pg = fxPlayerGui()
		if pg then
			for _, o in ipairs(pg:GetDescendants()) do
				if o:IsA("GuiObject") and not Fx.Ignore[o] and not Fx.Hidden[o] and fxDarkCover(o, cam.ViewportSize) and not fxIsOurs(o) then
					Fx.Hidden[o] = true
					pcall(function() o.BackgroundTransparency = 1 end)
				end
			end
		end
	end
end

local function fxEnd()
	Fx.Active = false
	if Fx.Conns then
		for _, c in ipairs(Fx.Conns) do
			pcall(function() c:Disconnect() end)
		end
	end
	Fx.Conns, Fx.Hooked = nil, nil
	Fx.Props, Fx.Effects, Fx.Atmos, Fx.Skies, Fx.Hidden, Fx.Ignore = nil, nil, nil, nil, nil, nil
end

