local function lockCamera()
	if not V2Visual.Active then
		return
	end
	local cam = workspace.CurrentCamera
	local subj = V2Visual.CameraSubject
	if cam and subj and subj.Parent and cam.CameraSubject ~= subj then
		pcall(function()
			cam.CameraSubject = subj
		end)
	end
end
local function hookCamera()
	if V2Visual.CamConn then
		pcall(function() V2Visual.CamConn:Disconnect() end)
		V2Visual.CamConn = nil
	end
	local cam = workspace.CurrentCamera
	if cam then
		V2Visual.CamConn = cam:GetPropertyChangedSignal("CameraSubject"):Connect(lockCamera)
	end
end
hookCamera()
V2Visual.CamConn2 = workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function()
