RunService:BindToRenderStep("FanKunV2_VisualCam", Enum.RenderPriority.Camera.Value + 1, function()
if not V2Visual.Active then
return
end
local live = localPlayer.Character
if live then
v2VisualHideCharacter(live)
end
lockCamera()
pcall(fxStep)
end)
end)
lockCamera()

return true
