local function zeroVel(part)
						part.AssemblyLinearVelocity = Vector3.zero
						part.AssemblyAngularVelocity = Vector3.zero
					end

					local function lineInfo()
						local world = workspace:FindFirstChild("World") or workspace:FindFirstChild("__OBJECTS")
						local areas = world and world:FindFirstChild("Areas")
						local line = areas and areas:FindFirstChild("SeparationLine")
						if line and line:IsA("BasePart") then
							return line.Position.X, line.Position.Y
						end
						return 552.2, 67.67
					end

					local function isRagdolled()
						local num = tonumber(localPlayer:GetAttribute("RagdollEndTime"))
						if num and num > workspace:GetServerTimeNow() then
							return true
						end
						local character = localPlayer.Character
						local hum = character and character:FindFirstChildOfClass("Humanoid")
						if hum then
							local state = hum:GetState()
							return state == Enum.HumanoidStateType.Physics
								or state == Enum.HumanoidStateType.Ragdoll
								or state == Enum.HumanoidStateType.FallingDown
						end
						return false
					end

					local function eggModelPos(uid)
						local model = workspace:FindFirstChild(uid)
						if model and model:IsA("Model") then
							local ok, cf, size = pcall(model.GetBoundingBox, model)
							if ok and typeof(cf) == "CFrame" then
								return Vector3.new(cf.X, cf.Y - size.Y / 2, cf.Z)
							end
						end
						return nil
					end

					-- return: record | false (snapshot ok tapi uid tidak ada) | nil (snapshot gagal)
					local function eggRecord(uid)
						local rf = networking:FindFirstChild("RF/EggWorld/AskFieldEggSnapshot")
						if not rf or not rf:IsA("RemoteFunction") then
							return nil
						end
						local ok, res = pcall(rf.InvokeServer, rf)
						local recs = ok and type(res) == "table" and res.Records or nil
						if type(recs) ~= "table" then
							return nil
						end
						for _, rec in pairs(recs) do
							if type(rec) == "table" and rec.Uid == uid then
								return rec
							end
						end
						return false
					end

					local function carryEgg(uid)
						local eggState = tbl.EggState
						if type(eggState) == "table" and type(eggState.CarryFieldEgg) == "function" then
							pcall(eggState.CarryFieldEgg, uid)
						end
					end

					-- ============================================================
					-- [V2 PROGRESS UI] Progress pop up stand alone, KHUSUS Instant Steal V2.
					-- Posisi: pojok kanan atas. Ada ikon egg/pet target.
					-- Muncul sejak teleport ke portal (terbang ke safe zone TIDAK ditampilkan),
					-- jalan: Berangkat -> Ambil telur -> Bawa pulang -> Masuk base.
					-- Waktu = hitungan mundur (estimasi belajar dari run sukses sebelumnya).
					-- Fase reset treadmill / ambil ulang tidak ditampilkan (bar menahan nilai).
					-- Hilang setelah V2VisualEnd. Hanya membaca str3, logic V2 tidak diubah.
					-- ============================================================
					do
						local TweenSvc = game:GetService("TweenService")
						local UISvc = game:GetService("UserInputService")
						local RunSvc = game:GetService("RunService")
						local GUI_NAME = "FanKunV2_Progress"

						local PROG = {
							Gui = nil, Root = nil, Fill = nil, Pct = nil, Stage = nil, Detail = nil, Timer = nil,
							IconImg = nil, IconEmoji = nil, IconStroke = nil,
							Conn = nil, Active = false, Visible = false, Token = 0,
							Value = 0, Shown = 0, StartAt = 0,
							Entry = nil, EntryAt = 0, Studs0 = nil, StageIdx = 1,
							TargetUid = nil,
						}
						sc.V2Progress = PROG

						-- [UI] warna disamakan dengan UI utama FanKun Hub (terang, aksen hitam)
						local COLOR_RUN = Color3.fromRGB(14, 14, 14)
						local COLOR_OK = Color3.fromRGB(30, 150, 90)
						local COLOR_FAIL = Color3.fromRGB(205, 40, 40)

						local STAGE_NAMES = { "Heading to target", "Taking pet", "Carrying home", "Entering base", "Chasing target" }

						-- { potongan teks str3 (huruf kecil), fase, nilai awal, nilai akhir, mode, tau }
						-- Status terbang ke safe zone / reset treadmill sengaja tidak ada di sini (tidak ditampilkan).
						local PATTERNS = {
							{ "touching the lane portal", 1, 0.00, 0.08 },
							{ "inside the fuse biome", 1, 0.08, 0.16, nil, nil, true },
							{ "running to the egg", 1, 0.16, 0.34, "studs" },
							{ "chasing the locked egg", 5, 0.16, 0.34 },
							{ "another player has the egg", 5, 0.16, 0.34 },
							{ "hit, getting up", 5, 0.16, 0.34 },
							{ "knocked down, moving", 2, 0.34, 0.36 },
							{ "grab and drop", 2, 0.36, 0.48, "count" },
							{ "wrong egg in hand", 2, 0.36, 0.48 },
							{ "taking the egg", 2, 0.48, 0.54 },
							{ "stepping the egg", 3, 0.54, 0.58 },
							{ "stepping home", 3, 0.58, 0.86, nil, 7 },
							{ "dropping the egg at the line", 3, 0.86, 0.89 },
							{ "the egg slipped", 5, 0.54, 0.58 },
							{ "the egg fell", 5, 0.54, 0.58 },
							{ "hit by guard", 5, 0.54, 0.58 },
							{ "stepping into the safe zone", 4, 0.89, 0.99 },
						}

						local FAIL_TEXTS = {
							"failed", "would not come free", "respawned", "could not", "went back to its nest",
							"egg is gone", "kept falling",
						}

						local function cleanText(s)
							local out = string.gsub(s, "^Instant Steal V2: ", "")
							out = string.gsub(out, "[Ee]ggs", "pets")
							out = string.gsub(out, "Egg", "Pet")
							out = string.gsub(out, "egg", "pet")
							return out
						end

						-- ikon PET dari data game (tbl.Assets.Directory[kategori]); field bernama "Pet*" diutamakan
						-- supaya yang tampil gambar pet, bukan gambar telur. Cadangan: huruf awal nama pet.
						local function toImage(v)
							if type(v) == "table" then
								for _, k in ipairs({ "Icon", "Image", "ImageId", "Thumbnail", "Texture", "TextureId" }) do
									local r = v[k]
									if r ~= nil and type(r) ~= "table" then
										v = r
										break
									end
								end
							end
							if v == nil or type(v) == "table" then
								return nil
							end
							if type(v) == "number" or (type(v) == "string" and tonumber(v)) then
								return "rbxassetid://" .. tostring(v)
							end
							v = tostring(v)
							if v == "" then
								return nil
							end
							return v
						end

						local function resolveIcon(category)
							if type(category) ~= "string" then
								return nil
							end
							local ok, dir = pcall(function()
								return tbl.Assets and tbl.Assets.Directory
							end)
							local entry = ok and type(dir) == "table" and dir[category] or nil
							if type(entry) ~= "table" and ok and type(dir) == "table" then
								local want = string.lower(category)
								for k, v in pairs(dir) do
									if type(v) == "table" and (string.lower(tostring(k)) == want or string.lower(tostring(v.DisplayName or "")) == want) then
										entry = v
										break
									end
								end
							end
							if type(entry) ~= "table" then
								return nil
							end
							-- 1) key yang namanya mengandung "pet" (PetIcon, PetImage, Pet = {Icon=..}, dst)
							for k, v in pairs(entry) do
								if type(k) == "string" and string.find(string.lower(k), "pet", 1, true) then
									local img = toImage(v)
									if img then
										return img
									end
								end
							end
							-- 2) ikon utama data game
							local main = toImage(entry.Icon) or toImage(entry.Image) or toImage(entry.Thumbnail)
								or toImage(entry.ImageId) or toImage(entry.Texture) or toImage(entry.TextureId)
							if main then
								return main
							end
							-- 3) key lain yang namanya mengandung icon/image/thumb
							for k, v in pairs(entry) do
								if type(k) == "string" then
									local lk = string.lower(k)
									if string.find(lk, "icon", 1, true) or string.find(lk, "image", 1, true) or string.find(lk, "thumb", 1, true) then
										local img = toImage(v)
										if img then
											return img
										end
									end
								end
							end
							return nil
						end

						local function applyIcon(category)
							if not PROG.IconImg then
								return
							end
							-- tidak pernah memakai huruf/emoji pengganti: hanya ikon pet
							PROG.IconEmoji.Visible = false
							if category == nil then
								PROG.IconCat = nil
								PROG.IconOk = false
								PROG.IconImg.Visible = false
								return
							end
							PROG.IconCat = category
							local icon = resolveIcon(category)
							if icon then
								PROG.IconImg.Image = icon
								PROG.IconImg.Visible = true
								PROG.IconOk = true
							else
								-- belum ketemu: step() akan mencoba lagi sampai ikon pet ada
								PROG.IconOk = false
							end
						end

						-- info target: rarity (chip berwarna), nama egg, Value, Harga jual, Berat
						local RARITY_FALLBACK = {
							common = Color3.fromRGB(110, 110, 120),
							uncommon = Color3.fromRGB(30, 150, 70),
							rare = Color3.fromRGB(40, 110, 220),
							epic = Color3.fromRGB(150, 70, 220),
							legendary = Color3.fromRGB(230, 150, 0),
							mythic = Color3.fromRGB(220, 50, 80),
							cosmic = Color3.fromRGB(0, 150, 160),
							secret = Color3.fromRGB(40, 40, 40),
							divine = Color3.fromRGB(200, 160, 20),
							eternal = Color3.fromRGB(200, 40, 200),
							ethernal = Color3.fromRGB(200, 40, 200),
						}

						local function fmtNum(n)
							n = tonumber(n) or 0
							local units = { { 1e12, "T" }, { 1e9, "B" }, { 1e6, "M" }, { 1e3, "K" } }
							for _, u in ipairs(units) do
								if n >= u[1] then
									local s = string.format("%.2f", n / u[1])
									s = string.gsub(s, "(%..-)0+$", "%1")
									s = string.gsub(s, "%.$", "")
									return s .. u[2]
								end
							end
							return tostring(math.floor(n + 0.5))
						end

						local function applyInfo(category, rec, target)
							if not PROG.Chip then
								return
							end
							if type(category) ~= "string" then
								PROG.Chip.Visible = false
								PROG.EggName.Text = ""
								PROG.Stats.Text = ""
								return
							end
							local okD, dir = pcall(function()
								return tbl.Assets and tbl.Assets.Directory
							end)
							local entry = okD and type(dir) == "table" and dir[category] or nil
							local rarity = type(entry) == "table" and type(entry.Rarity) == "table" and entry.Rarity or nil
							local rname = rarity and tostring(rarity.DisplayName or rarity._id or "") or ""
							local col = rarity and typeof(rarity.Color) == "Color3" and rarity.Color or nil
							col = col or RARITY_FALLBACK[string.lower((string.gsub(rname, "%s+", "")))] or Color3.fromRGB(110, 110, 120)
							-- chip: latar = warna rarity dipucatkan, teks = warna rarity digelapkan (terbaca di UI terang)
							local dark = Color3.new(col.R * 0.62, col.G * 0.62, col.B * 0.62)
							local soft = Color3.new(1 - (1 - col.R) * 0.16, 1 - (1 - col.G) * 0.16, 1 - (1 - col.B) * 0.16)
							if rname ~= "" then
								PROG.Chip.Visible = true
								PROG.Chip.BackgroundColor3 = soft
								PROG.ChipStroke.Color = col
								PROG.ChipTxt.TextColor3 = dark
								PROG.ChipTxt.Text = string.upper(rname)
							else
								PROG.Chip.Visible = false
							end
							PROG.EggName.Text = type(entry) == "table" and tostring(entry.DisplayName or category) or tostring(category)
							if PROG.IconStroke then
								PROG.IconStroke.Color = col
							end

							local t = type(target) == "table" and target or {}
							local scale = tonumber(t.Scale) or (type(rec) == "table" and tonumber(rec.AssetScale)) or nil

							-- Value (income per detik)
							local value = tonumber(t.Value)
							if not value and type(entry) == "table" and scale and scale > 0 then
								local rate = tonumber(entry.EarningRate) or 0
								local f = scale > 5 and (scale / 5) ^ 1.2 * 19.637875755794113 or scale ^ 1.85
								local mult = tonumber(t.Mutation) or 1
								if not t.Mutation and type(rec) == "table" and type(tbl.Mutations) == "table" and type(tbl.Mutations.EarningsFor) == "function" then
									local okM, r = pcall(tbl.Mutations.EarningsFor, type(rec.Mutations) == "table" and rec.Mutations or {})
									if okM and type(r) == "number" then
										mult = r
									end
								end
								value = rate * f * mult
							end

							-- Harga jual
							local price = nil
							local ER = tbl.EggRecords
							if type(rec) == "table" and type(ER) == "table" and type(ER.SellPrice) == "function" then
								local okP, r = pcall(ER.SellPrice, rec)
								price = okP and tonumber(r) or nil
							end

							-- Berat
							local weight = tonumber(t.Weight)
							if not weight and scale then
								local ER2 = tbl.EggRecords
								if type(ER2) == "table" and type(ER2.WeightKgForScale) == "function" then
									local okW, r = pcall(ER2.WeightKgForScale, category, scale)
									weight = okW and tonumber(r) or nil
								end
							end

							local parts = {}
							if value then
								parts[#parts + 1] = string.format('Value <font color="#0c0c0c"><b>%s/s</b></font>', fmtNum(value))
							end
							if price then
								parts[#parts + 1] = string.format('Harga <font color="#0c0c0c"><b>$%s</b></font>', fmtNum(price))
							end
							if weight then
								parts[#parts + 1] = string.format('<font color="#0c0c0c"><b>%.2f kg</b></font>', weight)
							end
							PROG.Stats.Text = table.concat(parts, "  \u{00B7}  ")
						end

						local function pickParent()
							if typeof(gethui) == "function" then
								local ok, hui = pcall(gethui)
								if ok and typeof(hui) == "Instance" then
									return hui
								end
							end
							local ok, core = pcall(function()
								return game:GetService("CoreGui")
							end)
							if ok and typeof(core) == "Instance" then
								return core
							end
							return localPlayer:FindFirstChildOfClass("PlayerGui")
						end

						local function build()
							if PROG.Gui and PROG.Gui.Parent then
								return true
							end

							local parent = pickParent()
							if parent then
								pcall(function()
									local old = parent:FindFirstChild(GUI_NAME)
									if old then
										old:Destroy()
									end
								end)
							end

							local gui = Instance.new("ScreenGui")
							gui.Name = GUI_NAME
							gui.ResetOnSpawn = false
