							iconBox.BorderSizePixel = 0
							iconBox.Parent = root
							local iconCorner = Instance.new("UICorner")
							iconCorner.CornerRadius = UDim.new(0, 8)
							iconCorner.Parent = iconBox
							local iconStroke = Instance.new("UIStroke")
							iconStroke.Color = COLOR_RUN
							iconStroke.Thickness = 1.5
							iconStroke.Parent = iconBox

							local iconImg = Instance.new("ImageLabel")
							iconImg.BackgroundTransparency = 1
							iconImg.AnchorPoint = Vector2.new(0.5, 0.5)
							iconImg.Position = UDim2.fromScale(0.5, 0.5)
							iconImg.Size = UDim2.new(1, -6, 1, -6)
							iconImg.ScaleType = Enum.ScaleType.Fit
							iconImg.Visible = false
							iconImg.Parent = iconBox

							local iconEmoji = Instance.new("TextLabel")
							iconEmoji.BackgroundTransparency = 1
							iconEmoji.Size = UDim2.fromScale(1, 1)
							iconEmoji.Font = Enum.Font.GothamBold
							iconEmoji.TextSize = 20
							iconEmoji.Text = "?"
							iconEmoji.TextColor3 = Color3.fromRGB(12, 12, 12)
							iconEmoji.Parent = iconBox

							local stage = Instance.new("TextLabel")
							stage.BackgroundTransparency = 1
							stage.Position = UDim2.fromOffset(56, 6)
							stage.Size = UDim2.new(1, -110, 0, 16)
							stage.Font = Enum.Font.GothamBold
							stage.TextSize = 12
							stage.TextXAlignment = Enum.TextXAlignment.Left
							stage.TextColor3 = Color3.fromRGB(12, 12, 12)
							stage.Text = "Instant Steal V2"
							stage.Parent = root

							local pct = Instance.new("TextLabel")
							pct.BackgroundTransparency = 1
							pct.AnchorPoint = Vector2.new(1, 0)
							pct.Position = UDim2.new(1, -10, 0, 6)
							pct.Size = UDim2.fromOffset(44, 16)
							pct.Font = Enum.Font.GothamBold
							pct.TextSize = 12
							pct.TextXAlignment = Enum.TextXAlignment.Right
							pct.TextColor3 = Color3.fromRGB(12, 12, 12)
							pct.Text = "0%"
							pct.Parent = root

							local barBg = Instance.new("Frame")
							barBg.Position = UDim2.fromOffset(56, 26)
							barBg.Size = UDim2.new(1, -66, 0, 6)
							barBg.BackgroundColor3 = Color3.fromRGB(225, 225, 225)
							barBg.BorderSizePixel = 0
							barBg.Parent = root
							local barCorner = Instance.new("UICorner")
							barCorner.CornerRadius = UDim.new(1, 0)
							barCorner.Parent = barBg

							local fill = Instance.new("Frame")
							fill.Size = UDim2.new(0, 0, 1, 0)
							fill.BackgroundColor3 = COLOR_RUN
							fill.BorderSizePixel = 0
							fill.Parent = barBg
							local fillCorner = Instance.new("UICorner")
							fillCorner.CornerRadius = UDim.new(1, 0)
							fillCorner.Parent = fill

							-- baris info target: chip rarity + nama egg
							local chip = Instance.new("Frame")
							chip.Name = "RarityChip"
							chip.Position = UDim2.fromOffset(56, 38)
							chip.Size = UDim2.fromOffset(0, 17)
							chip.AutomaticSize = Enum.AutomaticSize.X
							chip.BackgroundColor3 = Color3.fromRGB(230, 230, 230)
							chip.BorderSizePixel = 0
							chip.Visible = false
							chip.Parent = root
							local chipCorner = Instance.new("UICorner")
							chipCorner.CornerRadius = UDim.new(0, 5)
							chipCorner.Parent = chip
							local chipStroke = Instance.new("UIStroke")
							chipStroke.Color = Color3.fromRGB(205, 205, 205)
							chipStroke.Thickness = 1
							chipStroke.Parent = chip
							local chipPad = Instance.new("UIPadding")
							chipPad.PaddingLeft = UDim.new(0, 7)
							chipPad.PaddingRight = UDim.new(0, 7)
							chipPad.Parent = chip
							local chipTxt = Instance.new("TextLabel")
							chipTxt.BackgroundTransparency = 1
							chipTxt.Size = UDim2.fromOffset(0, 17)
							chipTxt.AutomaticSize = Enum.AutomaticSize.X
							chipTxt.Font = Enum.Font.GothamBold
							chipTxt.TextSize = 10
							chipTxt.TextColor3 = Color3.fromRGB(12, 12, 12)
							chipTxt.Text = ""
							chipTxt.Parent = chip

							local eggName = Instance.new("TextLabel")
							eggName.BackgroundTransparency = 1
							eggName.AnchorPoint = Vector2.new(1, 0)
							eggName.Position = UDim2.new(1, -10, 0, 38)
							eggName.Size = UDim2.new(1, -150, 0, 17)
							eggName.Font = Enum.Font.GothamMedium
							eggName.TextSize = 11
							eggName.TextXAlignment = Enum.TextXAlignment.Right
							eggName.TextTruncate = Enum.TextTruncate.AtEnd
							eggName.TextColor3 = Color3.fromRGB(100, 100, 100)
							eggName.Text = ""
							eggName.Parent = root

							-- baris statistik: Value / Harga / Berat
							local stats = Instance.new("TextLabel")
							stats.BackgroundTransparency = 1
							stats.Position = UDim2.fromOffset(10, 58)
							stats.Size = UDim2.new(1, -20, 0, 14)
							stats.Font = Enum.Font.GothamMedium
							stats.TextSize = 11
							stats.RichText = true
							stats.TextXAlignment = Enum.TextXAlignment.Left
							stats.TextTruncate = Enum.TextTruncate.AtEnd
							stats.TextColor3 = Color3.fromRGB(100, 100, 100)
							stats.Text = ""
							stats.Parent = root

							local detail = Instance.new("TextLabel")
							detail.BackgroundTransparency = 1
							detail.Position = UDim2.fromOffset(10, 74)
							detail.Size = UDim2.new(1, -72, 0, 14)
							detail.Font = Enum.Font.Gotham
							detail.TextSize = 10
							detail.TextXAlignment = Enum.TextXAlignment.Left
							detail.TextTruncate = Enum.TextTruncate.AtEnd
							detail.TextColor3 = Color3.fromRGB(100, 100, 100)
							detail.Text = ""
							detail.Parent = root

							local timer = Instance.new("TextLabel")
							timer.BackgroundTransparency = 1
							timer.AnchorPoint = Vector2.new(1, 0)
							timer.Position = UDim2.new(1, -10, 0, 74)
							timer.Size = UDim2.fromOffset(56, 14)
							timer.Font = Enum.Font.GothamBold
							timer.TextSize = 10
							timer.TextXAlignment = Enum.TextXAlignment.Right
							timer.TextColor3 = Color3.fromRGB(12, 12, 12)
							timer.Text = "0.0s"
							timer.Parent = root

							-- bisa digeser (mouse / sentuh)
							local dragging, dragStart, startPos = false, nil, nil
							root.InputBegan:Connect(function(input)
								if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
									dragging = true
									dragStart = input.Position
									startPos = root.Position
									input.Changed:Connect(function()
										if input.UserInputState == Enum.UserInputState.End then
											dragging = false
										end
									end)
								end
							end)
							UISvc.InputChanged:Connect(function(input)
								if dragging and dragStart and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
									local d = input.Position - dragStart
									root.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + d.X, startPos.Y.Scale, startPos.Y.Offset + d.Y)
								end
							end)

							PROG.Gui, PROG.Root, PROG.Fill = gui, root, fill
							PROG.Pct, PROG.Stage, PROG.Detail, PROG.Timer = pct, stage, detail, timer
							PROG.IconImg, PROG.IconEmoji, PROG.IconStroke = iconImg, iconEmoji, iconStroke
							PROG.Chip, PROG.ChipTxt, PROG.ChipStroke = chip, chipTxt, chipStroke
							PROG.EggName, PROG.Stats = eggName, stats
							return true
						end

						local function fade(toTransparency, hideAfter)
							local root = PROG.Root
							if not root then
								return
							end
							if toTransparency < 1 then
								root.Visible = true
							end
							local tw = TweenSvc:Create(root, TweenInfo.new(0.22), { GroupTransparency = toTransparency })
							tw:Play()
							if hideAfter then
								local token = PROG.Token
								tw.Completed:Connect(function()
									if PROG.Token == token and not PROG.Active and PROG.Root then
										PROG.Root.Visible = false
									end
								end)
							end
						end

						local function setAccent(color)
							if PROG.Fill then
								PROG.Fill.BackgroundColor3 = color
							end
							if PROG.IconStroke then
								PROG.IconStroke.Color = color
							end
						end

						-- sisa waktu (hitungan mundur): estimasi dari run sukses sebelumnya,
						-- dikoreksi dengan kecepatan progress yang sedang berjalan
						local function remaining()
							local eta = tonumber(sc.V2ProgressETA) or 25
							local el = os.clock() - (PROG.VisibleAt or PROG.StartAt)
							local total = eta
							if PROG.Value > 0.2 then
								total = 0.5 * eta + 0.5 * (el / PROG.Value)
							end
							return math.max(total - el, 0)
						end

						local function paint()
							if not PROG.Root then
								return
							end
							PROG.Fill.Size = UDim2.new(math.clamp(PROG.Shown, 0, 1), 0, 1, 0)
							PROG.Pct.Text = string.format("%d%%", math.floor(PROG.Shown * 100 + 0.5))
							PROG.Stage.Text = STAGE_NAMES[PROG.StageIdx] or "Instant Steal V2"
							PROG.Timer.Text = string.format("%.1fs", PROG.Visible and remaining() or (tonumber(sc.V2ProgressETA) or 25))
						end

						local function showNow()
							if not PROG.Visible then
								PROG.Visible = true
								PROG.VisibleAt = os.clock()
								fade(0, false)
							end
						end

						local function step(dt)
							if sc.V2On ~= true or sc.V2Method ~= "Instant" or os.clock() - PROG.StartAt > 240 then
								PROG.Hide()
								return
							end

							-- pastikan ikon pet selalu muncul, di lokasi mana pun
							if not PROG.IconOk and os.clock() - (PROG.IconTry or 0) >= 0.35 then
								PROG.IconTry = os.clock()
								if PROG.IconCat ~= nil then
									applyIcon(PROG.IconCat)
								else
									local lt = sc.V2LastTarget
									if type(lt) == "table" and type(lt.target) == "table" and os.clock() - lt.at < 90 then
										PROG.TargetUid = nil
										pcall(PROG.SetTarget, lt.target)
									elseif tbl4.Steal.Carrying and type(sc.Category) == "string" then
										applyIcon(sc.Category)
									end
								end
							end

							local s = str3
							if type(s) == "string" and s ~= "" then
								local low = string.lower(s)
								for i, p in ipairs(PATTERNS) do
									if string.find(low, p[1], 1, true) then
										if PROG.Entry ~= i then
											PROG.Entry = i
											PROG.EntryAt = os.clock()
											PROG.Studs0 = nil
										end
										PROG.StageIdx = p[2]

										local creep = nil
										if p[5] == "studs" then
											local n = tonumber(string.match(s, "(%d+) studs"))
											if n then
												if not PROG.Studs0 or n > PROG.Studs0 then
													PROG.Studs0 = n
												end
												creep = 1 - n / math.max(PROG.Studs0, 1)
											end
										elseif p[5] == "count" then
											local a, b = string.match(s, "(%d+)/(%d+)")
											if a and b and tonumber(b) > 0 then
												creep = tonumber(a) / tonumber(b)
											end
										end
										if creep == nil then
											creep = 1 - math.exp(-(os.clock() - PROG.EntryAt) / (p[6] or 2.5))
										end
										creep = math.clamp(creep, 0, 1)

										local want = math.min(p[3] + (p[4] - p[3]) * creep, 0.99)
										if want > PROG.Value then
											PROG.Value = want
										end
										PROG.Detail.Text = p[7] and "" or cleanText(s)
										showNow()
										break
									end
								end
							end

							PROG.Shown += (PROG.Value - PROG.Shown) * math.min(1, dt * 8)
							paint()
						end

						PROG.Start = function()
							if PROG.Active or sc.V2On ~= true or sc.V2Method ~= "Instant" then
								return
							end
							if not build() then
								return
							end
							PROG.Token += 1
							PROG.Active = true
							PROG.Visible = false
							PROG.VisibleAt = nil
							PROG.TargetUid = nil
							PROG.Value, PROG.Shown = 0, 0
							PROG.Entry, PROG.Studs0, PROG.StageIdx = nil, nil, 1
							PROG.StartAt = os.clock()
							setAccent(COLOR_RUN)
							PROG.Detail.Text = ""
							applyIcon(nil)
							applyInfo(nil)
							local lt0 = sc.V2LastTarget
							if type(lt0) == "table" and type(lt0.target) == "table" and os.clock() - lt0.at < 20 then
								pcall(PROG.SetTarget, lt0.target)
							end
							paint()
							if PROG.Root then
								PROG.Root.GroupTransparency = 1
								PROG.Root.Visible = false
							end
							if PROG.Conn then
								PROG.Conn:Disconnect()
							end
							PROG.Conn = RunSvc.Heartbeat:Connect(step)
						end

						-- dipanggil dari PortalTo (target telur) untuk ikon egg/pet
						PROG.SetTarget = function(target)
							if not PROG.Active or type(target) ~= "table" then
								return
							end
							local uid = target.Uid
							if uid ~= nil and uid == PROG.TargetUid then
								return
							end
							PROG.TargetUid = uid
							local cat = type(target.AssetCategory) == "string" and target.AssetCategory
								or type(target.Category) == "string" and target.Category
								or nil
							if cat then
								applyIcon(cat)
								applyInfo(cat, nil, target)
							end
							if type(uid) == "string" then
								local token = PROG.Token
								task.spawn(function()
									local rec = eggRecord(uid)
									if PROG.Token == token and type(rec) == "table" then
										local c = type(rec.AssetCategory) == "string" and rec.AssetCategory or cat
										if not cat or not PROG.IconOk then
											applyIcon(c)
										end
										applyInfo(c, rec, target)
									end
								end)
							end
						end

						-- dipanggil dari alur steal untuk SEMUA lokasi (bukan hanya zona V2 / PortalTo)
						sc.V2SetTarget = function(target)
							if type(target) ~= "table" then
								return
							end
							sc.V2LastTarget = { target = target, at = os.clock() }
							if PROG.Active then
								pcall(PROG.SetTarget, target)
							end
						end

						PROG.Hide = function()
							PROG.Active = false
							if PROG.Conn then
								PROG.Conn:Disconnect()
								PROG.Conn = nil
							end
							fade(1, true)
						end

						-- dipanggil saat V2 selesai (return / delivery selesai atau gagal)
						PROG.Finish = function()
							if not PROG.Active then
								return
							end
							PROG.Active = false
							if PROG.Conn then
								PROG.Conn:Disconnect()
								PROG.Conn = nil
							end
							local token = PROG.Token
							-- str3 hasil akhir diisi tepat setelah V2VisualEnd, jadi dibaca sesudah defer
							task.defer(function()
								if PROG.Token ~= token or not PROG.Root then
									return
								end
								local s = type(str3) == "string" and str3 or ""
								local low = string.lower(s)
								local verdict = nil
								if s == "Delivered" then
									verdict = "ok"
								else
									for _, f in ipairs(FAIL_TEXTS) do
										if string.find(low, f, 1, true) then
											verdict = "fail"
											break
										end
									end
								end

								if verdict == "ok" then
									local used = os.clock() - (PROG.VisibleAt or PROG.StartAt)
									sc.V2ProgressETA = math.clamp(0.6 * (tonumber(sc.V2ProgressETA) or 25) + 0.4 * used, 8, 120)
									PROG.Value, PROG.Shown = 1, 1
									PROG.StageIdx = 4
									setAccent(COLOR_OK)
									PROG.Detail.Text = "Pet delivered to base"
									paint()
									PROG.Stage.Text = "Done"
									PROG.Timer.Text = "0.0s"
									showNow()
								elseif verdict == "fail" then
									setAccent(COLOR_FAIL)
									local msg = cleanText(s)
									if string.find(low, "target egg is gone", 1, true) then
										msg = "Target is gone"
									elseif string.find(low, "chase time ran out", 1, true) then
										msg = "Chase time ran out"
									end
									PROG.Detail.Text = msg
									paint()
									PROG.Stage.Text = "Failed"
									PROG.Timer.Text = "0.0s"
									showNow()
								else
									-- V2 dilepas tanpa hasil (mis. portal tidak ada, lanjut alur biasa)
									fade(1, true)
									return
								end

								task.delay(1.6, function()
									if PROG.Token == token and not PROG.Active then
										fade(1, true)
									end
								end)
							end)
						end

						-- pasang ke titik mulai & selesai V2 (pemanggil di fn lain tidak perlu diubah)
						local baseBegin = sc.V2VisualBegin
						sc.V2VisualBegin = function(...)
							pcall(PROG.Start)
							return baseBegin(...)
						end

						local baseEnd = sc.V2VisualEnd
						sc.V2VisualEnd = function(...)
							pcall(PROG.Finish)
							return baseEnd(...)
						end
					end

					-- true bila telur masih ada di field (Slot/Dropped) atau snapshot tidak bisa dibaca
					sc.V2EggAlive = function(uid)
						local rec = eggRecord(uid)
						if rec == nil then
							return true
						end
						return type(rec) == "table" and rec.State ~= "Carried"
					end

					sc.V2Zone = function(rec)
						return type(rec) == "table" and sc.V2Zones[tostring(rec.Zone or rec.AreaId)] == true
					end

					-- [V2 VISUAL ALL ZONES] Selama Instant Steal V2 menjalankan steal di lokasi MANA PUN
					-- (bukan hanya Titan Temple / Light Dark / Enchanted Forest), karakter yang terlihat
					-- tetap diam di base walau karakter asli berjalan/terbang/mengantar telur.
					-- Zona V2 tetap memanggil Begin/End sendiri; watcher ini hanya menambah lokasi lain.
					do
						local activeSince, idleSince, lastTry = nil, nil, 0
						RunService.Heartbeat:Connect(function()
							local steal = tbl4.Steal
							local want = sc.V2On == true and sc.V2Method == "Instant" and type(steal) == "table" and steal.Active == true
							local now = os.clock()
							if want then
								idleSince = nil
								activeSince = activeSince or now
								-- tunggu 0.15s supaya percobaan yang langsung gagal tidak bikin clone keluar-masuk
								if not V2Visual.Active and now - activeSince >= 0.03 and now - lastTry >= 0.25 then
									lastTry = now
									pcall(sc.V2VisualBegin)
								end
							else
								activeSince = nil
								if V2Visual.Active then
									idleSince = idleSince or now
									-- jeda 0.4s: Steal.Active sempat false sesaat di antara dua siklus steal
									if now - idleSince >= 0.4 then
										idleSince = nil
										pcall(sc.V2VisualEnd)
									end
								else
									idleSince = nil
								end
							end
						end)
					end

					sc.V2_Portal = function()
						local world = workspace:FindFirstChild("World")
						local build = world and world:FindFirstChild("Build")
						local lanes = build and build:FindFirstChild("FuseBiomeLanePortals")
						local zone = build and build:FindFirstChild("FuseBiomeZone")
						local lanePart = lanes and (lanes:FindFirstChildWhichIsA("BasePart") or lanes:FindFirstChildWhichIsA("BasePart", true))
						return lanePart, zone and zone:FindFirstChild("ExitPart", true)
					end

					sc.V2_Touch = function(part, target)
						if type(firetouchinterest) == "function" and part and target then
							pcall(function()
								firetouchinterest(part, target, 0)
								firetouchinterest(part, target, 1)
							end)
						end
					end

					sc.V2_InZone = function()
						local r = tbl4.Root()
						return r ~= nil and r.Position.Y > 10000
					end

					sc.V2_LeaveZone = function()
						local _, exitPart = sc.V2_Portal()
						local untilT, nextTouch = os.clock() + 12, 0
						while os.clock() < untilT and sc.V2_InZone() do
							local r = tbl4.Root()
							if r and exitPart and os.clock() >= nextTouch then
								nextTouch = os.clock() + 0.25
								pcall(function()
									r.CFrame = CFrame.new(exitPart.Position)
									r.AssemblyLinearVelocity = Vector3.zero
								end)
								sc.V2_Touch(r, exitPart)
							end
							RunService.Heartbeat:Wait()
						end
						return not sc.V2_InZone()
					end

					sc.V2_Stand = function(pos)
						local character = localPlayer.Character
						local hum = character and character:FindFirstChildOfClass("Humanoid")
						local r = tbl4.Root()
						return Vector3.new(pos.X, pos.Y + (hum and hum.HipHeight or 2) + (r and r.Size.Y / 2 or 1), pos.Z)
					end

					-- Ambil telur: jalan ke telur + proximity prompt + CarryFieldEgg. return true bila telur di tangan.
					sc.V2Grab = function(target, token, timeout, chase)
						local uid = target.Uid
						if type(uid) ~= "string" then
							return false
						end
						local steal = tbl4.Steal
						local eggState = tbl.EggState
						local pos = typeof(target.CFrame) == "CFrame" and target.CFrame.Position or nil
						local deadline = os.clock() + (timeout or sc.V2GrabTime)
						local char = localPlayer.Character
						local hum = char and char:FindFirstChildOfClass("Humanoid")
						if hum and char:FindFirstChildWhichIsA("Tool") then
							pcall(function()
								hum:UnequipTools()
							end)
						end
						local checkAt, misses, inflight, sincePrompt = os.clock() + 0.5, 0, 0, math.huge
						while os.clock() < deadline and not fn16(token) do
							if localPlayer.Character ~= char then
								return false
							end
							if steal.Carrying and not steal.WrongEgg(uid) then
								return true
							end
							local now = os.clock()
							local live = eggModelPos(uid)
							if live then
								pos = live
							end
							if now >= checkAt then
								checkAt = now + 0.5
								local okSnap, snap = false, nil
								if type(eggState) == "table" and type(eggState.ReadFieldEggs) == "function" then
									okSnap, snap = pcall(eggState.ReadFieldEggs)
								end
								local recs = okSnap and type(snap) == "table" and type(snap.Records) == "table" and snap.Records or nil
								if recs then
									local rec
									for _, r2 in pairs(recs) do
										if type(r2) == "table" and r2.Uid == uid then
											rec = r2
											break
										end
									end
									if chase and rec and rec.State == "Slot" then
										break
									end
									if rec and rec.State ~= "Carried" then
										misses = 0
										if not live and typeof(rec.CFrame) == "CFrame" then
											pos = rec.CFrame.Position
										end
									else
										-- record belum muncul = toleransi lebih lama; "Carried" = dipegang orang lain
										misses += (rec and 1 or 0.34)
										if misses >= 3 then
											break
										end
									end
								end
							end
							local rp = tbl4.Root()
							if not rp then
								return false
							end
							if pos then
								local delta = Vector3.new(pos.X - rp.Position.X, 0, pos.Z - rp.Position.Z)
								if delta.Magnitude > 300 and not chase then
									break
								end
								str3 = isRagdolled() and "Instant Steal V2: knocked down, moving to the egg" or "Instant Steal V2: taking the egg"
								if delta.Magnitude > 4 then
									local speed = math.max(tbl4.WalkSpeed() * (sc.V2RunRatio or 1), 16)
									if chase then
										speed = math.clamp(delta.Magnitude * 3, speed, math.max(speed, sc.V2ChaseMax))
									end
									local vel = delta.Unit * math.min(speed, delta.Magnitude / 0.05)
									pcall(function()
										rp.AssemblyLinearVelocity = Vector3.new(vel.X, rp.AssemblyLinearVelocity.Y, vel.Z)
									end)
								else
									pcall(function()
										rp.AssemblyLinearVelocity = Vector3.new(0, rp.AssemblyLinearVelocity.Y, 0)
									end)
								end
								if sincePrompt >= 0.08 then
									sincePrompt = 0
									local prompt = fn30(uid, pos)
									if prompt then
										pcall(function()
											prompt.HoldDuration = 0
										end)
										if typeof(fireproximityprompt) == "function" then
											pcall(fireproximityprompt, prompt)
										end
									end
									if inflight < 3 then
										inflight += 1
										task.spawn(function()
											carryEgg(uid)
											inflight -= 1
										end)
									end
								end
							end
							sincePrompt += RunService.Heartbeat:Wait()
						end
						local w = 0
						while w < 0.6 and not (steal.Carrying and not steal.WrongEgg(uid)) and not fn16(token) do
							w += RunService.Heartbeat:Wait()
						end
						return steal.Carrying == true and not steal.WrongEgg(uid)
					end

					-- Setara RunTo (V2Straight) di Chili: lari lurus pakai WalkSpeed biasa (TANPA boost),
					-- tahan posisi di telur, grab-drop palsu (V2FakeGrabs), lalu ambil sungguhan.
					sc.V2RunTo = function(target, token)
						local uid = target.Uid
						local tpos = typeof(target.CFrame) == "CFrame" and target.CFrame.Position or nil
						if type(uid) ~= "string" or not tpos then
							return false
						end
						fn25()
						local steal = tbl4.Steal
						local eggState = tbl.EggState
						local char = localPlayer.Character
						local hum = char and char:FindFirstChildOfClass("Humanoid")
						if hum then
							hum.PlatformStand = false
							if char:FindFirstChildWhichIsA("Tool") then
								pcall(function()
									hum:UnequipTools()
								end)
							end
						end

						-- 1) lari lurus ke telur
						local startT = os.clock()
						local r0 = tbl4.Root()
						local lastPos, lastJump = r0 and r0.Position or nil, os.clock()
						while os.clock() - startT < 240 do
							if fn16(token) or localPlayer.Character ~= char then
								return false
							end
							local rp = tbl4.Root()
							if not rp then
								return false
							end
							local delta = Vector3.new(tpos.X - rp.Position.X, 0, tpos.Z - rp.Position.Z)
							if delta.Magnitude <= 2.5 then
								break
							end
							str3 = string.format("Running to the egg, %d studs left", math.floor(delta.Magnitude + 0.5))
							local speed = math.max(tbl4.WalkSpeed() * (sc.V2RunScale or 1), 8)
							local vel = delta.Unit * math.min(speed, delta.Magnitude / 0.05)
							pcall(function()
								rp.AssemblyLinearVelocity = Vector3.new(vel.X, rp.AssemblyLinearVelocity.Y, vel.Z)
							end)
							local now = os.clock()
							if now - lastJump >= 1.5 then
								if lastPos and (rp.Position - lastPos).Magnitude < 3 and hum then
									pcall(function()
										hum.Jump = true
									end)
								end
								lastJump, lastPos = now, rp.Position
							end
							RunService.Heartbeat:Wait()
						end
						local rEnd = tbl4.Root()
						if not rEnd then
							return false
						end
						pcall(function()
							rEnd.AssemblyLinearVelocity = Vector3.new(0, rEnd.AssemblyLinearVelocity.Y, 0)
						end)

						-- 2) tahan posisi di telur selama proses grab
						local away = Vector3.new(rEnd.Position.X - tpos.X, 0, rEnd.Position.Z - tpos.Z)
						local off = away.Magnitude > 0.1 and away.Unit * 2 or Vector3.zero
						local hold = Vector3.new(tpos.X + off.X, rEnd.Position.Y, tpos.Z + off.Z)
						local conn = RunService.Heartbeat:Connect(function()
							local r = tbl4.Root()
							if not r or steal.Carrying or tbl4.AntiGuard.Busy then
								return
							end
							local d = Vector3.new(hold.X - r.Position.X, 0, hold.Z - r.Position.Z)
							pcall(function()
								if d.Magnitude > 1.5 then
									r.CFrame = CFrame.new(hold.X, r.Position.Y, hold.Z) * r.CFrame.Rotation
								end
								r.AssemblyLinearVelocity = Vector3.new(0, math.min(r.AssemblyLinearVelocity.Y, 0), 0)
							end)
						end)

						local function dropEgg()
							if type(eggState) == "table" and type(eggState.DropFieldEgg) == "function" then
								pcall(eggState.DropFieldEgg, "PlayerRequest")
							end
							local w = 0
							while steal.Carrying and w < 1 and not fn16(token) do
								w += RunService.Heartbeat:Wait()
							end
						end
						local function grabFor(seconds)
							local untilT, nextSpam = os.clock() + seconds, 0
							while os.clock() < untilT and not fn16(token) do
								if steal.Carrying then
									if not steal.WrongEgg(uid) then
										return true
									end
									str3 = "Instant Steal V2: wrong egg in hand, dropping it"
									dropEgg()
									nextSpam = 0
								end
								if os.clock() >= nextSpam then
									nextSpam = os.clock() + 0.05
									task.spawn(carryEgg, uid)
								end
								RunService.Heartbeat:Wait()
							end
							return steal.Carrying == true and not steal.WrongEgg(uid)
						end

						-- 3) grab-drop palsu lalu ambil sungguhan
						local ok = false
						if steal.Carrying then
							dropEgg()
						end
						local fakes = math.max(math.floor(tonumber(sc.V2FakeGrabs) or 0), 0)
						for i = 1, fakes do
							if fn16(token) then
								break
							end
							str3 = string.format("Instant Steal V2: grab and drop %d/%d", i, fakes)
							if grabFor(1.5) then
								dropEgg()
							elseif steal.Carrying then
								dropEgg()
							end
						end
						if not fn16(token) then
							str3 = "Instant Steal V2: taking the egg for real"
							ok = grabFor(3)
						end
						conn:Disconnect()
						if not ok then
							return false
						end
						steal.LastFinishedAt = os.clock()
						return true
					end

					-- Teleport lewat portal Fuse Biome ke dekat telur lalu ambil.
					-- return: nil = tidak bisa (pakai alur biasa), false = gagal / respawn, true = telur di tangan.
					sc.PortalTo = function(target, token)
						local char = localPlayer.Character
						local tpos = typeof(target.CFrame) == "CFrame" and target.CFrame.Position or nil
						local lane, exitPart = sc.V2_Portal()
						if not tpos or not lane or not exitPart then
							return nil
						end
						fn25()
						if sc.V2_InZone() then
							str3 = "Instant Steal V2: leaving the Fuse Biome first"
							sc.V2_LeaveZone()
						end
						local r = tbl4.Root()
						if not r then
							return false
						end
						local flat = Vector3.new(tpos.X, 0, tpos.Z)
						local dEgg = (flat - Vector3.new(r.Position.X, 0, r.Position.Z)).Magnitude
						local dPortal = (flat - Vector3.new(lane.Position.X, 0, lane.Position.Z)).Magnitude
						if not (not tbl4.InsideBase() and dEgg < dPortal) then
							local home = stealHome()
							local nearHome = home ~= nil and (r.Position - home).Magnitude <= sc.V2DirectRadius
							if home and tbl4.InsideBase() and not nearHome then
								local goal = home + Vector3.new(0, 3, 0)
								local untilT, dt = os.clock() + 15, 1 / 60
								while not fn16(token) and os.clock() < untilT do
									if localPlayer.Character ~= char then
										return false
									end
									local rr = tbl4.Root()
									if not rr then
										return false
									end
									local delta = goal - rr.Position
									if delta.Magnitude <= sc.V2SafeHop then
										pcall(function()
											rr.CFrame = CFrame.new(goal) * rr.CFrame.Rotation
											zeroVel(rr)
										end)
										break
									end
									str3 = string.format("Instant Steal V2: flying to the safe zone, %d studs", math.floor(delta.Magnitude + 0.5))
									local move = math.min(sc.V2SafeSpeed * dt, delta.Magnitude)
									pcall(function()
										rr.CFrame = CFrame.new(rr.Position + delta.Unit * move) * rr.CFrame.Rotation
										zeroVel(rr)
									end)
									dt = math.clamp(RunService.Heartbeat:Wait(), 1 / 240, 0.05)
								end
								if fn16(token) then
									return false
								end
								local okPing, ping = pcall(function()
									return localPlayer:GetNetworkPing()
								end)
								local settle = math.clamp(sc.V2SafeWait + (okPing and tonumber(ping) or 0.1), sc.V2SafeWait, sc.V2SafeWaitMax)
								local settleUntil = os.clock() + settle
								str3 = "Instant Steal V2: in the safe zone, letting the server catch up"
								while os.clock() < settleUntil and not fn16(token) do
									local rr = tbl4.Root()
									if rr then
										pcall(function()
											rr.CFrame = CFrame.new(goal) * rr.CFrame.Rotation
											rr.AssemblyLinearVelocity = Vector3.zero
										end)
									end
									RunService.Heartbeat:Wait()
								end
								if fn16(token) then
									return false
								end
							end
							local through = false
							for attempt = 1, 3 do
								if fn16(token) then
									return false
								end
								str3 = string.format("Instant Steal V2: touching the lane portal (try %d)", attempt)
								local tryUntil = os.clock() + 5
								while os.clock() < tryUntil and not fn16(token) do
									if localPlayer.Character ~= char then
										return false
									end
									if sc.V2_InZone() then
										break
									end
									local rr = tbl4.Root()
									if rr then
										pcall(function()
											rr.CFrame = CFrame.new(lane.Position)
											rr.AssemblyLinearVelocity = Vector3.zero
										end)
										sc.V2_Touch(rr, lane)
									end
									RunService.Heartbeat:Wait()
								end
								if sc.V2_InZone() then
									str3 = "Instant Steal V2: inside the Fuse Biome, touching its exit"
									sc.V2_LeaveZone()
									local rr = tbl4.Root()
									if rr and (rr.Position - lane.Position).Magnitude < 200 then
										through = true
										break
									end
								else
									local rr = tbl4.Root()
									if rr then
										for _ = 1, 6 do
											sc.V2_Touch(rr, exitPart)
											task.wait(0.1)
										end
									end
									task.wait(0.5)
								end
							end
							if fn16(token) then
								return false
							end
							if not through then
								return nil
							end
						end
						fn25()
						if localPlayer.Character ~= char then
							return false
						end
						local got = sc.V2RunTo(target, token)
						if not got and not fn16(token) and localPlayer.Character == char then
							got = sc.V2Grab(target, token)
						end
						if got then
							tbl4.Steal.LastFinishedAt = os.clock()
						end
						return got
					end

					-- Bawa telur ke garis dengan lompatan, drop, reset treadmill, ambil ulang dari sisi aman.
					sc.TreadmillHome = function(token)
						local steal = tbl4.Steal
						local uid = steal.CarryUid
						local home = stealHome()
						local rp = tbl4.Root()
						if type(uid) ~= "string" or not home or not rp then
							return false
						end
						fn25()
						local char = localPlayer.Character
						local lineX, lineY = lineInfo()
						if not steal.Carrying or steal.WrongEgg(uid) then
							str3 = "Instant Steal V2: the egg slipped, taking it again"
							if not sc.V2Grab({ Uid = uid, CFrame = CFrame.new(rp.Position) }, token, 5) then
								str3 = "Instant Steal V2: the egg slipped and could not be taken again"
								return false
							end
							rp = tbl4.Root() or rp
						end
						local started = os.clock()
						local laneZ = math.clamp(rp.Position.Z, -425, -300)
						local stand = Vector3.new(lineX + sc.V2LineGap, lineY + 3.35, laneZ)
						local falls = 0
						while true do
							str3 = "Instant Steal V2: stepping the egg to the line"
							local r = tbl4.Root()
							if not r then
								return false
							end
							local y = stand.Y + sc.V2CarryHeight
							local x = r.Position.X
							local step = math.max(tbl4.WalkSpeed() * sc.V2HopRatio, 60)
							pcall(function()
								r.CFrame = CFrame.new(x, y, laneZ) * FACE
								zeroVel(r)
							end)
							while steal.Carrying and not fn16(token) and x - step > stand.X do
								x -= step
								str3 = string.format("Instant Steal V2: stepping home, X %d", math.floor(x))
								local waited = 0
								while waited < sc.V2HopGap and steal.Carrying and not fn16(token) do
									local rr = tbl4.Root()
									if rr then
										pcall(function()
											rr.CFrame = CFrame.new(x, y, laneZ) * FACE
											zeroVel(rr)
										end)
									end
									waited += RunService.Heartbeat:Wait()
								end
							end
							if steal.Carrying and not fn16(token) then
								local rr = tbl4.Root()
								if rr then
									pcall(function()
										rr.CFrame = CFrame.new(stand) * FACE
										zeroVel(rr)
									end)
								end
							end
							if fn16(token) then
								return false
							end
							local rr = tbl4.Root()
							if steal.Carrying or not rr or (rr.Position - stand).Magnitude < 60 then
								break
							end
							falls += 1
							if falls > sc.V2FallTries then
								str3 = "Instant Steal V2: the egg kept falling, giving up on it"
								return false
							end
							str3 = "Instant Steal V2: the egg fell, going straight back for it"
							if not sc.V2Grab({ Uid = uid, CFrame = CFrame.new(rr.Position) }, token, 10, true) then
								str3 = "Instant Steal V2: the egg fell and could not be taken again"
								return false
							end
						end

						local waited = 0
						while waited < sc.V2DropWait and steal.Carrying and not fn16(token) do
							waited += RunService.Heartbeat:Wait()
						end
						if steal.Carrying then
							str3 = "Instant Steal V2: dropping the egg at the line"
							local eggState = tbl.EggState
							if type(eggState) == "table" and type(eggState.DropFieldEgg) == "function" then
								pcall(eggState.DropFieldEgg, "PlayerRequest")
							end
							local w2 = 0
							while steal.Carrying and w2 < 1.5 and not fn16(token) do
								w2 += RunService.Heartbeat:Wait()
							end
						end
						local rAfter = tbl4.Root()
						-- [FIX] posisi egg yang di-drop dekat base: pakai posisi model egg (lebih akurat dari posisi player)
						local eggAt = eggModelPos(uid) or (rAfter and rAfter.Position) or stand

						local function anchored()
							local r = tbl4.Root()
							return r ~= nil and r.Anchored == true
						end
						-- [FIX] turun treadmill secepat mungkin: cek langsung tiap ~0.05s (dulu 0.15s)
						local function doff(seconds)
							local untilT = os.clock() + seconds
							local rf = networking:FindFirstChild("RF/Treadmill/AskDoff")
							while os.clock() < untilT do
								if rf then
									pcall(rf.InvokeServer, rf)
								end
								if not anchored() then
									return true
								end
								task.wait(0.05)
							end
							local r = tbl4.Root()
							if r and r.Anchored then
								pcall(function()
									r.Anchored = false
								end)
							end
							return not anchored()
						end

						str3 = "Instant Steal V2: resetting on the treadmill"
						-- [FIX] HANYA treadmill milik sendiri. Dulu script teleport ke treadmill SEMUA plot
						-- bergantian kalau gagal -> terlihat mutar/pindah-pindah tempat.
						local spot = nil
						do
							local bottom = nil
							local okPlot, ownPlot = pcall(function()
								return type(tbl4.Plot) == "function" and tbl4.Plot() or nil
							end)
							if okPlot and ownPlot then
								bottom = ownPlot:FindFirstChild("TreadmillBottom")
							end
							if not (bottom and bottom:IsA("BasePart")) then
								local okBelt, belt = pcall(function()
									return type(tbl4.Belt) == "function" and tbl4.Belt() or nil
								end)
								bottom = okBelt and belt or nil
							end
							if not (bottom and bottom:IsA("BasePart")) then
								-- fallback terakhir: SATU treadmill terdekat dari egg (bukan semua plot)
								local plots = workspace:FindFirstChild("Plots")
								local best = math.huge
								if plots then
									for _, plot in ipairs(plots:GetChildren()) do
										local b = plot:FindFirstChild("TreadmillBottom")
										if b and b:IsA("BasePart") then
											local d = (Vector3.new(b.Position.X, 0, b.Position.Z) - Vector3.new(eggAt.X, 0, eggAt.Z)).Magnitude
											if d < best then
												best = d
												bottom = b
											end
										end
									end
								end
							end
							if bottom and bottom:IsA("BasePart") then
								spot = Vector3.new(bottom.Position.X, 72, bottom.Position.Z)
							end
						end

						local rfStill = networking:FindFirstChild("RF/Treadmill/AskWearStill")
						local worn = false
						if spot and rfStill then
							-- maksimal 2x teleport, dua-duanya ke treadmill yang SAMA
							for _ = 1, 2 do
								if worn or fn16(token) then
									break
								end
								local r = tbl4.Root()
								if r then
									pcall(function()
										r.CFrame = CFrame.new(spot)
										r.AssemblyLinearVelocity = Vector3.zero
									end)
								end
								local tryUntil = os.clock() + 0.8
								while os.clock() < tryUntil do
									local ok, res = pcall(rfStill.InvokeServer, rfStill)
									if ok and res == true then
										worn = true
										break
									end
									task.wait(0.05)
								end
							end
						end
						-- [FIX] begitu sudah naik treadmill langsung turun lalu LANGSUNG ke egg (tanpa jeda)
						doff(worn and 3 or 0.6)

						str3 = "Instant Steal V2: grabbing the egg back"
						local regrabUntil = os.clock() + sc.V2RegrabTime
						local snapAt, inflight, wentFar = os.clock() + 1, 0, false
						local promptAt = 0
						local eggPos = eggAt
						while not (steal.Carrying and not steal.WrongEgg(uid)) and os.clock() < regrabUntil and not fn16(token) do
							if localPlayer.Character ~= char then
								str3 = "Instant Steal V2: respawned, starting over from the safe zone"
								return false
							end
							if anchored() then
								doff(2)
							elseif isRagdolled() then
								str3 = "Instant Steal V2: knocked down, waiting to grab the egg back"
								task.wait(0.05)
							else
								eggPos = eggModelPos(uid) or eggPos
								if (Vector3.new(eggPos.X, 0, eggPos.Z) - Vector3.new(eggAt.X, 0, eggAt.Z)).Magnitude > 400 then
									wentFar = true
									break
								end
								local r = tbl4.Root()
								if r then
									local at = sc.V2_Stand(eggPos)
									pcall(function()
										r.CFrame = CFrame.new(at) * FACE
										r.AssemblyLinearVelocity = Vector3.zero
									end)
								end
