-- ============================================================
-- [FanKun] Butterfly Bloom (event, diport dari CHILI HUB / chililatest-sae)
-- Fitur : Auto Butterfly Bloom (catch: Stand / Chase / Circle / Patrol),
--         Auto Trade Up, Smart Trade For Essence, Auto Craft Essence.
-- UI    : tab "Butterfly" (tab sendiri). Dijalankan lewat pcall supaya kalau ada error,
--         Auto Steal / Anti AFK / Dr Scramble tidak ikut terganggu.
-- Logic : sama dengan Chili. Bedanya prioritas gerak memakai sistem FanKun:
--         Auto Steal / Auto Place / Mech Boss / Scrambled jalan duluan,
--         Butterfly otomatis mengalah lalu lanjut lagi setelah mereka selesai.
-- ============================================================
do
	local function FK_butterflyBoot()
		local PathfindingService = game:GetService("PathfindingService")
		local section = FK_WIN._butterflySection or FK_SCR
		if section == nil then
			return
		end
		section = FK_wrapSection(section)

		local TIER_NAME = { Green = "Emerald", Blue = "Sapphire", Purple = "Amethyst", Golden = "Radiant" }
		local TIER_RANK = { Golden = 4, Purple = 3, Blue = 2, Green = 1 }
		local TIER_BONUS = { Golden = 4, Purple = 1.6, Blue = 0.8, Green = 0 }
		local TIER_PICK = {
			["Radiant Butterfly"] = "Golden",
			["Amethyst Butterfly"] = "Purple",
			["Sapphire Butterfly"] = "Blue",
			["Emerald Butterfly"] = "Green",
			["Legendary (Radiant)"] = "Golden",
			["Epic (Amethyst)"] = "Purple",
			["Rare (Sapphire)"] = "Blue",
			["Common (Emerald)"] = "Green",
			["Radiant (Golden)"] = "Golden",
			["Amethyst (Purple)"] = "Purple",
			["Sapphire (Blue)"] = "Blue",
			["Emerald (Green)"] = "Green",
			Golden = "Golden",
			Purple = "Purple",
			Blue = "Blue",
			Green = "Green",
		}
		local TRADES = {
			{ Label = "Emerald To Sapphire", From = "Green" },
			{ Label = "Sapphire To Amethyst", From = "Blue" },
			{ Label = "Amethyst To Radiant", From = "Purple" },
		}
		local TREE_NOTE = "Trade and craft need the Enchanted Tree open (finish the Wisp quest). It stays on and starts by itself once the tree is open."

		local B = {
			Status = "Off",
			Shown = nil,
			Busy = false,
			Claiming = false,
			Wants = false,
			Generation = 0,
			Speed = 320,
			Mode = "Stand Still",
			Priority = "Strict Rarity",
			Interval = 1800,
			Offset = 900,
			Reach = 14,
			SwingGap = 0.45,
			Counts = { Green = 0, Blue = 0, Purple = 0, Golden = 0 },
			Essence = 0,
			Caught = 0,
			NetClaimed = false,
			Recipe = { Green = 240, Blue = 115, Purple = 40, Golden = 1 },
			TradeCost = { Green = 10, Blue = 10, Purple = 50 },
			Trades = {},
			Tiers = { Green = true, Blue = true, Purple = true, Golden = true },
			Pending = {},
			Links = {},
			Live = {},
			RagdollTries = 0,
