		tbl4.Butterfly = B

		-- --------------------------------------------------------
		-- Modul game (semua opsional, dibungkus pcall)
		-- --------------------------------------------------------
		local Catalog, Swarm

		local function findModule(...)
			local node = ReplicatedStorage
			for _, name in ipairs({ ... }) do
				node = node and node:FindFirstChild(name)
			end
			return node
		end

		task.spawn(function()
			pcall(function()
				Catalog = require(ReplicatedStorage.Shared.Modules.ButterflyCatalog)
			end)
			pcall(function()
				local mod = findModule("Controllers", "Game", "AdminAbuseClientController", "Events", "ButterflyBloom", "Swarm")
				if not mod then
					local events = ReplicatedStorage:FindFirstChild("ButterflyBloom", true)
					mod = events and events:FindFirstChild("Swarm")
				end
				if not mod then
					local scripts = localPlayer:FindFirstChild("PlayerScripts")
					local bloom = scripts and scripts:FindFirstChild("ButterflyBloom", true)
					mod = bloom and bloom:FindFirstChild("Swarm")
				end
				if mod then
					Swarm = require(mod)
				end
			end)
			pcall(function()
				local flags = require(ReplicatedStorage.Shared.Flags.ButterflyFlags)
				B.Interval = tonumber(flags.IntervalSeconds:Get()) or B.Interval
				B.Offset = tonumber(flags.OffsetSeconds:Get()) or B.Offset
				B.Reach = tonumber(flags.NetReach:Get()) or B.Reach
				B.SwingGap = tonumber(flags.SwingCooldownSeconds:Get()) or B.SwingGap
				B.TradeCost.Green = tonumber(flags.GreenToBlueCost:Get()) or B.TradeCost.Green
				B.TradeCost.Blue = tonumber(flags.BlueToPurpleCost:Get()) or B.TradeCost.Blue
				B.TradeCost.Purple = tonumber(flags.PurpleToGoldenCost:Get()) or B.TradeCost.Purple
				B.Recipe = {
					Green = tonumber(flags.EssenceGreen:Get()) or B.Recipe.Green,
					Blue = tonumber(flags.EssenceBlue:Get()) or B.Recipe.Blue,
					Purple = tonumber(flags.EssencePurple:Get()) or B.Recipe.Purple,
					Golden = tonumber(flags.EssenceGolden:Get()) or B.Recipe.Golden,
				}
			end)
		end)

		-- --------------------------------------------------------
		-- Util dasar
		-- --------------------------------------------------------
		local function invoke(name, ...)
			local remote = networking:FindFirstChild(name)
			if not remote or not remote:IsA("RemoteFunction") then
				return false, "missing"
			end
			local result = table.pack(pcall(remote.InvokeServer, remote, ...))
			if not result[1] then
				return false, tostring(result[2])
			end
			return result[2], result[3], result[4]
		end

		local function on(handle)
			return tbl4.Toggle(handle, false) == true
		end

		local function wantsCatch()
			return on(B.Handle)
		end

		local function eventLive()
			return workspace:GetAttribute("Event_ButterflyBloom") == true
		end

		local function clock(seconds)
			seconds = math.max(0, math.floor(seconds + 0.5))
			return string.format("%d:%02d", math.floor(seconds / 60), seconds % 60)
		end

		local function timerText()
			local now = workspace:GetServerTimeNow()
			if eventLive() then
				local endsAt = tonumber(workspace:GetAttribute("ButterflyBloomEndsAt"))
				return endsAt and ("Butterfly Bloom live, " .. clock(endsAt - now) .. " left") or "Butterfly Bloom live"
			end
			local startedAt = math.floor((now - B.Offset) / B.Interval) * B.Interval + B.Offset
			local nextAt = startedAt <= now and startedAt + B.Interval or startedAt
			return "Next Butterfly Bloom in " .. clock(nextAt - now)
		end

		local function countsText()
			local c = B.Counts
			local text = string.format(
				"Emerald %d  Sapphire %d  Amethyst %d  Radiant %d  |  Essence %d",
				c.Green or 0,
				c.Blue or 0,
				c.Purple or 0,
				c.Golden or 0,
				B.Essence or 0
			)
			if B.MachineNote then
				text = text .. "  |  " .. B.MachineNote
			end
			if on(B.CraftHandle) then
				local missing = {}
				for _, tier in ipairs({ "Green", "Blue", "Purple", "Golden" }) do
					if next(B.Tiers) ~= nil and B.Tiers[tier] ~= true and (B.Counts[tier] or 0) < (B.Recipe[tier] or 0) then
						table.insert(missing, TIER_NAME[tier])
					end
				end
				if #missing > 0 then
					text = text .. "  |  Craft needs " .. table.concat(missing, ", ") .. " (pick it in Catch Butterflies)"
				end
			end
			return text
		end

		local function getSave()
			local save = tbl.Save
			local data
			if type(save) == "table" then
				for _, key in ipairs({ "Get", "Peek", "GetData" }) do
					if type(save[key]) == "function" then
						local ok, result = pcall(save[key])
						if ok and type(result) == "table" then
							data = result
							break
						end
					end
				end
			end
			return type(data) == "table" and data.Butterflies or nil
		end

		local function readCounts()
			local counts = { Green = 0, Blue = 0, Purple = 0, Golden = 0 }
			pcall(function()
				local saved = getSave()
				local source = type(saved) == "table" and type(saved.Counts) == "table" and saved.Counts or {}
				for tier in pairs(counts) do
					counts[tier] = tonumber(source[tier]) or 0
				end
				B.Essence = tonumber(saved and saved.Essence) or B.Essence
			end)
			B.Counts = counts
			return counts
		end

		-- sinkron data Save tiap 1 detik
		task.spawn(function()
			while true do
				pcall(function()
					local saved = getSave()
					if type(saved) == "table" then
						local source = type(saved.Counts) == "table" and saved.Counts or {}
						B.Counts = {
							Green = tonumber(source.Green) or 0,
							Blue = tonumber(source.Blue) or 0,
							Purple = tonumber(source.Purple) or 0,
							Golden = tonumber(source.Golden) or 0,
						}
						B.Essence = tonumber(saved.Essence) or 0
						B.Caught = tonumber(saved.TotalCaught) or 0
						B.NetClaimed = saved.NetClaimed == true
					end
				end)
				task.wait(1)
			end
		end)

		-- --------------------------------------------------------
		-- Kupu-kupu: spawn / remove / escape + posisi
		-- --------------------------------------------------------
		local function remember(flight)
			if type(flight) == "table" and flight.Id ~= nil then
				B.Live[flight.Id] = flight
			end
		end

		pcall(function()
			local spawned = networking:FindFirstChild("RE/Butterflies/Spawned")
			if spawned then
				table.insert(B.Links, spawned.OnClientEvent:Connect(function(flight)
					remember(flight)
				end))
			end
			local removed = networking:FindFirstChild("RE/Butterflies/Removed")
			if removed then
				table.insert(B.Links, removed.OnClientEvent:Connect(function(id)
					B.Live[id] = nil
				end))
			end
			local escaped = networking:FindFirstChild("RE/Butterflies/Escaped")
			if escaped then
				table.insert(B.Links, escaped.OnClientEvent:Connect(function(a, b)
					if type(a) == "table" then
						remember(a)
					elseif type(b) == "table" then
						remember(b)
					end
				end))
			end
		end)

		local function positionOf(inst)
			if typeof(inst) ~= "Instance" then
				return nil
			end
			if inst:IsA("BasePart") then
				return inst.Position
			end
			if inst:IsA("Model") then
				local ok, pivot = pcall(inst.GetPivot, inst)
				return ok and pivot.Position or nil
			end
			return nil
		end

		-- semua kupu-kupu yang terbang sekarang: { Id, Tier, Position, Flight }
		local function collect()
			local list, seen = {}, {}
			if Swarm and type(Swarm.Each) == "function" then
				pcall(function()
					for id, entry in Swarm.Each() do
						local flight = type(entry) == "table" and entry.Flight or nil
						local key = flight and flight.Id or id
						local position = type(entry) == "table" and positionOf(entry.Body) or nil
						if key ~= nil and position and not B.Pending[key] then
							seen[key] = true
							table.insert(list, {
								Id = key,
								Tier = tostring(flight and flight.Tier or "Green"),
								Position = position,
								Flight = flight,
							})
						end
					end
				end)
			end
			if Catalog and type(Catalog.PositionAt) == "function" then
				local now = workspace:GetServerTimeNow()
				for id, flight in pairs(B.Live) do
					if not seen[id] and not B.Pending[id] then
						local ok, position = pcall(Catalog.PositionAt, flight, now)
						if ok and typeof(position) == "Vector3" then
							table.insert(list, {
								Id = id,
								Tier = tostring(flight.Tier or "Green"),
								Position = position,
								Flight = flight,
							})
						end
					end
				end
			end
			return list
		end

		local function bloomArea()
			local world = workspace:FindFirstChild("World")
			local areas = world and world:FindFirstChild("Areas")
			return areas and areas:FindFirstChild("ButterflyBloom")
		end

		local function bloomBounds()
			local area = bloomArea()
			local bounds = area and area:FindFirstChild("Bounds")
			if bounds and bounds:IsA("BasePart") then
				return bounds
			end
			return nil
		end

		local function inBloom(position)
			local bounds = bloomBounds()
			if not bounds then
				return true
			end
			local rel = bounds.CFrame:PointToObjectSpace(position)
			return math.abs(rel.X) <= bounds.Size.X / 2 + 80 and math.abs(rel.Z) <= bounds.Size.Z / 2 + 80 and math.abs(rel.Y) <= 120
		end

		local function pick(list, from)
			local best, bestScore
			for _, item in ipairs(list) do
				if not inBloom(item.Position) or (next(B.Tiers) ~= nil and B.Tiers[item.Tier] ~= true) then
					continue
				end
				local score = (item.Position - from).Magnitude / math.max(B.Speed, 1)
				if B.Priority == "Rarest First" then
					score = score - (TIER_BONUS[item.Tier] or 0)
				elseif B.Priority == "Strict Rarity" then
					score = score + (5 - (TIER_RANK[item.Tier] or 1)) * 1000
				end
				if not bestScore or score < bestScore then
					best, bestScore = item, score
				end
			end
			return best
		end

		-- --------------------------------------------------------
		-- Butterfly Net
		-- --------------------------------------------------------
		local function findNet()
			for _, container in ipairs({ localPlayer.Character, localPlayer:FindFirstChildOfClass("Backpack") }) do
				if container then
					for _, child in ipairs(container:GetChildren()) do
						if
							child:IsA("Tool")
							and (child:GetAttribute("ButterflyNet") == true or tostring(child:GetAttribute("ItemType")) == "ButterflyNet" or child.Name == "Butterfly Net")
						then
							return child
						end
					end
				end
			end
			return nil
		end

		local function equipNet()
			local net = findNet()
			local character = localPlayer.Character
			local humanoid = character and character:FindFirstChildOfClass("Humanoid")
			if net and humanoid and net.Parent ~= character then
				pcall(function()
					humanoid:EquipTool(net)
				end)
			end
			return net
		end

		local function stationPosition(name)
			local world = workspace:FindFirstChild("World")
			local machines = world and world:FindFirstChild("Machines")
			local station = machines and machines:FindFirstChild("ButterflyStation")
			local machine = station and station:FindFirstChild(name)
			local anchor = machine and machine:FindFirstChild("Anchor")
			if anchor and anchor:IsA("BasePart") then
				return anchor.Position
			end
			if machine and machine:IsA("Model") then
				local ok, pivot = pcall(machine.GetPivot, machine)
				return ok and pivot.Position or nil
			end
			return nil
		end

		local function teleportTo(position)
			local character = localPlayer.Character
			local root = tbl4.Root()
			if not character or not root then
				return false
			end
			pcall(function()
				localPlayer:RequestStreamAroundAsync(position, 3)
			end)
			pcall(function()
				character:PivotTo(CFrame.new(position + Vector3.new(0, 3, 4)))
				root.AssemblyLinearVelocity = Vector3.zero
			end)
			task.wait(0.6)
			return true
		end

		-- --------------------------------------------------------
		-- Gerak di area Bloom
		-- --------------------------------------------------------
		local groundRay = RaycastParams.new()
		groundRay.FilterType = Enum.RaycastFilterType.Exclude

		local function groundSnap(position)
			local character = localPlayer.Character
			local root = tbl4.Root()
			local humanoid = character and character:FindFirstChildOfClass("Humanoid")
			if not character or not root then
				return position
			end
			local swarm = workspace:FindFirstChild("ButterflyBloomSwarm")
			groundRay.FilterDescendantsInstances = swarm and { character, swarm } or { character }
			local hit = workspace:Raycast(position + Vector3.new(0, 25, 0), Vector3.new(0, -120, 0), groundRay)
			if not hit then
				return position
			end
			local lift = (humanoid and humanoid.HipHeight or 2) + root.Size.Y / 2
			return Vector3.new(position.X, hit.Position.Y + lift, position.Z)
		end

		local function bloomFacing()
			local bounds = bloomBounds()
			local direction = Vector3.new(0, 0, -1)
			if bounds then
				local axis = bounds.Size.X >= bounds.Size.Z and bounds.CFrame.LookVector or bounds.CFrame.RightVector
				local flat = Vector3.new(axis.X, 0, axis.Z)
				if flat.Magnitude > 0.1 then
					direction = flat.Unit
				end
			end
			return CFrame.lookAt(Vector3.zero, direction)
		end

		local function bloomCentre()
			local bounds = bloomBounds()
			if bounds then
				return bounds.Position + Vector3.new(0, 6, 0)
			end
			return Vector3.new(6700, 74, -364)
		end

		local function patrolPoint()
			local bounds = bloomBounds()
			if not bounds then
				return bloomCentre()
			end
			local alongX = bounds.Size.X >= bounds.Size.Z
			local axis = alongX and bounds.CFrame.RightVector or bounds.CFrame.LookVector
			axis = Vector3.new(axis.X, 0, axis.Z).Unit
			local half = math.max(20, (alongX and bounds.Size.X or bounds.Size.Z) / 2 - 30)
			local now = os.clock()
			B.PatrolTravel = ((B.PatrolTravel or 0) + (B.Speed or 320) * math.clamp(now - (B.PatrolAt or now), 0, 0.1)) % (4 * half)
			B.PatrolAt = now
			local travel = B.PatrolTravel
			local offset = travel < 2 * half and travel - half or 3 * half - travel
			return bounds.Position + axis * offset + Vector3.new(0, 6, 0)
		end

		local function circlePoint()
			local bounds = bloomBounds()
			if not bounds then
				return bloomCentre()
			end
			local right = Vector3.new(bounds.CFrame.RightVector.X, 0, bounds.CFrame.RightVector.Z).Unit
			local look = Vector3.new(bounds.CFrame.LookVector.X, 0, bounds.CFrame.LookVector.Z).Unit
			local now = os.clock()
			B.CircleAngle = ((B.CircleAngle or 0) + (B.Speed or 320) / 25 * math.clamp(now - (B.CircleAt or now), 0, 0.1)) % (math.pi * 2)
			B.CircleAt = now
			return bounds.Position + right * (math.cos(B.CircleAngle) * 25) + look * (math.sin(B.CircleAngle) * 25) + Vector3.new(0, 6, 0)
		end

		local function stopMoving()
			local root = tbl4.Root()
			if root then
				pcall(function()
					root.AssemblyLinearVelocity = Vector3.zero
					root.AssemblyAngularVelocity = Vector3.zero
				end)
			end
		end

		-- gerak ke posisi dengan kecepatan B.Speed, return jarak tersisa
		local function moveToward(position, dt)
			local root = tbl4.Root()
			if not root then
				return math.huge
			end
			local delta = position - root.Position
			local distance = delta.Magnitude
			if distance < 0.5 then
				stopMoving()
				return distance
			end
			local speed = math.min(B.Speed, distance / math.max(dt, 1 / 60))
			pcall(function()
				root.AssemblyLinearVelocity = delta.Unit * speed
				root.AssemblyAngularVelocity = Vector3.zero
			end)
			return distance
		end

		-- --------------------------------------------------------
		-- Prioritas: Butterfly mengalah ke fitur FanKun lain
		-- --------------------------------------------------------
		local function mechWantsMovement()
			local mech = tbl4.Mech
			if type(mech) ~= "table" or not on(mech.Handle) then
				return false
			end
			return localPlayer:GetAttribute("InScrambleArena") == true or workspace:FindFirstChild("ScrambleArenaPortal") ~= nil
		end

		B.Yield = function()
			local steal = tbl4.Steal
			local movement = tbl4.Movement
			if movement.PlaceWanted == true then
				return "Auto Place Egg goes first"
			end
			if movement.MutationWanted == true or movement.ScrambleWanted == true then
				return "Scrambled Mutation goes first"
			end
			if on(v5) and steal ~= nil and (steal.Wanted == true or steal.Carrying == true or steal.Active == true) then
				return "Auto Steal goes first"
			end
			if mechWantsMovement() then
				return "Mech Boss goes first"
			end
			return nil
		end

		local function leaveTreadmill()
			pcall(function()
				local riding = tbl4.Treadmill and tbl4.Treadmill.Riding
				if not riding and type(tbl4.OnBelt) == "function" then
					riding = tbl4.OnBelt()
				end
				if riding then
					B.Status = "Leaving the treadmill first"
					tbl4.ExitBelt()
				end
			end)
		end

		-- --------------------------------------------------------
		-- Claim Butterfly Net
		-- --------------------------------------------------------
		local function claimNet(gen)
			for _, name in ipairs({ "NetStand", "ButterflyMachine" }) do
				if gen ~= B.Generation or B.NetClaimed then
					return B.NetClaimed
				end
				local position = stationPosition(name)
				if position then
					B.Status = "Going to the Butterfly Net"
					teleportTo(position)
					for _ = 1, 5 do
						if gen ~= B.Generation then
							return false
						end
						local root = tbl4.Root()
						if root and (root.Position - position).Magnitude > 12 then
							teleportTo(position)
						end
						local ok, message = invoke("RF/Butterflies/AskClaimNet")
						if ok == true then
							B.NetClaimed = true
							return true
						end
						B.Status = "Net claim: " .. tostring(message or "no answer")
						task.wait(0.8)
					end
				end
			end
			return false
		end

		-- --------------------------------------------------------
		-- Terbang ke Bloom (kalau jauh)
		-- --------------------------------------------------------
		local function travelToBloom()
			local root = tbl4.Root()
			if not root then
				return nil
			end
			if (root.Position - bloomCentre()).Magnitude < 1200 then
				return nil
			end
			if tbl4.IsNight() or tbl4.WallSealed() then
				B.Status = tbl4.IsNight() and "Night, waiting for daylight before flying to the bloom" or "Waiting for the wall to drop before flying to the bloom"
				return "wait"
			end
			B.Status = "Flying to the butterfly bloom"
			return nil
		end

		-- --------------------------------------------------------
		-- Loop utama: catch
		-- --------------------------------------------------------
		local function restoreInvisibility()
			if not tbl4.InvisButterfly then
				return
			end
			tbl4.InvisButterfly = false
			if type(FK_TBL4) == "table" and not tbl4.InvisMech then
				FK_TBL4.InvisSuspended = false
			end
			if tbl4.InvisibilityHandle ~= nil and on(tbl4.InvisibilityHandle) then
				tbl4.Notify("Invisibility", "Butterfly catching is done, Invisibility is back on.")
			end
		end

		local function stateName(item)
			return TIER_NAME[item.Tier] or item.Tier
		end

		local function catchLoop()
			B.Busy = true
			B.Generation = B.Generation + 1
			local gen = B.Generation
			local function alive()
				return gen == B.Generation and wantsCatch() and eventLive()
			end
			B.Wants = true
			B.RagdollTries = 0
			tbl4.Shield("butterfly", true)
			leaveTreadmill()
			tbl4.BeginFlight()

			if not B.NetClaimed and alive() then
				claimNet(gen)
			end

			while alive() do
				local dt = RunService.Heartbeat:Wait()
				local yieldReason = B.Yield()
				if yieldReason then
					B.Status = yieldReason
					break
				end
				if tbl4.AntiGuard and tbl4.AntiGuard.Busy then
					continue
				end

				if not B.NetClaimed and not findNet() then
					if not claimNet(gen) then
						B.Status = "Could not claim the net yet, retrying"
						task.wait(2)
					end
					continue
				end

				if travelToBloom() == "wait" then
					stopMoving()
					break
				end

				equipNet()
				local root = tbl4.Root()
				if not root then
					continue
				end
				local flying = collect()

				if B.Mode == "Stand Still" or B.Mode == "Patrol" or B.Mode == "Circle" then
					local inReach = {}
					for _, item in ipairs(flying) do
						if (item.Position - root.Position).Magnitude <= B.Reach - 2 then
							table.insert(inReach, item)
						end
					end
					local nearby = pick(inReach, root.Position)
					local anchor = B.Mode == "Patrol" and patrolPoint() or B.Mode == "Circle" and circlePoint() or bloomCentre()
					local spot = groundSnap(anchor)
					local facing = bloomFacing()
					if (spot - root.Position).Magnitude > 8 then
						moveToward(spot, dt)
						pcall(function()
							root.CFrame = CFrame.new(root.Position) * facing
							root.AssemblyAngularVelocity = Vector3.zero
						end)
						B.Status = "Going to the middle of the bloom"
					else
						pcall(function()
							root.CFrame = CFrame.new(spot) * facing
							root.AssemblyLinearVelocity = Vector3.zero
							root.AssemblyAngularVelocity = Vector3.zero
						end)
						if nearby then
							B.Status = string.format("Standing, catching a %s butterfly  |  %d flying", stateName(nearby), #flying)
						else
							B.Status = string.format("Standing in the bloom  |  %d flying", #flying)
						end
					end
					continue
				end

				-- mode Chase
				local target
				local lock = B.ChaseLock
				if lock and os.clock() < lock.Until then
					for _, item in ipairs(flying) do
						if item.Id == lock.Id then
							target = item
							break
						end
					end
				end
				if not target then
					target = pick(flying, root.Position)
					if target then
						B.ChaseLock = { Id = target.Id, Until = os.clock() + 1 }
					end
				end

				if target then
					local velocity = Vector3.zero
					if Catalog and type(Catalog.VelocityAt) == "function" and type(target.Flight) == "table" then
						local ok, result = pcall(Catalog.VelocityAt, target.Flight, workspace:GetServerTimeNow())
						if ok and typeof(result) == "Vector3" then
							velocity = result
						end
					end
					local lead = velocity.Magnitude > 0.1 and velocity.Unit * 1.5 or Vector3.zero
					local facing = bloomFacing()
					local distance = (target.Position - root.Position).Magnitude
					local aim = target.Position + lead
					if (aim - root.Position).Magnitude <= 8 then
						pcall(function()
							root.CFrame = CFrame.new(aim) * facing
							root.AssemblyLinearVelocity = Vector3.new(velocity.X, 0, velocity.Z)
							root.AssemblyAngularVelocity = Vector3.zero
						end)
					else
						moveToward(aim, dt)
						pcall(function()
							root.CFrame = CFrame.new(root.Position) * facing
							root.AssemblyAngularVelocity = Vector3.zero
						end)
					end
					B.Status = string.format("Catching a %s butterfly, %d studs  |  %d flying", stateName(target), math.floor(distance + 0.5), #flying)
				else
					moveToward(groundSnap(bloomCentre()), dt)
					B.Status = "Waiting for butterflies in the bloom"
				end
			end

			B.Wants = false
			restoreInvisibility()
			stopMoving()
			pcall(tbl4.EndFlight)
			tbl4.Shield("butterfly", false)
			tbl4.ReleaseMovement("butterfly")
			B.Busy = false
			tbl3.Wake()
		end

		-- --------------------------------------------------------
		-- Enchanted Tree + mesin (Trade Up / Craft Essence)
		-- --------------------------------------------------------
		local function inTree()
			return localPlayer:GetAttribute("InEnchantedTree") == true
		end

		local function treeMarker(name)
			local world = workspace:FindFirstChild("World")
			local build = world and world:FindFirstChild("Build")
			local interior = build and build:FindFirstChild("EnchantedTreeInterior")
			local markers = interior and interior:FindFirstChild("Markers")
			local marker = markers and markers:FindFirstChild(name)
			return marker and marker:IsA("BasePart") and marker.Position or nil
		end

		local function treePrompt()
			local world = workspace:FindFirstChild("World")
			local build = world and world:FindFirstChild("Build")
			local interior = build and build:FindFirstChild("EnchantedTreeInterior")
			local markers = interior and interior:FindFirstChild("Markers")
			local trigger = markers and markers:FindFirstChild("EnterTrigger")
			local entrance = trigger and trigger:FindFirstChild("EnchantedTreeEntrance")
			local prompt = entrance and entrance:FindFirstChild("EnchantedTreePrompt")
			if prompt and prompt:IsA("ProximityPrompt") then
				local parent = prompt.Parent
				if parent:IsA("Attachment") then
					return prompt, parent.WorldPosition
				elseif parent:IsA("BasePart") then
					return prompt, parent.Position
				end
			end
			return nil, nil
		end

		-- diam sebentar sampai karakter menapak tanah
		local function settle(duration)
			local character = localPlayer.Character
			local humanoid = character and character:FindFirstChildOfClass("Humanoid")
			local untilTime, grounded = os.clock() + (duration or 2), 0
			while os.clock() < untilTime do
				local root = tbl4.Root()
				if root then
					pcall(function()
						root.Anchored = false
						root.AssemblyLinearVelocity = Vector3.zero
						root.AssemblyAngularVelocity = Vector3.zero
					end)
				end
				if tbl4.Grounded() then
					grounded = grounded + 1
					if grounded >= 8 then
						break
					end
				else
					grounded = 0
				end
				RunService.Heartbeat:Wait()
			end
			if humanoid then
				local state = humanoid:GetState()
				if
					state == Enum.HumanoidStateType.Freefall
					or state == Enum.HumanoidStateType.None
					or state == Enum.HumanoidStateType.Physics
					or state == Enum.HumanoidStateType.Ragdoll
					or state == Enum.HumanoidStateType.FallingDown
				then
					pcall(function()
						humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
					end)
					task.wait(0.3)
				end
			end
		end

		local function flyTo(position, cancel)
			if type(tbl4.FlyTo) ~= "function" then
				return false
			end
			return pcall(tbl4.FlyTo, position, cancel, "butterfly")
		end

		-- jalan kaki ke mesin di dalam tree (pathfinding), true kalau sampai
		local function walkToStation(position, timeout)
			local character = localPlayer.Character
			local humanoid = character and character:FindFirstChildOfClass("Humanoid")
			local root = tbl4.Root()
			if not humanoid or not root or not position then
				return false
			end
			settle(0.3)
			if (root.Position - position).Magnitude > 6 then
				flyTo(position + Vector3.new(0, 3, 0), function()
					return not inTree()
				end)
				settle(0.5)
			end
			root = tbl4.Root() or root
			if inTree() and (root.Position - position).Magnitude > 8 then
				B.Status = "Walking to the machine"
				local exitMarker = treeMarker("ExitTrigger")
				local points = { position }
				pcall(function()
					local path = PathfindingService:CreatePath({ AgentRadius = 2, AgentHeight = 5, AgentCanJump = true, WaypointSpacing = 6 })
					path:ComputeAsync(root.Position, position)
					if path.Status == Enum.PathStatus.Success then
						points = {}
						for _, waypoint in ipairs(path:GetWaypoints()) do
							table.insert(points, waypoint.Position)
						end
						table.insert(points, position)
					end
				end)
				local deadline = os.clock() + (timeout or 15)
				for _, point in ipairs(points) do
					if (root.Position - position).Magnitude <= 6 or not inTree() or os.clock() >= deadline then
						break
					end
					if not (exitMarker and (point - exitMarker).Magnitude < 14) then
						local stepEnd = math.min(deadline, os.clock() + 3)
						while os.clock() < stepEnd and inTree() do
							if Vector3.new(point.X - root.Position.X, 0, point.Z - root.Position.Z).Magnitude <= 2.5 or (root.Position - position).Magnitude <= 6 then
								break
							end
							humanoid:MoveTo(point)
							task.wait(0.05)
						end
					end
				end
				pcall(function()
					humanoid:MoveTo(root.Position)
					root.AssemblyLinearVelocity = Vector3.zero
				end)
				task.wait(0.4)
			end
			return inTree() and (root.Position - position).Magnitude <= 8
		end

		local function firePrompt(prompt, attempt)
			if attempt % 2 == 1 and type(fireproximityprompt) == "function" then
				pcall(fireproximityprompt, prompt)
				return
			end
			pcall(function()
				prompt:InputHoldBegin()
				task.wait((tonumber(prompt.HoldDuration) or 0) + 0.1)
				prompt:InputHoldEnd()
			end)
		end

		local function say(text)
			if type(B.TripSay) == "function" then
				B.TripSay(text)
			else
				B.Status = text
			end
		end

		local function enterTree(cancel)
			if inTree() then
				return true
			end
			local prompt, entrance = treePrompt()
			if not prompt or not entrance then
				B.MachineError = "tree entrance not found"
				return false
			end
			local root = tbl4.Root()
			if not root then
				return false
			end
			local staging = entrance + Vector3.new(0, 3, -12)
			if (root.Position - staging).Magnitude > 60 then
				if cancel() then
					return false
				end
				say("Flying to the Enchanted Tree")
				flyTo(staging, cancel)
				settle(0.5)
			end
			for attempt = 1, 4 do
				if cancel() then
					return false
				end
				say("Entering the Enchanted Tree")
				local character = localPlayer.Character
				local humanoid = character and character:FindFirstChildOfClass("Humanoid")
				local rootNow = tbl4.Root()
				if character and rootNow then
					pcall(function()
						rootNow.Anchored = false
						if (rootNow.Position - entrance).Magnitude > 30 then
							character:PivotTo(CFrame.new(entrance + Vector3.new(0, 1, -12)))
							rootNow.AssemblyLinearVelocity = Vector3.zero
						end
					end)
					local waited = 0
					while humanoid and waited < 3 and (rootNow.Position - entrance).Magnitude > 4 do
						humanoid:MoveTo(entrance)
						waited = waited + task.wait(0.05)
					end
				end
				task.wait(0.1)
				firePrompt(prompt, attempt)
				local waited = 0
				while waited < 4 and not inTree() do
					waited = waited + task.wait(0.1)
				end
				if inTree() then
					task.wait(0.5)
					return true
				end
			end
			B.MachineError = "could not enter the tree"
			return false
		end

		local function leaveTree()
			if not inTree() then
				return
			end
			local exitMarker = treeMarker("ExitTrigger")
			local character = localPlayer.Character
			local humanoid = character and character:FindFirstChildOfClass("Humanoid")
			local root = tbl4.Root()
			if exitMarker and root then
				flyTo(exitMarker, function()
					return not inTree()
				end)
				local waited = 0
				while waited < 0.5 and inTree() do
					waited = waited + task.wait(0.05)
				end
			end
			if exitMarker and humanoid and root and inTree() then
				local waited = 0
				while waited < 6 and inTree() do
					humanoid:MoveTo(exitMarker)
					waited = waited + task.wait(0.1)
				end
			end
			if not inTree() then
				return
			end
			local _, entrance = treePrompt()
			local rootNow = tbl4.Root()
			if entrance and character and rootNow then
				pcall(function()
					character:PivotTo(CFrame.new(entrance + Vector3.new(0, 3, -30)))
					rootNow.AssemblyLinearVelocity = Vector3.zero
				end)
			end
			local waited = 0
			while waited < 3 and inTree() do
				waited = waited + task.wait(0.25)
			end
			if inTree() and exitMarker then
				flyTo(exitMarker, function()
					return not inTree()
				end)
				waited = 0
				while waited < 3 and inTree() do
					waited = waited + task.wait(0.25)
				end
			end
		end

		tbl4.TreeTrip = { Enter = enterTree, Leave = leaveTree, InTree = inTree, Settle = settle, Marker = treeMarker }

		-- pakai satu mesin: jalan ke mesin lalu panggil remote-nya
		local function useMachine(remote, station, ...)
			local anchor = stationPosition(station)
			if not anchor then
				B.MachineError = "machine not found"
				return false
			end
			if B.AtStation ~= station then
				local reached = walkToStation(anchor, 15)
				if not reached and type(B.TripStopped) == "function" and not B.TripStopped() then
					B.Status = "Trying the tree again"
					if not inTree() then
						enterTree(B.TripStopped)
					end
					reached = inTree() and walkToStation(anchor, 15)
				end
				if not reached then
					B.MachineError = inTree() and "could not reach the machine" or "left the tree"
					return false
				end
				B.AtStation = station
			end
			for _ = 1, 3 do
				local ok, message = invoke(remote, ...)
				if ok == true then
					return true
				end
				B.MachineError = tostring(message or "no answer")
				if not string.find(string.lower(B.MachineError), "closer", 1, true) then
					return false
				end
				if not walkToStation(anchor, 8) then
					return false
				end
			end
			return false
		end

		-- rencana Smart Trade: berapa Essence yang bisa dibuat + trade tiap tier
		local function smartPlan(counts)
			local recipe, cost = B.Recipe, B.TradeCost
			local green, blue, purple, golden = counts.Green or 0, counts.Blue or 0, counts.Purple or 0, counts.Golden or 0
			for batches = 60, 1, -1 do
				local purpleToGolden = math.max(0, batches * recipe.Golden - golden)
				local bluToPurple = math.max(0, batches * recipe.Purple + (cost.Purple or 50) * purpleToGolden - purple)
				local greenToBlue = math.max(0, batches * recipe.Blue + (cost.Blue or 10) * bluToPurple - blue)
				if green >= batches * recipe.Green + (cost.Green or 10) * greenToBlue then
					return { Essence = batches, Green = greenToBlue, Blue = bluToPurple, Purple = purpleToGolden }
				end
			end
			return nil
		end

		local function tradeOn()
			return on(B.TradeHandle)
		end

		local function smartOn()
			return tradeOn() and on(B.SmartHandle)
		end

		local function treeUnlocked()
			return localPlayer:GetAttribute("EnchantedTreeUnlocked") == true
		end

		local function visitMachines(token)
			local trading, crafting = tradeOn(), on(B.CraftHandle)
			if not trading and not crafting then
				return
			end
			if not treeUnlocked() then
				B.MachineNote = "Trade and craft need the Enchanted Tree open (finish the Wisp quest)"
				return
			end
			B.AtStation = nil
			B.MachineError = nil

			local function stopped()
				if token ~= B.TripToken or B.Yield() ~= nil then
					return true
				end
				if eventLive() and wantsCatch() then
					return true
				end
				return not (tradeOn() or on(B.CraftHandle))
			end
			B.TripStopped = stopped

			leaveTreadmill()

			if not enterTree(stopped) then
				B.MachineNote = "Could not get into the Enchanted Tree" .. (B.MachineError and (" (" .. B.MachineError .. ")") or "")
				return
			end

			local trades, crafts = 0, 0

			if trading and smartOn() then
				local plan = smartPlan(readCounts())
				if plan then
					for _, step in ipairs({
						{ From = "Green", Count = plan.Green },
						{ From = "Blue", Count = plan.Blue },
						{ From = "Purple", Count = plan.Purple },
					}) do
						for _ = 1, step.Count do
							if stopped() then
								break
							end
							B.Status = "Smart trade for Enchanted Essence"
							if not useMachine("RF/Butterflies/AskTradeUp", "ButterflyMachine", step.From) then
								break
							end
							trades = trades + 1
							task.wait(0.15)
						end
					end
				end
			elseif trading then
				for _, option in ipairs(TRADES) do
					if B.Trades[option.Label] then
						local cost = B.TradeCost[option.From] or 10
						local reserve = crafting and (B.Recipe[option.From] or 0) or 0
						for _ = 1, 400 do
							if stopped() then
								break
							end
							if (readCounts()[option.From] or 0) - reserve < cost then
								break
							end
							B.Status = "Trading " .. option.Label .. " at the machine"
							if not useMachine("RF/Butterflies/AskTradeUp", "ButterflyMachine", option.From) then
								break
							end
							trades = trades + 1
							task.wait(0.15)
						end
					end
				end
			end

			if crafting then
				for _ = 1, 50 do
					if stopped() then
						break
					end
					local counts, enough = readCounts(), true
					for tier, need in pairs(B.Recipe) do
						if (counts[tier] or 0) < need then
							enough = false
							break
						end
					end
					if not enough then
						break
					end
					B.Status = "Crafting Enchanted Essence at the shrine"
					if not useMachine("RF/Butterflies/AskCraftEssence", "MutationShrine") then
						break
					end
					crafts = crafts + 1
					task.wait(0.3)
				end
			end

			B.MachineNote = string.format("Last visit: %d trade%s, %d essence", trades, trades == 1 and "" or "s", crafts)
			if B.MachineError and trades == 0 and crafts == 0 then
				B.MachineNote = B.MachineNote .. " (" .. B.MachineError .. ")"
			end
			readCounts()
		end

		-- apakah ada trade / craft yang layak dikerjakan sekarang
		local function wantsMachines()
			if not treeUnlocked() then
				return false
			end
			local trading, crafting = tradeOn(), on(B.CraftHandle)
			local counts = B.Counts or {}
			if smartOn() then
				local plan = smartPlan(counts)
				if not plan then
					return false
				end
				return crafting or plan.Green + plan.Blue + plan.Purple > 0
			end
			if crafting then
				local enough = true
				for tier, need in pairs(B.Recipe) do
					if (counts[tier] or 0) < need then
						enough = false
					end
				end
				if enough then
					return true
				end
			end
			if trading then
				for _, option in ipairs(TRADES) do
					if B.Trades[option.Label] then
						local reserve = crafting and (B.Recipe[option.From] or 0) or 0
						if (counts[option.From] or 0) - reserve >= (B.TradeCost[option.From] or 10) then
							return true
						end
					end
				end
			end
			return false
		end

		-- --------------------------------------------------------
		-- UI (tab "Butterfly")
		-- --------------------------------------------------------
		section:CreateText({
			Name = "Butterfly Bloom",
			Text = "Event Butterfly Bloom: catch kupu-kupu otomatis, Trade Up, dan Craft Enchanted Essence.",
		})
		-- Status + baris icon butterfly (icon sama dengan Chili).
		local ICONS = {
			{ Key = "Green", Icon = "rbxassetid://107744695034799", Color = "#5BE873" },
			{ Key = "Blue", Icon = "rbxassetid://89995151383384", Color = "#5FA2FF" },
			{ Key = "Purple", Icon = "rbxassetid://121235713836098", Color = "#C27BFF" },
			{ Key = "Golden", Icon = "rbxassetid://98126365702697", Color = "#FFD452" },
			{ Key = "Essence", Icon = "rbxassetid://114750647204247", Color = "#6FF0FF" },
		}
		B.Row = section:CreateText({ Name = "Butterfly Status", Text = "Off" })
		B.CountShown = {}
		if type(section.CreateIconRow) == "function" then
			B.IconRow = section:CreateIconRow({ Items = ICONS })
			if type(B.IconRow) ~= "table" or not (B.IconRow.Built and B.IconRow.Built()) then
				B.IconRow = nil
			end
		end
		if not B.IconRow then
			B.Counter = section:CreateText({ Name = "Butterflies", Text = countsText() })
		end

		B.Handle = section:CreateToggle({
			Name = "Auto Butterfly Bloom",
			Default = false,
			Callback = function()
				if not wantsCatch() then
					B.Generation = B.Generation + 1
				end
				tbl3.Wake()
			end,
		})

		section:CreateDropdown({
			Name = "Catch Mode",
			Options = { "Stand", "Chase", "Circle", "Patrol" },
			Default = "Stand",
			ShowWhen = B.Handle,
			Callback = function(value)
				value = tostring(value)
				B.Mode = (value == "Chase" or value == "Patrol" or value == "Circle") and value or "Stand Still"
			end,
		})

		section:CreateDropdown({
			Name = "Catch Priority",
			Note = "Only for Chase mode",
			Options = { "Rarest", "Nearest" },
			Default = "Rarest",
			ShowWhen = B.Handle,
			Callback = function(value)
				value = tostring(value)
				B.Priority = (value == "Nearest" or value == "Nearest First") and "Nearest First" or "Strict Rarity"
			end,
		})

		local tierOptions = { "Radiant Butterfly", "Amethyst Butterfly", "Sapphire Butterfly", "Emerald Butterfly" }
		section:CreateMultiDropdown({
			Name = "Catch Butterflies",
			Note = "Only for Chase mode",
			Options = tierOptions,
			Default = tierOptions,
			ShowWhen = B.Handle,
			Callback = function(selected)
				local tiers = {}
				if type(selected) == "table" then
					for key, value in pairs(selected) do
						local name = value == true and type(key) == "string" and key or type(value) == "string" and value or nil
						local tier = name and TIER_PICK[name]
						if tier then
							tiers[tier] = true
						end
					end
				end
				B.Tiers = tiers
				tbl3.Wake()
			end,
		})

		section:CreateSlider({
			Name = "Butterfly Tween Speed",
			Min = 100,
			Max = 600,
			Default = 320,
			Increment = 10,
			Unit = "studs/s",
			ShowWhen = B.Handle,
			Callback = function(value)
				B.Speed = math.clamp(tonumber(value) or 320, 100, 600)
			end,
		})

		local function warnTree(value)
			if value == true and os.clock() - (B.BuiltAt or 0) > 4 and not treeUnlocked() then
				tbl4.Notify("Butterfly Bloom", TREE_NOTE)
			end
			tbl3.Wake()
		end

		B.TradeHandle = section:CreateToggle({
			Name = "Auto Trade Up",
			Default = false,
			Callback = warnTree,
		})

		section:CreateMultiDropdown({
			Name = "Trade Up Tiers",
			Options = { TRADES[1].Label, TRADES[2].Label, TRADES[3].Label },
			Default = {},
			ShowWhen = B.TradeHandle,
			Callback = function(selected)
				local legacy = {
					["Green To Blue"] = "Emerald To Sapphire",
					["Blue To Purple"] = "Sapphire To Amethyst",
					["Purple To Golden"] = "Amethyst To Radiant",
				}
				local trades = {}
				for key, value in pairs(type(selected) == "table" and selected or {}) do
					local name = value == true and type(key) == "string" and key or type(value) == "string" and value or nil
					if name then
						trades[legacy[name] or name] = true
					end
				end
				B.Trades = trades
				tbl3.Wake()
			end,
		})

		B.SmartHandle = section:CreateToggle({
			Name = "Smart Trade For Essence",
			Default = false,
			ShowWhen = B.TradeHandle,
			Callback = warnTree,
		})

		B.CraftHandle = section:CreateToggle({
			Name = "Auto Craft Essence",
			Default = false,
			Callback = warnTree,
		})

		-- --------------------------------------------------------
		-- Scheduler tick
		-- --------------------------------------------------------
		local function setRow(row, text, shownKey)
			if row and B[shownKey] ~= text and type(row.Set) == "function" then
				B[shownKey] = text
				pcall(row.Set, row, text)
			end
		end

		tbl3.Add(function()
			-- status + counter
			local text
			if not wantsCatch() then
				text = "Off  |  " .. timerText()
			elseif B.Busy then
				text = B.Status .. "  |  " .. timerText()
			else
				text = timerText()
			end
			setRow(B.Row, text, "Shown")
			setRow(B.Counter, countsText(), "CounterShown")

			-- baris icon: jumlah tiap tier (format have/need kalau ada resep)
			if B.IconRow then
				local c = B.Counts or {}
				local values = { Green = c.Green, Blue = c.Blue, Purple = c.Purple, Golden = c.Golden, Essence = B.Essence }
				for _, item in ipairs(ICONS) do
					local key = item.Key
					local need = B.Recipe and B.Recipe[key]
					local shown = need and string.format("%d/%d", values[key] or 0, need) or tostring(values[key] or 0)
					if B.CountShown[key] ~= shown then
						B.CountShown[key] = shown
						pcall(B.IconRow.SetCount, B.IconRow, key, shown)
					end
				end
			end

			-- kunjungan mesin (trade / craft) saat event tidak berlangsung
			if not B.Busy and not eventLive() and os.clock() >= (B.NextTrip or 0) and not tbl4.IsNight() and not tbl4.WallSealed() and wantsMachines() then
				local reason = B.Yield()
				if reason then
					B.Status = reason
				elseif tbl4.ClaimMovement("butterfly") then
					B.NextTrip = os.clock() + 60
					B.Busy = true
					B.TripToken = (B.TripToken or 0) + 1
					local token = B.TripToken
					task.spawn(function()
						pcall(visitMachines, token)
						pcall(leaveTree)
						tbl4.ReleaseMovement("butterfly")
						B.Busy = false
						tbl3.Wake()
					end)
					return true
				end
			end

			-- Invisibility balik lagi kalau catch sudah selesai
			if not B.Busy and tbl4.InvisButterfly and (not wantsCatch() or not eventLive()) then
				restoreInvisibility()
			end
			if not wantsCatch() or not eventLive() then
				B.Claiming = false
			end
			if not wantsCatch() or B.Busy or not eventLive() then
				return true
			end

			local reason = B.Yield()
			if reason then
				B.Status = reason
				B.Claiming = false
				return true
			end

			if tbl4.IsNight() or tbl4.WallSealed() then
				local root = tbl4.Root()
				if root and (root.Position - bloomCentre()).Magnitude >= 1200 then
					B.Status = "Night, waiting for daylight before flying to the bloom"
					B.Claiming = false
					return true
				end
			end

			B.Claiming = true

			-- Invisibility dijeda selama catch
			if not tbl4.InvisButterfly then
				tbl4.InvisButterfly = true
				if type(FK_TBL4) == "table" then
					FK_TBL4.InvisSuspended = true
				end
				if tbl4.InvisibilityHandle ~= nil and on(tbl4.InvisibilityHandle) then
					tbl4.Notify("Invisibility", "Invisibility is paused while catching butterflies and comes back after it.")
				end
			end
			local character = localPlayer.Character
			if character and character:GetAttribute("InvisApplied") == true then
				B.Status = "Leaving Invisibility before catching"
				return true
			end

			if not tbl4.ClaimMovement("butterfly") then
				B.Status = "Waiting for " .. tostring(tbl4.Movement.Owner or "movement")
				return true
			end

			task.spawn(function()
				local ok, err = pcall(catchLoop)
				if not ok then
					B.Status = "Stopped: " .. tostring(err)
					B.Wants = false
					restoreInvisibility()
					pcall(stopMoving)
					pcall(tbl4.EndFlight)
					pcall(tbl4.Shield, "butterfly", false)
					tbl4.ReleaseMovement("butterfly")
					B.Busy = false
				end
			end)
			return true
		end)

		fn4(function()
			B.Generation = B.Generation + 1
			B.TripToken = (B.TripToken or 0) + 1
			for _, link in ipairs(B.Links) do
				pcall(function()
					link:Disconnect()
				end)
			end
			table.clear(B.Links)
			restoreInvisibility()
			pcall(tbl4.Shield, "butterfly", false)
			pcall(tbl4.ReleaseMovement, "butterfly")
		end)
	end

	local okButterfly, errButterfly = pcall(FK_butterflyBoot)
	if not okButterfly then
		warn("[FanKun] Butterfly Bloom gagal dimuat: " .. tostring(errButterfly))
	end
end

-- ============================================================
-- [FanKun] Wisp Companion (diport dari CHILI HUB / chililatest-sae)
-- Fitur : Auto Wisp -> otomatis menyelesaikan quest Wisp sampai Enchanted Tree terbuka
--         (Accept -> kerjakan tiap stage -> Claim -> BeginReturn/Return).
--         Stage "EggSecured"  : Auto Steal otomatis mencuri egg yang dibutuhkan quest
--                               (lewat tbl4.Wisp.Need, nyalakan Auto Steal).
--         Stage "PetFused"    : otomatis load 3 pet sama ke Fuse Machine lalu BeginFuse.
-- UI    : tab "Wisp" (tab sendiri). Dijalankan lewat pcall.
-- Logic : sama dengan Chili. Bedanya travel jauh memakai tbl4.FlyTo (RagdollTravel
--         tidak ada di FanKun) dan prioritas gerak memakai sistem FanKun.
-- ============================================================
do
	local function FK_wispBoot()
		local section = FK_WIN._wispSection or FK_SCR
		if section == nil then
			return
		end
		section = FK_wrapSection(section)

		local W = {
			Status = "Off",
			Shown = nil,
			Busy = false,
			Stepping = false,
			Generation = 0,
			State = nil,
			SpeedPower = 0,
			Revealed = false,
			Quests = nil,
			StageCount = 4,
			Required = 50000000000,
			NextTry = 0,
			Signature = nil,
			Handle = nil,
			Row = nil,
			BuiltAt = os.clock(),
		}
		tbl4.Wisp = W

		local alive = true

		-- --------------------------------------------------------
		-- Util dasar
		-- --------------------------------------------------------
		local function on()
			return tbl4.Toggle(W.Handle, false) == true
		end

		local function invoke(name, ...)
			local remote = networking:FindFirstChild(name)
			if not remote or not remote:IsA("RemoteFunction") then
				return false, nil
			end
			return pcall(remote.InvokeServer, remote, ...)
		end

		-- RF/WispCompanion/Request: return (hasil server, pesan)
		local function wispRequest(action, arg)
			local remote = networking:FindFirstChild("RF/WispCompanion/Request")
			if not remote or not remote:IsA("RemoteFunction") then
				return false, "missing remote"
			end
			local ok, result, message = pcall(remote.InvokeServer, remote, action, arg)
			if not ok then
				return false, tostring(result)
			end
			return result, message
		end

		local function worldPosition(path)
			local node = workspace:FindFirstChild("World")
			for _, name in ipairs(path) do
				node = node and node:FindFirstChild(name)
			end
			if node and node:IsA("BasePart") then
				return node.Position
			end
			if node and node:IsA("Model") then
				local ok, pivot = pcall(node.GetPivot, node)
				return ok and pivot.Position or nil
			end
			return nil
		end

		local function saveData()
			local save = tbl.Save
			if type(save) ~= "table" then
				return nil
			end
			local getter = type(save.Get) == "function" and save.Get or save.Peek
			if type(getter) ~= "function" then
				return nil
			end
			local ok, data = pcall(getter)
			return ok and type(data) == "table" and data or nil
		end

		-- --------------------------------------------------------
		-- Data quest + sinkron state Save tiap 1 detik
		-- --------------------------------------------------------
		task.spawn(function()
			pcall(function()
				local quests = require(ReplicatedStorage.Data.WispQuests)
				W.Quests = quests.List
				W.StageCount = tonumber(quests.StageCount) or W.StageCount
				W.Required = tonumber(quests.RequiredSpeedPower) or W.Required
			end)
			while alive do
				pcall(function()
					local data = saveData()
					if data then
						W.State = type(data.WispCompanion) == "table" and data.WispCompanion or nil
						W.SpeedPower = tonumber(data.SpeedPower) or 0
						local state = W.State or {}
						local parts = { tostring(state.Accepted), tostring(state.Stage), tostring(state.Unlocked), tostring(state.Returning) }
						for key, value in pairs(type(state.Progress) == "table" and state.Progress or {}) do
							table.insert(parts, tostring(key) .. "=" .. tostring(value))
						end
						for key, value in pairs(type(state.Claimed) == "table" and state.Claimed or {}) do
							table.insert(parts, tostring(key) .. ":" .. tostring(value))
						end
						table.sort(parts)
						local signature = table.concat(parts, ",")
						if signature ~= W.Signature then
							W.Signature = signature
							W.NextTry = 0
							tbl3.Wake()
						end
					end
					local world = workspace:FindFirstChild("World")
					local build = world and world:FindFirstChild("Build")
					W.Revealed = build ~= nil and build:GetAttribute("EnchantedForestZoneRevealed") == true
				end)
				task.wait(1)
			end
		end)

		local function currentQuest()
			local state = W.State
			if type(state) ~= "table" or not state.Accepted or state.Unlocked or type(W.Quests) ~= "table" then
				return nil
			end
			return W.Quests[tonumber(state.Stage) or 1]
		end

		local function progressOf(quest)
			local state = W.State
			local progress = type(state) == "table" and type(state.Progress) == "table" and state.Progress or {}
			return tonumber(progress[quest.Id]) or 0
		end

		local function claimedOf(quest)
			local state = W.State
			local claimed = type(state) == "table" and type(state.Claimed) == "table" and state.Claimed or {}
			return claimed[quest.Id] == true
		end

		local function rarityName(category)
			local assets = tbl.Assets
			local directory = type(assets) == "table" and assets.Directory or nil
			local entry = type(directory) == "table" and directory[tostring(category)] or nil
			local rarity = type(entry) == "table" and entry.Rarity or nil
			return type(rarity) == "table" and tostring(rarity.DisplayName or rarity._id or "") or ""
		end

		-- daftar kategori (species) yang bisa drop di area tertentu
		local dropCache = {}
		local function areaDrops(areaId)
			areaId = tostring(areaId)
			if dropCache[areaId] then
				return dropCache[areaId]
			end
			local set = {}
			pcall(function()
				local configs = ReplicatedStorage.Data.Areas.Configs
				local config = require(configs[areaId])
				for _, entry in ipairs(type(config.DropTable) == "table" and config.DropTable or {}) do
					if type(entry) == "table" and entry[1] ~= nil then
						set[tostring(entry[1])] = true
					end
				end
			end)
			dropCache[areaId] = set
			return set
		end

		-- quest PetFused yang masih berjalan -> quest, set species area-nya
		local function fuseQuest()
			local quest = currentQuest()
			if not quest or quest.Event ~= "PetFused" or claimedOf(quest) or progressOf(quest) >= (tonumber(quest.Target) or 1) then
				return nil
			end
			local areaId = type(quest.Match) == "table" and quest.Match.AreaId or nil
			if areaId == nil then
				return nil
			end
			return quest, areaDrops(areaId)
		end

		local function eggIncome(category, scale, mutations)
			if type(tbl4.EggIncome) ~= "function" then
				return tonumber(scale) or 0
			end
			local ok, value = pcall(tbl4.EggIncome, { AssetCategory = category, AssetScale = scale, Mutations = mutations })
			return ok and tonumber(value) or 0
		end

		-- pet di inventory (bukan favorite, bukan equipped) per species
		local function petUids(save, categories)
			local equipped = {}
			for _, uid in pairs(type(save.EquippedAssets) == "table" and save.EquippedAssets or {}) do
				equipped[uid] = true
			end
			local result = {}
			for uid, item in pairs(type(save.Inventory) == "table" and save.Inventory or {}) do
				local category = type(item) == "table" and tostring(item.Category) or nil
				if category and categories[category] and item.IsFavorite ~= true and not equipped[uid] then
					result[category] = result[category] or {}
					table.insert(result[category], uid)
				end
			end
			return result
		end

		-- jumlah terbanyak (pet + egg) dari satu species
		local function maxOwned(save, categories)
			local counts = {}
			for category, list in pairs(petUids(save, categories)) do
				counts[category] = #list
			end
			pcall(function()
				local eggState = tbl.EggState
				local eggs = eggState.ReadOwnerEggs(localPlayer.UserId)
				for _, egg in pairs(type(eggs) == "table" and eggs or {}) do
					local category = type(egg) == "table" and tostring(egg.AssetCategory) or nil
					if category and categories[category] then
						counts[category] = (counts[category] or 0) + 1
					end
				end
			end)
			local best = 0
			for _, count in pairs(counts) do
				best = math.max(best, count)
			end
			return best
		end

		local ownedCache = { At = 0, Value = 0 }
		local function ownedCached(save, categories)
			if os.clock() - ownedCache.At > 2 then
				ownedCache.At = os.clock()
				ownedCache.Value = maxOwned(save, categories)
			end
			return ownedCache.Value
		end

		-- rencana fuse: species terbaik + pet + uid egg yang harus dipertahankan
		local plan = { At = 0, Species = nil, Uids = {}, Pets = {} }
		local function fusePlan()
			if os.clock() - plan.At < 2 then
				return plan
			end
			plan.At = os.clock()
			plan.Species = nil
			plan.Uids = {}
			plan.Pets = {}
			local quest, categories = fuseQuest()
			local save = quest and saveData() or nil
			if not quest or not save then
				return plan
			end

			local inventory = type(save.Inventory) == "table" and save.Inventory or {}
			local petsBySpecies = {}
			for species, uids in pairs(petUids(save, categories)) do
				local list = {}
				for _, uid in ipairs(uids) do
					local item = inventory[uid]
					table.insert(list, { Uid = uid, Value = eggIncome(species, item and item.Scale, item and item.Mutations) })
				end
				table.sort(list, function(a, b)
					return a.Value < b.Value
				end)
				petsBySpecies[species] = list
			end

			local placed, eggsBySpecies, growth = {}, {}, {}
			pcall(function()
				local eggs = tbl.EggState.ReadOwnerEggs(localPlayer.UserId)
				local records = nil
				pcall(function()
					records = require(ReplicatedStorage.Shared.Util.EggRecords)
				end)
				for uid, egg in pairs(type(eggs) == "table" and eggs or {}) do
					local category = type(egg) == "table" and tostring(egg.AssetCategory) or nil
					if category and categories[category] then
						if egg.Placement ~= nil then
							placed[category] = (placed[category] or 0) + 1
						else
							eggsBySpecies[category] = eggsBySpecies[category] or {}
							table.insert(eggsBySpecies[category], { Uid = uid, Value = eggIncome(category, egg.AssetScale, egg.Mutations) })
						end
						if records and type(records.GrowthDuration) == "function" then
							local okGrowth, duration = pcall(records.GrowthDuration, egg)
							if okGrowth and type(duration) == "number" then
								growth[category] = math.min(growth[category] or math.huge, duration)
							end
						end
					end
				end
			end)

			local bestTime, bestValue, bestSpecies = math.huge, math.huge, nil
			for species in pairs(categories) do
				local pets = petsBySpecies[species] or {}
				local eggs = eggsBySpecies[species] or {}
				table.sort(eggs, function(a, b)
					return a.Value < b.Value
				end)
				if #pets + (placed[species] or 0) + #eggs >= 3 then
					local waitTime = #pets >= 3 and 0 or (growth[species] or math.huge)
					local value, taken = 0, 0
					for _, pet in ipairs(pets) do
						if taken < 3 then
							value = value + pet.Value
							taken = taken + 1
						end
					end
					for _, egg in ipairs(eggs) do
						if taken < 3 then
							value = value + egg.Value
							taken = taken + 1
						end
					end
					if waitTime < bestTime or (waitTime == bestTime and value < bestValue) then
						bestTime, bestValue, bestSpecies = waitTime, value, species
					end
				end
			end

			plan.Species = bestSpecies
			if bestSpecies then
				plan.Pets = petsBySpecies[bestSpecies] or {}
				local eggs = eggsBySpecies[bestSpecies] or {}
				for index = 1, math.max(0, 3 - #plan.Pets - (placed[bestSpecies] or 0)) do
					local egg = eggs[index]
					if egg then
						plan.Uids[egg.Uid] = true
					end
				end
			end
			return plan
		end

		-- apakah masih perlu mencari egg untuk fuse
		local function fuseNeeds()
			local quest, categories = fuseQuest()
			if not quest then
				return false, nil
			end
			local save = saveData()
			return save ~= nil and ownedCached(save, categories) < 3, quest
		end

		-- --------------------------------------------------------
		-- Hook untuk Auto Steal
		-- --------------------------------------------------------
		-- true kalau egg ini dibutuhkan quest Wisp yang sedang jalan
		W.Need = function(record)
			if not on() or type(record) ~= "table" then
				return false
			end
			local quest = currentQuest()
			if quest and quest.Event == "PetFused" then
				local needs, fuse = fuseNeeds()
				return needs == true and type(fuse.Match) == "table" and tostring(record.AreaId) == tostring(fuse.Match.AreaId)
			end
			if not quest or quest.Event ~= "EggSecured" or claimedOf(quest) or progressOf(quest) >= (tonumber(quest.Target) or 1) then
				return false
			end
			for key, value in pairs(type(quest.Match) == "table" and quest.Match or {}) do
				if key == "AreaId" then
					if tostring(record.AreaId) ~= tostring(value) then
						return false
					end
				elseif key == "Rarity" then
					if rarityName(record.AssetCategory) ~= tostring(value) then
						return false
					end
				else
					return false
				end
			end
			return true
		end

		-- true kalau Auto Wisp sedang butuh Auto Steal
		W.Steals = function()
			if not on() then
				return false
			end
			local quest = currentQuest()
			if quest and quest.Event == "PetFused" then
				return (fuseNeeds()) == true
			end
			return quest ~= nil and quest.Event == "EggSecured" and not claimedOf(quest) and progressOf(quest) < (tonumber(quest.Target) or 1)
		end

		-- uid egg yang sebaiknya jangan dijual / dipakai (dibutuhkan fuse)
		W.FuseUids = function()
			if not on() then
				return {}
			end
			return fusePlan().Uids
		end

		-- Hook publik di tbl4 (sama dengan Chili): dipakai Auto Place / Auto Hatch / Auto Steal
		tbl4.WispFuseUids = function()
			return W.FuseUids()
		end
		tbl4.WispSteals = function()
			return W.Steals()
		end
		-- true kalau Auto Place harus menaruh egg supaya pet untuk fuse bisa tumbuh
		tbl4.WispPlaceOn = function()
			if not on() or fuseQuest() == nil then
				return false
			end
			local current = fusePlan()
			if current.Species == nil then
				return false
			end
			local save = saveData()
			local owned = save and petUids(save, { [current.Species] = true }) or {}
			return (owned[current.Species] and #owned[current.Species] or 0) < 3
		end
		-- true kalau egg species ini harus di-hatch untuk fuse
		tbl4.WispFuseEggs = function(category)
			if not on() then
				return false
			end
			return fusePlan().Species == tostring(category)
		end
		-- true kalau stage sekarang butuh egg Eternal (rarity) di server ini
		tbl4.WispEternalStage = function()
			if not on() then
				return false
			end
			local quest = currentQuest()
			return quest ~= nil and quest.Event == "EggSecured" and type(quest.Match) == "table" and quest.Match.Rarity ~= nil
		end

		-- --------------------------------------------------------
		-- Fuse Machine (stage PetFused)
		-- --------------------------------------------------------
		local function fuseStep()
			local quest, categories = fuseQuest()
			local save = saveData()
			if not quest or not save then
				return nil
			end
			if save.FusionLocked == true then
				if type(save.FusionEggReward) == "table" then
					invoke("RF/Fusery/FinishReveal")
				end
				return "Fusing, waiting for the result"
			end

			local current = fusePlan()
			local species, uids
			if current.Species and #current.Pets >= 3 then
				species, uids = current.Species, {}
				for index = 1, 3 do
					table.insert(uids, current.Pets[index].Uid)
				end
			end
			if not species then
				if maxOwned(save, categories) >= 3 then
					return "Hatching Enchanted Forest eggs for the fuse"
				end
				return "Stealing Enchanted Forest eggs for the fuse"
			end

			local slots = type(save.FusionSlots) == "table" and save.FusionSlots or {}
			local wanted = {}
			for index = 1, 3 do
				wanted[uids[index]] = true
			end
			for index = 1, 3 do
				local slot = slots[index]
				if slot ~= nil and not wanted[slot] then
					invoke("RF/Fusery/EjectPet", slot)
					task.wait(0.35)
				end
			end
			if save.FusionInfoAcknowledged == false then
				invoke("RF/Fusery/ConfirmBriefing")
				task.wait(0.35)
			end
			local loaded = {}
			for index = 1, 3 do
				if slots[index] ~= nil then
					loaded[slots[index]] = true
				end
			end
			for index = 1, 3 do
				local uid = uids[index]
				if not loaded[uid] then
					local ok, result = invoke("RF/Fusery/LoadPet", uid)
					if not ok or result == false then
						return "Could not load the pets into the Fuse Machine"
					end
					task.wait(0.35)
				end
			end
			local ok, result = invoke("RF/Fusery/BeginFuse")
			if not ok or result == false then
				return "Fuse Machine refused (money or slots)"
			end
			return "Fusing 3 " .. species
		end

		-- --------------------------------------------------------
		-- Travel + prioritas gerak
		-- --------------------------------------------------------
		local function yieldReason()
			local butterfly = tbl4.Butterfly
			if type(butterfly) == "table" and type(butterfly.Yield) == "function" then
				local ok, reason = pcall(butterfly.Yield)
				if ok then
					return reason
				end
			end
			local steal = tbl4.Steal
			local movement = tbl4.Movement
			if movement.PlaceWanted == true then
				return "Auto Place Egg goes first"
			end
			if movement.MutationWanted == true or movement.ScrambleWanted == true then
				return "Scrambled Mutation goes first"
			end
			if on(v5) and steal ~= nil and (steal.Wanted == true or steal.Carrying == true or steal.Active == true) then
				return "Auto Steal goes first"
			end
			return nil
		end

		-- ke posisi tujuan; false kalau sedang malam / wall tertutup (tunggu siang)
		local function travelTo(position, gen)
			local character = localPlayer.Character
			local root = tbl4.Root()
			if not character or not root or not position then
				return false
			end
			pcall(function()
				localPlayer:RequestStreamAroundAsync(position, 3)
			end)

			local target = position + Vector3.new(0, 3, 3)
			if (root.Position - position).Magnitude > 1200 then
				if tbl4.IsNight() or tbl4.WallSealed() then
					return false
				end
				local humanoid = character:FindFirstChildOfClass("Humanoid")
				if humanoid then
					pcall(function()
						humanoid:UnequipTools()
					end)
				end
				if type(tbl4.FlyTo) == "function" then
					pcall(tbl4.FlyTo, target, function()
						return gen ~= W.Generation or not on()
					end, "wisp")
				end
			end

			root = tbl4.Root()
			if root and (root.Position - position).Magnitude > 40 then
				pcall(function()
					character:PivotTo(CFrame.new(target))
					root.AssemblyLinearVelocity = Vector3.zero
				end)
			end

			local humanoid = character:FindFirstChildOfClass("Humanoid")
			local waited = 0
			root = tbl4.Root()
			while humanoid and root and waited < 3 and (root.Position - position).Magnitude > 6 do
				humanoid:MoveTo(position)
				waited = waited + task.wait(0.2)
			end
			task.wait(0.5)
			return true
		end

		-- jalankan aksi yang butuh gerak, dengan klaim movement "wisp"
		local function withMovement(fn)
			local reason = yieldReason()
			if reason then
				W.Status = reason
				return false
			end
			if not tbl4.ClaimMovement("wisp") then
				W.Status = "Waiting for " .. tostring(tbl4.Movement.Owner or "movement")
				return false
			end
			W.Busy = true
			local ok, result = pcall(fn)
			tbl4.ReleaseMovement("wisp")
			W.Busy = false
			return ok and result
		end

		-- --------------------------------------------------------
		-- Satu langkah Auto Wisp
		-- --------------------------------------------------------
		local function step()
			local state = W.State
			if type(state) ~= "table" then
				W.Status = "Reading your Wisp"
				return
			end
			if state.Unlocked then
				W.Status = "Done, the Enchanted Tree is open"
				return
			end

			pcall(function()
				local save = saveData()
				if save and save.FusionLocked == true and type(save.FusionEggReward) == "table" then
					invoke("RF/Fusery/FinishReveal")
				end
			end)

			local gen = W.Generation

			if not state.Accepted then
				if W.SpeedPower < W.Required then
					W.Status = string.format("Needs %.0fB Speed Power to meet the Wisp (you have %.2fB)", W.Required / 1000000000, W.SpeedPower / 1000000000)
					return
				end
				if not W.Revealed then
					W.Status = "Enchanted Forest is not open yet"
					return
				end
				withMovement(function()
					W.Status = "Meeting the Wisp"
					if not travelTo(worldPosition({ "Build", "EnchantedForestZone", "WispSpawn" }), gen) then
						W.Status = "Night, waiting for daylight before travelling"
						return
					end
					local ok, message = wispRequest("Accept")
					W.Status = ok and "Wisp accepted" or "Accept: " .. tostring(message or "no answer")
				end)
				return
			end

			local stage = tonumber(state.Stage) or 1
			local quest = currentQuest()
			if quest and not claimedOf(quest) and progressOf(quest) >= (tonumber(quest.Target) or 1) then
				W.Status = "Claiming " .. tostring(quest.Title)
				local ok, message = wispRequest("Claim", quest.Id)
				if not ok then
					W.Status = "Claim: " .. tostring(message or "no answer")
				end
				return
			end

			if stage >= W.StageCount then
				withMovement(function()
					W.Status = "Taking the Wisp back to the Enchanted Tree"
					if not state.Returning then
						wispRequest("BeginReturn")
					end
					if not travelTo(worldPosition({ "Build", "EnchantedForestZone", "Zone13Props", "EnchantedTree", "WispAnchor" }), gen) then
						W.Status = "Night, waiting for daylight before travelling"
						return
					end
					local ok, message = wispRequest("Return")
					W.Status = ok and "Wisp returned, the seal is broken" or "Return: " .. tostring(message or "no answer")
				end)
				return
			end

			if quest then
				local extra = ""
				if quest.Event == "PetFused" then
					local ok, text = pcall(fuseStep)
					extra = ok and text and ("  |  " .. text) or ""
				elseif quest.Event == "EggSecured" and type(quest.Match) == "table" and quest.Match.Rarity ~= nil then
					extra = "  |  waiting for an Eternal egg in this server"
				end
				W.Status = string.format("Stage %d/%d  |  %s %d/%d%s", stage, W.StageCount, tostring(quest.Title), progressOf(quest), tonumber(quest.Target) or 1, extra)
			end
		end

		-- --------------------------------------------------------
		-- UI (tab "Wisp")
		-- --------------------------------------------------------
		section:CreateText({
			Name = "Wisp Companion",
			Text = "Quest Wisp otomatis sampai Enchanted Tree terbuka. Nyalakan Auto Steal supaya egg quest ikut dicuri.",
		})
		W.Row = section:CreateText({ Name = "Wisp Status", Text = "Off" })
		W.Handle = section:CreateToggle({
			Name = "Auto Wisp",
			Default = false,
			Callback = function(value)
				if value == true and os.clock() - (W.BuiltAt or 0) > 4 then
					local accepted, unlocked, speed = false, false, 0
					pcall(function()
						local data = saveData()
						speed = tonumber(data.SpeedPower) or 0
						accepted = type(data.WispCompanion) == "table" and data.WispCompanion.Accepted == true
						unlocked = type(data.WispCompanion) == "table" and data.WispCompanion.Unlocked == true
					end)
					if not accepted and not unlocked and speed < W.Required then
						tbl4.Notify(
							"Auto Wisp",
							string.format(
								"Needs %.0fB Speed Power to meet the Wisp (you have %.2fB). It stays on and starts by itself once you reach %.0fB.",
								W.Required / 1000000000,
								speed / 1000000000,
								W.Required / 1000000000
							)
						)
					end
				end
				W.Generation = W.Generation + 1
				W.NextTry = 0
				tbl3.Wake()
			end,
		})
		W.BuiltAt = os.clock()

		tbl3.Add(function()
			if on() and not W.Busy and not W.Stepping and os.clock() >= W.NextTry then
				W.NextTry = os.clock() + 3
				W.Stepping = true
				task.spawn(function()
					pcall(step)
					W.Stepping = false
					tbl3.Wake()
				end)
			end
			local text = on() and W.Status or "Off"
			pcall(function()
				local banjo = tbl4.Banjo
				if localPlayer:GetAttribute("EnchantedTreeUnlocked") == true and type(banjo) == "table" and tbl4.Toggle(banjo.Handle, false) == true then
					text = "Banjo Cricket: " .. tostring(banjo.Status)
				end
			end)
			if W.Row and W.Shown ~= text and type(W.Row.Set) == "function" then
				W.Shown = text
				pcall(W.Row.Set, W.Row, text)
			end
			return true
		end)

		fn4(function()
			alive = false
			W.Generation = W.Generation + 1
			pcall(tbl4.ReleaseMovement, "wisp")
		end)
	end

	local okWisp, errWisp = pcall(FK_wispBoot)
	if not okWisp then
		warn("[FanKun] Wisp Companion gagal dimuat: " .. tostring(errWisp))
	end
end

end

