-- ============================================================
-- TAB INFORMASI: tab pertama (di atas Auto Steal) + tab yang terbuka saat execute
-- Isi: avatar, region, executor, FPS, ping, memori, info map (icon + Place ID), server, perangkat.
-- ============================================================
xpcall(function()
    local Players = game:GetService("Players")
    local RunService = game:GetService("RunService")
    local UserInputService = game:GetService("UserInputService")
    local Stats = game:GetService("Stats")
    local MarketplaceService = game:GetService("MarketplaceService")
    local LocalizationService = game:GetService("LocalizationService")
    local LP = Players.LocalPlayer
    local startClock = os.clock()

    local P = {
        panel2 = Color3.fromRGB(247, 247, 247),
        field = Color3.fromRGB(230, 230, 230),
        stroke = Color3.fromRGB(205, 205, 205),
        text = Color3.fromRGB(12, 12, 12),
        sub = Color3.fromRGB(100, 100, 100),
        accent = Color3.fromRGB(14, 14, 14),
        green = Color3.fromRGB(30, 150, 90),
        amber = Color3.fromRGB(190, 135, 0),
        orange = Color3.fromRGB(205, 100, 0),
        red = Color3.fromRGB(205, 40, 40),
    }

    local function new(class, props, parent)
        local o = Instance.new(class)
        for k, val in pairs(props or {}) do
            o[k] = val
        end
        if parent then
            o.Parent = parent
        end
        return o
    end
    local function round(o, r)
        return new("UICorner", { CornerRadius = UDim.new(0, r or 10) }, o)
    end
    local function stroke(o, color, thick, trans)
        return new("UIStroke", {
            Color = color or P.stroke,
            Thickness = thick or 1,
            Transparency = trans or 0,
            ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
        }, o)
    end

    local function fmtDur(sec)
        sec = math.max(0, math.floor(tonumber(sec) or 0))
        return string.format("%d:%02d:%02d", math.floor(sec / 3600), math.floor(sec / 60) % 60, sec % 60)
    end

    local COUNTRY = {
        ID = "Indonesia", US = "Amerika Serikat", MY = "Malaysia", SG = "Singapura", PH = "Filipina",
        TH = "Thailand", VN = "Vietnam", JP = "Jepang", KR = "Korea Selatan", CN = "Tiongkok",
        IN = "India", AU = "Australia", NZ = "Selandia Baru", GB = "Inggris", DE = "Jerman",
        FR = "Prancis", NL = "Belanda", ES = "Spanyol", IT = "Italia", BR = "Brasil",
        MX = "Meksiko", CA = "Kanada", RU = "Rusia", TR = "Turki", SA = "Arab Saudi",
        AE = "Uni Emirat Arab", PL = "Polandia", AR = "Argentina", CL = "Chili", HK = "Hong Kong",
        TW = "Taiwan",
    }

    local function executorName()
        local ok, a, b = pcall(function()
            if type(identifyexecutor) == "function" then
                return identifyexecutor()
            end
        end)
        if ok and a then
            return tostring(a) .. (b and (" " .. tostring(b)) or "")
        end
        return "Tidak diketahui"
    end

    local function platformName()
        local ok, r = pcall(function()
            if UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled then
                return "Mobile"
            end
            if UserInputService.GamepadEnabled and not UserInputService.KeyboardEnabled then
                return "Konsol / Gamepad"
            end
            return "PC"
        end)
        return ok and r or "-"
    end

    local function resolutionText()
        local ok, r = pcall(function()
            local v = workspace.CurrentCamera.ViewportSize
            return string.format("%d x %d", v.X, v.Y)
        end)
        return ok and r or "-"
    end

    local function qualityText()
        local ok, r = pcall(function()
            local lvl = UserSettings():GetService("UserGameSettings").SavedQualityLevel
            local n = tostring(lvl.Name):gsub("QualityLevel", "Level ")
            return n
        end)
        return ok and r or "-"
    end

    local function copyText(txt)
        local f = (type(setclipboard) == "function" and setclipboard)
            or (type(toclipboard) == "function" and toclipboard)
            or nil
        if not f then
            return false
        end
        return (pcall(f, tostring(txt)))
    end

    local tab = v2:CreateTab({ Name = "Informasi" })
    local wtab = tab._w
    if not wtab or not wtab.Page then
        return
    end
    pcall(function()
        wtab.UIElements.Main.LayoutOrder = 0 -- paling atas di sidebar
    end)
    local page = wtab.Page

    local order = 0
    local function nextOrder()
        order += 1
        return order
    end

    local live = {}

    local function section(title)
        local f = new("Frame", {
            Size = UDim2.new(1, 0, 0, 30),
            BackgroundTransparency = 1,
            LayoutOrder = nextOrder(),
        }, page)
        new("TextLabel", {
            Position = UDim2.fromOffset(2, 0),
            Size = UDim2.new(1, -4, 1, -6),
            BackgroundTransparency = 1,
            Text = string.upper(title),
            Font = Enum.Font.GothamBlack,
            TextSize = 13,
            TextColor3 = P.accent,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextYAlignment = Enum.TextYAlignment.Bottom,
        }, f)
        new("Frame", {
            AnchorPoint = Vector2.new(0, 1),
            Position = UDim2.new(0, 0, 1, 0),
            Size = UDim2.new(1, 0, 0, 1),
            BackgroundColor3 = P.stroke,
            BorderSizePixel = 0,
        }, f)
    end

    local function note(text)
        new("TextLabel", {
            Size = UDim2.new(1, 0, 0, 14),
            BackgroundTransparency = 1,
            Text = text,
            Font = Enum.Font.GothamMedium,
            TextSize = 10,
            TextColor3 = P.sub,
            TextXAlignment = Enum.TextXAlignment.Left,
            LayoutOrder = nextOrder(),
        }, page)
    end

    -- kartu hero: gambar + judul + sub + tag
    local function hero(imageUrl, circle, titleText, subText, tagText)
        local c = new("Frame", {
            Size = UDim2.new(1, 0, 0, 78),
            BackgroundColor3 = P.panel2,
            BorderSizePixel = 0,
            LayoutOrder = nextOrder(),
        }, page)
        round(c, 10)
        stroke(c, P.stroke, 1, 0.15)
        local img = new("ImageLabel", {
            Position = UDim2.fromOffset(12, 11),
            Size = UDim2.fromOffset(56, 56),
            BackgroundColor3 = P.field,
            BorderSizePixel = 0,
            Image = imageUrl,
            ScaleType = Enum.ScaleType.Crop,
        }, c)
        if circle then
            new("UICorner", { CornerRadius = UDim.new(1, 0) }, img)
        else
            round(img, 12)
        end
        stroke(img, P.stroke, 1, 0.3)
        local t = new("TextLabel", {
            Position = UDim2.fromOffset(80, 12),
            Size = UDim2.new(1, -92, 0, 22),
            BackgroundTransparency = 1,
            Text = titleText,
            Font = Enum.Font.GothamBold,
            TextSize = 16,
            TextColor3 = P.text,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextTruncate = Enum.TextTruncate.AtEnd,
        }, c)
        local sTxt = new("TextLabel", {
            Position = UDim2.fromOffset(80, 36),
            Size = UDim2.new(1, -92, 0, 16),
            BackgroundTransparency = 1,
            Text = subText,
            Font = Enum.Font.GothamMedium,
            TextSize = 12,
            TextColor3 = P.sub,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextTruncate = Enum.TextTruncate.AtEnd,
        }, c)
        local g = new("TextLabel", {
            Position = UDim2.fromOffset(80, 54),
            Size = UDim2.new(1, -92, 0, 14),
            BackgroundTransparency = 1,
            Text = tagText,
            Font = Enum.Font.GothamBold,
            TextSize = 11,
            TextColor3 = P.green,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextTruncate = Enum.TextTruncate.AtEnd,
        }, c)
        return img, t, sTxt, g
    end

    -- kartu daftar baris: rows = { {label, value, key=?, copy=?}, ... }
    local function rowsCard(rows)
        local c = new("Frame", {
            Size = UDim2.new(1, 0, 0, 0),
            AutomaticSize = Enum.AutomaticSize.Y,
            BackgroundColor3 = P.panel2,
            BorderSizePixel = 0,
            LayoutOrder = nextOrder(),
        }, page)
        round(c, 10)
        stroke(c, P.stroke, 1, 0.15)
        new("UIPadding", {
            PaddingLeft = UDim.new(0, 14),
            PaddingRight = UDim.new(0, 14),
            PaddingTop = UDim.new(0, 4),
            PaddingBottom = UDim.new(0, 4),
        }, c)
        new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder }, c)
        for i, d in ipairs(rows) do
            local r = new("TextButton", {
                Size = UDim2.new(1, 0, 0, 28),
                BackgroundTransparency = 1,
                Text = "",
                AutoButtonColor = false,
                LayoutOrder = i,
            }, c)
            new("TextLabel", {
                Size = UDim2.new(0.4, 0, 1, 0),
                BackgroundTransparency = 1,
                Text = d[1],
                Font = Enum.Font.GothamMedium,
                TextSize = 12,
                TextColor3 = P.sub,
                TextXAlignment = Enum.TextXAlignment.Left,
                TextTruncate = Enum.TextTruncate.AtEnd,
            }, r)
            local val = new("TextLabel", {
                AnchorPoint = Vector2.new(1, 0),
                Position = UDim2.new(1, 0, 0, 0),
                Size = UDim2.new(0.6, 0, 1, 0),
                BackgroundTransparency = 1,
                Text = tostring(d[2] or "-"),
                Font = Enum.Font.GothamBold,
                TextSize = 12,
                TextColor3 = P.text,
                TextXAlignment = Enum.TextXAlignment.Right,
                TextTruncate = Enum.TextTruncate.AtEnd,
            }, r)
            if i < #rows then
                new("Frame", {
                    AnchorPoint = Vector2.new(0, 1),
                    Position = UDim2.new(0, 0, 1, 0),
                    Size = UDim2.new(1, 0, 0, 1),
                    BackgroundColor3 = P.stroke,
                    BackgroundTransparency = 0.5,
                    BorderSizePixel = 0,
                }, r)
            end
            local shown = tostring(d[2] or "-")
            if d.key then
                live[d.key] = function(text, color)
                    shown = tostring(text)
                    val.Text = shown
                    val.TextColor3 = color or P.text
                end
            end
            if d.copy then
                local token = 0
                r.MouseButton1Click:Connect(function()
                    local ok = copyText(d.copy)
                    token += 1
                    local my = token
                    val.Text = ok and "Disalin!" or "Gagal salin"
                    task.delay(1, function()
                        if my == token and val.Parent then
                            val.Text = shown
                        end
                    end)
                end)
            end
        end
        return c
    end

    local function statusColor(kind, n)
        if kind == "fps" then
            return n >= 55 and P.green or (n >= 35 and P.amber or P.red)
        end
        if n <= 50 then
            return P.green
        elseif n <= 100 then
            return P.amber
        elseif n <= 180 then
            return P.orange
        end
        return P.red
    end

    -- ---------------- PEMAIN ----------------
    local userId = LP and LP.UserId or 0
    local avatarUrl = "rbxthumb://type=AvatarHeadShot&id=" .. tostring(userId) .. "&w=150&h=150"
    local isPremium = LP and LP.MembershipType == Enum.MembershipType.Premium
    hero(
        avatarUrl,
        true,
        LP and LP.DisplayName or "Player",
        "@" .. (LP and LP.Name or "player"),
        isPremium and "Roblox Premium" or "Akun Standar"
    )

    -- strip statistik live
    local strip = new("Frame", {
        Size = UDim2.new(1, 0, 0, 54),
        BackgroundTransparency = 1,
        LayoutOrder = nextOrder(),
    }, page)
    new("UIGridLayout", {
        CellSize = UDim2.new(0.25, -6, 1, 0),
        CellPadding = UDim2.fromOffset(8, 0),
        SortOrder = Enum.SortOrder.LayoutOrder,
    }, strip)
    local function tile(caption, ord)
        local t = new("Frame", {
            BackgroundColor3 = P.panel2,
            BorderSizePixel = 0,
            LayoutOrder = ord,
        }, strip)
        round(t, 10)
        stroke(t, P.stroke, 1, 0.15)
        local num = new("TextLabel", {
            Position = UDim2.fromOffset(0, 7),
            Size = UDim2.new(1, 0, 0, 22),
            BackgroundTransparency = 1,
            Text = "--",
            Font = Enum.Font.GothamBlack,
            TextSize = 17,
            TextColor3 = P.text,
        }, t)
        new("TextLabel", {
            Position = UDim2.fromOffset(0, 31),
            Size = UDim2.new(1, 0, 0, 14),
            BackgroundTransparency = 1,
            Text = caption,
            Font = Enum.Font.GothamMedium,
            TextSize = 10,
            TextColor3 = P.sub,
        }, t)
        return num
    end
    local fpsNum = tile("FPS", 1)
    local msNum = tile("MS", 2)
    local memNum = tile("MEMORI", 3)
    local plrNum = tile("PEMAIN", 4)

    section("Pemain")
    local ageDays = LP and LP.AccountAge or 0
    rowsCard({
        { "User ID", tostring(userId), copy = tostring(userId) },
        { "Umur akun", string.format("%d hari (%.1f tahun)", ageDays, ageDays / 365) },
        { "Membership", isPremium and "Premium" or "Standar" },
        { "Region", "memuat...", key = "region" },
        { "Bahasa / locale", LP and LP.LocaleId or "-" },
    })

    -- ---------------- MAP ----------------
    local placeId = game.PlaceId
    local universeId = game.GameId
    local mapImg, mapTitle, mapSub = hero(
        "rbxthumb://type=GameIcon&id=" .. tostring(universeId) .. "&w=150&h=150",
        false,
        game.Name ~= "" and game.Name or "Map",
        "memuat info map...",
        "Place ID " .. tostring(placeId)
    )
    -- huruf awal sebagai cadangan visual (hilang otomatis kalau gambar sudah termuat)
    local mapInitial = new("TextLabel", {
        Size = UDim2.fromScale(1, 1),
        BackgroundTransparency = 1,
        Text = string.upper(string.sub(game.Name ~= "" and game.Name or "M", 1, 1)),
        Font = Enum.Font.GothamBlack,
        TextSize = 24,
        TextColor3 = P.sub,
        ZIndex = 2,
    }, mapImg)
    -- coba beberapa sumber icon berurutan sampai ada yang benar-benar termuat:
    -- 1) GameIcon Universe ID  2) GameIcon Place ID  3) IconImageAssetId (GetProductInfo)
    -- 4) Thumbnails API -> unduh -> getcustomasset (executor yang mendukung)
    task.spawn(function()
        local HttpService = game:GetService("HttpService")
        local function tryImage(url, wait)
            if not (mapImg and mapImg.Parent) then
                return true
            end
            mapImg.Image = url
            local t0 = os.clock()
            while os.clock() - t0 < (wait or 4) do
                if not (mapImg and mapImg.Parent) then
                    return true
                end
                if mapImg.IsLoaded then
                    return true
                end
                task.wait(0.25)
            end
            return mapImg.IsLoaded
        end
        local function done()
            if mapInitial and mapInitial.Parent then
                mapInitial.Visible = false
            end
        end

        if tryImage("rbxthumb://type=GameIcon&id=" .. tostring(universeId) .. "&w=150&h=150", 5) then
            return done()
        end
        if tryImage("rbxthumb://type=GameIcon&id=" .. tostring(placeId) .. "&w=150&h=150", 5) then
            return done()
        end

        local okInfo, info = pcall(function()
            return MarketplaceService:GetProductInfo(placeId)
        end)
        if okInfo and type(info) == "table" then
            local assetId = tonumber(info.IconImageAssetId)
            if assetId and assetId > 0 and tryImage("rbxassetid://" .. tostring(assetId), 6) then
                return done()
            end
        end

        local req = (typeof(request) == "function" and request)
            or (typeof(http_request) == "function" and http_request)
            or (syn and syn.request)
            or (http and http.request)
        if req and typeof(writefile) == "function" and typeof(getcustomasset) == "function" then
            local okApi, res = pcall(req, {
                Url = "https://thumbnails.roblox.com/v1/games/icons?universeIds=" .. tostring(universeId)
                    .. "&returnPolicy=PlaceHolder&size=150x150&format=Png&isCircular=false",
                Method = "GET",
            })
            if okApi and res and res.Body then
                local okJson, data = pcall(HttpService.JSONDecode, HttpService, res.Body)
                local imgUrl = okJson and data and data.data and data.data[1] and data.data[1].imageUrl
                if imgUrl then
                    local okImg, imgRes = pcall(req, { Url = imgUrl, Method = "GET" })
                    if okImg and imgRes and imgRes.Body and #imgRes.Body > 0 then
                        local fileName = "fankun_mapicon_" .. tostring(universeId) .. ".png"
                        local okW = pcall(writefile, fileName, imgRes.Body)
                        if okW then
                            local okA, asset = pcall(getcustomasset, fileName)
                            if okA and asset and tryImage(asset, 5) then
                                return done()
                            end
                        end
                    end
                end
            end
        end
        -- semua gagal: tetap tampil huruf awal (tidak pernah kotak kosong)
    end)
    task.spawn(function()
        local ok, info = pcall(function()
            return MarketplaceService:GetProductInfo(placeId)
        end)
        if ok and type(info) == "table" and mapTitle.Parent then
            mapTitle.Text = tostring(info.Name or mapTitle.Text)
            local creator = type(info.Creator) == "table" and info.Creator.Name or nil
            mapSub.Text = creator and ("oleh " .. tostring(creator)) or "info map dimuat"
        elseif mapSub.Parent then
            mapSub.Text = "info map tidak tersedia"
        end
    end)

    section("Map & Server")
    local jobId = tostring(game.JobId or "")
    local jobShown = jobId == "" and "Studio / lokal" or (jobId:sub(1, 8) .. "...")
    rowsCard({
        { "Place ID", tostring(placeId), copy = tostring(placeId) },
        { "Universe ID", tostring(universeId), copy = tostring(universeId) },
        { "Server ID", jobShown, copy = jobId ~= "" and jobId or nil },
        { "Tipe server", (game.PrivateServerId ~= "" and "Private") or "Publik" },
        { "Versi place", tostring(game.PlaceVersion) },
        { "Pemain", "-", key = "players" },
        { "Server uptime", "-", key = "uptime" },
    })
    note("Ketuk Place ID, Universe ID, atau Server ID untuk menyalin.")

    -- ---------------- PERANGKAT ----------------
    section("Perangkat")
    rowsCard({
        { "Executor", executorName() },
        { "Platform", platformName() },
        { "Resolusi", resolutionText() },
        { "Kualitas grafis", qualityText() },
        { "Waktu lokal", "-", key = "clock" },
        { "Sesi script", "-", key = "session" },
    })

    -- region pemain (negara) - diambil asinkron
    task.spawn(function()
        local ok, code = pcall(function()
            return LocalizationService:GetCountryRegionForPlayerAsync(LP)
        end)
        if live.region then
            if ok and type(code) == "string" and code ~= "" then
                local name = COUNTRY[code]
                live.region(name and (name .. " (" .. code .. ")") or code)
            else
                live.region("Tidak diketahui")
            end
        end
    end)

    -- ---------------- update live tiap 1 detik ----------------
    local frames = 0
    local conn = RunService.RenderStepped:Connect(function()
        frames += 1
    end)
    task.spawn(function()
        local last = os.clock()
        while page and page.Parent do
            task.wait(1)
            local now = os.clock()
            local fps = math.floor(frames / math.max(now - last, 0.001) + 0.5)
            frames = 0
            last = now

            pcall(function()
                fpsNum.Text = tostring(fps)
                fpsNum.TextColor3 = statusColor("fps", fps)

                local okP, ping = pcall(function()
                    return math.floor(Stats.Network.ServerStatsItem["Data Ping"]:GetValue() + 0.5)
                end)
                if okP and ping then
                    msNum.Text = tostring(ping)
                    msNum.TextColor3 = statusColor("ping", ping)
                end

                local okM, mem = pcall(function()
                    return math.floor(Stats:GetTotalMemoryUsageMb() + 0.5)
                end)
                if okM and mem then
                    memNum.Text = mem .. " MB"
                end

                local count = #Players:GetPlayers()
                plrNum.Text = tostring(count)
                if live.players then
                    live.players(count .. " / " .. tostring(Players.MaxPlayers))
                end
                if live.uptime then
                    live.uptime(fmtDur(workspace.DistributedGameTime))
                end
                if live.clock then
                    live.clock(os.date("%d %b %Y  %H:%M:%S"))
                end
                if live.session then
                    live.session(fmtDur(os.clock() - startClock))
                end
            end)
        end
        pcall(function()
            conn:Disconnect()
        end)
    end)

    -- buka tab Informasi saat script dieksekusi
    pcall(function()
        v2:_selectTab(tab)
    end)
end, function(e)
    warn("[FanKun] Tab Informasi gagal dimuat: " .. tostring(e))
end)

-- ============================================================
-- FanKun STEAL PANEL (matches main hub UI) + toggle
-- ============================================================
do
    local TweenService = game:GetService("TweenService")
    local panelOpen = false
    local panelGui = nil
    local listFrame = nil
    local statusLbl = nil
    local refreshToken = 0
    local eggCache = {}

    local function hui()
        if typeof(gethui) == "function" then
            local ok, r = pcall(gethui)
            if ok and typeof(r) == "Instance" then return r end
        end
        return game:GetService("CoreGui")
    end

    local function corner(o, r)
        local c = Instance.new("UICorner")
        c.CornerRadius = UDim.new(0, r or 8)
        c.Parent = o
        return c
    end
    local function stroke(o, col)
        local s = Instance.new("UIStroke")
        s.Color = col or Color3.fromRGB(205, 205, 205)
        s.Thickness = 1
        s.Transparency = 0.15
        s.Parent = o
        return s
    end

    local function formatValue(v)
        v = tonumber(v) or 0
        if v >= 1e12 then return string.format("$%.2fT/s", v / 1e12) end
        if v >= 1e9 then return string.format("$%.2fB/s", v / 1e9) end
        if v >= 1e6 then return string.format("$%.2fM/s", v / 1e6) end
        if v >= 1e3 then return string.format("$%.2fK/s", v / 1e3) end
        if v > 0 and v < 1 then return string.format("$%.2f/s", v) end
        return string.format("$%.0f/s", v)
    end

    local function assetEntry(cat)
        cat = tostring(cat or "")
        local directory = tbl and tbl.Assets and tbl.Assets.Directory
        if type(directory) ~= "table" then return nil end
        local a = directory[cat]
        if type(a) == "table" then return a end
        -- case-insensitive fallback
        local lower = string.lower(cat)
        for k, v in pairs(directory) do
            if type(k) == "string" and string.lower(k) == lower and type(v) == "table" then
                return v
            end
        end
        return nil
    end

    local function readEggs()
        local records = nil
        local eggState = tbl and tbl.EggState
        if type(eggState) == "table" and type(eggState.ReadFieldEggs) == "function" then
            local ok, result = pcall(eggState.ReadFieldEggs)
            if ok and type(result) == "table" then
                if type(result.Records) == "table" then
                    records = result.Records
                elseif next(result) ~= nil then
                    records = result
                end
            end
        end
        if not records or next(records) == nil then
            local rf = networking and networking:FindFirstChild("RF/EggWorld/AskFieldEggSnapshot")
            if rf and rf:IsA("RemoteFunction") then
                local ok, result = pcall(rf.InvokeServer, rf)
                if ok and type(result) == "table" then
                    if type(result.Records) == "table" then
                        records = result.Records
                    elseif next(result) ~= nil then
                        records = result
                    end
                end
            end
        end
        return records
    end

    -- Same formula as hub EggIncome / original steal panel fn34
    local function eggValue(rec)
        if type(rec) ~= "table" then return 0 end
        if type(tbl4.EggIncome) == "function" then
            local ok, v = pcall(tbl4.EggIncome, rec)
            if ok and type(v) == "number" and v > 0 then return v end
        end
        local entry = assetEntry(rec.AssetCategory)
        local rate = type(entry) == "table" and tonumber(entry.EarningRate) or 0
        local scale = tonumber(rec.AssetScale) or tonumber(rec.Scale) or 0
        if rate <= 0 or scale <= 0 then
            local direct = tonumber(rec.Value) or tonumber(rec.Rate) or tonumber(rec.CashPerSecond) or 0
            return direct
        end
        local scaled = scale > 5 and (scale / 5) ^ 1.2 * 19.637875755794113 or scale ^ 1.85
        local mult = 1
        local mutations = type(rec.Mutations) == "table" and rec.Mutations or {}
        if #mutations == 0 and type(rec.BaseMutation) == "string" and rec.BaseMutation ~= "" then
            mutations = { rec.BaseMutation }
        end
        local mutMod = tbl and tbl.Mutations
        if type(mutMod) == "table" and type(mutMod.EarningsFor) == "function" then
            local ok, m = pcall(mutMod.EarningsFor, mutations)
            if ok and type(m) == "number" and m > 0 then mult = m end
        end
        return rate * scaled * mult
    end

    local function eggWeight(rec)
        if type(rec) ~= "table" then return 0 end
        local cat = rec.AssetCategory
        local scale = tonumber(rec.AssetScale) or tonumber(rec.Scale) or 0
        local eggRecords = tbl and tbl.EggRecords
        if type(eggRecords) == "table" and type(eggRecords.WeightKgForScale) == "function" then
            local ok, w = pcall(eggRecords.WeightKgForScale, cat, scale)
            if ok and type(w) == "number" and w > 0 then return w end
        end
        -- fallback approximations
        local w = tonumber(rec.Weight) or tonumber(rec.WeightKg) or tonumber(rec.Kg)
        if w and w > 0 then return w end
        if scale > 0 then
            -- rough visual scale → kg proxy used by many egg games
            return math.max(0.01, scale * 0.35)
        end
        return 0
    end

    local function eggIcon(rec)
        if type(rec) ~= "table" then return "" end
        local entry = assetEntry(rec.AssetCategory)
        if type(entry) ~= "table" then return "" end
        local icon = entry.Icon or entry.Image or entry.Thumbnail or entry.ImageId
        if icon == nil or icon == "" then return "" end
        if type(icon) == "number" or (type(icon) == "string" and tonumber(icon)) then
            return "rbxassetid://" .. tostring(icon)
        end
        local s = tostring(icon)
        if string.find(s, "rbxasset", 1, true) then return s end
        if tonumber(s) then return "rbxassetid://" .. s end
        return s
    end

    local function eggName(rec)
        if type(rec) ~= "table" then return "?" end
        local cat = rec.AssetCategory or rec.Name or rec.Id or "Egg"
        local entry = assetEntry(cat)
        if type(entry) == "table" then
            return tostring(entry.DisplayName or entry.Name or cat)
        end
        return tostring(cat)
    end

    local function eggRarity(rec)
        if type(rec) ~= "table" then return "Common" end
        local entry = assetEntry(rec.AssetCategory)
        if type(entry) == "table" and type(entry.Rarity) == "table" then
            return tostring(entry.Rarity.DisplayName or entry.Rarity._id or "Common")
        end
        return tostring(rec.Rarity or "Common")
    end

    local function eggRarityNumber(rec)
        if type(rec) ~= "table" then return 0 end
        local entry = assetEntry(rec.AssetCategory)
        local name, num = nil, 0
        if type(entry) == "table" and type(entry.Rarity) == "table" then
            name = entry.Rarity.DisplayName or entry.Rarity._id
            num = tonumber(entry.Rarity.RarityNumber or entry.Rarity.Rank) or 0
        else
            name = rec.Rarity
            num = tonumber(rec.RarityNumber or rec.Rank) or 0
        end
        -- Same RarityOrder as SAG: Cosmic=7 > Mythic=6, Eternal=10 highest
        local key = tostring(name or ""):gsub("%s+", ""):lower()
        local order = {
            common = 1, uncommon = 2, rare = 3, epic = 4, legendary = 5,
            mythic = 6, cosmic = 7, secret = 8, divine = 9, eternal = 10, ethernal = 10,
        }
        if order[key] then return order[key] end
        for k, score in pairs(order) do
            if key ~= "" and string.find(key, k, 1, true) then return score end
        end
        return num
    end

    -- ============================================================
    -- STEAL PANEL v2 (desain baru + ikut berubah saat filter Auto Steal diganti)
    -- ============================================================
    local C = {
        bg = Color3.fromRGB(255, 255, 255), -- sama dengan UI utama
        head = Color3.fromRGB(242, 242, 242),
        card = Color3.fromRGB(247, 247, 247),
        row = Color3.fromRGB(255, 255, 255),
        line = Color3.fromRGB(205, 205, 205),
        text = Color3.fromRGB(12, 12, 12),
        muted = Color3.fromRGB(100, 100, 100),
        accent = Color3.fromRGB(14, 14, 14),
        accentBg = Color3.fromRGB(14, 14, 14), -- tab / tombol aktif (hitam)
        onAccent = Color3.fromRGB(255, 255, 255), -- teks di atas accentBg
        good = Color3.fromRGB(30, 150, 90),
        danger = Color3.fromRGB(210, 50, 50),
        btn = Color3.fromRGB(230, 230, 230),
    }
    local RARITY_COLORS = {
        common = Color3.fromRGB(110, 110, 120),
        uncommon = Color3.fromRGB(30, 150, 70),
        rare = Color3.fromRGB(30, 100, 220),
        epic = Color3.fromRGB(140, 60, 220),
        legendary = Color3.fromRGB(220, 120, 0),
        mythic = Color3.fromRGB(210, 40, 70),
        cosmic = Color3.fromRGB(0, 150, 160),
        secret = Color3.fromRGB(60, 60, 80),
        divine = Color3.fromRGB(180, 140, 0),
        eternal = Color3.fromRGB(0, 150, 100),
        ethernal = Color3.fromRGB(0, 150, 100),
    }

    local R = {}
    local destroyConns = {}
    local mode = "all"
    local lastFilterSig = nil
    local lastItemsSig = nil
    local setPanelVisible

    local function toHex(c)
        return string.format("#%02X%02X%02X", math.floor(c.R * 255 + 0.5), math.floor(c.G * 255 + 0.5), math.floor(c.B * 255 + 0.5))
    end

    local function rarityColor(name)
        local key = tostring(name or ""):gsub("%s+", ""):lower()
        return RARITY_COLORS[key] or C.muted
    end

    local function mk(class, props, parent)
        local o = Instance.new(class)
        for k, v in pairs(props) do
            o[k] = v
        end
        if parent then
            o.Parent = parent
        end
        return o
    end

    -- ---------- filter Auto Steal (dibaca live dari SAE) ----------
    local function readFilters()
        local getter = tbl4.StealFilters
        if type(getter) ~= "function" then
            return nil
        end
        local ok, f = pcall(getter)
        if ok and type(f) == "table" then
            return f
        end
        return nil
    end

    local function setKeys(t)
        local keys = {}
        if type(t) == "table" then
            for k, v in pairs(t) do
                if v == true and type(k) == "string" then
                    keys[#keys + 1] = k
                end
            end
        end
        table.sort(keys)
        return keys
    end

    local function filterSig(f)
        if not f then
            return "nofilter"
        end
        return table.concat({
            table.concat(f.RarityNames or {}, ","),
            tostring(tonumber(f.MinValue) or 0),
            table.concat(setKeys(f.Areas), ","),
            table.concat(setKeys(f.Eggs), ","),
        }, "|")
    end

    local function filterRarity(rec)
        local entry = assetEntry(rec.AssetCategory)
        if type(entry) == "table" and type(entry.Rarity) == "table" then
            return tonumber(entry.Rarity.RarityNumber or entry.Rarity.Rank) or 0
        end
        return 0
    end

    -- rumus sama persis dengan yang dipakai Auto Steal (biar angka di panel = angka filter)
    local function stealValue(rec)
        local entry = assetEntry(rec.AssetCategory)
        local rate = type(entry) == "table" and tonumber(entry.EarningRate) or 0
        local scale = tonumber(rec.AssetScale) or 1
        local scaled = scale > 5 and (scale / 5) ^ 1.2 * 19.637875755794113 or scale ^ 1.85
        local mult = 1
        local mutMod = tbl and tbl.Mutations
        if type(mutMod) == "table" and type(mutMod.EarningsFor) == "function" then
            local ok, m = pcall(mutMod.EarningsFor, type(rec.Mutations) == "table" and rec.Mutations or {})
            if ok and type(m) == "number" then
                mult = m
            end
        end
        local v = rate * scaled * mult
        if v <= 0 then
            v = eggValue(rec)
        end
        return v
    end

    local function matchesFilters(it, f)
        if not f then
            return true
        end
        local rarSel = type(f.Rarities) == "table" and next(f.Rarities) ~= nil
        if rarSel and f.Rarities[it.FilterRarity or 0] ~= true then
            return false
        end
        local minV = tonumber(f.MinValue) or 0
        if minV > 0 and (it.Value or 0) < minV then
            return false
        end
        if type(f.Eggs) == "table" and next(f.Eggs) ~= nil and f.Eggs[it.Category] ~= true then
            return false
        end
        local areaSel = type(f.Areas) == "table" and next(f.Areas) ~= nil
        if areaSel then
            if f.Areas[it.AreaId] ~= true then
                return false -- area dipilih = hanya egg di area itu
            end
        elseif not rarSel then
            return false -- tanpa area & tanpa rarity = belum ada target (sama dengan Auto Steal)
        end
        return true
    end

    local function collectItems(f)
        local records = readEggs()
        local items = {}
        R.filtersEmpty = (not f)
            or (#(f.RarityNames or {}) == 0
                and (tonumber(f.MinValue) or 0) == 0
                and #setKeys(f.Areas) == 0
                and #setKeys(f.Eggs) == 0)
        if type(records) ~= "table" then
            return items
        end
        for _, rec in pairs(records) do
            if type(rec) == "table" then
                local st = rec.State
                if st == "Slot" or st == "Dropped" or st == "Carried" or st == nil then
                    local uid = rec.Uid or rec.UID or rec.Id
                    if uid then
                        local it = {
                            Uid = tostring(uid),
                            Category = tostring(rec.AssetCategory),
                            AreaId = tostring(rec.AreaId),
                            Name = eggName(rec),
                            Rarity = eggRarity(rec),
                            RarityNumber = eggRarityNumber(rec),
                            FilterRarity = filterRarity(rec),
                            Value = stealValue(rec),
                            Weight = eggWeight(rec),
                            Icon = eggIcon(rec),
                            State = tostring(st or "?"),
                            CFrame = typeof(rec.BottomCFrame) == "CFrame" and rec.BottomCFrame or nil,
                        }
                        it.Match = matchesFilters(it, f)
                        items[#items + 1] = it
                    end
                end
            end
        end
        table.sort(items, function(a, b)
            -- rarity tertinggi selalu paling atas, lalu yang cocok filter, lalu value terbesar
            if a.RarityNumber ~= b.RarityNumber then
                return a.RarityNumber > b.RarityNumber
            end
            if a.Match ~= b.Match then
                return a.Match
            end
            if a.Value ~= b.Value then
                return a.Value > b.Value
            end
            if a.Name ~= b.Name then
                return a.Name < b.Name
            end
            return a.Uid < b.Uid
        end)
        return items
    end

    -- ---------- update bagian atas panel ----------
    local function updateFilterBar(f)
        if not R.chipRarity then
            return
        end
        local acc = toHex(C.accent)
        local function hl(s)
            return string.format('<font color="%s"><b>%s</b></font>', acc, tostring(s))
        end
        if not f then
            R.chipRarity.Text = "Rarity  " .. hl("-")
            R.chipValue.Text = "Min value  " .. hl("-")
            R.chipAreas.Text = "Areas  " .. hl("-")
            R.chipEggs.Text = "Eggs  " .. hl("-")
            return
        end
        local rarityTxt = "None"
        local rn = f.RarityNames or {}
        if #rn > 0 then
            rarityTxt = table.concat({ rn[#rn], rn[#rn - 1] }, ", ")
            if #rn == 1 then
                rarityTxt = rn[1]
            elseif #rn > 2 then
                rarityTxt = rarityTxt .. " +" .. (#rn - 2)
            end
        end
        local minV = tonumber(f.MinValue) or 0
        local valueTxt = minV > 0 and ("≥ " .. formatValue(minV)) or "Off"
        local areaKeys = setKeys(f.Areas)
        local areaTotal = tonumber(f.AreaTotal) or #areaKeys
        local eggKeys = setKeys(f.Eggs)
        local eggTxt = #eggKeys == 0 and "None" or (#eggKeys .. " picked")
        R.chipRarity.Text = "Rarity  " .. hl(rarityTxt)
        R.chipValue.Text = "Min value  " .. hl(valueTxt)
        R.chipAreas.Text = "Areas  " .. hl(#areaKeys == 0 and "None" or (#areaKeys .. "/" .. areaTotal))
        R.chipEggs.Text = "Eggs  " .. hl(eggTxt)
    end

    local function updateStatusPill()
        if not R.pill then
            return
        end
        local st = type(tbl4.Steal) == "table" and tbl4.Steal or {}
        local txt, col = "IDLE", C.muted
        if st.Carrying then
            txt, col = "CARRYING", C.accent
        elseif st.Active then
            txt, col = "STEALING", C.good
        end
        if R.pill.Text ~= txt then
            R.pill.Text = txt
            R.pill.TextColor3 = col
        end
    end

    local function styleTabs()
        if not R.tabTargets then
            return
        end
        local function apply(btn, active)
            btn.BackgroundColor3 = active and C.accentBg or C.btn
            btn.TextColor3 = active and C.onAccent or C.muted
        end
        apply(R.tabTargets, mode == "targets")
        apply(R.tabAll, mode == "all")
    end

    local function destroyPanel()
        for _, c in ipairs(destroyConns) do
            pcall(function()
                c:Disconnect()
            end)
        end
        table.clear(destroyConns)
        if panelGui then
            pcall(function()
                panelGui:Destroy()
            end)
        end
        panelGui = nil
        listFrame = nil
        statusLbl = nil
        R = {}
        panelOpen = false
        refreshToken = refreshToken + 1
    end

    -- ---------- daftar egg ----------
    local function makeRow(it, order)
        local lit = it.Match or R.filtersEmpty == true
        local dim = not lit
        local row = mk("Frame", {
            Size = UDim2.new(1, -4, 0, 40),
            BackgroundColor3 = C.row,
            BorderSizePixel = 0,
            LayoutOrder = order,
        }, listFrame)
        corner(row, 7)
        stroke(row, C.line).Transparency = 0.35

        if lit then
            local bar = mk("Frame", {
                Size = UDim2.new(0, 2, 1, -12),
                Position = UDim2.fromOffset(0, 6),
                BackgroundColor3 = C.accent,
                BorderSizePixel = 0,
            }, row)
            corner(bar, 2)
        end

        local iconBg = mk("Frame", {
            Size = UDim2.fromOffset(30, 30),
            Position = UDim2.fromOffset(7, 5),
            BackgroundColor3 = Color3.fromRGB(242, 242, 242),
            BorderSizePixel = 0,
        }, row)
        corner(iconBg, 7)
        mk("ImageLabel", {
            Size = UDim2.fromScale(1, 1),
            BackgroundTransparency = 1,
            ScaleType = Enum.ScaleType.Fit,
            Image = it.Icon or "",
            ImageTransparency = dim and 0.5 or 0,
        }, iconBg)

        mk("TextLabel", {
            Size = UDim2.new(1, -100, 0, 12),
            Position = UDim2.fromOffset(43, 3),
            BackgroundTransparency = 1,
            Font = Enum.Font.GothamBold,
            TextSize = 10,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextColor3 = C.text,
            TextTransparency = dim and 0.45 or 0,
            TextTruncate = Enum.TextTruncate.AtEnd,
            Text = it.Name,
        }, row)

        local kg = tonumber(it.Weight) or 0
        local kgText = kg >= 10 and string.format("%.1f kg", kg) or string.format("%.2f kg", kg)
        mk("TextLabel", {
            Size = UDim2.new(1, -100, 0, 11),
            Position = UDim2.fromOffset(43, 16),
            BackgroundTransparency = 1,
            Font = Enum.Font.Gotham,
            TextSize = 9,
            RichText = true,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextColor3 = C.muted,
            TextTransparency = dim and 0.35 or 0,
            Text = string.format('<font color="%s">%s</font>  ·  %s', toHex(rarityColor(it.Rarity)), it.Rarity, kgText),
        }, row)

        mk("TextLabel", {
            Size = UDim2.new(1, -100, 0, 11),
            Position = UDim2.fromOffset(43, 27),
            BackgroundTransparency = 1,
            Font = Enum.Font.GothamBold,
            TextSize = 9,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextColor3 = C.good,
            TextTransparency = dim and 0.45 or 0,
            Text = formatValue(it.Value) .. (it.State == "Carried" and "  ·  carried" or ""),
        }, row)

        local btn = mk("TextButton", {
            Size = UDim2.fromOffset(46, 22),
            Position = UDim2.new(1, -52, 0.5, -11),
            BackgroundColor3 = lit and C.accentBg or C.btn,
            Text = "STEAL",
            TextColor3 = lit and C.onAccent or C.muted,
            Font = Enum.Font.GothamBold,
            TextSize = 9,
            BorderSizePixel = 0,
            AutoButtonColor = true,
        }, row)
        corner(btn, 6)
        stroke(btn, lit and C.accent or C.line).Transparency = lit and 0.55 or 0.3

        btn.MouseButton1Click:Connect(function()
            task.spawn(function()
                -- [FIX PANEL v2] Klik STEAL di panel = steal SEKALI untuk egg itu saja.
                -- Auto Steal utama dinyalakan sementara (mesin steal-nya dibutuhkan), lalu
                -- otomatis dimatikan lagi begitu egg dari panel selesai / gagal.
                -- Kalau Auto Steal utama memang sudah ON dari awal, tidak disentuh.
                local ps = tbl4.PanelSteal
                if not ps then
                    ps = { pending = {}, count = 0, weTurnedOn = false, watching = false }
                    tbl4.PanelSteal = ps

                    local function mainHandle()
                        local h = tbl4.AutoStealHandle
                        return type(h) == "table" and h or nil
                    end

                    local function finishPanelSteal()
                        ps.pending = {}
                        ps.count = 0
                        ps.watching = false
                        if ps.weTurnedOn and not ps.finishing then
                            ps.finishing = true
                            task.spawn(function()
                                -- tunggu sampai egg benar-benar sampai (tidak carrying & tidak aktif)
                                -- baru Auto Steal dimatikan, supaya bawaan egg tidak terputus di tengah jalan
                                local t0 = os.clock()
                                local calm = 0
                                while os.clock() - t0 < 90 do
                                    if ps.count > 0 then
                                        break -- ada antrean baru dari panel, jangan dimatikan
                                    end
                                    local st = tbl4.Steal
                                    if st and (st.Active or st.Carrying) then
                                        calm = 0
                                    else
                                        calm = calm + 0.25
                                    end
                                    if calm >= 1.5 then
                                        break
                                    end
                                    task.wait(0.25)
                                end
                                ps.finishing = false
                                if ps.count > 0 then
                                    return
                                end
                                if ps.weTurnedOn then
                                    ps.weTurnedOn = false
                                    local h = mainHandle()
                                    if h then
                                        pcall(h.Set, h, false)
                                    end
                                end
                            end)
                        end
                    end

                    -- dipanggil worker Auto Steal saat egg antrean (Once) selesai
                    tbl4.OnceStealDone = function(uid)
                        if ps.pending[uid] then
                            ps.pending[uid] = nil
                            ps.count = math.max(0, ps.count - 1)
                        end
                        if ps.count <= 0 then
                            finishPanelSteal()
                        end
                    end

                    -- cadangan: kalau egg hilang (dicuri orang lain) hook di atas tidak terpanggil
                    ps.startWatch = function()
                        if ps.watching then return end
                        ps.watching = true
                        task.spawn(function()
                            local idle = 0
                            while ps.watching do
                                task.wait(0.5)
                                local st = tbl4.Steal
                                if st and (st.Active or st.Carrying) then
                                    idle = 0
                                else
                                    idle = idle + 1
                                end
                                if idle >= 12 then -- 6 detik tanpa aktivitas steal
                                    finishPanelSteal()
                                    break
                                end
                            end
                        end)
                    end
                end

                local handle = tbl4.AutoStealHandle
                if type(handle) == "table" then
                    local isOn = false
                    pcall(function()
                        isOn = handle:GetValue() == true
                    end)
                    if not isOn then
                        ps.weTurnedOn = true
                        pcall(handle.Set, handle, true)
                        task.wait(0.2) -- beri waktu callback Auto Steal selesai dulu
                    end
                end
                if not ps.pending[it.Uid] then
                    ps.pending[it.Uid] = true
                    ps.count = ps.count + 1
                end
                if ps.weTurnedOn then
                    ps.startWatch()
                end
                if type(tbl4.StealNowManual) == "function" then
                    pcall(tbl4.StealNowManual, it.Uid)
                elseif type(tbl4.StealNow) == "function" then
                    pcall(tbl4.StealNow, it.Uid, true)
                elseif type(tbl4.PrioritizeSteal) == "function" then
                    pcall(tbl4.PrioritizeSteal, it.Uid)
                end
            end)
            if statusLbl then
                statusLbl.Text = "Queue → " .. it.Name
            end
            btn.Text = "QUEUED"
            task.delay(1.2, function()
                if btn and btn.Parent then
                    btn.Text = "STEAL"
                end
            end)
        end)
    end

    local function rebuildList(force)
        if not listFrame or not listFrame.Parent then
            return
        end
        local f = readFilters()
        local items = collectItems(f)
        local shown, matchCount = {}, 0
        for _, it in ipairs(items) do
            if it.Match then
                matchCount = matchCount + 1
            end
            if mode == "all" or it.Match then
                shown[#shown + 1] = it
            end
        end

        if R.tabTargets then
            R.tabTargets.Text = "TARGETS · " .. matchCount
            R.tabAll.Text = "ALL · " .. #items
        end
        if statusLbl then
            statusLbl.Text = R.filtersEmpty == true and (#items .. " egg di map")
                or (matchCount .. " target cocok  /  " .. #items .. " egg di map")
        end

        local parts = { mode }
        for i, it in ipairs(shown) do
            if i > 50 then
                break
            end
            parts[#parts + 1] = it.Uid .. (it.Match and "+" or "-") .. math.floor(it.Value)
        end
        local sig = table.concat(parts, ",")
        if not force and sig == lastItemsSig then
            return
        end
        lastItemsSig = sig

        local savedPos = listFrame.CanvasPosition
        for _, ch in ipairs(listFrame:GetChildren()) do
            if not ch:IsA("UIListLayout") and not ch:IsA("UIPadding") then
                ch:Destroy()
            end
        end

        if #shown == 0 then
            local empty = mk("Frame", {
                Size = UDim2.new(1, -4, 0, 56),
                BackgroundTransparency = 1,
                LayoutOrder = 1,
            }, listFrame)
            mk("TextLabel", {
                Size = UDim2.fromScale(1, 1),
                BackgroundTransparency = 1,
                Font = Enum.Font.Gotham,
                TextSize = 10,
                TextWrapped = true,
                TextColor3 = C.muted,
                Text = mode == "targets" and "Tidak ada egg yang cocok dengan filter Auto Steal saat ini.\nUbah filter atau buka tab ALL." or "Belum ada egg di map.",
            }, empty)
        else
            for i, it in ipairs(shown) do
                if i > 50 then
                    break
                end
                makeRow(it, i)
            end
        end

        task.defer(function()
            if listFrame and listFrame.Parent then
                listFrame.CanvasPosition = savedPos
            end
        end)
    end

    -- ---------- bangun panel ----------
    local function createPanel()
        destroyPanel()
        local sg = mk("ScreenGui", {
            Name = "FanKunHub_StealPanel",
            ResetOnSpawn = false,
            IgnoreGuiInset = true,
            DisplayOrder = 1000,
            ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
        })
        sg.Parent = hui()
        panelGui = sg

        local main = mk("Frame", {
            Size = UDim2.fromOffset(236, 318),
            Position = UDim2.new(1, -252, 0.5, -159),
            BackgroundColor3 = C.bg,
            BorderSizePixel = 0,
            Active = true,
        }, sg)
        corner(main, 12)
        do
            local ms = stroke(main, Color3.fromRGB(150, 150, 150))
            ms.Thickness = 1.5
            ms.Transparency = 0.25
        end
        local touchOnly = UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled
        if touchOnly then
            mk("UIScale", { Scale = 0.85 }, main)
        end

        -- header (area drag) - gaya sama dengan header UI utama FanKun Hub
        local head = mk("Frame", {
            Size = UDim2.new(1, 0, 0, 34),
            BackgroundTransparency = 1,
            Active = true,
        }, main)
        local logo = mk("ImageLabel", {
            Position = UDim2.fromOffset(10, 7),
            Size = UDim2.fromOffset(20, 20),
            BackgroundTransparency = 1,
            Image = "rbxassetid://96012031195817",
            ScaleType = Enum.ScaleType.Fit,
        }, head)
        corner(logo, 100)
        mk("UIStroke", { Color = Color3.fromRGB(0, 0, 0), Thickness = 2, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }, logo)
        mk("TextLabel", {
            Position = UDim2.fromOffset(36, 0),
            Size = UDim2.new(0, 100, 1, 0),
            BackgroundTransparency = 1,
            Text = "STEAL<font color='#6e6e6e'>PANEL</font>",
            RichText = true,
            Font = Enum.Font.GothamBlack,
            TextSize = 13,
            TextColor3 = C.text,
            TextXAlignment = Enum.TextXAlignment.Left,
        }, head)
        R.pill = mk("TextLabel", {
            Size = UDim2.fromOffset(58, 16),
            Position = UDim2.new(1, -94, 0, 9),
            BackgroundColor3 = C.card,
            Font = Enum.Font.GothamBold,
            TextSize = 8,
            TextColor3 = C.muted,
            Text = "IDLE",
            BorderSizePixel = 0,
        }, head)
        corner(R.pill, 8)
        stroke(R.pill, C.line).Transparency = 0.25
        local closeBtn = mk("TextButton", {
            AnchorPoint = Vector2.new(1, 0.5),
            Size = UDim2.fromOffset(24, 22),
            Position = UDim2.new(1, -6, 0.5, 0),
            BackgroundColor3 = C.btn,
            BackgroundTransparency = 1,
            Text = "-",
            TextColor3 = C.muted,
            Font = Enum.Font.GothamBold,
            TextSize = 20,
            AutoButtonColor = false,
            BorderSizePixel = 0,
        }, head)
        corner(closeBtn, 6)
        closeBtn.MouseEnter:Connect(function()
            closeBtn.BackgroundTransparency = 0
            closeBtn.TextColor3 = C.text
        end)
        closeBtn.MouseLeave:Connect(function()
            closeBtn.BackgroundTransparency = 1
            closeBtn.TextColor3 = C.muted
        end)
        mk("Frame", {
            Position = UDim2.fromOffset(0, 34),
            Size = UDim2.new(1, 0, 0, 1),
            BackgroundColor3 = C.line,
            BorderSizePixel = 0,
        }, main)

        do
            local dragging, dragStart, startPos = false, nil, nil
            destroyConns[#destroyConns + 1] = head.InputBegan:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                    dragging = true
                    dragStart = input.Position
                    startPos = main.Position
                    input.Changed:Connect(function()
                        if input.UserInputState == Enum.UserInputState.End then
                            dragging = false
                        end
                    end)
                end
            end)
            destroyConns[#destroyConns + 1] = UserInputService.InputChanged:Connect(function(input)
                if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
                    local d = input.Position - dragStart
                    main.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + d.X, startPos.Y.Scale, startPos.Y.Offset + d.Y)
                end
            end)
        end

        -- kartu filter aktif (ikut berubah otomatis)
        local filterGrid = mk("Frame", {
            Size = UDim2.new(1, -12, 0, 42),
            Position = UDim2.fromOffset(6, 41),
            BackgroundTransparency = 1,
        }, main)
        mk("UIGridLayout", {
            CellSize = UDim2.new(0.5, -2, 0, 19),
            CellPadding = UDim2.fromOffset(4, 4),
            SortOrder = Enum.SortOrder.LayoutOrder,
        }, filterGrid)
        local function chip(order)
            local box = mk("Frame", {
                BackgroundColor3 = C.card,
                BorderSizePixel = 0,
                LayoutOrder = order,
            }, filterGrid)
            corner(box, 5)
            stroke(box, C.line).Transparency = 0.4
            return mk("TextLabel", {
                Size = UDim2.new(1, -10, 1, 0),
                Position = UDim2.fromOffset(6, 0),
                BackgroundTransparency = 1,
                Font = Enum.Font.Gotham,
                TextSize = 9,
                RichText = true,
                TextXAlignment = Enum.TextXAlignment.Left,
                TextColor3 = C.muted,
                TextTruncate = Enum.TextTruncate.AtEnd,
                Text = "",
            }, box)
        end
        R.chipRarity = chip(1)
        R.chipValue = chip(2)
        R.chipAreas = chip(3)
        R.chipEggs = chip(4)

        -- tab TARGETS / ALL + refresh
        local tabs = mk("Frame", {
            Size = UDim2.new(1, -12, 0, 22),
            Position = UDim2.fromOffset(6, 90),
            BackgroundTransparency = 1,
        }, main)
        R.tabTargets = mk("TextButton", {
            Size = UDim2.new(0.34, -3, 1, 0),
            BackgroundColor3 = C.accentBg,
            Font = Enum.Font.GothamBold,
            TextSize = 9,
            Text = "TARGETS",
            TextColor3 = C.onAccent,
            BorderSizePixel = 0,
        }, tabs)
        corner(R.tabTargets, 5)
        R.tabAll = mk("TextButton", {
            Size = UDim2.new(0.34, -3, 1, 0),
            Position = UDim2.new(0.34, 0, 0, 0),
            BackgroundColor3 = C.btn,
            Font = Enum.Font.GothamBold,
            TextSize = 9,
            Text = "ALL",
            TextColor3 = C.muted,
            BorderSizePixel = 0,
        }, tabs)
        corner(R.tabAll, 5)
        local refreshBtn = mk("TextButton", {
            Size = UDim2.new(0.32, 0, 1, 0),
            Position = UDim2.new(0.68, 0, 0, 0),
            BackgroundColor3 = C.btn,
            Font = Enum.Font.GothamBold,
            TextSize = 9,
            Text = "REFRESH",
            TextColor3 = C.text,
            BorderSizePixel = 0,
        }, tabs)
        corner(refreshBtn, 5)

        -- list
        listFrame = mk("ScrollingFrame", {
            Size = UDim2.new(1, -8, 1, -142),
            Position = UDim2.fromOffset(4, 118),
            BackgroundColor3 = C.card,
            BorderSizePixel = 0,
            ScrollBarThickness = 2,
            ScrollBarImageColor3 = C.accent,
            CanvasSize = UDim2.fromOffset(0, 0),
            AutomaticCanvasSize = Enum.AutomaticSize.Y,
        }, main)
        corner(listFrame, 8)
        mk("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 4) }, listFrame)
        mk("UIPadding", {
            PaddingTop = UDim.new(0, 4),
            PaddingLeft = UDim.new(0, 3),
            PaddingRight = UDim.new(0, 3),
            PaddingBottom = UDim.new(0, 4),
        }, listFrame)

        statusLbl = mk("TextLabel", {
            Size = UDim2.new(1, -12, 0, 18),
            Position = UDim2.new(0, 8, 1, -21),
            BackgroundTransparency = 1,
            Font = Enum.Font.Gotham,
            TextSize = 9,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextColor3 = C.muted,
            Text = "Loading…",
        }, main)

        -- "-" = minimize: panel menciut jadi header saja, ketuk "+" untuk membuka lagi
        local panelMin, panelSaved = false, {}
        closeBtn.MouseButton1Click:Connect(function()
            panelMin = not panelMin
            if panelMin then
                panelSaved = {}
                for _, ch in ipairs(main:GetChildren()) do
                    if ch:IsA("GuiObject") and ch ~= head then
                        panelSaved[ch] = ch.Visible
                        ch.Visible = false
                    end
                end
                main.Size = UDim2.fromOffset(236, 35)
                closeBtn.Text = "+"
                closeBtn.TextSize = 18
            else
                for ch, vis in pairs(panelSaved) do
                    if ch.Parent then
                        ch.Visible = vis
                    end
                end
                panelSaved = {}
                main.Size = UDim2.fromOffset(236, 318)
                closeBtn.Text = "-"
                closeBtn.TextSize = 20
            end
        end)
        R.tabTargets.MouseButton1Click:Connect(function()
            mode = "targets"
            styleTabs()
            rebuildList(true)
        end)
        R.tabAll.MouseButton1Click:Connect(function()
            mode = "all"
            styleTabs()
            rebuildList(true)
        end)
        refreshBtn.MouseButton1Click:Connect(function()
            rebuildList(true)
        end)

        panelOpen = true
        lastFilterSig = nil
        lastItemsSig = nil
        styleTabs()
        local f0 = readFilters()
        lastFilterSig = filterSig(f0)
        updateFilterBar(f0)
        updateStatusPill()
        rebuildList(true)

        -- watcher: filter berubah -> UI langsung ikut berubah; daftar egg refresh berkala
        refreshToken = refreshToken + 1
        local my = refreshToken
        task.spawn(function()
            local lastList = os.clock()
            while panelOpen and my == refreshToken and panelGui and panelGui.Parent do
                local f = readFilters()
                local fs = filterSig(f)
                local changed = fs ~= lastFilterSig
                if changed then
                    lastFilterSig = fs
                    updateFilterBar(f)
                end
                updateStatusPill()
                local now = os.clock()
                if changed or now - lastList >= 1.5 then
                    lastList = now
                    pcall(rebuildList, changed)
                end
                task.wait(0.2)
            end
        end)
    end

    setPanelVisible = function(on)
        on = on == true
        if on then
            createPanel()
        else
            destroyPanel()
        end
        tbl4.StealPanelVisible = on
    end

    tbl4.SetStealPanelVisible = setPanelVisible
    tbl4.RestoreStealPanel = function()
        if tbl4.StealPanelVisible then
            setPanelVisible(true)
        end
    end

end


-- ============================================================
-- FANJUNHUB ADD-ON: FIREBASE ANNOUNCEMENT + ONLINE PRESENCE
-- Added as a standalone layer. Existing FANJUNHUB logic/UI is untouched.
-- Shared Firebase backend with SAE/FanKunHUB.
-- ============================================================
do
    local Players = game:GetService("Players")
    local HttpService = game:GetService("HttpService")
    local LocalPlayer = Players.LocalPlayer

    local FIREBASE_BASE = "https://fankunhub-6fb0b-default-rtdb.asia-southeast1.firebasedatabase.app"
    local ANNOUNCEMENT_URL = FIREBASE_BASE .. "/announcement.json"

    local ANNOUNCEMENT_CHECK_INTERVAL = 0.50
    local ANNOUNCEMENT_MAX_AGE = 60
    local PRESENCE_HEARTBEAT = 5

    local FAN_FIREBASE_STATE = {
        dead = false,
        announcementRunning = false,
        announcementBootstrapped = false,
        announcementLastId = 0,
        announcementLastShownId = 0,
        presenceRunning = false,
        presenceUrl = nil,
        presenceSessionId = nil,
        presenceUserId = nil,
    }

    -- --------------------------------------------------------
    -- HTTP helper: same executor compatibility style as SAE.
    -- --------------------------------------------------------
    local function FanFirebaseRequest(options)
        options = options or {}
        local method = tostring(options.Method or "GET")
        local url = tostring(options.Url or "")
        if url == "" then return nil end

        local headers = options.Headers or {
            ["Accept"] = "application/json,text/plain,*/*",
            ["Content-Type"] = "application/json",
        }

        local function bodyOf(response)
            if type(response) == "string" then
                return response
            end
            if type(response) == "table" then
                return response.Body or response.body
                    or response.ResponseBody or response.responseBody
            end
            return nil
        end

        local function call(fn)
            local ok, response = pcall(fn)
            if ok then
                local body = bodyOf(response)
                if body ~= nil then return response end
            end
            return nil
        end

        if type(request) == "function" then
            local r = call(function()
                return request({
                    Url = url,
                    URL = url,
                    Method = method,
                    Headers = headers,
                    Body = options.Body,
                })
            end)
            if r then return r end
        end

        if type(http_request) == "function" then
            local r = call(function()
                return http_request({
                    Url = url,
                    URL = url,
                    Method = method,
                    Headers = headers,
                    Body = options.Body,
                })
            end)
            if r then return r end
        end

        if syn and type(syn.request) == "function" then
            local r = call(function()
                return syn.request({
                    Url = url,
                    URL = url,
                    Method = method,
                    Headers = headers,
                    Body = options.Body,
                })
            end)
            if r then return r end
        end

        if type(http) == "table" and type(http.request) == "function" then
            local r = call(function()
                return http.request({
                    Url = url,
                    URL = url,
                    Method = method,
                    Headers = headers,
                    Body = options.Body,
                })
            end)
            if r then return r end
        end

        if method == "GET" then
            local ok, result = pcall(function()
                return game:HttpGet(url, true)
            end)
            if ok and type(result) == "string" then
                return { Body = result }
            end
        end

        return nil
    end

    local function FanFirebaseGet(url)
        local bust = tostring(os.time()) .. tostring(math.random(100000, 999999))
        local fullUrl = tostring(url)
        if fullUrl:find("?", 1, true) then
            fullUrl = fullUrl .. "&t=" .. bust
        else
            fullUrl = fullUrl .. "?t=" .. bust
        end

        local response = FanFirebaseRequest({
            Url = fullUrl,
            Method = "GET",
            Headers = {
                ["Cache-Control"] = "no-cache, no-store, must-revalidate",
                ["Pragma"] = "no-cache",
                ["Expires"] = "0",
                ["Accept"] = "application/json,text/plain,*/*",
            },
        })

        if type(response) == "string" then
            return response
        end
        if type(response) == "table" then
            return response.Body or response.body
                or response.ResponseBody or response.responseBody
        end
        return nil
    end

