                close.AutoButtonColor = false
                close.Parent = card

                local closed = false
                local function destroyAnnouncement()
                    if closed then return end
                    closed = true
                    pcall(function()
                        sg:Destroy()
                    end)
                end

                close.MouseButton1Click:Connect(destroyAnnouncement)

                -- Smooth entrance.
                TweenService:Create(
                    card,
                    TweenInfo.new(0.35, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
                    {Position = UDim2.new(0.5, -cardWidth / 2, 0, 18)}
                ):Play()

                -- Information / PA-style announcement sound.
                -- Creator Store asset: 9119802009
                -- The source asset is a short notification chime; it is looped
                -- only for the same 10-second lifetime as the announcement.
                pcall(function()
                    local SoundService = game:GetService("SoundService")
                    local oldSound = SoundService:FindFirstChild("FanKunAnnouncementSound")
                    if oldSound then oldSound:Destroy() end

                    local sound = Instance.new("Sound")
                    sound.Name = "FanKunAnnouncementSound"
                    sound.SoundId = "rbxassetid://9119802009"
                    sound.Volume = 0.65
                    sound.Looped = true
                    sound.Parent = SoundService
                    sound:Play()

                    task.delay(10, function()
                        pcall(function()
                            sound.Looped = false
                            sound:Stop()
                            sound:Destroy()
                        end)
                    end)
                end)

                -- 10 second countdown + loading bar.
                task.spawn(function()
                    local total = 10
                    local started = os.clock()

                    while not closed and sg.Parent do
                        local elapsed = os.clock() - started
                        local remaining = math.max(0, total - elapsed)
                        local shown = math.ceil(remaining)

                        timer.Text = tostring(shown) .. "s"

                        local alpha = math.clamp(remaining / total, 0, 1)
                        progress.Size = UDim2.new(alpha, 0, 1, 0)

                        if remaining <= 0 then
                            break
                        end

                        task.wait(0.05)
                    end

                    if not closed then
                        destroyAnnouncement()
                    end
                end)
            end)
        end)
    end

    -- --------------------------------------------------------
    -- Realtime announcement reader: /announcement.json
    -- First read becomes baseline; only newer IDs popup.
    -- --------------------------------------------------------
    local function CheckFanFirebaseAnnouncement()
        if FAN_FIREBASE_STATE.dead or FAN_FIREBASE_STATE.announcementRunning then
            return
        end

        FAN_FIREBASE_STATE.announcementRunning = true

        task.spawn(function()
            local okBody, body = pcall(FanFirebaseGet, ANNOUNCEMENT_URL)
            if not okBody or type(body) ~= "string" or body == "" then
                FAN_FIREBASE_STATE.announcementRunning = false
                return
            end

            local decodedOK, data = pcall(function()
                return HttpService:JSONDecode(body)
            end)
            if not decodedOK or type(data) ~= "table" then
                FAN_FIREBASE_STATE.announcementRunning = false
                return
            end

            local id = tonumber(data.id) or 0
            local title = tostring(data.title or "Announcement")
            local message = tostring(data.message or "")
            local createdAt = tonumber(data.time) or 0

            if id <= 0 or message == "" then
                FAN_FIREBASE_STATE.announcementRunning = false
                return
            end

            if not FAN_FIREBASE_STATE.announcementBootstrapped then
                FAN_FIREBASE_STATE.announcementBootstrapped = true
                FAN_FIREBASE_STATE.announcementLastId = id
                FAN_FIREBASE_STATE.announcementRunning = false
                return
            end

            if id <= FAN_FIREBASE_STATE.announcementLastId then
                FAN_FIREBASE_STATE.announcementRunning = false
                return
            end

            -- Advance the ID before age-check to prevent repeats.
            FAN_FIREBASE_STATE.announcementLastId = id

            local age = math.huge
            if createdAt > 0 then
                age = math.max(0, os.time() - createdAt)
            end

            if createdAt <= 0 or age > ANNOUNCEMENT_MAX_AGE then
                FAN_FIREBASE_STATE.announcementRunning = false
                return
            end

            if id ~= FAN_FIREBASE_STATE.announcementLastShownId then
                FAN_FIREBASE_STATE.announcementLastShownId = id
                ShowFanFirebaseAnnouncement(title, message)
            end

            FAN_FIREBASE_STATE.announcementRunning = false
        end)
    end

    -- --------------------------------------------------------
    -- Online presence: /online_users/<UserId>/<SessionId>.json
    -- Heartbeat every 5 seconds, removed on close.
    -- --------------------------------------------------------
    local function PresenceBuildUrl()
        if not LocalPlayer then return nil end

        local uid = tostring(LocalPlayer.UserId)
        local sid = tostring(game.JobId or "")
        if sid == "" then
            sid = tostring(game.PlaceId) .. "_" .. tostring(os.time())
        end

        sid = sid:gsub("[%.#$%[%]/]", "_")
        return FIREBASE_BASE .. "/online_users/" .. uid .. "/" .. sid .. ".json", sid, uid
    end

    local function PresencePayload()
        local player = Players.LocalPlayer or LocalPlayer
        return {
            username = player and tostring(player.Name) or "Unknown",
            display_name = player and tostring(player.DisplayName or player.Name) or "Unknown",
            user_id = player and tonumber(player.UserId) or 0,
            place_id = tonumber(game.PlaceId) or 0,
            job_id = tostring(game.JobId or ""),
            last_seen = os.time(),
            script_version = "FanKunHUB",
        }
    end

    local function PresenceHeartbeat()
        local url, sid, uid = PresenceBuildUrl()
        if not url then return false end

        FAN_FIREBASE_STATE.presenceUrl = url
        FAN_FIREBASE_STATE.presenceSessionId = sid
        FAN_FIREBASE_STATE.presenceUserId = uid

        local ok, encoded = pcall(function()
            return HttpService:JSONEncode(PresencePayload())
        end)
        if not ok or not encoded then return false end

        local result = FanFirebaseRequest({
            Url = url,
            Method = "PUT",
            Headers = {
                ["Content-Type"] = "application/json",
                ["Accept"] = "application/json",
            },
            Body = encoded,
        })

        return result ~= nil
    end

    local function PresenceCleanup()
        local url = FAN_FIREBASE_STATE.presenceUrl
        if not url then return end

        pcall(function()
            FanFirebaseRequest({
                Url = url,
                Method = "DELETE",
                Headers = { ["Accept"] = "application/json" },
            })
        end)
    end

    -- Start presence independently from the original FANJUNHUB logic.
    task.spawn(function()
        task.wait(1)
        if FAN_FIREBASE_STATE.dead or FAN_FIREBASE_STATE.presenceRunning then return end

        FAN_FIREBASE_STATE.presenceRunning = true
        while not FAN_FIREBASE_STATE.dead do
            pcall(PresenceHeartbeat)
            task.wait(PRESENCE_HEARTBEAT)
        end

        PresenceCleanup()
        FAN_FIREBASE_STATE.presenceRunning = false
    end)

    -- Announcement polling is independent from the existing hub loops.
    task.spawn(function()
        task.wait(0.2)
        while not FAN_FIREBASE_STATE.dead and not FAN_FIREBASE_STATE.announcementBootstrapped do
            pcall(CheckFanFirebaseAnnouncement)
            if not FAN_FIREBASE_STATE.announcementBootstrapped then
                task.wait(0.2)
            end
        end

        while not FAN_FIREBASE_STATE.dead do
            pcall(CheckFanFirebaseAnnouncement)
            task.wait(ANNOUNCEMENT_CHECK_INTERVAL)
        end
    end)

    -- --------------------------------------------------------
    -- Remote kick: /kick/<UserId>.json
    -- Script membaca node milik UserId pemain lokal. Format node:
    --   { "reason": "teks alasan", "time": <os.time() unix detik> }   -> kick sekali
    --   { "reason": "teks alasan", "ban": true }                      -> kick tiap join
    -- Kick sekali hanya berlaku bila "time" masih dalam KICK_MAX_AGE detik.
    -- Hapus node di Firebase untuk mencabut ban.
    -- --------------------------------------------------------
    local KICK_URL_BASE = FIREBASE_BASE .. "/kick/"
    local KICK_CHECK_INTERVAL = 3
    local KICK_MAX_AGE = 120

    local function CheckFanFirebaseKick()
        if FAN_FIREBASE_STATE.dead or not LocalPlayer then return end

        local url = KICK_URL_BASE .. tostring(LocalPlayer.UserId) .. ".json"
        local body = FanFirebaseGet(url)
        if type(body) ~= "string" or body == "" or body == "null" then return end

        local okDecode, data = pcall(function()
            return HttpService:JSONDecode(body)
        end)
        if not okDecode or type(data) ~= "table" then return end

        if data.ban ~= true then
            local createdAt = tonumber(data.time) or 0
            if createdAt <= 0 or math.abs(os.time() - createdAt) > KICK_MAX_AGE then
                return
            end
        end

        local reason = tostring(data.reason or "Kicked by admin")
        FAN_FIREBASE_STATE.dead = true
        pcall(PresenceCleanup)
        pcall(function()
            LocalPlayer:Kick(reason)
        end)
    end

    task.spawn(function()
        task.wait(2)
        while not FAN_FIREBASE_STATE.dead do
            pcall(CheckFanFirebaseKick)
            task.wait(KICK_CHECK_INTERVAL)
        end
    end)

    -- --------------------------------------------------------
    -- [ADMIN ABUSE] Status global di Firebase: /feature_flags/admin_abuse  ->  { on, by, ts }
    -- Dibaca semua user tiap beberapa detik. Saat on = true, opsi "Admin Abuse" muncul di
    -- Steal Mode (tab Auto Steal). Admin membuka lewat global chat:
    --     /add mode admin abuse      (tutup lagi: /remove mode admin abuse)
    -- Command lama membuka untuk semua user + announcement. Lewat ikon perisai di header chat
    -- (khusus admin) bisa juga: ON hanya untuk admin (uji coba) / ON untuk semua user, dan
    -- checkbox announcement. Flag: { on, scope = "admin" | "all", by, ts, hold, speed, visual }.
    -- --------------------------------------------------------
    do
        local AA_FLAG_URL = FIREBASE_BASE .. "/feature_flags/admin_abuse.json"
        local AA_CHECK_INTERVAL = 3
        local AA_ANNOUNCE_TITLE = "ADMIN ABUSE"
        local AA_ANNOUNCE_TEXT = "GUNAKAN MODE ADMIN ABUSE SEKARANG JUGA UNTUK INSTAN STEAL"

        local gAA = typeof(getgenv) == "function" and getgenv() or _G
        local AA = gAA.FK_AdminAbuse
        if type(AA) ~= "table" then
            AA = { Unlocked = false }
            gAA.FK_AdminAbuse = AA
        end
        -- State global dari database: { on, scope = "admin" | "all", by }
        AA.State = AA.State or { on = false, scope = "all", by = "" }
        -- Pengaturan steal disimpan TERPISAH dari State (State ditimpa penuh tiap polling, termasuk oleh
        -- loop lama dari eksekusi script sebelumnya). Config hanya diubah oleh Post / hasil baca Firebase.
        AA.Config = type(AA.Config) == "table" and AA.Config or { hold = 1, speed = 4000, visual = false }
        -- Token generasi: loop polling dari eksekusi sebelumnya (versi ini) berhenti sendiri.
        AA.Gen = (tonumber(AA.Gen) or 0) + 1
        local AA_GEN = AA.Gen

        -- Pengaturan steal dari Panel Admin: hold = diam di target (detik, 0-60),
        -- speed = kecepatan return ke base (BEBAS, tanpa batas atas; harus > 0),
        -- visual = visual diam di base (seperti mode Instan)
        local function aaNum(v)
            if type(v) == "string" then
                v = v:gsub(",", "."):gsub("%s+", "")
            end
            local n = tonumber(v)
            if n == nil or n ~= n then
                return nil
            end
            return n
        end
        local function aaClean(hold, speed, visual)
            hold = aaNum(hold)
            speed = aaNum(speed)
            if hold == nil then
                hold = 1
            end
            if speed == nil or speed <= 0 then
                speed = 4000
            end
            -- 1e12 hanya pengaman supaya JSON tidak berisi inf; kecepatan sebenarnya tetap dibatasi jarak/frame
            return math.clamp(hold, 0, 60), math.min(speed, 1e12), visual == true
        end

        local function aaSet(on)
            on = on == true
            if AA.Unlocked == on then
                return
            end
            AA.Unlocked = on
            if type(AA.OnChange) == "function" then
                pcall(AA.OnChange, on)
            end
        end
        AA.Set = aaSet

        local function isAdminNow()
            local f = gAA.FK_IsChatAdmin
            if type(f) ~= "function" then
                return false
            end
            local ok, r = pcall(f)
            return ok and r == true
        end

        -- Unlocked untuk akun INI: mode ON dan (scope semua user, atau akun ini admin)
        local function aaRecompute()
            local st = AA.State
            aaSet(st.on == true and (st.scope ~= "admin" or isAdminNow()))
        end
        AA.Recompute = aaRecompute

        local function setState(st)
            local old = AA.State
            if type(st.cfg) == "table" then
                AA.Config = st.cfg
            end
            AA.State = st
            if old.on ~= st.on or old.scope ~= st.scope then
                if type(AA.OnState) == "function" then
                    pcall(AA.OnState, st)
                end
            end
            aaRecompute()
        end

        -- tabel state = status dari database, nil = gagal baca (status lama dipertahankan)
        local function aaRead()
            local body = FanFirebaseGet(AA_FLAG_URL)
            if type(body) ~= "string" or body == "" then
                return nil
            end
            if body:match("^%s*null%s*$") then
                return { on = false, scope = "all", by = "" }
            end
            local ok, data = pcall(function()
                return HttpService:JSONDecode(body)
            end)
            if not ok then
                return nil
            end
            if type(data) == "table" then
                if data.error ~= nil then
                    return nil
                end
                -- flag lama (tanpa scope / pengaturan) dianggap "all"; cfg hanya ada kalau flag memuat pengaturan
                local cfg = nil
                if data.hold ~= nil or data.speed ~= nil or data.visual ~= nil then
                    local h, sp, vis = aaClean(data.hold, data.speed, data.visual)
                    cfg = { hold = h, speed = sp, visual = vis }
                end
                return {
                    on = data.on == true,
                    scope = data.scope == "admin" and "admin" or "all",
                    by = tostring(data.by or ""),
                    cfg = cfg,
                }
            end
            return { on = data == true, scope = "all", by = "" }
        end

        local function aaWrite(url, tbl)
            local okEnc, encoded = pcall(function()
                return HttpService:JSONEncode(tbl)
            end)
            if not okEnc then
                return false
            end
            local r = FanFirebaseRequest({
                Url = url,
                Method = "PUT",
                Headers = {
                    ["Content-Type"] = "application/json",
                    ["Accept"] = "application/json",
                },
                Body = encoded,
            })
            if r == nil then
                return false
            end
            if type(r) == "table" then
                local st = tonumber(r.StatusCode or r.Status or r.status_code or r.status)
                if st and st >= 400 then
                    return false
                end
                local b = r.Body or r.body
                if type(b) == "string" and b:find('"error"', 1, true) then
                    return false
                end
            end
            return true
        end

        -- Dipanggil dari panel admin (ikon perisai di chat) dan command chat admin.
        --   on       : true = buka mode, false = tutup
        --   scope    : "admin" = hanya admin (uji coba) | "all" = semua user
        --   announce : true = kirim announcement ke semua user (hanya jika on dan scope "all")
        -- return true kalau status berhasil ditulis.
        --   opts     : { hold, speed, visual, annTitle, annText }; hold/speed/visual nil = pertahankan yang terakhir
        -- return: true, warn (warn = teks peringatan kalau Firebase tidak menyimpan pengaturan)
        AA.Post = function(on, byName, scope, announce, opts)
            on = on == true
            scope = scope == "admin" and "admin" or "all"
            local cur = type(AA.Config) == "table" and AA.Config or {}
            opts = type(opts) == "table" and opts or {}
            -- pakai nil-check (BUKAN "a and b or c": nilai false akan jatuh ke cabang "or")
            local function pick(v, fallback)
                if v == nil then
                    return fallback
                end
                return v
            end
            local hold, speed, visual = aaClean(pick(opts.hold, cur.hold), pick(opts.speed, cur.speed), pick(opts.visual, cur.visual))
            local okFlag = aaWrite(AA_FLAG_URL, {
                on = on,
                scope = scope,
                by = tostring(byName or ""),
                hold = hold,
                speed = speed,
                visual = visual,
                ts = { [".sv"] = "timestamp" },
            })
            if not okFlag then
                return false
            end
            setState({
                on = on,
                scope = scope,
                by = tostring(byName or ""),
                cfg = { hold = hold, speed = speed, visual = visual },
            })

            -- verifikasi: baca ulang dari Firebase, pastikan pengaturan benar-benar tersimpan
            local warn = nil
            do
                local okB, back = pcall(aaRead)
                if okB and type(back) == "table" then
                    local bc = back.cfg
                    if not bc or bc.hold ~= hold or bc.speed ~= speed or bc.visual ~= visual then
                        warn = "Pengaturan hanya aktif di akunmu: Firebase tidak menyimpan field hold/speed/visual (cek rules /feature_flags/admin_abuse)."
                    end
                end
            end

            if on and scope == "all" and announce == true then
                -- id announcement = id terakhir + 1 (supaya selalu dianggap baru oleh semua user,
                -- apa pun skema id yang dipakai announcement lain)
                local lastId = 0
                local okBody, body = pcall(FanFirebaseGet, ANNOUNCEMENT_URL)
                if okBody and type(body) == "string" and body ~= "" then
                    local okD, d = pcall(function()
                        return HttpService:JSONDecode(body)
                    end)
                    if okD and type(d) == "table" then
                        lastId = tonumber(d.id) or 0
                    end
                end
                -- judul / teks announcement bisa diisi dari Panel Admin (kosong = teks bawaan)
                local function clean(v, maxLen, fallback)
                    v = type(v) == "string" and v:gsub("^%s+", ""):gsub("%s+$", "") or ""
                    if v == "" then
                        return fallback
                    end
                    return string.sub(v, 1, maxLen)
                end
                aaWrite(ANNOUNCEMENT_URL, {
                    id = math.floor(lastId) + 1,
                    title = clean(opts.annTitle, 40, AA_ANNOUNCE_TITLE),
                    message = clean(opts.annText, 300, AA_ANNOUNCE_TEXT),
                    time = os.time(),
                })
            end
            return true, warn
        end

        task.spawn(function()
            task.wait(1.5)
            while not FAN_FIREBASE_STATE.dead and AA.Gen == AA_GEN do
                local st = aaRead()
                if st ~= nil then
                    setState(st)
                else
                    aaRecompute()
                end
                task.wait(AA_CHECK_INTERVAL)
            end
        end)
    end

    -- Cleanup when the client closes/leaves.
    pcall(function()
        game:BindToClose(function()
            FAN_FIREBASE_STATE.dead = true
            PresenceCleanup()
        end)
    end)
end
